      cand0.opt_in_whatsapp,
      cand0.band,
      cand0.tms_ref_num
    FROM public.candidates AS cand0
    CROSS JOIN row_ids AS ids
    LEFT JOIN contract_row AS ct1 ON TRUE
    WHERE cand0.id = COALESCE(ids.candidate_id, ct1.candidate_id)
    LIMIT 1
  ),
  client_row AS (
    SELECT
      cli0.id,
      cli0.cli_ref,
      cli0.name,
