          jsonb_build_object('kind', 'TRAVEL', 'present', (COALESCE(payload_rows.evidence_has_attached_travel, FALSE) OR COALESCE(payload_rows.evidence_has_staged_travel, FALSE)), 'has_evidence', (COALESCE(payload_rows.evidence_has_attached_travel, FALSE) OR COALESCE(payload_rows.evidence_has_staged_travel, FALSE))),
          jsonb_build_object('kind', 'ACCOMMODATION', 'present', (COALESCE(payload_rows.evidence_has_attached_accommodation, FALSE) OR COALESCE(payload_rows.evidence_has_staged_accommodation, FALSE)), 'has_evidence', (COALESCE(payload_rows.evidence_has_attached_accommodation, FALSE) OR COALESCE(payload_rows.evidence_has_staged_accommodation, FALSE))),
          jsonb_build_object('kind', 'OTHER', 'present', (COALESCE(payload_rows.evidence_has_attached_other, FALSE) OR COALESCE(payload_rows.evidence_has_staged_other, FALSE)), 'has_evidence', (COALESCE(payload_rows.evidence_has_attached_other, FALSE) OR COALESCE(payload_rows.evidence_has_staged_other, FALSE)))
        )
      )
      || jsonb_build_object(
        'count_deltas', payload_rows.count_deltas_json,
        'cache_invalidation_hints', payload_rows.cache_hints_json,
        'action_flags', jsonb_build_object(
          'can_save', payload_rows.can_save_calc,
          'can_process', payload_rows.can_process_calc,
          'has_retained_financial_history', COALESCE(payload_rows.has_retained_financial_history, FALSE),
          'can_unprocess', payload_rows.can_unprocess_calc,
          'unprocess_block_reason', payload_rows.unprocess_block_reason,
          'unprocess_action_visible', payload_rows.unprocess_action_visible_calc,
          'unprocess_block_message', CASE WHEN payload_rows.unprocess_block_reason = 'FINANCIAL_HISTORY_PREVENTS_UNPROCESS' THEN 'This timesheet has already been financially linked and cannot be unprocessed. You can archive the timesheet instead.' ELSE NULL::text END,
          'can_bulk_authorise', payload_rows.can_bulk_authorise_calc,
          'can_bulk_unauthorise', payload_rows.can_bulk_unauthorise_calc,
          'can_edit_timesheet_data', payload_rows.can_edit_timesheet_data_calc,
          'can_manage_evidence', payload_rows.can_manage_evidence_calc,
          'can_add_additional_manual', payload_rows.can_add_additional_manual_calc,
          'review_only', payload_rows.review_only_calc,
          'is_adjustment', payload_rows.effective_is_adjustment_calc,
          'additional_seq', COALESCE(payload_rows.contract_week_additional_seq, payload_rows.additional_seq, 0),
          'supportsUnprocessedExpenseDraft', (
            payload_rows.is_manual_additional_adjustment_calc = TRUE
            AND payload_rows.contract_week_id IS NOT NULL
            AND payload_rows.route_family_calc = 'MANUAL_NON_QR'
            AND payload_rows.locked_calc = FALSE
            AND payload_rows.is_authorised_calc = FALSE
            AND (payload_rows.timesheet_id IS NULL OR payload_rows.is_unprocessed_calc = TRUE)
          ),
          'supports_unprocessed_expense_draft', (
            payload_rows.is_manual_additional_adjustment_calc = TRUE
            AND payload_rows.contract_week_id IS NOT NULL
            AND payload_rows.route_family_calc = 'MANUAL_NON_QR'
            AND payload_rows.locked_calc = FALSE
            AND payload_rows.is_authorised_calc = FALSE
            AND (payload_rows.timesheet_id IS NULL OR payload_rows.is_unprocessed_calc = TRUE)
          ),
          'expense_storage_target', CASE
            WHEN payload_rows.is_manual_additional_adjustment_calc = TRUE
             AND payload_rows.contract_week_id IS NOT NULL
             AND payload_rows.route_family_calc = 'MANUAL_NON_QR'
             AND payload_rows.locked_calc = FALSE
             AND payload_rows.is_authorised_calc = FALSE
             AND (payload_rows.timesheet_id IS NULL OR payload_rows.is_unprocessed_calc = TRUE) THEN 'CONTRACT_WEEK_DRAFT'
            WHEN payload_rows.timesheet_id IS NOT NULL AND payload_rows.route_family_calc = 'MANUAL_NON_QR' THEN 'TSFIN'
            ELSE NULL::text
          END,
          'expense_evidence_storage_target', CASE
            WHEN payload_rows.is_manual_additional_adjustment_calc = TRUE
             AND payload_rows.contract_week_id IS NOT NULL
             AND payload_rows.route_family_calc = 'MANUAL_NON_QR'
             AND payload_rows.locked_calc = FALSE
             AND payload_rows.is_authorised_calc = FALSE
             AND (payload_rows.timesheet_id IS NULL OR payload_rows.is_unprocessed_calc = TRUE) THEN 'CONTRACT_WEEK_STAGED_EVIDENCE'
            WHEN payload_rows.timesheet_id IS NOT NULL AND payload_rows.route_family_calc = 'MANUAL_NON_QR' THEN 'TIMESHEET_EVIDENCE'
            ELSE NULL::text
          END
        ),
        'artifact_hints', jsonb_build_object(
          'route_family', payload_rows.route_family_calc,
          'route_subfamily', payload_rows.route_subfamily_calc,
          'underlying_channel_family', payload_rows.underlying_channel_family_calc,
          'primary_artifact_storage_key', payload_rows.primary_artifact_storage_key_calc,
          'primary_artifact_preview_mode', payload_rows.primary_artifact_preview_mode_calc,
          'has_any_evidence', (COALESCE(payload_rows.evidence_attached_count, 0) > 0 OR COALESCE(payload_rows.evidence_staged_count, 0) > 0 OR payload_rows.primary_artifact_storage_key_calc IS NOT NULL),
          'attached_evidence_count', COALESCE(payload_rows.evidence_attached_count, 0),
          'queue_staged_count', COALESCE(payload_rows.evidence_staged_count, 0)
        ),
        'row_patch', (
          jsonb_build_object(
            'previous_row_key', v_previous_row_key,
            'row_key', payload_rows.row_key_calc,
            'new_row_key', payload_rows.row_key_calc,
            'stable_row_id', payload_rows.stable_row_id_calc,
            'timesheet_id', payload_rows.timesheet_id,
            'current_timesheet_id', payload_rows.timesheet_id,
            'requested_timesheet_id', payload_rows.timesheet_id,
            'expected_timesheet_id', payload_rows.timesheet_id,
            'contract_week_id', payload_rows.contract_week_id,
            'row_signature', payload_rows.row_signature_calc,
            'backend_row_signature', payload_rows.backend_row_signature_calc,
            'mutation_row_signature', payload_rows.mutation_row_signature_calc,
            'render_signature', payload_rows.row_signature_calc,
            'previous_row_signature', NULL::text,
            'timesheet_version', payload_rows.timesheet_version,
            'current_version', payload_rows.timesheet_version,
            'updated_at', COALESCE(payload_rows.timesheet_updated_at, payload_rows.contract_week_updated_at, payload_rows.tsfin_updated_at),
            'is_current', COALESCE(payload_rows.timesheet_is_current, TRUE),
            'was_stale', FALSE,
            'candidate_id', payload_rows.candidate_id,
            'candidate_name', payload_rows.candidate_name,
            'candidate_display_name', payload_rows.candidate_name,
            'client_id', payload_rows.client_id,
            'client_name', payload_rows.client_name,
            'client_display_name', payload_rows.client_name,
            'booking_id', payload_rows.booking_id,
            'booking_ref', payload_rows.booking_id,
            'occupant_key_norm', payload_rows.occupant_key_norm,
            'hospital_name', payload_rows.hospital_norm,
            'hospital_norm', payload_rows.hospital_norm,
            'week_ending_date', COALESCE(payload_rows.contract_week_ending_date, payload_rows.week_ending_date),
            'work_date', CASE WHEN payload_rows.period_type = 'DAILY' THEN payload_rows.week_ending_date ELSE NULL::date END,
            'period_type', payload_rows.period_type,
            'sheet_scope', payload_rows.sheet_scope,
            'timesheet_scope', payload_rows.sheet_scope,
            'submission_mode', payload_rows.submission_mode,
            'submission_mode_snapshot', payload_rows.submission_mode,
            'basis', payload_rows.basis,
            'route_type', payload_rows.effective_route_type_calc,
            'route_display', CASE
          WHEN UPPER(COALESCE(payload_rows.effective_route_type_calc, '')) IN ('NHSP', 'WEEKLY_NHSP') THEN 'NHSP'
          WHEN UPPER(COALESCE(payload_rows.effective_route_type_calc, '')) = 'WEEKLY_NHSP_ADJUSTMENT' THEN 'NHSP Adjustment'
          WHEN UPPER(COALESCE(payload_rows.effective_route_type_calc, '')) IN ('HEALTHROSTER', 'WEEKLY_HEALTHROSTER') THEN 'HealthRoster'
          WHEN UPPER(COALESCE(payload_rows.effective_route_type_calc, '')) = 'WEEKLY_HEALTHROSTER_ADJUSTMENT' THEN 'HealthRoster Adjustment'
          WHEN UPPER(COALESCE(payload_rows.effective_route_type_calc, '')) = 'HEALTHROSTER_DAILY' THEN 'HealthRoster Daily'
          WHEN UPPER(COALESCE(payload_rows.effective_route_type_calc, '')) = 'WEEKLY_MANUAL_ADJUSTMENT' THEN 'Manual Adjustment'
          WHEN UPPER(COALESCE(payload_rows.effective_route_type_calc, '')) = 'QR' THEN 'QR'
          WHEN UPPER(COALESCE(payload_rows.effective_route_type_calc, '')) = 'NO_TIMESHEET_REQUIRED' THEN 'No timesheet required'
          WHEN COALESCE(payload_rows.effective_route_type_calc, '') <> '' THEN initcap(replace(payload_rows.effective_route_type_calc, '_', ' '))
          ELSE 'Manual'
        END,
            'route_family', payload_rows.route_family_calc,
            'route_subfamily', payload_rows.route_subfamily_calc
          )
          || jsonb_build_object(
            'underlying_channel_family', payload_rows.underlying_channel_family_calc,
            'is_import_authoritative', payload_rows.route_family_calc = 'IMPORT_AUTHORITATIVE',
            'compare_block_required', payload_rows.compare_block_required_calc,
            'is_adjustment', payload_rows.effective_is_adjustment_calc,
            'additional_seq', COALESCE(payload_rows.contract_week_additional_seq, payload_rows.additional_seq, 0),
            'actual_schedule_json', payload_rows.actual_schedule_json_calc,
            'planned_schedule_json', payload_rows.planned_schedule_json_calc,
            'contract_week_totals_json', COALESCE(payload_rows.contract_week_totals_json, '{}'::jsonb),
            'suppress_standard_schedule_fallback', payload_rows.keep_additional_manual_adjustment_schedule_empty_calc,
            'keep_additional_manual_adjustment_schedule_empty', payload_rows.keep_additional_manual_adjustment_schedule_empty_calc,
            '__suppressStandardScheduleFallback', payload_rows.keep_additional_manual_adjustment_schedule_empty_calc,
            '__keepAdditionalManualAdjustmentScheduleEmpty', payload_rows.keep_additional_manual_adjustment_schedule_empty_calc,
            'processing_status', payload_rows.processing_status::text,
            'processing_status_display', payload_rows.processing_status_display,
            'summary_stage', CASE
          WHEN UPPER(COALESCE(payload_rows.tools_stage, '')) = 'ARCHIVED' THEN 'ARCHIVED'
          WHEN payload_rows.is_unprocessed_calc THEN 'UNPROCESSED'
          ELSE payload_rows.summary_stage
        END,
            'tools_stage', CASE
          WHEN UPPER(COALESCE(payload_rows.tools_stage, '')) = 'ARCHIVED' THEN 'ARCHIVED'
          WHEN payload_rows.is_unprocessed_calc THEN 'UNPROCESSED'
          ELSE payload_rows.tools_stage
        END,
            'bulk_process_bucket', payload_rows.bulk_process_bucket_calc,
            'previous_bulk_process_bucket', NULL::text,
            'bulk_authorise_classification', payload_rows.bulk_authorise_classification_calc,
            'bulk_authorise_section', payload_rows.bulk_authorise_section_calc,
            'correction_id',payload_rows.timesheet_correction_id,
            'correction_kind',payload_rows.timesheet_correction_kind,
            'adjustment_origin',payload_rows.timesheet_adjustment_origin,
            'correction_source_system',case when payload_rows.timesheet_is_current=true and payload_rows.timesheet_archived_at_utc is null
              and coalesce(payload_rows.timesheet_is_adjustment,false) and payload_rows.timesheet_parent_timesheet_id is not null
              and payload_rows.timesheet_correction_id is not null and upper(coalesce(payload_rows.timesheet_adjustment_origin,''))='IMPORT_CORRECTION'
              and payload_rows.timesheet_correction_kind in ('CHANGED_HOURS_REVERSAL','CHANGED_HOURS_REPLACEMENT')
              then case when payload_rows.bulk_authorise_classification_calc='HR' then 'HEALTHROSTER' else 'NHSP' end end,
            'correction_display_label',case when payload_rows.timesheet_is_current=true and payload_rows.timesheet_archived_at_utc is null
              and coalesce(payload_rows.timesheet_is_adjustment,false) and payload_rows.timesheet_parent_timesheet_id is not null
              and payload_rows.timesheet_correction_id is not null and upper(coalesce(payload_rows.timesheet_adjustment_origin,''))='IMPORT_CORRECTION'
              then case
                when payload_rows.bulk_authorise_classification_calc='HR' and payload_rows.timesheet_correction_kind='CHANGED_HOURS_REVERSAL' then 'HealthRoster Reversal'
                when payload_rows.bulk_authorise_classification_calc='HR' and payload_rows.timesheet_correction_kind='CHANGED_HOURS_REPLACEMENT' then 'HealthRoster Corrected Hours'
                when payload_rows.bulk_authorise_classification_calc='NHSP' and payload_rows.timesheet_correction_kind='CHANGED_HOURS_REVERSAL' then 'NHSP Reversal'
                when payload_rows.bulk_authorise_classification_calc='NHSP' and payload_rows.timesheet_correction_kind='CHANGED_HOURS_REPLACEMENT' then 'NHSP Corrected Hours' end end,
            'previous_bulk_authorise_section', NULL::text,
            'is_authorised', payload_rows.is_authorised_calc,
            'authorised_at_utc', COALESCE(payload_rows.tsfin_authorised_at_utc, payload_rows.authorised_at_server),
            'authorised_at_server', payload_rows.authorised_at_server,
            'processed_at_utc', COALESCE(payload_rows.tsfin_processed_at_utc, NULL::timestamp with time zone),
            'requires_authorisation', payload_rows.requires_authorisation_calc,
            'locked', payload_rows.locked_calc,
            'locked_by_invoice_id', payload_rows.locked_by_invoice_id,
            'paid_at_utc', payload_rows.paid_at_utc,
            'review_only', payload_rows.review_only_calc,
            'can_save', payload_rows.can_save_calc,
            'can_process', payload_rows.can_process_calc,
            'has_retained_financial_history', COALESCE(payload_rows.has_retained_financial_history, FALSE),
            'can_unprocess', payload_rows.can_unprocess_calc,
            'unprocess_block_reason', payload_rows.unprocess_block_reason,
            'unprocess_action_visible', payload_rows.unprocess_action_visible_calc,
            'unprocess_block_message', CASE WHEN payload_rows.unprocess_block_reason = 'FINANCIAL_HISTORY_PREVENTS_UNPROCESS' THEN 'This timesheet has already been financially linked and cannot be unprocessed. You can archive the timesheet instead.' ELSE NULL::text END,
            'can_bulk_authorise', payload_rows.can_bulk_authorise_calc,
            'can_bulk_unauthorise', payload_rows.can_bulk_unauthorise_calc,
            'can_edit_timesheet_data', payload_rows.can_edit_timesheet_data_calc,
            'can_manage_evidence', payload_rows.can_manage_evidence_calc,
            'can_add_additional_manual', payload_rows.can_add_additional_manual_calc
          )
          || jsonb_build_object(
            'total_hours', COALESCE(payload_rows.total_hours_calc, 0::numeric),
            'total_pay_ex_vat', COALESCE(payload_rows.total_pay_ex_vat, 0::numeric),
            'total_charge_ex_vat', COALESCE(payload_rows.total_charge_ex_vat, 0::numeric),
            'margin_ex_vat', COALESCE(payload_rows.margin_ex_vat, 0::numeric),
            'net_delta_ex_vat', COALESCE(payload_rows.net_delta_ex_vat, COALESCE(payload_rows.total_charge_ex_vat, 0::numeric) - COALESCE(payload_rows.total_pay_ex_vat, 0::numeric)),
            'invoice_is_paid', COALESCE(payload_rows.invoice_is_paid, FALSE),
            'invoice_segments_total', COALESCE(payload_rows.invoice_segments_total, 0),
            'invoice_segments_locked', COALESCE(payload_rows.invoice_segments_locked, 0),
            'invoice_segments_unlocked', COALESCE(payload_rows.invoice_segments_unlocked, 0),
            'invoice_segment_stage', payload_rows.invoice_segment_stage,
            'pay_icon_code', payload_rows.pay_icon_code,
            'pay_status_code', payload_rows.pay_status_code,
            'pay_paid_at_utc', payload_rows.pay_paid_at_utc,
            'issue_codes', COALESCE(to_jsonb(payload_rows.issue_codes), '[]'::jsonb),
            'validation_status', payload_rows.validation_status::text,
            'hr_crosscheck_status', payload_rows.hr_crosscheck_status,
            'hr_crosscheck_issues', COALESCE(to_jsonb(payload_rows.hr_crosscheck_issues), '[]'::jsonb),
            'hr_validation_awaiting', payload_rows.hr_validation_awaiting_calc,
            'qr_unsigned_blocked', payload_rows.qr_unsigned_blocked_calc,
            'qr_signed_returned', payload_rows.qr_signed_returned_calc,
            'is_qr', payload_rows.is_qr_route,
            'qr_status', payload_rows.qr_status::text,
            'qr_generated_at', payload_rows.timesheet_qr_generated_at,
            'qr_scanned_at', payload_rows.timesheet_qr_scanned_at,
            'is_adjusted', COALESCE(payload_rows.is_adjusted, FALSE),
            'needs_attention', COALESCE(payload_rows.needs_attention, FALSE),
            'has_rate_issue', COALESCE(payload_rows.has_rate_issue, FALSE),
            'has_pay_channel_issue', COALESCE(payload_rows.has_pay_channel_issue, FALSE)
          )
          || jsonb_build_object(
            'client_requires_hr', COALESCE(payload_rows.client_requires_hr, FALSE),
            'client_no_timesheet_required', COALESCE(payload_rows.client_no_timesheet_required, FALSE),
            'client_autoprocess_hr', COALESCE(payload_rows.client_autoprocess_hr, FALSE),
            'client_is_nhsp', COALESCE(payload_rows.client_is_nhsp, FALSE),
            'has_any_evidence', (
              COALESCE(payload_rows.evidence_attached_count, 0) > 0
              OR COALESCE(payload_rows.evidence_staged_count, 0) > 0
              OR payload_rows.primary_artifact_storage_key_calc IS NOT NULL
            ),
            'attached_evidence_count', COALESCE(payload_rows.evidence_attached_count, 0),
            'queue_staged_count', COALESCE(payload_rows.evidence_staged_count, 0),
            'evidence_count', COALESCE(payload_rows.evidence_attached_count, 0) + COALESCE(payload_rows.evidence_staged_count, 0),
            'primary_artifact_storage_key', payload_rows.primary_artifact_storage_key_calc,
            'previous_primary_artifact_storage_key', NULL::text,
            'primary_artifact_display_name', payload_rows.primary_artifact_display_name_calc,
            'primary_artifact_preview_mode', payload_rows.primary_artifact_preview_mode_calc,
            'evidence_badges', jsonb_build_array(
              jsonb_build_object('kind', 'TIMESHEET', 'present', (COALESCE(payload_rows.evidence_has_attached_timesheet, FALSE) OR COALESCE(payload_rows.evidence_has_staged_timesheet, FALSE) OR NULLIF(BTRIM(COALESCE(payload_rows.manual_pdf_r2_key, '')), '') IS NOT NULL OR NULLIF(BTRIM(COALESCE(payload_rows.qr_r2_key, '')), '') IS NOT NULL OR NULLIF(BTRIM(COALESCE(payload_rows.uploaded_pdf_r2_key, '')), '') IS NOT NULL), 'has_evidence', (COALESCE(payload_rows.evidence_has_attached_timesheet, FALSE) OR COALESCE(payload_rows.evidence_has_staged_timesheet, FALSE) OR NULLIF(BTRIM(COALESCE(payload_rows.manual_pdf_r2_key, '')), '') IS NOT NULL OR NULLIF(BTRIM(COALESCE(payload_rows.qr_r2_key, '')), '') IS NOT NULL OR NULLIF(BTRIM(COALESCE(payload_rows.uploaded_pdf_r2_key, '')), '') IS NOT NULL)),
              jsonb_build_object('kind', 'MILEAGE', 'present', (COALESCE(payload_rows.evidence_has_attached_mileage, FALSE) OR COALESCE(payload_rows.evidence_has_staged_mileage, FALSE)), 'has_evidence', (COALESCE(payload_rows.evidence_has_attached_mileage, FALSE) OR COALESCE(payload_rows.evidence_has_staged_mileage, FALSE))),
              jsonb_build_object('kind', 'TRAVEL', 'present', (COALESCE(payload_rows.evidence_has_attached_travel, FALSE) OR COALESCE(payload_rows.evidence_has_staged_travel, FALSE)), 'has_evidence', (COALESCE(payload_rows.evidence_has_attached_travel, FALSE) OR COALESCE(payload_rows.evidence_has_staged_travel, FALSE))),
              jsonb_build_object('kind', 'ACCOMMODATION', 'present', (COALESCE(payload_rows.evidence_has_attached_accommodation, FALSE) OR COALESCE(payload_rows.evidence_has_staged_accommodation, FALSE)), 'has_evidence', (COALESCE(payload_rows.evidence_has_attached_accommodation, FALSE) OR COALESCE(payload_rows.evidence_has_staged_accommodation, FALSE))),
              jsonb_build_object('kind', 'OTHER', 'present', (COALESCE(payload_rows.evidence_has_attached_other, FALSE) OR COALESCE(payload_rows.evidence_has_staged_other, FALSE)), 'has_evidence', (COALESCE(payload_rows.evidence_has_attached_other, FALSE) OR COALESCE(payload_rows.evidence_has_staged_other, FALSE)))
            ),
            'count_deltas', payload_rows.count_deltas_json,
            'cache_invalidation_hints', payload_rows.cache_hints_json
          )
        )
      )
    )) AS row_json
  FROM payload_rows
  ORDER BY
    COALESCE(payload_rows.contract_week_ending_date, payload_rows.week_ending_date) ASC NULLS LAST,
    payload_rows.client_name ASC NULLS LAST,
    payload_rows.candidate_name ASC NULLS LAST,
    payload_rows.row_key_calc ASC;
END;
$function$;

-- bulk_timesheet_workbench_row_source_v1(jsonb)
CREATE OR REPLACE FUNCTION public.bulk_timesheet_workbench_row_source_v1(p_filters jsonb DEFAULT '{}'::jsonb)
 RETURNS TABLE(timesheet_id uuid, timesheet_status timesheet_status_enum, week_ending_date date, booking_id text, occupant_key_norm text, hospital_norm text, sheet_scope timesheet_scope_enum, submission_mode submission_mode_enum, authorised_at_server timestamp with time zone, candidate_id uuid, client_id uuid, pay_method text, processing_status ts_fin_processing_status_enum, basis timesheet_fin_basis_enum, total_hours numeric, total_pay_ex_vat numeric, total_charge_ex_vat numeric, margin_ex_vat numeric, paid_at_utc timestamp with time zone, pay_on_hold boolean, ready_to_pay boolean, locked_by_invoice_id uuid, candidate_name text, client_name text, nhsp_shift_count integer, nhsp_shift_included_count integer, nhsp_shift_deferred_count integer, validation_status validation_status_enum, summary_stage text, route_type text, contract_week_id uuid, contract_week_ending_date date, contract_week_status contract_week_status_enum, additional_seq integer, is_adjustment boolean, qr_status timesheet_qr_status_enum, pay_adjustment_count integer, has_pay_adjustments boolean, is_adjusted boolean, is_qr boolean, needs_attention boolean, client_autoprocess_hr boolean, has_rate_issue boolean, has_pay_channel_issue boolean, hr_crosscheck_status text, hr_crosscheck_issues text[], external_source_rows_json jsonb, issue_codes text[], client_requires_hr boolean, client_no_timesheet_required boolean, client_is_nhsp boolean, client_pay_reference_required boolean, client_invoice_reference_required boolean, client_hr_validation_required boolean, client_ts_reference_required boolean, require_reference_to_pay boolean, require_reference_to_invoice boolean, qr_token text, qr_generated_at timestamp with time zone, qr_scanned_at timestamp with time zone, candidate_hint_text jsonb, expenses_pay_ex_vat numeric, expenses_description text, mileage_units numeric, mileage_pay_rate numeric, mileage_charge_rate numeric, mileage_pay_ex_vat numeric, travel_pay_ex_vat numeric, travel_charge_ex_vat numeric, accommodation_pay_ex_vat numeric, accommodation_charge_ex_vat numeric, other_pay_ex_vat numeric, other_charge_ex_vat numeric, hr_validation_required_for_invoice boolean, invoice_segments_total integer, invoice_segments_locked integer, invoice_segments_unlocked integer, invoice_segment_stage text, tools_stage text, processing_status_display text, invoice_is_paid boolean, refs_block_invoicing boolean, refs_block_issuing_invoices boolean, refs_block_invoice_and_issuing boolean, pay_icon_code text, pay_status_code text, pay_paid_at_utc timestamp with time zone, net_delta_ex_vat numeric)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_filters jsonb := COALESCE(p_filters, '{}'::jsonb);
  v_candidate_id_text text := NULL;
  v_client_id_text text := NULL;
  v_candidate_id uuid := NULL;
  v_client_id uuid := NULL;
  v_timesheet_ids uuid[] := NULL;
  v_contract_week_ids uuid[] := NULL;
  v_row_keys text[] := NULL;
  v_row_key_timesheet_ids uuid[] := NULL;
  v_row_key_contract_week_ids uuid[] := NULL;
  v_has_contract_week_row_key boolean := FALSE;
  v_dataset_mode text := NULL;
  v_period_filter text := NULL;
  v_date_from_text text := NULL;
  v_date_to_text text := NULL;
  v_week_ending_text text := NULL;
  v_week_ending_from_text text := NULL;
  v_week_ending_to_text text := NULL;
  v_date_from date := NULL;
  v_date_to date := NULL;
  v_week_ending_date date := NULL;
  v_week_ending_from date := NULL;
  v_week_ending_to date := NULL;
  v_uuid_re text := '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$';
  v_numeric_re text := E'^[-+]?[0-9]+(\\.[0-9]+)?$';
BEGIN
  v_candidate_id_text := NULLIF(BTRIM(COALESCE(v_filters->>'candidate_id', v_filters->>'candidateId', '')), '');
  BEGIN
    IF v_candidate_id_text IS NOT NULL THEN
      v_candidate_id := v_candidate_id_text::uuid;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    v_candidate_id := NULL;
  END;

  v_client_id_text := NULLIF(BTRIM(COALESCE(v_filters->>'client_id', v_filters->>'clientId', '')), '');
  BEGIN
    IF v_client_id_text IS NOT NULL THEN
      v_client_id := v_client_id_text::uuid;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    v_client_id := NULL;
  END;

  IF v_filters ? 'timesheet_ids' AND jsonb_typeof(v_filters->'timesheet_ids') = 'array' THEN
    SELECT ARRAY_AGG(uuid_values.uuid_value)
      INTO v_timesheet_ids
    FROM (
      SELECT DISTINCT input_values.value::uuid AS uuid_value
      FROM jsonb_array_elements_text(v_filters->'timesheet_ids') AS input_values(value)
      WHERE input_values.value ~* v_uuid_re
    ) AS uuid_values;
  ELSIF v_filters ? 'timesheetIds' AND jsonb_typeof(v_filters->'timesheetIds') = 'array' THEN
    SELECT ARRAY_AGG(uuid_values.uuid_value)
      INTO v_timesheet_ids
    FROM (
      SELECT DISTINCT input_values.value::uuid AS uuid_value
      FROM jsonb_array_elements_text(v_filters->'timesheetIds') AS input_values(value)
      WHERE input_values.value ~* v_uuid_re
    ) AS uuid_values;
  ELSIF v_filters ? 'timesheet_id' AND NULLIF(BTRIM(COALESCE(v_filters->>'timesheet_id', '')), '') IS NOT NULL AND (v_filters->>'timesheet_id') ~* v_uuid_re THEN
    v_timesheet_ids := ARRAY[(v_filters->>'timesheet_id')::uuid];
  ELSIF v_filters ? 'timesheetId' AND NULLIF(BTRIM(COALESCE(v_filters->>'timesheetId', '')), '') IS NOT NULL AND (v_filters->>'timesheetId') ~* v_uuid_re THEN
    v_timesheet_ids := ARRAY[(v_filters->>'timesheetId')::uuid];
  END IF;

  IF v_filters ? 'contract_week_ids' AND jsonb_typeof(v_filters->'contract_week_ids') = 'array' THEN
    SELECT ARRAY_AGG(uuid_values.uuid_value)
      INTO v_contract_week_ids
    FROM (
      SELECT DISTINCT input_values.value::uuid AS uuid_value
      FROM jsonb_array_elements_text(v_filters->'contract_week_ids') AS input_values(value)
      WHERE input_values.value ~* v_uuid_re
    ) AS uuid_values;
  ELSIF v_filters ? 'contractWeekIds' AND jsonb_typeof(v_filters->'contractWeekIds') = 'array' THEN
    SELECT ARRAY_AGG(uuid_values.uuid_value)
      INTO v_contract_week_ids
    FROM (
      SELECT DISTINCT input_values.value::uuid AS uuid_value
      FROM jsonb_array_elements_text(v_filters->'contractWeekIds') AS input_values(value)
      WHERE input_values.value ~* v_uuid_re
    ) AS uuid_values;
  ELSIF v_filters ? 'contract_week_id' AND NULLIF(BTRIM(COALESCE(v_filters->>'contract_week_id', '')), '') IS NOT NULL AND (v_filters->>'contract_week_id') ~* v_uuid_re THEN
    v_contract_week_ids := ARRAY[(v_filters->>'contract_week_id')::uuid];
  ELSIF v_filters ? 'contractWeekId' AND NULLIF(BTRIM(COALESCE(v_filters->>'contractWeekId', '')), '') IS NOT NULL AND (v_filters->>'contractWeekId') ~* v_uuid_re THEN
    v_contract_week_ids := ARRAY[(v_filters->>'contractWeekId')::uuid];
  END IF;

  IF v_filters ? 'row_keys' AND jsonb_typeof(v_filters->'row_keys') = 'array' THEN
    SELECT ARRAY_AGG(row_key_values.row_key_value)
      INTO v_row_keys
    FROM (
      SELECT DISTINCT NULLIF(BTRIM(input_values.value), '') AS row_key_value
      FROM jsonb_array_elements_text(v_filters->'row_keys') AS input_values(value)
    ) AS row_key_values
    WHERE row_key_values.row_key_value IS NOT NULL;
  ELSIF v_filters ? 'rowKeys' AND jsonb_typeof(v_filters->'rowKeys') = 'array' THEN
    SELECT ARRAY_AGG(row_key_values.row_key_value)
      INTO v_row_keys
    FROM (
      SELECT DISTINCT NULLIF(BTRIM(input_values.value), '') AS row_key_value
      FROM jsonb_array_elements_text(v_filters->'rowKeys') AS input_values(value)
    ) AS row_key_values
    WHERE row_key_values.row_key_value IS NOT NULL;
  ELSIF v_filters ? 'row_key' AND NULLIF(BTRIM(COALESCE(v_filters->>'row_key', '')), '') IS NOT NULL THEN
    v_row_keys := ARRAY[NULLIF(BTRIM(v_filters->>'row_key'), '')];
  ELSIF v_filters ? 'rowKey' AND NULLIF(BTRIM(COALESCE(v_filters->>'rowKey', '')), '') IS NOT NULL THEN
    v_row_keys := ARRAY[NULLIF(BTRIM(v_filters->>'rowKey'), '')];
  END IF;


  IF v_row_keys IS NOT NULL THEN
    SELECT ARRAY_AGG(parsed_values.uuid_value)
      INTO v_row_key_timesheet_ids
    FROM (
      SELECT DISTINCT SUBSTRING(row_key_values.row_key_value FROM 11)::uuid AS uuid_value
      FROM UNNEST(v_row_keys) AS row_key_values(row_key_value)
      WHERE LOWER(LEFT(row_key_values.row_key_value, 10)) = 'timesheet:'
        AND SUBSTRING(row_key_values.row_key_value FROM 11) ~* v_uuid_re
    ) AS parsed_values;

    SELECT ARRAY_AGG(parsed_values.uuid_value)
      INTO v_row_key_contract_week_ids
    FROM (
      SELECT DISTINCT SUBSTRING(row_key_values.row_key_value FROM 15)::uuid AS uuid_value
      FROM UNNEST(v_row_keys) AS row_key_values(row_key_value)
      WHERE LOWER(LEFT(row_key_values.row_key_value, 14)) = 'contract_week:'
        AND SUBSTRING(row_key_values.row_key_value FROM 15) ~* v_uuid_re
    ) AS parsed_values;

    v_has_contract_week_row_key := COALESCE(ARRAY_LENGTH(v_row_key_contract_week_ids, 1), 0) > 0;

    IF v_row_key_timesheet_ids IS NOT NULL THEN
      SELECT ARRAY_AGG(merged_ids.uuid_value)
        INTO v_timesheet_ids
      FROM (
        SELECT DISTINCT existing_ids.uuid_value
        FROM UNNEST(COALESCE(v_timesheet_ids, ARRAY[]::uuid[])) AS existing_ids(uuid_value)
        UNION
        SELECT DISTINCT row_key_ids.uuid_value
        FROM UNNEST(v_row_key_timesheet_ids) AS row_key_ids(uuid_value)
      ) AS merged_ids;
    END IF;

    IF v_row_key_contract_week_ids IS NOT NULL THEN
      SELECT ARRAY_AGG(merged_ids.uuid_value)
        INTO v_contract_week_ids
      FROM (
        SELECT DISTINCT existing_ids.uuid_value
        FROM UNNEST(COALESCE(v_contract_week_ids, ARRAY[]::uuid[])) AS existing_ids(uuid_value)
        UNION
        SELECT DISTINCT row_key_ids.uuid_value
        FROM UNNEST(v_row_key_contract_week_ids) AS row_key_ids(uuid_value)
      ) AS merged_ids;
    END IF;
  END IF;

  v_dataset_mode := UPPER(NULLIF(BTRIM(COALESCE(v_filters->>'dataset_mode', v_filters->>'datasetMode', '')), ''));
  IF v_dataset_mode NOT IN ('PROCESS', 'AUTHORISE', 'ROW_CONTEXT') THEN
    v_dataset_mode := NULL;
  END IF;

  v_period_filter := UPPER(NULLIF(BTRIM(COALESCE(v_filters->>'period_type', v_filters->>'periodType', v_filters->>'sheet_scope', v_filters->>'sheetScope', '')), ''));
  IF v_period_filter NOT IN ('DAILY', 'WEEKLY') THEN
    v_period_filter := NULL;
  END IF;

  v_date_from_text := NULLIF(BTRIM(COALESCE(v_filters->>'date_from', v_filters->>'dateFrom', v_filters->>'from_date', v_filters->>'fromDate', '')), '');
  v_date_to_text := NULLIF(BTRIM(COALESCE(v_filters->>'date_to', v_filters->>'dateTo', v_filters->>'to_date', v_filters->>'toDate', '')), '');
  v_week_ending_text := NULLIF(BTRIM(COALESCE(v_filters->>'week_ending_date', v_filters->>'weekEndingDate', v_filters->>'week_ending', v_filters->>'weekEnding', '')), '');
  v_week_ending_from_text := NULLIF(BTRIM(COALESCE(v_filters->>'week_ending_from', v_filters->>'weekEndingFrom', '')), '');
  v_week_ending_to_text := NULLIF(BTRIM(COALESCE(v_filters->>'week_ending_to', v_filters->>'weekEndingTo', '')), '');

  BEGIN
    IF v_date_from_text IS NOT NULL THEN
      v_date_from := v_date_from_text::date;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    v_date_from := NULL;
  END;

  BEGIN
    IF v_date_to_text IS NOT NULL THEN
      v_date_to := v_date_to_text::date;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    v_date_to := NULL;
  END;

  BEGIN
    IF v_week_ending_text IS NOT NULL THEN
      v_week_ending_date := v_week_ending_text::date;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    v_week_ending_date := NULL;
  END;

  BEGIN
    IF v_week_ending_from_text IS NOT NULL THEN
      v_week_ending_from := v_week_ending_from_text::date;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    v_week_ending_from := NULL;
  END;

  BEGIN
    IF v_week_ending_to_text IS NOT NULL THEN
      v_week_ending_to := v_week_ending_to_text::date;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    v_week_ending_to := NULL;
  END;

  RETURN QUERY
  WITH client_hr AS MATERIALIZED (
    SELECT
      cs0.client_id,
      BOOL_OR(cs0.autoprocess_hr) AS autoprocess_hr,
      BOOL_OR(cs0.requires_hr) AS requires_hr,
      BOOL_OR(cs0.no_timesheet_required) AS no_timesheet_required,
      BOOL_OR(cs0.pay_reference_required) AS pay_reference_required,
      BOOL_OR(cs0.invoice_reference_required) AS invoice_reference_required,
      BOOL_OR(cs0.reference_number_required_to_issue_invoice) AS reference_number_required_to_issue_invoice,
      BOOL_OR(cs0.hr_validation_required) AS hr_validation_required,
      BOOL_OR(cs0.ts_reference_required) AS ts_reference_required,
      BOOL_OR(cs0.is_nhsp) AS is_nhsp
    FROM public.client_settings AS cs0
    GROUP BY cs0.client_id
  ),
  timesheet_scope_rows AS MATERIALIZED (
    SELECT
      ts0.timesheet_id,
      cw0.id AS contract_week_id,
      COALESCE(cw0.week_ending_date, ts0.week_ending_date) AS effective_week_ending_date,
      ts0.sheet_scope AS effective_sheet_scope,
      COALESCE(ts0.contract_id, cw0.contract_id) AS effective_contract_id
    FROM public.timesheets AS ts0
    LEFT JOIN public.contract_weeks AS cw0
      ON cw0.timesheet_id = ts0.timesheet_id
    WHERE ts0.is_current = TRUE
      AND (v_timesheet_ids IS NULL OR ts0.timesheet_id = ANY(v_timesheet_ids))
      AND (
        v_contract_week_ids IS NULL
        OR cw0.id = ANY(v_contract_week_ids)
        OR v_timesheet_ids IS NOT NULL
        OR (v_row_key_timesheet_ids IS NOT NULL AND ts0.timesheet_id = ANY(v_row_key_timesheet_ids))
      )
      AND (
        v_row_keys IS NULL
        OR ('timesheet:' || ts0.timesheet_id::text) = ANY(v_row_keys)
        OR (v_row_key_timesheet_ids IS NOT NULL AND ts0.timesheet_id = ANY(v_row_key_timesheet_ids))
      )
      AND (
        v_week_ending_date IS NULL
        OR COALESCE(cw0.week_ending_date, ts0.week_ending_date) = v_week_ending_date
      )
      AND (
        v_week_ending_from IS NULL
        OR COALESCE(cw0.week_ending_date, ts0.week_ending_date) >= v_week_ending_from
      )
      AND (
        v_week_ending_to IS NULL
        OR COALESCE(cw0.week_ending_date, ts0.week_ending_date) <= v_week_ending_to
      )
      AND (
        v_date_from IS NULL
        OR (
          CASE
            WHEN ts0.sheet_scope = 'DAILY'::public.timesheet_scope_enum THEN COALESCE(ts0.worked_start_iso::date, ts0.scheduled_start_iso::date, ts0.week_ending_date)
            ELSE COALESCE(cw0.week_ending_date, ts0.week_ending_date)
          END
        ) >= v_date_from
      )
      AND (
        v_date_to IS NULL
        OR (
          CASE
            WHEN ts0.sheet_scope = 'DAILY'::public.timesheet_scope_enum THEN COALESCE(ts0.worked_start_iso::date, ts0.scheduled_start_iso::date, ts0.week_ending_date)
            ELSE COALESCE(cw0.week_ending_date, ts0.week_ending_date)
          END
        ) <= v_date_to
      )
      AND (
        v_period_filter IS NULL
        OR UPPER(ts0.sheet_scope::text) = v_period_filter
      )
  ),
  contract_week_scope_rows AS MATERIALIZED (
    SELECT
      cw0.id AS contract_week_id,
      cw0.contract_id,
      cw0.week_ending_date AS effective_week_ending_date
    FROM public.contract_weeks AS cw0
    JOIN public.contracts AS ct_scope
      ON ct_scope.id = cw0.contract_id
    WHERE cw0.timesheet_id IS NULL
      AND (
        v_timesheet_ids IS NULL
        OR v_contract_week_ids IS NOT NULL
        OR v_has_contract_week_row_key = TRUE
      )
      AND (
        COALESCE(v_dataset_mode, 'PROCESS') <> 'AUTHORISE'
        OR v_has_contract_week_row_key = TRUE
      )
      AND (v_candidate_id IS NULL OR ct_scope.candidate_id = v_candidate_id)
      AND (v_client_id IS NULL OR ct_scope.client_id = v_client_id)
      AND (v_contract_week_ids IS NULL OR cw0.id = ANY(v_contract_week_ids))
      AND (
        v_row_keys IS NULL
        OR ('contract_week:' || cw0.id::text) = ANY(v_row_keys)
      )
      AND (
        v_week_ending_date IS NULL
        OR cw0.week_ending_date = v_week_ending_date
      )
      AND (
        v_week_ending_from IS NULL
        OR cw0.week_ending_date >= v_week_ending_from
      )
      AND (
        v_week_ending_to IS NULL
        OR cw0.week_ending_date <= v_week_ending_to
      )
      AND (
        v_date_from IS NULL
        OR cw0.week_ending_date >= v_date_from
      )
      AND (
        v_date_to IS NULL
        OR cw0.week_ending_date <= v_date_to
      )
      AND (
        v_period_filter IS NULL
        OR v_period_filter = 'WEEKLY'
      )
  ),
  tf_ranked AS MATERIALIZED (
    SELECT
      tf0.id,
      tf0.timesheet_id,
      tf0.candidate_id,
      tf0.client_id,
      tf0.pay_method,
      tf0.processing_status,
      tf0.basis,
      tf0.total_hours,
      tf0.total_pay_ex_vat,
      tf0.total_charge_ex_vat,
      tf0.margin_ex_vat,
      tf0.paid_at_utc,
      tf0.pay_on_hold,
      tf0.locked_by_invoice_id,
      tf0.has_rate_issue,
      tf0.has_pay_channel_issue,
      tf0.hr_crosscheck_status,
      tf0.hr_crosscheck_issues,
      tf0.external_source_rows_json,
      tf0.invoice_breakdown_json,
      tf0.expenses_pay_ex_vat,
      tf0.expenses_description,
      tf0.mileage_units,
      tf0.mileage_pay_rate,
      tf0.mileage_charge_rate,
      tf0.mileage_pay_ex_vat,
      tf0.mileage_charge_ex_vat,
      tf0.travel_pay_ex_vat,
      tf0.travel_charge_ex_vat,
      tf0.accommodation_pay_ex_vat,
      tf0.accommodation_charge_ex_vat,
      tf0.other_pay_ex_vat,
      tf0.other_charge_ex_vat,
      tf0.created_at,
      tf0.updated_at,
      ROW_NUMBER() OVER (
        PARTITION BY tf0.timesheet_id
        ORDER BY tf0.created_at DESC NULLS LAST, tf0.updated_at DESC NULLS LAST, tf0.id DESC
      ) AS rn
    FROM public.timesheets_financials AS tf0
    WHERE tf0.is_current = TRUE
      AND EXISTS (
        SELECT 1
        FROM timesheet_scope_rows AS ts_scope_tf
        WHERE ts_scope_tf.timesheet_id = tf0.timesheet_id
      )
  ),
  tf_latest AS MATERIALIZED (
    SELECT
      tf1.id,
      tf1.timesheet_id,
      tf1.candidate_id,
      tf1.client_id,
      tf1.pay_method,
      tf1.processing_status,
      tf1.basis,
      tf1.total_hours,
      tf1.total_pay_ex_vat,
      tf1.total_charge_ex_vat,
      tf1.margin_ex_vat,
      tf1.paid_at_utc,
      tf1.pay_on_hold,
      tf1.locked_by_invoice_id,
      tf1.has_rate_issue,
      tf1.has_pay_channel_issue,
      tf1.hr_crosscheck_status,
      tf1.hr_crosscheck_issues,
      tf1.external_source_rows_json,
      tf1.invoice_breakdown_json,
      tf1.expenses_pay_ex_vat,
      tf1.expenses_description,
      tf1.mileage_units,
      tf1.mileage_pay_rate,
      tf1.mileage_charge_rate,
      tf1.mileage_pay_ex_vat,
      tf1.mileage_charge_ex_vat,
      tf1.travel_pay_ex_vat,
      tf1.travel_charge_ex_vat,
      tf1.accommodation_pay_ex_vat,
      tf1.accommodation_charge_ex_vat,
      tf1.other_pay_ex_vat,
      tf1.other_charge_ex_vat
    FROM tf_ranked AS tf1
    WHERE tf1.rn = 1
  ),
  tv_ranked AS MATERIALIZED (
    SELECT
      tv0.id,
      tv0.timesheet_id,
      tv0.status,
      tv0.reason_code,
      tv0.created_at,
      tv0.updated_at,
      ROW_NUMBER() OVER (
        PARTITION BY tv0.timesheet_id
        ORDER BY tv0.updated_at DESC NULLS LAST, tv0.created_at DESC NULLS LAST, tv0.id DESC
      ) AS rn
    FROM public.timesheet_validations AS tv0
    WHERE tv0.timesheet_id IS NOT NULL
      AND EXISTS (
        SELECT 1
        FROM timesheet_scope_rows AS ts_scope_tv
        WHERE ts_scope_tv.timesheet_id = tv0.timesheet_id
      )
  ),
  tv_latest AS MATERIALIZED (
    SELECT
      tv1.timesheet_id,
      tv1.status
    FROM tv_ranked AS tv1
    WHERE tv1.rn = 1
  ),
  evidence_agg AS MATERIALIZED (
    SELECT
      te0.timesheet_id,
      COUNT(te0.id) FILTER (
        WHERE NULLIF(BTRIM(COALESCE(te0.storage_key, '')), '') IS NOT NULL
      )::integer AS evidence_count,
      COALESCE(BOOL_OR(
        UPPER(COALESCE(te0.kind, '')) = 'TIMESHEET'
        AND NULLIF(BTRIM(COALESCE(te0.storage_key, '')), '') IS NOT NULL
      ), FALSE) AS has_timesheet_evidence,
      COALESCE(BOOL_OR(
        UPPER(COALESCE(te0.kind, '')) = 'MILEAGE'
        AND NULLIF(BTRIM(COALESCE(te0.storage_key, '')), '') IS NOT NULL
      ), FALSE) AS has_mileage_evidence,
      COALESCE(BOOL_OR(
        UPPER(COALESCE(te0.kind, '')) = 'TRAVEL'
        AND NULLIF(BTRIM(COALESCE(te0.storage_key, '')), '') IS NOT NULL
      ), FALSE) AS has_travel_evidence,
      COALESCE(BOOL_OR(
        UPPER(COALESCE(te0.kind, '')) = 'ACCOMMODATION'
        AND NULLIF(BTRIM(COALESCE(te0.storage_key, '')), '') IS NOT NULL
      ), FALSE) AS has_accommodation_evidence,
      COALESCE(BOOL_OR(
        UPPER(COALESCE(te0.kind, '')) = 'OTHER'
        AND NULLIF(BTRIM(COALESCE(te0.storage_key, '')), '') IS NOT NULL
      ), FALSE) AS has_other_evidence
    FROM public.timesheet_evidence AS te0
    WHERE te0.timesheet_id IS NOT NULL
      AND EXISTS (
        SELECT 1
        FROM timesheet_scope_rows AS ts_scope_te
        WHERE ts_scope_te.timesheet_id = te0.timesheet_id
      )
    GROUP BY te0.timesheet_id
  ),
  nhsp_agg AS MATERIALIZED (
    SELECT
      ns0.timesheet_id,
      COUNT(ns0.id)::integer AS nhsp_shift_count,
      (COUNT(ns0.id) FILTER (WHERE ns0.invoice_status = 'INCLUDED'))::integer AS nhsp_shift_included_count,
      (COUNT(ns0.id) FILTER (WHERE ns0.invoice_status = 'DEFERRED'))::integer AS nhsp_shift_deferred_count
    FROM public.nhsp_shifts AS ns0
    WHERE ns0.timesheet_id IS NOT NULL
      AND EXISTS (
        SELECT 1
        FROM timesheet_scope_rows AS ts_scope_ns
        WHERE ts_scope_ns.timesheet_id = ns0.timesheet_id
      )
    GROUP BY ns0.timesheet_id
  ),
  pay_adjustments_agg AS MATERIALIZED (
    SELECT
      pa0.timesheet_id,
      COUNT(pa0.id)::integer AS pay_adjustment_count
    FROM public.ts_pay_adjustments AS pa0
    WHERE pa0.timesheet_id IS NOT NULL
      AND EXISTS (
        SELECT 1
        FROM timesheet_scope_rows AS ts_scope_pa
        WHERE ts_scope_pa.timesheet_id = pa0.timesheet_id
      )
    GROUP BY pa0.timesheet_id
  ),
  timesheet_rows AS MATERIALIZED (
    SELECT
      ts0.timesheet_id AS timesheet_id,
      ts0.status AS timesheet_status,
      ts0.week_ending_date AS week_ending_date,
      ts0.booking_id AS booking_id,
      ts0.occupant_key_norm AS occupant_key_norm,
      ts0.hospital_norm AS hospital_norm,
      ts0.sheet_scope AS sheet_scope,
      ts0.submission_mode AS submission_mode,
      ts0.authorised_at_server AS authorised_at_server,
      COALESCE(tf2.candidate_id, ct0.candidate_id) AS candidate_id,
      COALESCE(tf2.client_id, ct0.client_id) AS client_id,
      tf2.pay_method AS pay_method,
      tf2.processing_status AS processing_status,
      tf2.basis AS basis,
      tf2.total_hours AS total_hours,
      tf2.total_pay_ex_vat AS total_pay_ex_vat,
      tf2.total_charge_ex_vat AS total_charge_ex_vat,
      tf2.margin_ex_vat AS margin_ex_vat,
      tf2.paid_at_utc AS paid_at_utc,
      tf2.pay_on_hold AS pay_on_hold,
      tf2.locked_by_invoice_id AS locked_by_invoice_id,
      CASE
        WHEN COALESCE(tf2.candidate_id, ct0.candidate_id) IS NULL
         AND ts0.candidate_hint_text IS NOT NULL
         AND jsonb_typeof(ts0.candidate_hint_text) = 'object'
         AND (
           NULLIF(BTRIM(CONCAT_WS(' ', NULLIF(BTRIM(ts0.candidate_hint_text->>'first_name'), ''), NULLIF(BTRIM(ts0.candidate_hint_text->>'surname'), ''))), '') IS NOT NULL
           OR NULLIF(BTRIM(ts0.candidate_hint_text->>'display_name'), '') IS NOT NULL
           OR NULLIF(BTRIM(ts0.candidate_hint_text->>'email'), '') IS NOT NULL
         ) THEN
          'Unresolved Timesheet - '
          || COALESCE(
            NULLIF(BTRIM(CONCAT_WS(' ', NULLIF(BTRIM(ts0.candidate_hint_text->>'first_name'), ''), NULLIF(BTRIM(ts0.candidate_hint_text->>'surname'), ''))), ''),
            NULLIF(BTRIM(ts0.candidate_hint_text->>'display_name'), ''),
            'Candidate'
          )
          || CASE
               WHEN NULLIF(BTRIM(ts0.candidate_hint_text->>'email'), '') IS NOT NULL THEN ', Email - ' || BTRIM(ts0.candidate_hint_text->>'email')
               ELSE ''
             END
        ELSE COALESCE(cand0.display_name, ts0.occupant_key_norm)
      END AS candidate_name,
      cli0.name AS client_name,
      COALESCE(ns1.nhsp_shift_count, 0) AS nhsp_shift_count,
      COALESCE(ns1.nhsp_shift_included_count, 0) AS nhsp_shift_included_count,
      COALESCE(ns1.nhsp_shift_deferred_count, 0) AS nhsp_shift_deferred_count,
      tv2.status AS validation_status,
      cw0.id AS contract_week_id,
      cw0.week_ending_date AS contract_week_ending_date,
      cw0.status AS contract_week_status,
      cw0.additional_seq AS additional_seq,
      COALESCE(ts0.is_adjustment, cw0.is_adjustment, FALSE) AS is_adjustment,
      ts0.qr_status AS qr_status,
      ts0.qr_token AS qr_token,
      ts0.qr_generated_at AS qr_generated_at,
      ts0.qr_scanned_at AS qr_scanned_at,
      ts0.qr_last_sent_hash AS qr_last_sent_hash,
      COALESCE(pa1.pay_adjustment_count, 0) AS pay_adjustment_count,
      COALESCE(
        CASE WHEN ct0.overrideclientsettings THEN ct0.autoprocess_hr ELSE NULL::boolean END,
        ch0.autoprocess_hr,
        FALSE
      ) AS client_autoprocess_hr,
      COALESCE(
        CASE WHEN ct0.overrideclientsettings THEN ct0.requires_hr ELSE NULL::boolean END,
        ch0.requires_hr,
        FALSE
      ) AS client_requires_hr,
      COALESCE(
        CASE WHEN ct0.overrideclientsettings THEN ct0.no_timesheet_required ELSE NULL::boolean END,
        ch0.no_timesheet_required,
        FALSE
      ) AS client_no_timesheet_required,
      COALESCE(ch0.pay_reference_required, FALSE) AS client_pay_reference_required,
      COALESCE(ch0.invoice_reference_required, FALSE) AS client_invoice_reference_required,
      COALESCE(
        CASE WHEN ct0.overrideclientsettings THEN ct0.requires_hr ELSE NULL::boolean END,
        ch0.hr_validation_required,
        FALSE
      ) AS client_hr_validation_required,
      COALESCE(ch0.ts_reference_required, FALSE) AS client_ts_reference_required,
      COALESCE(
        CASE WHEN ct0.overrideclientsettings THEN ct0.is_nhsp ELSE NULL::boolean END,
        ch0.is_nhsp,
        FALSE
      ) AS client_is_nhsp,
      COALESCE(tf2.has_rate_issue, FALSE) AS has_rate_issue,
      COALESCE(tf2.has_pay_channel_issue, FALSE) AS has_pay_channel_issue,
      tf2.hr_crosscheck_status AS hr_crosscheck_status,
      tf2.hr_crosscheck_issues AS hr_crosscheck_issues,
      tf2.external_source_rows_json AS external_source_rows_json,
      ts0.reference_number AS reference_number,
      ts0.day_references_json AS day_references_json,
      ts0.actual_schedule_json AS actual_schedule_json,
      ts0.r2_nurse_key AS r2_nurse_key,
      ts0.r2_auth_key AS r2_auth_key,
      ts0.manual_pdf_r2_key AS manual_pdf_r2_key,
      COALESCE(
        CASE WHEN ct0.overrideclientsettings THEN ct0.require_reference_to_pay ELSE NULL::boolean END,
        ch0.pay_reference_required,
        FALSE
      ) AS require_reference_to_pay,
      COALESCE(
        CASE WHEN ct0.overrideclientsettings THEN ct0.require_reference_to_invoice ELSE NULL::boolean END,
        ch0.invoice_reference_required,
        FALSE
      ) AS require_reference_to_invoice,
      COALESCE(ev1.evidence_count, 0) AS evidence_count,
      COALESCE(ev1.has_timesheet_evidence, FALSE) AS has_timesheet_evidence,
      COALESCE(ev1.has_mileage_evidence, FALSE) AS has_mileage_evidence,
      COALESCE(ev1.has_travel_evidence, FALSE) AS has_travel_evidence,
      COALESCE(ev1.has_accommodation_evidence, FALSE) AS has_accommodation_evidence,
      COALESCE(ev1.has_other_evidence, FALSE) AS has_other_evidence,
      ts0.candidate_hint_text AS candidate_hint_text,
      tf2.expenses_pay_ex_vat AS expenses_pay_ex_vat,
      tf2.expenses_description AS expenses_description,
      tf2.mileage_units AS mileage_units,
      tf2.mileage_pay_rate AS mileage_pay_rate,
      tf2.mileage_charge_rate AS mileage_charge_rate,
      tf2.mileage_pay_ex_vat AS mileage_pay_ex_vat,
      tf2.mileage_charge_ex_vat AS mileage_charge_ex_vat,
      tf2.travel_pay_ex_vat AS travel_pay_ex_vat,
      tf2.travel_charge_ex_vat AS travel_charge_ex_vat,
      tf2.accommodation_pay_ex_vat AS accommodation_pay_ex_vat,
      tf2.accommodation_charge_ex_vat AS accommodation_charge_ex_vat,
      tf2.other_pay_ex_vat AS other_pay_ex_vat,
      tf2.other_charge_ex_vat AS other_charge_ex_vat,
      tf2.invoice_breakdown_json AS invoice_breakdown_json
    FROM timesheet_scope_rows AS ts_scope
    JOIN public.timesheets AS ts0
      ON ts0.timesheet_id = ts_scope.timesheet_id
     AND ts0.is_current = TRUE
    LEFT JOIN public.contract_weeks AS cw0
      ON cw0.id = ts_scope.contract_week_id
    LEFT JOIN public.contracts AS ct0
      ON ct0.id = COALESCE(ts0.contract_id, cw0.contract_id)
    LEFT JOIN tf_latest AS tf2
      ON tf2.timesheet_id = ts0.timesheet_id
    LEFT JOIN tv_latest AS tv2
      ON tv2.timesheet_id = ts0.timesheet_id
    LEFT JOIN evidence_agg AS ev1
      ON ev1.timesheet_id = ts0.timesheet_id
    LEFT JOIN nhsp_agg AS ns1
      ON ns1.timesheet_id = ts0.timesheet_id
    LEFT JOIN pay_adjustments_agg AS pa1
      ON pa1.timesheet_id = ts0.timesheet_id
    LEFT JOIN public.candidates AS cand0
      ON cand0.id = COALESCE(tf2.candidate_id, ct0.candidate_id)
    LEFT JOIN public.clients AS cli0
      ON cli0.id = COALESCE(tf2.client_id, ct0.client_id)
    LEFT JOIN client_hr AS ch0
      ON ch0.client_id = COALESCE(tf2.client_id, ct0.client_id)
  ),
  planned_week_rows AS MATERIALIZED (
    SELECT
      NULL::uuid AS timesheet_id,
      NULL::public.timesheet_status_enum AS timesheet_status,
      cw0.week_ending_date AS week_ending_date,
      NULL::text AS booking_id,
      NULL::text AS occupant_key_norm,
      NULL::text AS hospital_norm,
      'WEEKLY'::public.timesheet_scope_enum AS sheet_scope,
      cw0.submission_mode_snapshot AS submission_mode,
      NULL::timestamp with time zone AS authorised_at_server,
      ct0.candidate_id AS candidate_id,
      ct0.client_id AS client_id,
      NULL::text AS pay_method,
      NULL::public.ts_fin_processing_status_enum AS processing_status,
      NULL::public.timesheet_fin_basis_enum AS basis,
      ROUND(
        (
          CASE WHEN NULLIF(BTRIM(COALESCE(cw0.totals_json #>> '{hours,day}', '')), '') ~ v_numeric_re THEN (cw0.totals_json #>> '{hours,day}')::numeric ELSE 0::numeric END
          + CASE WHEN NULLIF(BTRIM(COALESCE(cw0.totals_json #>> '{hours,night}', '')), '') ~ v_numeric_re THEN (cw0.totals_json #>> '{hours,night}')::numeric ELSE 0::numeric END
          + CASE WHEN NULLIF(BTRIM(COALESCE(cw0.totals_json #>> '{hours,sat}', '')), '') ~ v_numeric_re THEN (cw0.totals_json #>> '{hours,sat}')::numeric ELSE 0::numeric END
          + CASE WHEN NULLIF(BTRIM(COALESCE(cw0.totals_json #>> '{hours,sun}', '')), '') ~ v_numeric_re THEN (cw0.totals_json #>> '{hours,sun}')::numeric ELSE 0::numeric END
          + CASE WHEN NULLIF(BTRIM(COALESCE(cw0.totals_json #>> '{hours,bh}', '')), '') ~ v_numeric_re THEN (cw0.totals_json #>> '{hours,bh}')::numeric ELSE 0::numeric END
        ),
        2
      ) AS total_hours,
      NULL::numeric AS total_pay_ex_vat,
      NULL::numeric AS total_charge_ex_vat,
      NULL::numeric AS margin_ex_vat,
      NULL::timestamp with time zone AS paid_at_utc,
      FALSE AS pay_on_hold,
      NULL::uuid AS locked_by_invoice_id,
      cand0.display_name AS candidate_name,
      cli0.name AS client_name,
      0::integer AS nhsp_shift_count,
      0::integer AS nhsp_shift_included_count,
      0::integer AS nhsp_shift_deferred_count,
      NULL::public.validation_status_enum AS validation_status,
      cw0.id AS contract_week_id,
      cw0.week_ending_date AS contract_week_ending_date,
      cw0.status AS contract_week_status,
      cw0.additional_seq AS additional_seq,
      cw0.is_adjustment AS is_adjustment,
      NULL::public.timesheet_qr_status_enum AS qr_status,
      NULL::text AS qr_token,
      NULL::timestamp with time zone AS qr_generated_at,
      NULL::timestamp with time zone AS qr_scanned_at,
      NULL::text AS qr_last_sent_hash,
      0::integer AS pay_adjustment_count,
      COALESCE(
        CASE WHEN ct0.overrideclientsettings THEN ct0.autoprocess_hr ELSE NULL::boolean END,
        ch0.autoprocess_hr,
        FALSE
      ) AS client_autoprocess_hr,
      COALESCE(
        CASE WHEN ct0.overrideclientsettings THEN ct0.requires_hr ELSE NULL::boolean END,
        ch0.requires_hr,
        FALSE
      ) AS client_requires_hr,
      COALESCE(
        CASE WHEN ct0.overrideclientsettings THEN ct0.no_timesheet_required ELSE NULL::boolean END,
        ch0.no_timesheet_required,
        FALSE
      ) AS client_no_timesheet_required,
      COALESCE(ch0.pay_reference_required, FALSE) AS client_pay_reference_required,
      COALESCE(ch0.invoice_reference_required, FALSE) AS client_invoice_reference_required,
      COALESCE(
        CASE WHEN ct0.overrideclientsettings THEN ct0.requires_hr ELSE NULL::boolean END,
        ch0.hr_validation_required,
        FALSE
      ) AS client_hr_validation_required,
      COALESCE(ch0.ts_reference_required, FALSE) AS client_ts_reference_required,
      COALESCE(
        CASE WHEN ct0.overrideclientsettings THEN ct0.is_nhsp ELSE NULL::boolean END,
        ch0.is_nhsp,
        FALSE
      ) AS client_is_nhsp,
      FALSE AS has_rate_issue,
      FALSE AS has_pay_channel_issue,
      NULL::text AS hr_crosscheck_status,
      NULL::text[] AS hr_crosscheck_issues,
      NULL::jsonb AS external_source_rows_json,
      NULL::text AS reference_number,
      NULL::jsonb AS day_references_json,
      NULL::jsonb AS actual_schedule_json,
      NULL::text AS r2_nurse_key,
      NULL::text AS r2_auth_key,
      NULL::text AS manual_pdf_r2_key,
      COALESCE(
        CASE WHEN ct0.overrideclientsettings THEN ct0.require_reference_to_pay ELSE NULL::boolean END,
        ch0.pay_reference_required,
        FALSE
      ) AS require_reference_to_pay,
      COALESCE(
        CASE WHEN ct0.overrideclientsettings THEN ct0.require_reference_to_invoice ELSE NULL::boolean END,
        ch0.invoice_reference_required,
        FALSE
      ) AS require_reference_to_invoice,
      0::integer AS evidence_count,
      FALSE AS has_timesheet_evidence,
      FALSE AS has_mileage_evidence,
      FALSE AS has_travel_evidence,
      FALSE AS has_accommodation_evidence,
      FALSE AS has_other_evidence,
      NULL::jsonb AS candidate_hint_text,
      NULL::numeric AS expenses_pay_ex_vat,
      NULL::text AS expenses_description,
      NULL::numeric AS mileage_units,
      NULL::numeric AS mileage_pay_rate,
      NULL::numeric AS mileage_charge_rate,
      NULL::numeric AS mileage_pay_ex_vat,
      NULL::numeric AS mileage_charge_ex_vat,
      NULL::numeric AS travel_pay_ex_vat,
      NULL::numeric AS travel_charge_ex_vat,
      NULL::numeric AS accommodation_pay_ex_vat,
      NULL::numeric AS accommodation_charge_ex_vat,
      NULL::numeric AS other_pay_ex_vat,
      NULL::numeric AS other_charge_ex_vat,
      NULL::jsonb AS invoice_breakdown_json
    FROM contract_week_scope_rows AS cw_scope
    JOIN public.contract_weeks AS cw0
      ON cw0.id = cw_scope.contract_week_id
    JOIN public.contracts AS ct0
      ON ct0.id = cw0.contract_id
    LEFT JOIN public.candidates AS cand0
      ON cand0.id = ct0.candidate_id
    LEFT JOIN public.clients AS cli0
      ON cli0.id = ct0.client_id
    LEFT JOIN client_hr AS ch0
      ON ch0.client_id = ct0.client_id
  ),
  base_union AS MATERIALIZED (
    SELECT
      tr0.timesheet_id,
      tr0.timesheet_status,
      tr0.week_ending_date,
      tr0.booking_id,
      tr0.occupant_key_norm,
      tr0.hospital_norm,
      tr0.sheet_scope,
      tr0.submission_mode,
      tr0.authorised_at_server,
      tr0.candidate_id,
      tr0.client_id,
      tr0.pay_method,
      tr0.processing_status,
      tr0.basis,
      tr0.total_hours,
      tr0.total_pay_ex_vat,
      tr0.total_charge_ex_vat,
      tr0.margin_ex_vat,
      tr0.paid_at_utc,
      tr0.pay_on_hold,
      tr0.locked_by_invoice_id,
      tr0.candidate_name,
      tr0.client_name,
      tr0.nhsp_shift_count,
      tr0.nhsp_shift_included_count,
      tr0.nhsp_shift_deferred_count,
      tr0.validation_status,
      tr0.contract_week_id,
      tr0.contract_week_ending_date,
      tr0.contract_week_status,
      tr0.additional_seq,
      tr0.is_adjustment,
      tr0.qr_status,
      tr0.qr_token,
      tr0.qr_generated_at,
      tr0.qr_scanned_at,
      tr0.qr_last_sent_hash,
      tr0.pay_adjustment_count,
      tr0.client_autoprocess_hr,
      tr0.client_requires_hr,
      tr0.client_no_timesheet_required,
      tr0.client_pay_reference_required,
      tr0.client_invoice_reference_required,
      tr0.client_hr_validation_required,
      tr0.client_ts_reference_required,
      tr0.client_is_nhsp,
      tr0.has_rate_issue,
      tr0.has_pay_channel_issue,
      tr0.hr_crosscheck_status,
      tr0.hr_crosscheck_issues,
      tr0.external_source_rows_json,
      tr0.reference_number,
      tr0.day_references_json,
      tr0.actual_schedule_json,
      tr0.r2_nurse_key,
      tr0.r2_auth_key,
      tr0.manual_pdf_r2_key,
      tr0.require_reference_to_pay,
      tr0.require_reference_to_invoice,
      tr0.evidence_count,
      tr0.has_timesheet_evidence,
      tr0.has_mileage_evidence,
      tr0.has_travel_evidence,
      tr0.has_accommodation_evidence,
      tr0.has_other_evidence,
      tr0.candidate_hint_text,
      tr0.expenses_pay_ex_vat,
      tr0.expenses_description,
      tr0.mileage_units,
      tr0.mileage_pay_rate,
      tr0.mileage_charge_rate,
      tr0.mileage_pay_ex_vat,
      tr0.mileage_charge_ex_vat,
      tr0.travel_pay_ex_vat,
      tr0.travel_charge_ex_vat,
      tr0.accommodation_pay_ex_vat,
      tr0.accommodation_charge_ex_vat,
      tr0.other_pay_ex_vat,
      tr0.other_charge_ex_vat,
      tr0.invoice_breakdown_json
    FROM timesheet_rows AS tr0
    UNION ALL
    SELECT
      pwr0.timesheet_id,
      pwr0.timesheet_status,
      pwr0.week_ending_date,
      pwr0.booking_id,
      pwr0.occupant_key_norm,
      pwr0.hospital_norm,
      pwr0.sheet_scope,
      pwr0.submission_mode,
      pwr0.authorised_at_server,
      pwr0.candidate_id,
      pwr0.client_id,
      pwr0.pay_method,
      pwr0.processing_status,
      pwr0.basis,
      pwr0.total_hours,
      pwr0.total_pay_ex_vat,
      pwr0.total_charge_ex_vat,
      pwr0.margin_ex_vat,
      pwr0.paid_at_utc,
      pwr0.pay_on_hold,
      pwr0.locked_by_invoice_id,
      pwr0.candidate_name,
      pwr0.client_name,
      pwr0.nhsp_shift_count,
      pwr0.nhsp_shift_included_count,
      pwr0.nhsp_shift_deferred_count,
      pwr0.validation_status,
      pwr0.contract_week_id,
      pwr0.contract_week_ending_date,
      pwr0.contract_week_status,
      pwr0.additional_seq,
      pwr0.is_adjustment,
      pwr0.qr_status,
      pwr0.qr_token,
      pwr0.qr_generated_at,
      pwr0.qr_scanned_at,
      pwr0.qr_last_sent_hash,
      pwr0.pay_adjustment_count,
      pwr0.client_autoprocess_hr,
      pwr0.client_requires_hr,
      pwr0.client_no_timesheet_required,
      pwr0.client_pay_reference_required,
      pwr0.client_invoice_reference_required,
      pwr0.client_hr_validation_required,
      pwr0.client_ts_reference_required,
      pwr0.client_is_nhsp,
      pwr0.has_rate_issue,
      pwr0.has_pay_channel_issue,
      pwr0.hr_crosscheck_status,
      pwr0.hr_crosscheck_issues,
      pwr0.external_source_rows_json,
      pwr0.reference_number,
      pwr0.day_references_json,
      pwr0.actual_schedule_json,
      pwr0.r2_nurse_key,
      pwr0.r2_auth_key,
      pwr0.manual_pdf_r2_key,
      pwr0.require_reference_to_pay,
      pwr0.require_reference_to_invoice,
      pwr0.evidence_count,
      pwr0.has_timesheet_evidence,
      pwr0.has_mileage_evidence,
      pwr0.has_travel_evidence,
      pwr0.has_accommodation_evidence,
      pwr0.has_other_evidence,
      pwr0.candidate_hint_text,
      pwr0.expenses_pay_ex_vat,
      pwr0.expenses_description,
      pwr0.mileage_units,
      pwr0.mileage_pay_rate,
      pwr0.mileage_charge_rate,
      pwr0.mileage_pay_ex_vat,
      pwr0.mileage_charge_ex_vat,
      pwr0.travel_pay_ex_vat,
      pwr0.travel_charge_ex_vat,
      pwr0.accommodation_pay_ex_vat,
      pwr0.accommodation_charge_ex_vat,
      pwr0.other_pay_ex_vat,
      pwr0.other_charge_ex_vat,
      pwr0.invoice_breakdown_json
    FROM planned_week_rows AS pwr0
  ),
  issue_rows AS MATERIALIZED (
    SELECT
      bu0.*,
      (
        ARRAY[]::text[]
        || CASE
             WHEN COALESCE(bu0.has_rate_issue, FALSE) = TRUE OR bu0.processing_status = 'RATE_MISSING'::public.ts_fin_processing_status_enum THEN ARRAY['Rate'::text]
             ELSE ARRAY[]::text[]
           END
        || CASE
             WHEN COALESCE(bu0.has_pay_channel_issue, FALSE) = TRUE OR bu0.processing_status = 'PAY_CHANNEL_MISSING'::public.ts_fin_processing_status_enum THEN ARRAY['Pay channel'::text]
             ELSE ARRAY[]::text[]
           END
        || CASE
             WHEN bu0.processing_status = 'UNASSIGNED'::public.ts_fin_processing_status_enum THEN ARRAY['Candidate ID'::text]
             WHEN bu0.processing_status = 'CLIENT_UNRESOLVED'::public.ts_fin_processing_status_enum THEN ARRAY['Client ID'::text]
             ELSE ARRAY[]::text[]
           END
        || CASE
             WHEN COALESCE(bu0.pay_on_hold, FALSE) = TRUE THEN ARRAY['On hold'::text]
             ELSE ARRAY[]::text[]
           END
        || CASE
             WHEN NOT (
                    bu0.timesheet_id IS NOT NULL
                    AND COALESCE(bu0.client_hr_validation_required, FALSE) = TRUE
                    AND COALESCE(bu0.client_no_timesheet_required, FALSE) = FALSE
                    AND COALESCE(bu0.total_hours, 0::numeric) > 0::numeric
                  )
              AND (
                    bu0.hr_crosscheck_status = 'HOURS_MISMATCH_HR'
                    OR COALESCE(bu0.hr_crosscheck_issues, ARRAY[]::text[]) && ARRAY['HOURS_MISMATCH_HR'::text]
                  ) THEN ARRAY['Hours mismatch HR'::text]
             ELSE ARRAY[]::text[]
           END
        || CASE
             WHEN NOT (
                    bu0.timesheet_id IS NOT NULL
                    AND COALESCE(bu0.client_hr_validation_required, FALSE) = TRUE
                    AND COALESCE(bu0.client_no_timesheet_required, FALSE) = FALSE
                    AND COALESCE(bu0.total_hours, 0::numeric) > 0::numeric
                  )
              AND COALESCE(bu0.hr_crosscheck_issues, ARRAY[]::text[]) && ARRAY['HR_HOURS_MISSING'::text] THEN ARRAY['HR hours missing'::text]
             ELSE ARRAY[]::text[]
           END
        || CASE
             WHEN COALESCE(bu0.hr_crosscheck_issues, ARRAY[]::text[]) && ARRAY['DUPLICATE_CONTRACTS'::text] THEN ARRAY['Duplicate contracts'::text]
             ELSE ARRAY[]::text[]
           END

        || CASE
             WHEN bu0.timesheet_id IS NOT NULL
              AND (
                    COALESCE(bu0.travel_charge_ex_vat, 0::numeric) > 0::numeric
                    OR COALESCE(bu0.travel_pay_ex_vat, 0::numeric) > 0::numeric
                    OR COALESCE(bu0.accommodation_charge_ex_vat, 0::numeric) > 0::numeric
                    OR COALESCE(bu0.accommodation_pay_ex_vat, 0::numeric) > 0::numeric
                    OR COALESCE(bu0.other_charge_ex_vat, 0::numeric) > 0::numeric
                    OR COALESCE(bu0.other_pay_ex_vat, 0::numeric) > 0::numeric
                  )
              AND (
                    ((COALESCE(bu0.travel_charge_ex_vat, 0::numeric) > 0::numeric OR COALESCE(bu0.travel_pay_ex_vat, 0::numeric) > 0::numeric) AND COALESCE(bu0.has_travel_evidence, FALSE) = FALSE)
                    OR ((COALESCE(bu0.accommodation_charge_ex_vat, 0::numeric) > 0::numeric OR COALESCE(bu0.accommodation_pay_ex_vat, 0::numeric) > 0::numeric) AND COALESCE(bu0.has_accommodation_evidence, FALSE) = FALSE)
                    OR ((COALESCE(bu0.other_charge_ex_vat, 0::numeric) > 0::numeric OR COALESCE(bu0.other_pay_ex_vat, 0::numeric) > 0::numeric) AND COALESCE(bu0.has_other_evidence, FALSE) = FALSE)
                  ) THEN ARRAY['Expenses evidence'::text]
             ELSE ARRAY[]::text[]
           END
        || CASE
             WHEN bu0.timesheet_id IS NOT NULL
              AND (
                    COALESCE(bu0.mileage_units, 0::numeric) > 0::numeric
                    OR COALESCE(bu0.mileage_charge_ex_vat, 0::numeric) > 0::numeric
                    OR COALESCE(bu0.mileage_pay_ex_vat, 0::numeric) > 0::numeric
                  )
              AND COALESCE(bu0.has_mileage_evidence, FALSE) = FALSE THEN ARRAY['Mileage evidence'::text]
             ELSE ARRAY[]::text[]
           END


        || CASE
             WHEN bu0.timesheet_id IS NOT NULL
              AND COALESCE(bu0.client_hr_validation_required, FALSE) = TRUE
              AND COALESCE(bu0.client_no_timesheet_required, FALSE) = FALSE
              AND COALESCE(bu0.total_hours, 0::numeric) > 0::numeric
              AND (bu0.validation_status IS NULL OR bu0.validation_status = 'PENDING'::public.validation_status_enum) THEN ARRAY['Awaiting validation'::text]
             WHEN bu0.timesheet_id IS NOT NULL
              AND COALESCE(bu0.client_hr_validation_required, FALSE) = TRUE
              AND COALESCE(bu0.client_no_timesheet_required, FALSE) = FALSE
              AND COALESCE(bu0.total_hours, 0::numeric) > 0::numeric
              AND bu0.validation_status IS NOT NULL
              AND bu0.validation_status <> ALL (ARRAY['VALIDATION_OK'::public.validation_status_enum, 'OVERRIDDEN'::public.validation_status_enum, 'PENDING'::public.validation_status_enum]) THEN ARRAY['Validation failed'::text]
             ELSE ARRAY[]::text[]
           END
        || CASE
             WHEN bu0.timesheet_id IS NOT NULL
              AND COALESCE(bu0.client_requires_hr, FALSE) = TRUE
              AND COALESCE(bu0.client_autoprocess_hr, FALSE) = FALSE
              AND bu0.authorised_at_server IS NULL THEN ARRAY['Authorisation'::text]
             ELSE ARRAY[]::text[]
           END
      ) AS lightweight_issue_codes
    FROM base_union AS bu0
  ),
  segment_rows AS MATERIALIZED (
    SELECT
      ir0.*,
      segment_stats.seg_total AS invoice_segments_total_calc,
      segment_stats.seg_locked AS invoice_segments_locked_calc,
      COALESCE(invoice_paid_stats.invoice_paid_any, FALSE) AS invoice_is_paid_calc
    FROM issue_rows AS ir0
    LEFT JOIN LATERAL (
      SELECT
        CASE
          WHEN ir0.timesheet_id IS NULL THEN NULL::integer
          WHEN ir0.invoice_breakdown_json IS NOT NULL
           AND jsonb_typeof(ir0.invoice_breakdown_json) = 'object'
           AND UPPER(COALESCE(ir0.invoice_breakdown_json->>'mode', '')) = 'SEGMENTS'
           AND jsonb_typeof(ir0.invoice_breakdown_json->'segments') = 'array' THEN jsonb_array_length(ir0.invoice_breakdown_json->'segments')::integer
          ELSE 1::integer
        END AS seg_total,
        CASE
          WHEN ir0.timesheet_id IS NULL THEN NULL::integer
          WHEN ir0.invoice_breakdown_json IS NOT NULL
           AND jsonb_typeof(ir0.invoice_breakdown_json) = 'object'
           AND UPPER(COALESCE(ir0.invoice_breakdown_json->>'mode', '')) = 'SEGMENTS'
           AND jsonb_typeof(ir0.invoice_breakdown_json->'segments') = 'array' THEN (
             SELECT COUNT(*)::integer
             FROM jsonb_array_elements(ir0.invoice_breakdown_json->'segments') AS lock_segment(segment_value)
             WHERE NULLIF(BTRIM(COALESCE(lock_segment.segment_value->>'invoice_locked_invoice_id', '')), '') IS NOT NULL
           )
          ELSE CASE WHEN ir0.locked_by_invoice_id IS NULL THEN 0::integer ELSE 1::integer END
        END AS seg_locked
    ) AS segment_stats
      ON TRUE
    LEFT JOIN LATERAL (
      SELECT
        CASE
          WHEN ir0.timesheet_id IS NULL THEN FALSE
          WHEN ir0.invoice_breakdown_json IS NOT NULL
           AND jsonb_typeof(ir0.invoice_breakdown_json) = 'object'
           AND UPPER(COALESCE(ir0.invoice_breakdown_json->>'mode', '')) = 'SEGMENTS'
           AND jsonb_typeof(ir0.invoice_breakdown_json->'segments') = 'array' THEN EXISTS (
             SELECT 1
             FROM jsonb_array_elements(ir0.invoice_breakdown_json->'segments') AS paid_segment(segment_value)
             JOIN public.invoices AS inv2
               ON inv2.id = CASE
                 WHEN NULLIF(BTRIM(COALESCE(paid_segment.segment_value->>'invoice_locked_invoice_id', '')), '') ~* v_uuid_re THEN (paid_segment.segment_value->>'invoice_locked_invoice_id')::uuid
                 ELSE NULL::uuid
               END
             WHERE inv2.status = 'PAID'::public.invoice_status_enum
                OR inv2.paid_at_utc IS NOT NULL
           )
          ELSE EXISTS (
             SELECT 1
             FROM public.invoices AS inv3
             WHERE inv3.id = ir0.locked_by_invoice_id
               AND (inv3.status = 'PAID'::public.invoice_status_enum OR inv3.paid_at_utc IS NOT NULL)
           )
        END AS invoice_paid_any
    ) AS invoice_paid_stats
      ON TRUE
  ),
  issue_normalised_rows AS MATERIALIZED (
    SELECT
      sr0.*,
      COALESCE(sr0.lightweight_issue_codes, ARRAY[]::text[]) AS workbench_issue_codes
    FROM segment_rows AS sr0
  ),
  result_rows AS MATERIALIZED (
    SELECT
      sr0.timesheet_id,
      sr0.timesheet_status,
      sr0.week_ending_date,
      sr0.booking_id,
      sr0.occupant_key_norm,
      sr0.hospital_norm,
      sr0.sheet_scope,
      sr0.submission_mode,
      sr0.authorised_at_server,
      sr0.candidate_id,
      sr0.client_id,
      sr0.pay_method,
      sr0.processing_status,
      sr0.basis,
      sr0.total_hours,
      sr0.total_pay_ex_vat,
      sr0.total_charge_ex_vat,
      sr0.margin_ex_vat,
      sr0.paid_at_utc,
      sr0.pay_on_hold,
      FALSE AS ready_to_pay,
      sr0.locked_by_invoice_id,
      sr0.candidate_name,
      sr0.client_name,
      sr0.nhsp_shift_count,
      sr0.nhsp_shift_included_count,
      sr0.nhsp_shift_deferred_count,
      sr0.validation_status,
      CASE
        WHEN sr0.timesheet_id IS NOT NULL
         AND EXISTS (
           SELECT 1
           FROM public.timesheets AS archived_timesheet
           WHERE archived_timesheet.timesheet_id = sr0.timesheet_id
             AND archived_timesheet.archived_at_utc IS NOT NULL
         ) THEN 'ARCHIVED'
        WHEN sr0.timesheet_id IS NULL THEN CASE sr0.contract_week_status
          WHEN 'PLANNED'::public.contract_week_status_enum THEN 'PLANNED'
          WHEN 'OPEN'::public.contract_week_status_enum THEN 'PLANNED'
          WHEN 'SUBMITTED'::public.contract_week_status_enum THEN 'PENDING_AUTH'
          WHEN 'AUTHORISED'::public.contract_week_status_enum THEN 'READY_FOR_INVOICE'
          WHEN 'INVOICED'::public.contract_week_status_enum THEN 'INVOICED'
          WHEN 'CANCELLED'::public.contract_week_status_enum THEN 'NEEDS_ATTENTION'
          ELSE 'UNKNOWN'
        END
        WHEN sr0.paid_at_utc IS NOT NULL THEN 'PAID'
        WHEN sr0.locked_by_invoice_id IS NOT NULL
          OR (
            sr0.invoice_segments_total_calc IS NOT NULL
            AND sr0.invoice_segments_total_calc > 0
            AND COALESCE(sr0.invoice_segments_locked_calc, 0) >= sr0.invoice_segments_total_calc
          ) THEN 'INVOICED'
        WHEN sr0.processing_status = 'READY_FOR_INVOICE'::public.ts_fin_processing_status_enum THEN 'READY_FOR_INVOICE'
        WHEN sr0.processing_status = 'READY_FOR_HR'::public.ts_fin_processing_status_enum THEN 'READY_FOR_HR'
        WHEN sr0.processing_status = 'PENDING_AUTH'::public.ts_fin_processing_status_enum THEN 'PENDING_AUTH'
        WHEN sr0.processing_status = 'UNPROCESSED'::public.ts_fin_processing_status_enum THEN 'UNPROCESSED'
        WHEN sr0.processing_status = ANY (ARRAY['UNASSIGNED'::public.ts_fin_processing_status_enum, 'CLIENT_UNRESOLVED'::public.ts_fin_processing_status_enum, 'RATE_MISSING'::public.ts_fin_processing_status_enum, 'PAY_CHANNEL_MISSING'::public.ts_fin_processing_status_enum]) THEN 'NEEDS_ATTENTION'
        ELSE 'UNKNOWN'
      END AS summary_stage,
      CASE
        WHEN sr0.sheet_scope = 'DAILY'::public.timesheet_scope_enum AND sr0.submission_mode = 'ELECTRONIC'::public.submission_mode_enum THEN 'DAILY_ELECTRONIC'
        WHEN sr0.sheet_scope = 'DAILY'::public.timesheet_scope_enum AND sr0.submission_mode = 'MANUAL'::public.submission_mode_enum THEN 'DAILY_MANUAL'
        WHEN sr0.sheet_scope = 'WEEKLY'::public.timesheet_scope_enum
         AND sr0.submission_mode = 'MANUAL'::public.submission_mode_enum
         AND (
           COALESCE(sr0.is_adjustment, FALSE) = TRUE
           OR COALESCE(sr0.additional_seq, 0) > 0
           OR COALESCE(sr0.pay_adjustment_count, 0) > 0
           OR UPPER(COALESCE(sr0.basis::text, '')) IN ('NHSP_ADJUSTMENT', 'HEALTHROSTER_ADJUSTMENT', 'MANUAL_ADJUSTMENT')
         )
         AND (
           COALESCE(sr0.client_is_nhsp, FALSE) = TRUE
           OR UPPER(COALESCE(sr0.basis::text, '')) IN ('NHSP', 'NHSP_ADJUSTMENT')
         ) THEN 'WEEKLY_NHSP_ADJUSTMENT'
        WHEN sr0.sheet_scope = 'WEEKLY'::public.timesheet_scope_enum
         AND sr0.submission_mode = 'MANUAL'::public.submission_mode_enum
         AND (
           COALESCE(sr0.is_adjustment, FALSE) = TRUE
           OR COALESCE(sr0.additional_seq, 0) > 0
           OR COALESCE(sr0.pay_adjustment_count, 0) > 0
           OR UPPER(COALESCE(sr0.basis::text, '')) IN ('NHSP_ADJUSTMENT', 'HEALTHROSTER_ADJUSTMENT', 'MANUAL_ADJUSTMENT')
         )
         AND (
           COALESCE(sr0.client_autoprocess_hr, FALSE) = TRUE
           OR UPPER(COALESCE(sr0.basis::text, '')) IN ('HEALTHROSTER_ADJUSTMENT', 'HEALTHROSTER_SELF_BILL')
         ) THEN 'WEEKLY_HEALTHROSTER_ADJUSTMENT'
        WHEN sr0.sheet_scope = 'WEEKLY'::public.timesheet_scope_enum
         AND sr0.submission_mode = 'MANUAL'::public.submission_mode_enum
         AND (
           COALESCE(sr0.is_adjustment, FALSE) = TRUE
           OR COALESCE(sr0.additional_seq, 0) > 0
           OR COALESCE(sr0.pay_adjustment_count, 0) > 0
           OR UPPER(COALESCE(sr0.basis::text, '')) IN ('NHSP_ADJUSTMENT', 'HEALTHROSTER_ADJUSTMENT', 'MANUAL_ADJUSTMENT')
         ) THEN 'WEEKLY_MANUAL_ADJUSTMENT'
        WHEN sr0.sheet_scope = 'WEEKLY'::public.timesheet_scope_enum AND COALESCE(sr0.client_autoprocess_hr, FALSE) = TRUE THEN 'WEEKLY_HEALTHROSTER'
        WHEN sr0.sheet_scope = 'WEEKLY'::public.timesheet_scope_enum AND sr0.basis = 'NHSP_ADJUSTMENT'::public.timesheet_fin_basis_enum THEN 'WEEKLY_NHSP_ADJUSTMENT'
        WHEN sr0.sheet_scope = 'WEEKLY'::public.timesheet_scope_enum AND sr0.basis = 'NHSP'::public.timesheet_fin_basis_enum THEN 'WEEKLY_NHSP'
        WHEN sr0.sheet_scope = 'WEEKLY'::public.timesheet_scope_enum AND COALESCE(sr0.client_is_nhsp, FALSE) = TRUE THEN 'WEEKLY_NHSP'
        WHEN sr0.sheet_scope = 'WEEKLY'::public.timesheet_scope_enum AND sr0.submission_mode = 'ELECTRONIC'::public.submission_mode_enum THEN 'WEEKLY_ELECTRONIC'
        WHEN sr0.sheet_scope = 'WEEKLY'::public.timesheet_scope_enum AND sr0.submission_mode = 'MANUAL'::public.submission_mode_enum THEN 'WEEKLY_MANUAL'
        ELSE 'UNKNOWN'
      END AS route_type,
      sr0.contract_week_id,
      sr0.contract_week_ending_date,
      sr0.contract_week_status,
      sr0.additional_seq,
      sr0.is_adjustment,
      sr0.qr_status,
      sr0.pay_adjustment_count,
      (COALESCE(sr0.pay_adjustment_count, 0) > 0) AS has_pay_adjustments,
      (COALESCE(sr0.is_adjustment, FALSE) OR COALESCE(sr0.pay_adjustment_count, 0) > 0) AS is_adjusted,
      (sr0.qr_status IS NOT NULL) AS is_qr,
      (
        sr0.processing_status = ANY (ARRAY['UNASSIGNED'::public.ts_fin_processing_status_enum, 'CLIENT_UNRESOLVED'::public.ts_fin_processing_status_enum, 'RATE_MISSING'::public.ts_fin_processing_status_enum, 'PAY_CHANNEL_MISSING'::public.ts_fin_processing_status_enum])
        OR (
          NOT (
            sr0.timesheet_id IS NOT NULL
            AND COALESCE(sr0.client_hr_validation_required, FALSE) = TRUE
            AND COALESCE(sr0.client_no_timesheet_required, FALSE) = FALSE
            AND COALESCE(sr0.total_hours, 0::numeric) > 0::numeric
          )
          AND sr0.hr_crosscheck_status IS NOT NULL
          AND sr0.hr_crosscheck_status <> 'OK'
        )
        OR (
          NOT (
            sr0.timesheet_id IS NOT NULL
            AND COALESCE(sr0.client_hr_validation_required, FALSE) = TRUE
            AND COALESCE(sr0.client_no_timesheet_required, FALSE) = FALSE
            AND COALESCE(sr0.total_hours, 0::numeric) > 0::numeric
          )
          AND COALESCE(sr0.hr_crosscheck_issues, ARRAY[]::text[]) && ARRAY['DUPLICATE_CONTRACTS'::text]
        )
        OR COALESCE(array_length(sr0.workbench_issue_codes, 1), 0) > 0
      ) AS needs_attention,
      sr0.client_autoprocess_hr,
      sr0.has_rate_issue,
      sr0.has_pay_channel_issue,
      sr0.hr_crosscheck_status,
      sr0.hr_crosscheck_issues,
      sr0.external_source_rows_json,
      COALESCE(sr0.workbench_issue_codes, ARRAY[]::text[]) AS issue_codes,
      sr0.client_requires_hr,
      sr0.client_no_timesheet_required,
      sr0.client_is_nhsp,
      sr0.client_pay_reference_required,
      sr0.client_invoice_reference_required,
      sr0.client_hr_validation_required,
      sr0.client_ts_reference_required,
      sr0.require_reference_to_pay,
      sr0.require_reference_to_invoice,
      sr0.qr_token,
      sr0.qr_generated_at,
      sr0.qr_scanned_at,
      sr0.candidate_hint_text,
      sr0.expenses_pay_ex_vat,
      sr0.expenses_description,
      sr0.mileage_units,
      sr0.mileage_pay_rate,
      sr0.mileage_charge_rate,
      sr0.mileage_pay_ex_vat,
      sr0.travel_pay_ex_vat,
      sr0.travel_charge_ex_vat,
      sr0.accommodation_pay_ex_vat,
      sr0.accommodation_charge_ex_vat,
      sr0.other_pay_ex_vat,
      sr0.other_charge_ex_vat,
      (
        sr0.timesheet_id IS NOT NULL
        AND COALESCE(sr0.client_hr_validation_required, FALSE) = TRUE
        AND COALESCE(sr0.client_no_timesheet_required, FALSE) = FALSE
        AND COALESCE(sr0.total_hours, 0::numeric) > 0::numeric
      ) AS hr_validation_required_for_invoice,
      sr0.invoice_segments_total_calc AS invoice_segments_total,
      sr0.invoice_segments_locked_calc AS invoice_segments_locked,
      CASE
        WHEN sr0.invoice_segments_total_calc IS NULL THEN NULL::integer
        ELSE GREATEST(sr0.invoice_segments_total_calc - COALESCE(sr0.invoice_segments_locked_calc, 0), 0)
      END AS invoice_segments_unlocked,
      CASE
        WHEN sr0.invoice_segments_total_calc IS NULL THEN NULL::text
        WHEN COALESCE(sr0.invoice_segments_locked_calc, 0) = 0 THEN 'NOT_INVOICED'
        WHEN COALESCE(sr0.invoice_segments_locked_calc, 0) >= sr0.invoice_segments_total_calc THEN 'FULLY_INVOICED'
        ELSE 'PARTIALLY_INVOICED'
      END AS invoice_segment_stage,
      CASE
        WHEN sr0.timesheet_id IS NOT NULL
         AND EXISTS (
           SELECT 1
           FROM public.timesheets AS archived_timesheet
           WHERE archived_timesheet.timesheet_id = sr0.timesheet_id
             AND archived_timesheet.archived_at_utc IS NOT NULL
         ) THEN 'ARCHIVED'
        WHEN sr0.timesheet_id IS NULL THEN 'UNPROCESSED'
        WHEN sr0.processing_status = 'UNPROCESSED'::public.ts_fin_processing_status_enum THEN 'UNPROCESSED'
        WHEN sr0.locked_by_invoice_id IS NOT NULL OR COALESCE(sr0.invoice_segments_locked_calc, 0) > 0 THEN 'INVOICED'
        WHEN sr0.timesheet_id IS NOT NULL
         AND sr0.authorised_at_server IS NULL
         AND (
           sr0.processing_status = 'PENDING_AUTH'::public.ts_fin_processing_status_enum
           OR (
             COALESCE(sr0.client_requires_hr, FALSE) = TRUE
             AND COALESCE(sr0.client_autoprocess_hr, FALSE) = FALSE
             AND COALESCE(array_length(sr0.workbench_issue_codes, 1), 0) = 1
             AND sr0.workbench_issue_codes @> ARRAY['Authorisation'::text]
           )
         ) THEN 'PROCESSED'
        WHEN sr0.timesheet_id IS NOT NULL
         AND sr0.processing_status = 'READY_FOR_INVOICE'::public.ts_fin_processing_status_enum THEN 'AUTHORISED_FOR_INVOICING'
        ELSE 'PROCESSING_DELAYED'
      END AS tools_stage,
      CASE
        WHEN sr0.timesheet_id IS NOT NULL
         AND EXISTS (
           SELECT 1
           FROM public.timesheets AS archived_timesheet
           WHERE archived_timesheet.timesheet_id = sr0.timesheet_id
             AND archived_timesheet.archived_at_utc IS NOT NULL
         ) THEN 'Archived'
        WHEN sr0.timesheet_id IS NULL THEN 'Unprocessed'
        WHEN sr0.processing_status = 'UNPROCESSED'::public.ts_fin_processing_status_enum THEN 'Unprocessed'
        WHEN sr0.locked_by_invoice_id IS NOT NULL OR COALESCE(sr0.invoice_segments_locked_calc, 0) > 0 THEN
          CASE
            WHEN sr0.invoice_segments_total_calc IS NOT NULL
             AND COALESCE(sr0.invoice_segments_locked_calc, 0) > 0
             AND COALESCE(sr0.invoice_segments_locked_calc, 0) < sr0.invoice_segments_total_calc THEN 'Partially Invoiced'
            ELSE 'Invoiced'
          END
        WHEN sr0.timesheet_id IS NOT NULL
         AND sr0.authorised_at_server IS NULL
         AND (
           sr0.processing_status = 'PENDING_AUTH'::public.ts_fin_processing_status_enum
           OR (
             COALESCE(sr0.client_requires_hr, FALSE) = TRUE
             AND COALESCE(sr0.client_autoprocess_hr, FALSE) = FALSE
             AND COALESCE(array_length(sr0.workbench_issue_codes, 1), 0) = 1
             AND sr0.workbench_issue_codes @> ARRAY['Authorisation'::text]
           )
         ) THEN 'Processed'
        WHEN sr0.timesheet_id IS NOT NULL
         AND sr0.processing_status = 'READY_FOR_INVOICE'::public.ts_fin_processing_status_enum THEN 'Authorised for Invoicing'
        ELSE 'Processing Delayed'
      END AS processing_status_display,
      COALESCE(sr0.invoice_is_paid_calc, FALSE) AS invoice_is_paid,
      FALSE AS refs_block_invoicing,
      FALSE AS refs_block_issuing_invoices,
      FALSE AS refs_block_invoice_and_issuing,
      CASE
        WHEN COALESCE(summary_pay_cache.summary_state_applies, FALSE)
          THEN summary_pay_cache.summary_pay_icon_code
        WHEN tps.summary_pay_icon_code IS NOT NULL THEN tps.summary_pay_icon_code
        WHEN tps.summary_pay_status_code = 'PAID' THEN 'COIN'
        WHEN tps.summary_pay_status_code = 'PARTIALLY_PAID' THEN 'HALF_COIN'
        WHEN tps.summary_pay_status_code IN ('PROCESSING','ADVANCED') THEN 'CLOCK'
        WHEN tps.summary_pay_status_code = 'UNPAID' THEN 'NONE'
        WHEN tps.last_settled_at_utc IS NOT NULL OR sr0.paid_at_utc IS NOT NULL THEN 'COIN'
        ELSE 'NONE'
      END::text AS pay_icon_code,
      COALESCE(
        CASE
          WHEN COALESCE(summary_pay_cache.summary_state_applies, FALSE)
            THEN summary_pay_cache.summary_pay_status_code
          ELSE NULL
        END,
        tps.summary_pay_status_code,
        CASE
          WHEN tps.last_settled_at_utc IS NOT NULL OR sr0.paid_at_utc IS NOT NULL THEN 'PAID'
          ELSE 'UNPAID'
        END
      )::text AS pay_status_code,
      CASE
        WHEN COALESCE(summary_pay_cache.summary_state_applies, FALSE)
          THEN summary_pay_cache.last_paid_at_utc
        WHEN tps.summary_pay_status_code IS NOT NULL OR tps.summary_pay_icon_code IS NOT NULL THEN tps.summary_pay_paid_at_utc
        ELSE COALESCE(tps.last_settled_at_utc, sr0.paid_at_utc)
      END AS pay_paid_at_utc,
      COALESCE(
        CASE
          WHEN COALESCE(summary_pay_cache.summary_state_applies, FALSE)
            THEN summary_pay_cache.net_delta_ex_vat
          ELSE NULL
        END,
        tps.summary_net_delta_ex_vat,
        0
      )::numeric AS net_delta_ex_vat
    FROM issue_normalised_rows AS sr0
    LEFT JOIN public.timesheet_summary_pay_state_cache AS summary_pay_cache
      ON summary_pay_cache.timesheet_id = sr0.timesheet_id
    LEFT JOIN public.timesheet_pay_state AS tps
      ON tps.timesheet_id = sr0.timesheet_id
  )
  SELECT
    rr0.timesheet_id,
    rr0.timesheet_status,
    rr0.week_ending_date,
    rr0.booking_id,
    rr0.occupant_key_norm,
    rr0.hospital_norm,
    rr0.sheet_scope,
    rr0.submission_mode,
    rr0.authorised_at_server,
    rr0.candidate_id,
    rr0.client_id,
    rr0.pay_method,
    rr0.processing_status,
    rr0.basis,
    rr0.total_hours,
    rr0.total_pay_ex_vat,
    rr0.total_charge_ex_vat,
    rr0.margin_ex_vat,
    rr0.paid_at_utc,
    rr0.pay_on_hold,
    rr0.ready_to_pay,
    rr0.locked_by_invoice_id,
    rr0.candidate_name,
    rr0.client_name,
    rr0.nhsp_shift_count,
    rr0.nhsp_shift_included_count,
    rr0.nhsp_shift_deferred_count,
    rr0.validation_status,
    rr0.summary_stage,
    rr0.route_type,
    rr0.contract_week_id,
    rr0.contract_week_ending_date,
    rr0.contract_week_status,
    rr0.additional_seq,
    rr0.is_adjustment,
    rr0.qr_status,
    rr0.pay_adjustment_count,
    rr0.has_pay_adjustments,
    rr0.is_adjusted,
    rr0.is_qr,
    rr0.needs_attention,
    rr0.client_autoprocess_hr,
    rr0.has_rate_issue,
    rr0.has_pay_channel_issue,
    rr0.hr_crosscheck_status,
    rr0.hr_crosscheck_issues,
    rr0.external_source_rows_json,
    rr0.issue_codes,
    rr0.client_requires_hr,
    rr0.client_no_timesheet_required,
    rr0.client_is_nhsp,
    rr0.client_pay_reference_required,
    rr0.client_invoice_reference_required,
    rr0.client_hr_validation_required,
    rr0.client_ts_reference_required,
    rr0.require_reference_to_pay,
    rr0.require_reference_to_invoice,
    rr0.qr_token,
    rr0.qr_generated_at,
    rr0.qr_scanned_at,
    rr0.candidate_hint_text,
    rr0.expenses_pay_ex_vat,
    rr0.expenses_description,
    rr0.mileage_units,
    rr0.mileage_pay_rate,
    rr0.mileage_charge_rate,
    rr0.mileage_pay_ex_vat,
    rr0.travel_pay_ex_vat,
    rr0.travel_charge_ex_vat,
    rr0.accommodation_pay_ex_vat,
    rr0.accommodation_charge_ex_vat,
    rr0.other_pay_ex_vat,
    rr0.other_charge_ex_vat,
    rr0.hr_validation_required_for_invoice,
    rr0.invoice_segments_total,
    rr0.invoice_segments_locked,
    rr0.invoice_segments_unlocked,
    rr0.invoice_segment_stage,
    rr0.tools_stage,
    rr0.processing_status_display,
    rr0.invoice_is_paid,
    rr0.refs_block_invoicing,
    rr0.refs_block_issuing_invoices,
    rr0.refs_block_invoice_and_issuing,
    rr0.pay_icon_code,
    rr0.pay_status_code,
    rr0.pay_paid_at_utc,
    rr0.net_delta_ex_vat
  FROM result_rows AS rr0
  WHERE (v_candidate_id IS NULL OR rr0.candidate_id = v_candidate_id)
    AND (v_client_id IS NULL OR rr0.client_id = v_client_id);
END;
$function$;

-- calendar_candidate_contracts_range(uuid,date,date)
CREATE OR REPLACE FUNCTION public.calendar_candidate_contracts_range(candidate_id uuid, from_date date, to_date date)
 RETURNS TABLE(contract_id uuid, client_id uuid, client_name text, role text, band text, start_date date, end_date date, "from" date, "to" date)
 LANGUAGE sql
 STABLE
AS $function$
  select
    c.id as contract_id,
    c.client_id,
    cl.name as client_name,
    c.role,
    c.band,
    c.start_date,
    c.end_date,
    greatest(c.start_date, $2) as "from",
    least(coalesce(c.end_date, $3), $3) as "to"
  from contracts c
  left join clients cl on cl.id = c.client_id
  where c.candidate_id = $1
    and c.start_date <= $3
    and coalesce(c.end_date, $3) >= $2
  order by greatest(c.start_date, $2), cl.name nulls last, c.role nulls last, c.band nulls last;
$function$;

-- calendar_candidate_day_feed(uuid,date,date)
CREATE OR REPLACE FUNCTION public.calendar_candidate_day_feed(candidate_id uuid, from_date date, to_date date)
 RETURNS TABLE(date date, contract_id uuid, state text, planned boolean, has_tsfin boolean, any_ready boolean, pay_on_hold boolean, invoice_on_hold boolean, invoiced boolean, paid boolean, pay_line_on_hold boolean, invoice_line_on_hold boolean, invoice_nos text)
 LANGUAGE sql
 STABLE
AS $function$
with candidate_contracts as (
  select c.id as contract_id
  from contracts c
  where c.candidate_id = $1
    and c.start_date <= $3
    and coalesce(c.end_date, $3) >= $2
),

planned_days as (
  select
    cw.contract_id,
    (p->>'date')::date as date
  from contract_weeks cw
  join candidate_contracts cc on cc.contract_id = cw.contract_id
  cross join lateral jsonb_array_elements(coalesce(cw.planned_schedule_json, '[]'::jsonb)) p
  where (p->>'date')::date between $2 and $3
),

ts_with_tf as (
  select
    ts.timesheet_id,
    ts.contract_id,

    -- link weekly timesheet to its contract_week via contract_weeks.timesheet_id
    cw.id as contract_week_id,
    cw.planned_schedule_json as cw_planned_schedule_json,

    ts.week_ending_date,
    ts.sheet_scope,
    ts.worked_start_iso,
    ts.actual_schedule_json,

    tf.id as tsfin_id,
    tf.processing_status,
    coalesce(tf.pay_on_hold,false) as pay_on_hold,
    tf.paid_at_utc,
    tf.locked_by_invoice_id,
    tf.invoice_breakdown_json
  from timesheets ts
  join candidate_contracts cc on cc.contract_id = ts.contract_id

  left join contract_weeks cw
    on cw.timesheet_id = ts.timesheet_id

  left join timesheets_financials tf
    on tf.timesheet_id = ts.timesheet_id
   and tf.is_current = true

  where
    (
      -- weekly timesheets relevant to window (+/- 14 days buffer)
      (ts.sheet_scope = 'WEEKLY'
       and ts.week_ending_date between ($2 - 14) and ($3 + 14)
      )
      or
      -- daily timesheets relevant to window
      (ts.sheet_scope = 'DAILY'
       and ts.worked_start_iso is not null
       and ((ts.worked_start_iso)::timestamptz at time zone 'Europe/London')::date between $2 and $3
      )
    )
),

-- 1) SEGMENTS mode: authoritative worked days come from segments[].date
segment_events as (
  select
    t.contract_id,
    (seg->>'date')::date as date,

    t.tsfin_id,
    t.processing_status::text as processing_status,
    t.pay_on_hold,
    t.paid_at_utc,

    -- invoice per segment (NHSP/HR), fallback to tsfin lock if present
    coalesce(
      nullif(seg->>'invoice_locked_invoice_id','')::uuid,
      t.locked_by_invoice_id
    ) as invoice_id,

    -- pay line hold (segment-level)
    coalesce((seg->>'exclude_from_pay')::boolean,false) as pay_line_on_hold,

    -- invoice line delayed/held (segment-level)
    (
      nullif(seg->>'invoice_locked_invoice_id','') is null
      and nullif(seg->>'invoice_target_week_start','') is not null
      and (
        (nullif(seg->>'invoice_target_week_start','')::date) <>
        (case
          when t.week_ending_date is not null then (t.week_ending_date - 6)
          else date_trunc('week', ((seg->>'date')::date)::timestamp)::date
        end)
      )
    ) as invoice_line_on_hold

  from ts_with_tf t
  cross join lateral jsonb_array_elements(coalesce(t.invoice_breakdown_json->'segments','[]'::jsonb)) seg
  where t.tsfin_id is not null
    and coalesce(t.invoice_breakdown_json->>'mode','') = 'SEGMENTS'
    and (seg->>'date')::date between $2 and $3
),

-- 2) WEEKLY non-segments: worked days from timesheets.actual_schedule_json[*].date
weekly_schedule_events as (
  select
    t.contract_id,
    (s->>'date')::date as date,

    t.tsfin_id,
    t.processing_status::text as processing_status,
    t.pay_on_hold,
    t.paid_at_utc,
    t.locked_by_invoice_id as invoice_id,

    false as pay_line_on_hold,
    false as invoice_line_on_hold
  from ts_with_tf t
  cross join lateral jsonb_array_elements(coalesce(t.actual_schedule_json,'[]'::jsonb)) s
  where t.sheet_scope = 'WEEKLY'
    and coalesce(t.invoice_breakdown_json->>'mode','') <> 'SEGMENTS'
    and (s->>'date')::date between $2 and $3
),

-- 3) WEEKLY fallback: TSFIN exists but no segments & no schedule -> apply TSFIN onto linked planned days
weekly_plan_fallback_events as (
  select
    t.contract_id,
    (p->>'date')::date as date,

    t.tsfin_id,
    t.processing_status::text as processing_status,
    t.pay_on_hold,
    t.paid_at_utc,
    t.locked_by_invoice_id as invoice_id,

    false as pay_line_on_hold,
    false as invoice_line_on_hold
  from ts_with_tf t
  cross join lateral jsonb_array_elements(coalesce(t.cw_planned_schedule_json,'[]'::jsonb)) p
  where t.sheet_scope = 'WEEKLY'
    and t.tsfin_id is not null
    and coalesce(t.invoice_breakdown_json->>'mode','') <> 'SEGMENTS'
    and coalesce(jsonb_array_length(coalesce(t.actual_schedule_json,'[]'::jsonb)),0) = 0
    and (p->>'date')::date between $2 and $3
),

-- 4) DAILY: worked day from worked_start_iso UK date
daily_events as (
  select
    t.contract_id,
    ((t.worked_start_iso)::timestamptz at time zone 'Europe/London')::date as date,

    t.tsfin_id,
    t.processing_status::text as processing_status,
    t.pay_on_hold,
    t.paid_at_utc,
    t.locked_by_invoice_id as invoice_id,

    false as pay_line_on_hold,
    false as invoice_line_on_hold
  from ts_with_tf t
  where t.sheet_scope = 'DAILY'
    and t.worked_start_iso is not null
    and ((t.worked_start_iso)::timestamptz at time zone 'Europe/London')::date between $2 and $3
),

all_events as (
  -- planned markers
  select
    p.contract_id,
    p.date,
    true as planned,
    null::uuid as tsfin_id,
    null::text as processing_status,
    false as pay_on_hold,
    null::timestamptz as paid_at_utc,
    null::uuid as invoice_id,
    false as pay_line_on_hold,
    false as invoice_line_on_hold
  from planned_days p

  union all
  select
    e.contract_id,
    e.date,
    false as planned,
    e.tsfin_id,
    e.processing_status,
    e.pay_on_hold,
    e.paid_at_utc,
    e.invoice_id,
    e.pay_line_on_hold,
    e.invoice_line_on_hold
  from segment_events e

  union all
  select
    e.contract_id,
    e.date,
    false, e.tsfin_id, e.processing_status, e.pay_on_hold, e.paid_at_utc, e.invoice_id,
    e.pay_line_on_hold, e.invoice_line_on_hold
  from weekly_schedule_events e

  union all
  select
    e.contract_id,
    e.date,
    false, e.tsfin_id, e.processing_status, e.pay_on_hold, e.paid_at_utc, e.invoice_id,
    e.pay_line_on_hold, e.invoice_line_on_hold
  from weekly_plan_fallback_events e

  union all
  select
    e.contract_id,
    e.date,
    false, e.tsfin_id, e.processing_status, e.pay_on_hold, e.paid_at_utc, e.invoice_id,
    e.pay_line_on_hold, e.invoice_line_on_hold
  from daily_events e
),

events_with_invoice as (
  select
    a.*,
    inv.status::text as invoice_status,
    inv.invoice_no as invoice_no
  from all_events a
  left join invoices inv on inv.id = a.invoice_id
),

agg as (
  select
    date,
    contract_id,

    bool_or(planned) as planned,
    bool_or(tsfin_id is not null) as has_tsfin,
    bool_or(processing_status = 'READY_FOR_INVOICE') as any_ready,

    bool_or(pay_on_hold) as pay_on_hold,
    bool_or(invoice_status = 'ON_HOLD') as invoice_on_hold,
    bool_or(invoice_id is not null and coalesce(invoice_status,'') <> 'ON_HOLD') as invoiced,
    bool_or(paid_at_utc is not null) as paid,

    bool_or(pay_line_on_hold) as pay_line_on_hold,
    bool_or(invoice_line_on_hold) as invoice_line_on_hold,

    string_agg(distinct invoice_no, ',') filter (where invoice_no is not null) as invoice_nos
  from events_with_invoice
  group by date, contract_id
)

select
  date,
  contract_id,
  case
    when paid then 'PAID'
    when pay_on_hold and invoice_on_hold then 'PAY_AND_INVOICE_ON_HOLD'
    when pay_on_hold then 'PAY_ON_HOLD'
    when invoice_on_hold then 'INVOICE_ON_HOLD'
    when invoiced then 'INVOICED'
    when has_tsfin and any_ready then 'READY'
    when has_tsfin then 'PROCESSED_NOT_READY'
    when planned then 'PLANNED'
    else 'EMPTY'
  end as state,

  planned,
  has_tsfin,
  any_ready,
  pay_on_hold,
  invoice_on_hold,
  invoiced,
  paid,
  pay_line_on_hold,
  invoice_line_on_hold,
  invoice_nos
from agg
where date between $2 and $3
order by date, contract_id;
$function$;

-- calendar_contract_day_feed(uuid,date,date)
CREATE OR REPLACE FUNCTION public.calendar_contract_day_feed(contract_id uuid, from_date date, to_date date)
 RETURNS TABLE(date date, contract_id uuid, state text, planned boolean, has_tsfin boolean, any_ready boolean, pay_on_hold boolean, invoice_on_hold boolean, invoiced boolean, paid boolean, pay_line_on_hold boolean, invoice_line_on_hold boolean, invoice_nos text)
 LANGUAGE sql
 STABLE
AS $function$
  select *
  from public.calendar_candidate_day_feed(
    (select c.candidate_id from contracts c where c.id = $1),
    $2,
    $3
  ) as f
  where f.contract_id = $1;
$function$;

-- candidate_app_bootstrap_v1(uuid,text,integer,timestamp with time zone)
CREATE OR REPLACE FUNCTION public.candidate_app_bootstrap_v1(p_session_id uuid, p_environment text, p_expected_rotation integer, p_now_utc timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
declare
  v_context jsonb;
  v_candidate public.candidates%rowtype;
  v_flags jsonb;
  v_contract_enabled boolean:=false;
  v_daily_capability jsonb;
begin
  perform private._candidate_require_feature_v1(p_environment,'candidate_app_reads');
  v_context:=private._candidate_session_context_v1(p_session_id,p_environment,p_expected_rotation,p_now_utc,false);
  if nullif(v_context->>'selected_candidate_id','') is not null then
    select * into v_candidate from public.candidates where id=(v_context->>'selected_candidate_id')::uuid;
    select exists(
      select 1
      from public.contract_weeks cw
      join public.contracts c on c.id=cw.contract_id and c.candidate_id=v_candidate.id
      left join lateral (
        select cs.week_ending_weekday
        from public.client_settings cs
        where cs.client_id=c.client_id
          and cs.effective_from<=(p_now_utc at time zone 'Europe/London')::date
        order by cs.effective_from desc,cs.updated_at desc nulls last,cs.id desc
        limit 1
      ) effective_client on true
      cross join lateral (
        select (
          (p_now_utc at time zone 'Europe/London')::date
          + mod(
              coalesce(c.week_ending_weekday_snapshot,effective_client.week_ending_weekday,0)
              - extract(dow from (p_now_utc at time zone 'Europe/London')::date)::integer
              + 7,
              7
            )
        )::date as current_week_ending_date
      ) entitlement_window
      left join public.timesheets t on t.timesheet_id=cw.timesheet_id
        and t.is_current=true and t.archived_at_utc is null
      left join public.timesheets_financials tf on tf.timesheet_id=t.timesheet_id and tf.is_current=true
      where cw.week_ending_date >= (entitlement_window.current_week_ending_date-interval '6 months')::date
        and cw.week_ending_date <= entitlement_window.current_week_ending_date
        and (
          cw.status in ('OPEN','SUBMITTED','AUTHORISED','INVOICED')
          or tf.processing_status in (
            'UNASSIGNED','CLIENT_UNRESOLVED','RATE_MISSING','PAY_CHANNEL_MISSING',
            'READY_FOR_HR','READY_FOR_INVOICE','PENDING_AUTH',
            'AWAITING_MANUAL_SIGNATURE','UNPROCESSED'
          )
          or cw.week_ending_date=entitlement_window.current_week_ending_date
        )
    ) into v_contract_enabled;
  end if;
  select candidate_app_feature_flags_json into v_flags from public.settings_defaults where id=1;
  v_daily_capability:=private._candidate_daily_capability_v1(
    upper(v_context->>'environment'),
    nullif(v_context->>'selected_candidate_id','')::uuid,
    p_now_utc
  );
  return jsonb_build_object(
    'ok',true,
    'feature_contract_version','candidate-app-private-v1',
    'environment',v_context->>'environment',
    'account_id',v_context->'account_id',
    'selected_candidate_id',v_context->'selected_candidate_id',
    'selection_required',coalesce((v_context#>>'{eligibility,selection_required}')::boolean,false)
      and (v_context->>'selected_candidate_id') is null,
    'selectable_candidate_ids',case
      when upper(v_context->>'environment')='TEST' then v_context#>'{eligibility,candidate_ids}'
      else '[]'::jsonb end,
    'entitlements',jsonb_build_object(
      'contract',v_contract_enabled,
      'daily',nullif(btrim(coalesce(v_candidate.key_norm,'')),'') is not null,
      'gck_present',nullif(btrim(coalesce(v_candidate.key_norm,'')),'') is not null
    ),
    'notification_preferences',v_context->'notification_preferences',
    'feature_flags',coalesce(v_flags,'{}'::jsonb),
    'capabilities',jsonb_build_object('daily_availability',v_daily_capability),
    'session',jsonb_build_object(
      'rotation',(v_context->>'rotation')::integer,
      'session_version',(v_context->>'session_version')::bigint,
      'expires_at_utc',v_context->'expires_at_utc',
      'absolute_expires_at_utc',v_context->'absolute_expires_at_utc'
    )
  );
end;
$function$;

-- candidate_app_federated_membership_link_set_v1(jsonb,text,bytea,uuid,integer,uuid,text,text,timestamp with time zone)
CREATE OR REPLACE FUNCTION public.candidate_app_federated_membership_link_set_v1(p_internal_context jsonb, p_environment text, p_global_account_identity_hmac bytea, p_membership_id uuid, p_membership_generation integer, p_candidate_id uuid, p_candidate_code text, p_target_state text, p_now_utc timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_environment text:=pg_catalog.upper(pg_catalog.btrim(coalesce(p_environment,'')));
  v_target_state text:=pg_catalog.upper(pg_catalog.btrim(coalesce(p_target_state,'')));
  v_candidate public.candidates%rowtype;
  v_email text;
  v_account public.candidate_app_accounts%rowtype;
  v_link public.candidate_app_global_membership_links%rowtype;
begin
  if pg_catalog.jsonb_typeof(p_internal_context) is distinct from 'object'
     or p_internal_context->>'route_context_verified' is distinct from 'true'
     or p_internal_context->>'audience' is distinct from 'FEDERATED_MEMBERSHIP_LINK'
     or v_environment not in ('TEST','LIVE')
     or p_membership_id is null or p_candidate_id is null
     or coalesce(p_membership_generation,0)<1
     or coalesce(pg_catalog.octet_length(p_global_account_identity_hmac),0)<>32
     or v_target_state not in ('PENDING','ACTIVE','DISABLED','REVOKED')
     or p_now_utc is null
     or (p_candidate_code is not null
       and pg_catalog.upper(pg_catalog.btrim(p_candidate_code)) !~ '^CID1-[0-9A-HJKMNP-TV-Z]{5,160}$') then
    raise exception using errcode='22023',message='CANDIDATE_FEDERATED_LINK_INVALID';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('candidate-federated-membership:'||p_membership_id::text,0)
  );

  select * into strict v_candidate
  from public.candidates c
  where c.id=p_candidate_id and c.active is true
  for share;
  v_email:=pg_catalog.lower(pg_catalog.btrim(coalesce(v_candidate.email,'')));
  if v_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
     or (p_candidate_code is not null
       and pg_catalog.upper(pg_catalog.btrim(coalesce(v_candidate.key_norm,'')))
         <>pg_catalog.upper(pg_catalog.btrim(p_candidate_code))) then
    raise exception using errcode='28000',message='CANDIDATE_FEDERATED_CANDIDATE_INVALID';
  end if;

  select * into v_link
  from public.candidate_app_global_membership_links l
  where l.membership_id=p_membership_id
  for update;
  if found then
    if v_link.global_account_identity_hmac<>p_global_account_identity_hmac
       or v_link.candidate_id<>p_candidate_id
       or p_membership_generation<v_link.membership_generation
       or (v_link.candidate_code is not null and p_candidate_code is not null
         and v_link.candidate_code<>pg_catalog.upper(pg_catalog.btrim(p_candidate_code))) then
      raise exception using errcode='28000',message='CANDIDATE_FEDERATED_MEMBERSHIP_STALE';
    end if;
    update public.candidate_app_global_membership_links
    set membership_generation=p_membership_generation,
        candidate_code=coalesce(
          candidate_code,pg_catalog.upper(pg_catalog.btrim(p_candidate_code))
        ),
        state=v_target_state,
        updated_at_utc=p_now_utc,
        revoked_at_utc=case when v_target_state='REVOKED' then p_now_utc else null end,
        revoke_reason=case when v_target_state='REVOKED' then 'CONTROL_PLANE_REVOKED' else null end
    where membership_id=p_membership_id
    returning * into v_link;
    if v_target_state in ('DISABLED','REVOKED') then
      update public.candidate_app_sessions
      set status='REVOKED',revoked_at_utc=p_now_utc,
          revoke_reason='FEDERATED_MEMBERSHIP_'||v_target_state,updated_at_utc=p_now_utc
      where auth_source='CONTROL_PLANE' and membership_id=p_membership_id and status='ACTIVE';
    end if;
    return pg_catalog.jsonb_build_object(
      'ok',true,'status','UPDATED','state',v_link.state,
      'membership_generation',v_link.membership_generation,'internal_only',true
    );
  end if;

  if v_target_state in ('DISABLED','REVOKED') then
    return pg_catalog.jsonb_build_object(
      'ok',true,'status','UNCHANGED','state',v_target_state,
      'membership_generation',p_membership_generation,'internal_only',true
    );
  end if;

  select * into v_account
  from public.candidate_app_accounts a
  where a.environment=v_environment and a.email_normalized=v_email
  for update;
  if found then
    if v_account.status in ('LOCKED','DISABLED') then
      raise exception using errcode='28000',message='CANDIDATE_FEDERATED_ACCOUNT_REVIEW_REQUIRED';
    end if;
    if v_account.status='SETUP_REQUIRED' then
      update public.candidate_app_accounts
      set status='ACTIVE',updated_at_utc=p_now_utc
      where id=v_account.id
      returning * into v_account;
    end if;
  else
    insert into public.candidate_app_accounts(
      environment,email_normalized,status,created_at_utc,updated_at_utc
    ) values(v_environment,v_email,'ACTIVE',p_now_utc,p_now_utc)
    returning * into v_account;
  end if;

  insert into public.candidate_app_global_membership_links(
    membership_id,global_account_identity_hmac,account_id,candidate_id,candidate_code,
    membership_generation,state,linked_at_utc,updated_at_utc
  ) values(
    p_membership_id,p_global_account_identity_hmac,v_account.id,p_candidate_id,
    case when p_candidate_code is null then null else pg_catalog.upper(pg_catalog.btrim(p_candidate_code)) end,
    p_membership_generation,v_target_state,p_now_utc,p_now_utc
  ) returning * into v_link;

  return pg_catalog.jsonb_build_object(
    'ok',true,'status','LINKED','state',v_link.state,
    'membership_generation',v_link.membership_generation,'internal_only',true
  );
exception
  when no_data_found then
    raise exception using errcode='28000',message='CANDIDATE_FEDERATED_CANDIDATE_INVALID';
  when unique_violation then
    raise exception using errcode='28000',message='CANDIDATE_FEDERATED_LINK_CONFLICT';
end;
$function$;

-- candidate_app_federated_session_project_v1(text,bytea,bytea,uuid,integer,uuid,integer,bigint,timestamp with time zone,timestamp with time zone)
CREATE OR REPLACE FUNCTION public.candidate_app_federated_session_project_v1(p_environment text, p_global_account_identity_hmac bytea, p_global_session_identity_hmac bytea, p_membership_id uuid, p_membership_generation integer, p_candidate_id uuid, p_route_version integer, p_session_epoch bigint, p_now_utc timestamp with time zone, p_expires_at_utc timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_environment text:=pg_catalog.upper(pg_catalog.btrim(coalesce(p_environment,'')));
  v_link public.candidate_app_global_membership_links%rowtype;
  v_account public.candidate_app_accounts%rowtype;
  v_existing public.candidate_app_sessions%rowtype;
  v_session_id uuid:=pg_catalog.gen_random_uuid();
  v_expiry timestamptz;
begin
  if v_environment not in ('TEST','LIVE')
     or p_membership_id is null or p_candidate_id is null
     or p_membership_generation<1 or p_route_version<1 or p_session_epoch<1
     or coalesce(pg_catalog.octet_length(p_global_account_identity_hmac),0)<>32
     or coalesce(pg_catalog.octet_length(p_global_session_identity_hmac),0)<>32
     or p_now_utc is null or p_expires_at_utc is null
     or p_expires_at_utc<=p_now_utc
     or p_expires_at_utc>p_now_utc+interval '5 minutes' then
    raise exception 'CANDIDATE_FEDERATED_CONTEXT_INVALID' using errcode='22023';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('candidate-federated-membership:'||p_membership_id::text,0)
  );

  select * into strict v_link
  from public.candidate_app_global_membership_links
  where membership_id=p_membership_id
  for update;

  if v_link.state<>'ACTIVE'
     or v_link.global_account_identity_hmac<>p_global_account_identity_hmac
     or v_link.membership_generation<>p_membership_generation
     or v_link.candidate_id<>p_candidate_id then
    raise exception 'CANDIDATE_FEDERATED_MEMBERSHIP_STALE' using errcode='28000';
  end if;

  select * into strict v_account
  from public.candidate_app_accounts
  where id=v_link.account_id
  for share;
  if v_account.environment<>v_environment or v_account.status<>'ACTIVE'
     or not exists(
       select 1 from public.candidates c
       where c.id=v_link.candidate_id and c.active=true
         and pg_catalog.lower(pg_catalog.btrim(coalesce(c.email,'')))=v_account.email_normalized
     ) then
    raise exception 'CANDIDATE_AUTHORITY_REVOKED' using errcode='28000';
  end if;

  update public.candidate_app_sessions
  set status='REVOKED',revoked_at_utc=p_now_utc,revoke_reason='FEDERATED_CONTEXT_STALE',updated_at_utc=p_now_utc
  where auth_source='CONTROL_PLANE' and membership_id=p_membership_id and status='ACTIVE'
    and (membership_generation<>p_membership_generation
      or route_version<>p_route_version
      or session_epoch<>p_session_epoch
      or global_account_identity_hmac<>p_global_account_identity_hmac
      or global_session_identity_hmac<>p_global_session_identity_hmac
      or selected_candidate_id<>p_candidate_id
      or expires_at_utc<=p_now_utc);

  select * into v_existing
  from public.candidate_app_sessions
  where auth_source='CONTROL_PLANE' and membership_id=p_membership_id
    and membership_generation=p_membership_generation
    and route_version=p_route_version and session_epoch=p_session_epoch
    and global_account_identity_hmac=p_global_account_identity_hmac
    and global_session_identity_hmac=p_global_session_identity_hmac
    and selected_candidate_id=p_candidate_id and status='ACTIVE'
    and expires_at_utc>p_now_utc and absolute_expires_at_utc>p_now_utc
  for update;
  if found then
    update public.candidate_app_sessions
    set last_used_at_utc=p_now_utc,updated_at_utc=p_now_utc
    where id=v_existing.id;
    return pg_catalog.jsonb_build_object(
      'ok',true,'idempotent_reuse',true,'session_id',v_existing.id,
      'account_id',v_existing.account_id,'selected_candidate_id',v_existing.selected_candidate_id,
      'environment',v_existing.environment,'rotation',v_existing.rotation,
      'issued_at_utc',v_existing.issued_at_utc,'expires_at_utc',v_existing.expires_at_utc,
      'absolute_expires_at_utc',v_existing.absolute_expires_at_utc,
      'membership_id',v_existing.membership_id,'membership_generation',v_existing.membership_generation,
      'route_version',v_existing.route_version,'session_epoch',v_existing.session_epoch,
      'internal_only',true
    );
  end if;

  v_expiry:=least(p_expires_at_utc,p_now_utc+interval '5 minutes');
  insert into public.candidate_app_sessions(
    id,account_id,environment,selected_candidate_id,status,refresh_token_hash,
    token_family_id,rotation,issued_at_utc,expires_at_utc,absolute_expires_at_utc,
    last_used_at_utc,auth_source,global_account_identity_hmac,global_session_identity_hmac,
    membership_id,membership_generation,route_version,session_epoch,created_at_utc,updated_at_utc
  ) values (
    v_session_id,v_link.account_id,v_environment,p_candidate_id,'ACTIVE',
    extensions.digest(pg_catalog.gen_random_uuid()::text,'sha256'),
    pg_catalog.gen_random_uuid(),0,p_now_utc,v_expiry,v_expiry,p_now_utc,'CONTROL_PLANE',
    p_global_account_identity_hmac,p_global_session_identity_hmac,p_membership_id,
    p_membership_generation,p_route_version,p_session_epoch,p_now_utc,p_now_utc
  ) returning * into v_existing;

  return pg_catalog.jsonb_build_object(
    'ok',true,'idempotent_reuse',false,'session_id',v_existing.id,
    'account_id',v_existing.account_id,'selected_candidate_id',v_existing.selected_candidate_id,
    'environment',v_existing.environment,'rotation',v_existing.rotation,
    'issued_at_utc',v_existing.issued_at_utc,'expires_at_utc',v_existing.expires_at_utc,
    'absolute_expires_at_utc',v_existing.absolute_expires_at_utc,
    'membership_id',v_existing.membership_id,'membership_generation',v_existing.membership_generation,
    'route_version',v_existing.route_version,'session_epoch',v_existing.session_epoch,
    'internal_only',true
  );
exception when no_data_found then
  raise exception 'CANDIDATE_FEDERATED_MEMBERSHIP_INVALID' using errcode='28000';
end;
$function$;

-- candidate_app_timesheet_detail_v1(uuid,text,uuid,uuid,uuid,timestamp with time zone)
CREATE OR REPLACE FUNCTION public.candidate_app_timesheet_detail_v1(p_session_id uuid, p_environment text, p_timesheet_id uuid DEFAULT NULL::uuid, p_contract_week_id uuid DEFAULT NULL::uuid, p_workflow_id uuid DEFAULT NULL::uuid, p_now_utc timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
declare
  v_context jsonb;
  v_candidate_id uuid;
  v_week public.contract_weeks%rowtype;
  v_contract public.contracts%rowtype;
  v_client public.clients%rowtype;
  v_timesheet public.timesheets%rowtype;
  v_fin public.timesheets_financials%rowtype;
  v_workflow public.candidate_submission_workflows%rowtype;
  v_capabilities jsonb;
  v_evidence jsonb;
  v_components jsonb;
  v_claims jsonb;
  v_document_state jsonb:='{}'::jsonb;
  v_effective_week_ending_weekday integer;
  v_effective_current_week_ending_date date;
  v_tab_bucket text;
  v_candidate_status_code text;
  v_active_workflow_state text;
  v_rejected_workflow jsonb;
  v_primary_action jsonb;
  v_action_contract jsonb;
  v_detail_source_timesheet_id uuid;
begin
  perform private._candidate_require_feature_v1(p_environment,'candidate_app_reads');
  if num_nonnulls(p_timesheet_id,p_contract_week_id,p_workflow_id)<>1 then
    raise exception 'CANDIDATE_DETAIL_IDENTITY_INVALID' using errcode='22023';
  end if;
  v_context:=private._candidate_session_context_v1(p_session_id,p_environment,null,p_now_utc,false);
  v_candidate_id:=nullif(v_context->>'selected_candidate_id','')::uuid;
  if v_candidate_id is null then raise exception 'CANDIDATE_SELECTION_REQUIRED' using errcode='28000'; end if;

  if p_workflow_id is not null then
    select * into v_workflow from public.candidate_submission_workflows where id=p_workflow_id and candidate_id=v_candidate_id;
    if not found then raise exception 'CANDIDATE_DETAIL_NOT_FOUND' using errcode='P0002'; end if;
    v_detail_source_timesheet_id:=case
      when v_workflow.workflow_kind='CONTRACT_EXPENSE'
        or v_workflow.rejection_scope='COMPLETE_EXPENSE_CLAIM'
        then coalesce(v_workflow.anchor_timesheet_id,v_workflow.target_timesheet_id)
      else coalesce(v_workflow.target_timesheet_id,v_workflow.anchor_timesheet_id) end;
    if v_detail_source_timesheet_id is not null then
      select current_version.timesheet_id into p_timesheet_id
      from public.timesheets source_version
      join public.timesheets current_version on current_version.is_current=true
        and current_version.archived_at_utc is null
        and (
          (nullif(btrim(coalesce(source_version.booking_id,'')),'') is not null
            and current_version.booking_id=source_version.booking_id
            and current_version.contract_id is not distinct from source_version.contract_id
            and current_version.week_ending_date is not distinct from source_version.week_ending_date)
          or (nullif(btrim(coalesce(source_version.booking_id,'')),'') is null
            and current_version.timesheet_id=source_version.timesheet_id)
        )
      where source_version.timesheet_id=v_detail_source_timesheet_id
        and upper(coalesce(current_version.line_type::text,'')) not in ('EXPENSES','MILEAGE')
      order by current_version.version desc,current_version.timesheet_id
      limit 1;
    end if;
    if p_timesheet_id is not null then
      select week_row.id into p_contract_week_id
      from public.contract_weeks week_row
      where week_row.timesheet_id=p_timesheet_id
        and week_row.contract_id=v_workflow.contract_id
        and week_row.week_ending_date=v_workflow.week_ending_date
      order by week_row.updated_at desc,week_row.id desc limit 1;
    end if;
    if p_contract_week_id is null then p_contract_week_id:=v_workflow.contract_week_id; end if;
  end if;
  if p_contract_week_id is not null then
    select * into v_week from public.contract_weeks where id=p_contract_week_id;
  else
    select * into v_week from public.contract_weeks where timesheet_id=p_timesheet_id order by updated_at desc,id desc limit 1;
  end if;
  if not found then raise exception 'CANDIDATE_DETAIL_NOT_FOUND' using errcode='P0002'; end if;
  select * into v_contract from public.contracts where id=v_week.contract_id and candidate_id=v_candidate_id;
  if not found then raise exception 'CANDIDATE_DETAIL_NOT_FOUND' using errcode='P0002'; end if;
  select * into v_client from public.clients where id=v_contract.client_id;
  select coalesce(
    v_contract.week_ending_weekday_snapshot,
    (
      select settings.week_ending_weekday
      from public.client_settings settings
      where settings.client_id=v_contract.client_id
        and settings.effective_from<=(p_now_utc at time zone 'Europe/London')::date
      order by settings.effective_from desc,settings.updated_at desc nulls last,settings.id desc
      limit 1
    ),0
  ) into v_effective_week_ending_weekday;
  v_effective_current_week_ending_date:=(
    (p_now_utc at time zone 'Europe/London')::date
    +mod(
      v_effective_week_ending_weekday
      -extract(dow from (p_now_utc at time zone 'Europe/London')::date)::integer+7,7
    )
  )::date;
  if p_timesheet_id is null then p_timesheet_id:=v_week.timesheet_id; end if;
  if p_timesheet_id is not null then
    select * into v_timesheet from public.timesheets where timesheet_id=p_timesheet_id and is_current=true and archived_at_utc is null;
    if not found then raise exception 'CANDIDATE_DETAIL_NOT_FOUND' using errcode='P0002'; end if;
    select * into v_fin from public.timesheets_financials where timesheet_id=p_timesheet_id and is_current=true
    order by computed_at_utc desc nulls last,updated_at desc,id desc limit 1;
  end if;
  v_capabilities:=private._candidate_record_capabilities_v1(p_timesheet_id,v_week.id,'{}'::jsonb);

  select coalesce(jsonb_agg(jsonb_build_object(
    'id',e.id,'kind',e.kind,'document_role',e.document_role,'display_name',e.display_name,
    'processing_state',e.processing_state,'created_at',e.created_at
  ) order by e.created_at,e.id),'[]'::jsonb)
  into v_evidence from public.timesheet_evidence e
  where e.timesheet_id=p_timesheet_id and e.processing_state<>'SUPERSEDED';

  select coalesce(jsonb_agg(jsonb_build_object(
    'id',c.id,'workflow_id',c.workflow_id,'workflow_generation',c.workflow_generation,
    'component_kind',c.component_kind,
    'expense_category',c.expense_category,'document_role',c.document_role,'state',c.state,
    'media_type',c.media_type,'byte_size',c.byte_size,'created_at_utc',c.created_at_utc,
    'required',c.required,'review_ordinal',c.review_ordinal,
    'review_document_ready',c.review_render_state='READY',
    'review_document_generation',c.workflow_generation,
    'review_page_count',c.review_page_count,
    'review_content_sha256',case when c.review_content_sha256 is null then null else encode(c.review_content_sha256,'hex') end,
    'final_signed_document_ready',c.final_signed_render_state='READY',
    'final_signed_page_count',c.final_signed_page_count
  ) order by c.created_at_utc,c.component_no),'[]'::jsonb)
  into v_components from public.candidate_submission_components c
  join public.candidate_submission_workflows w on w.id=c.workflow_id
  where w.candidate_id=v_candidate_id
    and private._candidate_workflow_maps_to_card_v1(w.id,p_timesheet_id,v_week.id)
    and c.state<>'SUPERSEDED';

  select coalesce(jsonb_agg(jsonb_build_object(
    'workflow_id',w.id,'workflow_kind',w.workflow_kind,'state',w.state,'generation',w.generation,
    'detail_action_owner',w.id=p_workflow_id,
    'claim_family',rejection_policy.claim_family,
    'route',w.route,'target_timesheet_id',w.target_timesheet_id,
    'anchor_timesheet_id',w.anchor_timesheet_id,'issue_codes',w.issue_codes,
    'rejection_reason',w.rejection_reason,'rejection_scope',w.rejection_scope,
    'required_resubmission_action',case
      when w.state<>'REJECTED' or not rejection_policy.rejection_actionable then null
      when w.workflow_kind='CONTRACT_EXPENSE' or w.rejection_scope='COMPLETE_EXPENSE_CLAIM'
        then 'RESUBMIT_EXPENSE_CLAIM'
      when w.workflow_kind='CONTRACT_COMBINED' then 'RESUBMIT_TIMESHEET_AND_EXPENSES'
      else 'RESUBMIT_TIMESHEET' end,
    'rejection_actionable',rejection_policy.rejection_actionable,
    'review_document_ready',exists(select 1 from public.candidate_submission_components review_component
      where review_component.workflow_id=w.id and review_component.workflow_generation=w.generation
        and review_component.required=true and review_component.state<>'SUPERSEDED')
      and not exists(select 1 from public.candidate_submission_components review_component
      where review_component.workflow_id=w.id and review_component.workflow_generation=w.generation
        and review_component.required=true and review_component.state<>'SUPERSEDED'
        and review_component.review_render_state<>'READY'),
    'review_document_generation',w.generation,
    'review_page_count',(select sum(coalesce(review_component.review_page_count,0))
      from public.candidate_submission_components review_component
      where review_component.workflow_id=w.id and review_component.workflow_generation=w.generation
        and review_component.required=true and review_component.state<>'SUPERSEDED'),
    'manager_approval_state',coalesce((select approval.state
      from public.candidate_approval_requests approval where approval.workflow_id=w.id
        and approval.workflow_generation=w.generation
      order by approval.request_generation desc,approval.created_at_utc desc limit 1),w.state),
    'final_signed_document_ready',exists(select 1 from public.candidate_submission_components final_component
      where final_component.workflow_id=w.id and final_component.workflow_generation=w.generation
        and final_component.required=true and final_component.state<>'SUPERSEDED')
      and not exists(select 1 from public.candidate_submission_components final_component
      where final_component.workflow_id=w.id and final_component.workflow_generation=w.generation
        and final_component.required=true and final_component.state<>'SUPERSEDED'
        and final_component.final_signed_render_state<>'READY'),
    'updated_at_utc',w.updated_at_utc
  ) order by w.updated_at_utc desc,w.id desc),'[]'::jsonb)
  into v_claims from public.candidate_submission_workflows w
  cross join lateral (
    select
      case when w.workflow_kind='CONTRACT_EXPENSE'
          or w.rejection_scope='COMPLETE_EXPENSE_CLAIM'
        then 'EXPENSES' else 'HOURS' end as claim_family,
      case when w.state<>'REJECTED' then false
        else not private._candidate_rejection_replaced_v1(w.id)
      end as rejection_actionable
  ) rejection_policy
  where w.candidate_id=v_candidate_id and w.contract_id=v_contract.id
    and w.week_ending_date=v_week.week_ending_date and w.state<>'SUPERSEDED'
    and private._candidate_workflow_maps_to_card_v1(w.id,p_timesheet_id,v_week.id);

  select jsonb_build_object(
    'workflow_id',document_workflow.id,
    'workflow_generation',document_workflow.generation,
    'review_document_ready',coalesce(document_readiness.review_ready,false),
    'review_document_component_id',hours_component.id,
    'review_document_generation',hours_component.workflow_generation,
    'review_page_count',hours_component.review_page_count,
    'manager_approval_state',coalesce(latest_approval.state,document_workflow.state),
    'final_signed_document_ready',coalesce(document_readiness.final_ready,false)
  ) into v_document_state
  from public.candidate_submission_workflows document_workflow
  left join lateral (
    select component.* from public.candidate_submission_components component
    where component.workflow_id=document_workflow.id
      and component.workflow_generation=document_workflow.generation
      and component.component_kind='HOURS_TIMESHEET' and component.state<>'SUPERSEDED'
    order by component.review_ordinal,component.id limit 1
  ) hours_component on true
  left join lateral (
    select
      count(*)>0 and bool_and(component.review_render_state='READY') as review_ready,
      count(*)>0 and bool_and(component.final_signed_render_state='READY') as final_ready
    from public.candidate_submission_components component
    where component.workflow_id=document_workflow.id
      and component.workflow_generation=document_workflow.generation
      and component.required=true and component.state<>'SUPERSEDED'
  ) document_readiness on true
  left join lateral (
    select approval.* from public.candidate_approval_requests approval
    where approval.workflow_id=document_workflow.id
      and approval.workflow_generation=document_workflow.generation
    order by approval.request_generation desc,approval.created_at_utc desc limit 1
  ) latest_approval on true
  where document_workflow.candidate_id=v_candidate_id
    and private._candidate_workflow_maps_to_card_v1(
      document_workflow.id,p_timesheet_id,v_week.id
    )
    and document_workflow.state<>'SUPERSEDED'
  order by (document_workflow.id=p_workflow_id) desc,document_workflow.updated_at_utc desc
  limit 1;

  select workflow_item->>'state' into v_active_workflow_state
  from jsonb_array_elements(coalesce(v_claims,'[]'::jsonb)) workflow_item
  where workflow_item->>'state' in (
    'CREATED','WORKER_DRAFT','WORKER_SUBMITTED',
    'WORKER_SUBMITTED_PENDING_REVIEW_DOCUMENT','READY_FOR_MANAGER_APPROVAL',
    'AWAITING_MANAGER_APPROVAL','MANAGER_APPROVED',
    'MANAGER_APPROVED_PENDING_FINAL_DOCUMENT','READY_TO_FINALISE',
    'AWAITING_PAPER_RETURN','RECEIVED','REFUSED'
  )
  order by coalesce((workflow_item->>'detail_action_owner')::boolean,false) desc,
    workflow_item->>'updated_at_utc' desc,workflow_item->>'workflow_id'
  limit 1;
  select workflow_item into v_rejected_workflow
  from jsonb_array_elements(coalesce(v_claims,'[]'::jsonb)) workflow_item
  where workflow_item->>'state'='REJECTED'
    and coalesce((workflow_item->>'rejection_actionable')::boolean,false)
  order by coalesce((workflow_item->>'detail_action_owner')::boolean,false) desc,
    workflow_item->>'updated_at_utc' desc,workflow_item->>'workflow_id'
  limit 1;
  v_candidate_status_code:=private._candidate_status_code_v1(
    v_fin.paid_at_utc is not null,
    v_fin.authorised_at_utc is not null,
    v_fin.locked_by_invoice_id is not null
      or upper(coalesce(v_timesheet.status::text,''))='INVOICED',
    v_active_workflow_state,v_rejected_workflow is not null,
    v_fin.processing_status::text,v_week.status::text
  );
  v_tab_bucket:=case
    when v_week.week_ending_date>v_effective_current_week_ending_date then 'EXCLUDED'
    when v_fin.paid_at_utc is null or v_fin.paid_at_utc>p_now_utc then 'CURRENT'
    when v_fin.paid_at_utc>=p_now_utc-interval '7 days' then 'CURRENT'
    when v_fin.paid_at_utc<p_now_utc-interval '7 days'
      and v_week.week_ending_date between v_effective_current_week_ending_date-105
        and v_effective_current_week_ending_date then 'HISTORY'
    else 'EXCLUDED' end;
  v_primary_action:=private._candidate_timesheet_primary_action_v1(
    v_candidate_status_code,v_claims,v_capabilities,p_timesheet_id,v_week.id
  );
  v_action_contract:=private._candidate_timesheet_action_contract_v1(
    v_candidate_status_code,v_claims,v_capabilities,p_timesheet_id,v_week.id,p_now_utc
  );
  v_primary_action:=v_action_contract->'primary_action';
  if v_active_workflow_state='AWAITING_PAPER_RETURN' then
    v_candidate_status_code:=case v_action_contract->'paper_pack'->>'state'
      when 'READY' then 'AWAITING_SIGNED_DOCUMENTS'
      when 'FAILED' then 'DOCUMENT_PREPARATION_FAILED'
      when 'RETIRED' then 'PAPER_DELIVERY_RETIRED'
      when 'STALE' then 'PAPER_DELIVERY_STALE'
      else 'PREPARING_DOCUMENTS' end;
  end if;

  return jsonb_build_object(
    'ok',true,
    'week_ending_label',private._candidate_week_ending_label_v1(v_week.week_ending_date),
    'candidate_status_code',v_candidate_status_code,
    'list_membership',jsonb_build_object(
      'tab_bucket',v_tab_bucket,
      'effective_current_week_ending_date',v_effective_current_week_ending_date,
      'paid_current_cutoff_utc',p_now_utc-interval '7 days'
    ),
    'primary_action',v_primary_action,
    'available_actions',coalesce(v_action_contract->'available_actions','[]'::jsonb),
    'manager_approval',v_action_contract->'manager_approval',
    'paper_pack',v_action_contract->'paper_pack',
    'contract_week',jsonb_build_object(
      'id',v_week.id,'contract_id',v_contract.id,'week_ending_date',v_week.week_ending_date,
      'week_ending_weekday',btrim(to_char(v_week.week_ending_date,'FMDay')),
      'client_name',v_client.name,'job_title',v_contract.role,'band',v_contract.band,
      'additional_seq',v_week.additional_seq,'status',v_week.status,'planned_schedule_json',v_week.planned_schedule_json
    ),
    'timesheet',case when v_timesheet.timesheet_id is null then null else jsonb_build_object(
      'id',v_timesheet.timesheet_id,'status',v_timesheet.status,'submission_mode',v_timesheet.submission_mode,
      'sheet_scope',v_timesheet.sheet_scope,'actual_schedule_json',v_timesheet.actual_schedule_json,
      'additional_units_week',v_timesheet.additional_units_week,'qr_status',v_timesheet.qr_status,
      'canonical_work_date',case when v_timesheet.sheet_scope='DAILY' then private._candidate_daily_work_date_v1(
        v_timesheet.worked_start_iso,v_timesheet.scheduled_start_iso,v_timesheet.week_ending_date) else null end
    ) end,
    'hours',jsonb_build_object('total_hours',coalesce(v_fin.total_hours,0),'actual_schedule_json',v_fin.actual_schedule_json),
    'expenses',jsonb_build_object(
      'expenses_pay_ex_vat',coalesce(v_fin.expenses_pay_ex_vat,0),'expenses_description',v_fin.expenses_description,
      'mileage_units',coalesce(v_fin.mileage_units,0),'mileage_pay_ex_vat',coalesce(v_fin.mileage_pay_ex_vat,0),
      'travel_pay_ex_vat',coalesce(v_fin.travel_pay_ex_vat,0),
      'accommodation_pay_ex_vat',coalesce(v_fin.accommodation_pay_ex_vat,0),
      'other_pay_ex_vat',coalesce(v_fin.other_pay_ex_vat,0)
    ),
    'lifecycle',jsonb_build_object(
      'processing_status',v_fin.processing_status,'authorised_at_utc',v_fin.authorised_at_utc,
      'paid_at_utc',v_fin.paid_at_utc,'invoice_locked',v_fin.locked_by_invoice_id is not null
    ),
    'capabilities',v_capabilities,
    'manager_review',coalesce(v_document_state,'{}'::jsonb),
    'evidence',v_evidence,
    'components',v_components,
    'workflows',v_claims,
    'rejections',(
      select coalesce(jsonb_agg(workflow_item order by
        workflow_item->>'updated_at_utc' desc,workflow_item->>'workflow_id'),'[]'::jsonb)
      from jsonb_array_elements(v_claims) workflow_item
      where workflow_item->>'state'='REJECTED'
        and coalesce((workflow_item->>'rejection_actionable')::boolean,false)
    )
  );
end;
$function$;

-- candidate_app_timesheet_page_v1(uuid,text,text,text,integer,timestamp with time zone)
CREATE OR REPLACE FUNCTION public.candidate_app_timesheet_page_v1(p_session_id uuid, p_environment text, p_view text DEFAULT 'CURRENT'::text, p_cursor text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_now_utc timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
declare
  v_context jsonb;
  v_candidate_id uuid;
  v_view text:=upper(btrim(coalesce(p_view,'CURRENT')));
  v_snapshot_utc timestamptz:=p_now_utc;
  v_limit integer:=least(greatest(coalesce(p_limit,50),1),100);
  v_cursor_parts text[];
  v_cursor_view text;
  v_cursor_snapshot timestamptz;
  v_cursor_candidate_id uuid;
  v_cursor_date date;
  v_cursor_contract_id uuid;
  v_cursor_additional_seq integer;
  v_cursor_id uuid;
  v_rows jsonb;
  v_next_cursor text;
  v_conflicts jsonb;
begin
  if v_view not in ('CURRENT','HISTORY') then
    raise exception 'CANDIDATE_VIEW_INVALID' using errcode='22023';
  end if;
  perform private._candidate_require_feature_v1(p_environment,'candidate_app_reads');
  v_context:=private._candidate_session_context_v1(p_session_id,p_environment,null,p_now_utc,false);
  v_candidate_id:=nullif(v_context->>'selected_candidate_id','')::uuid;
  if v_candidate_id is null then raise exception 'CANDIDATE_SELECTION_REQUIRED' using errcode='28000'; end if;

  if nullif(btrim(coalesce(p_cursor,'')),'') is not null then
    begin
      v_cursor_parts:=string_to_array(p_cursor,'|');
      if cardinality(v_cursor_parts)<>8 then
        raise exception 'CANDIDATE_CURSOR_INVALID' using errcode='22023';
      end if;
      if v_cursor_parts[1]<>'v2' then
        raise exception 'CANDIDATE_CURSOR_VERSION_UNSUPPORTED' using errcode='22023';
      end if;
      v_cursor_view:=upper(v_cursor_parts[2]);
      v_cursor_snapshot:=v_cursor_parts[3]::timestamptz;
      v_cursor_candidate_id:=v_cursor_parts[4]::uuid;
      v_cursor_date:=v_cursor_parts[5]::date;
      v_cursor_contract_id:=v_cursor_parts[6]::uuid;
      v_cursor_additional_seq:=v_cursor_parts[7]::integer;
      v_cursor_id:=v_cursor_parts[8]::uuid;
    exception when others then
      if sqlerrm in (
        'CANDIDATE_CURSOR_VERSION_UNSUPPORTED','CANDIDATE_CURSOR_INVALID'
      ) then raise; end if;
      raise exception 'CANDIDATE_CURSOR_INVALID' using errcode='22023';
    end;
    if v_cursor_view<>v_view then
      raise exception 'CANDIDATE_CURSOR_VIEW_MISMATCH' using errcode='22023';
    end if;
    if v_cursor_candidate_id<>v_candidate_id then
      raise exception 'CANDIDATE_CURSOR_CANDIDATE_MISMATCH' using errcode='22023';
    end if;
    if v_cursor_snapshot is null or v_cursor_snapshot>p_now_utc+interval '1 minute' then
      raise exception 'CANDIDATE_CURSOR_SNAPSHOT_INVALID' using errcode='22023';
    end if;
    if v_cursor_snapshot<p_now_utc-interval '24 hours' then
      raise exception 'CANDIDATE_CURSOR_EXPIRED' using errcode='22023';
    end if;
    v_snapshot_utc:=v_cursor_snapshot;
  end if;

  with candidate_weeks as materialized (
    select cw.*,c.client_id,c.candidate_id,c.weekly_timesheet_source,
           client.name as client_name,
           coalesce(nullif(t.job_title_norm,''),nullif(c.role,'')) as display_job_title,
           coalesce(nullif(t.band,''),nullif(c.band,'')) as display_band,
           coalesce(c.week_ending_weekday_snapshot,effective_client.week_ending_weekday,0) as effective_week_ending_weekday,
           current_window.current_week_ending_date,
           t.booking_id,t.parent_timesheet_id,t.status as timesheet_status,t.submission_mode,t.line_type,t.sheet_scope,t.is_current,
           t.additional_units_week,t.additional_units_per_day,
           tf.additional_units_json,tf.total_hours,tf.processing_status,tf.authorised_at_utc,tf.paid_at_utc,tf.locked_by_invoice_id,
           tf.expenses_pay_ex_vat,tf.expenses_charge_ex_vat,
           tf.mileage_units,tf.mileage_pay_ex_vat,tf.mileage_charge_ex_vat,
           tf.travel_pay_ex_vat,tf.travel_charge_ex_vat,
           tf.accommodation_pay_ex_vat,tf.accommodation_charge_ex_vat,
           tf.other_pay_ex_vat,tf.other_charge_ex_vat,
           private._candidate_record_capabilities_v1(t.timesheet_id,cw.id,'{}'::jsonb) as capabilities
    from public.contract_weeks cw
    join public.contracts c on c.id=cw.contract_id and c.candidate_id=v_candidate_id
    join public.clients client on client.id=c.client_id
    left join lateral (
      select cs.week_ending_weekday
      from public.client_settings cs
      where cs.client_id=c.client_id
        and cs.effective_from<=(v_snapshot_utc at time zone 'Europe/London')::date
      order by cs.effective_from desc,cs.updated_at desc nulls last,cs.id desc
      limit 1
    ) effective_client on true
    cross join lateral (
      select (
        (v_snapshot_utc at time zone 'Europe/London')::date
        +mod(
          coalesce(c.week_ending_weekday_snapshot,effective_client.week_ending_weekday,0)
          -extract(dow from (v_snapshot_utc at time zone 'Europe/London')::date)::integer+7,
          7
        )
      )::date as current_week_ending_date
    ) current_window
    left join public.timesheets t on t.timesheet_id=cw.timesheet_id
    left join lateral (
      select f.* from public.timesheets_financials f
      where f.timesheet_id=t.timesheet_id and f.is_current=true
      order by f.computed_at_utc desc nulls last,f.updated_at desc,f.id desc limit 1
    ) tf on true
    where t.timesheet_id is null or (t.is_current=true and t.archived_at_utc is null)
  ), current_version_resolution as materialized (
    -- Candidate workflow and parent anchors are immutable historical UUIDs.
    -- Resolve every historical member through booking_id to the one current
    -- Candidate-safe row in that version family. A missing or ambiguous
    -- current member deliberately resolves to NULL so the caller fails closed.
    select history.timesheet_id as historical_timesheet_id,
      count(distinct current_week.timesheet_id)::integer as current_count,
      case when count(distinct current_week.timesheet_id)=1
        then min(current_week.timesheet_id::text)::uuid else null::uuid end
        as current_timesheet_id
    from public.timesheets history
    join public.timesheets current_row
      on nullif(btrim(coalesce(current_row.booking_id,'')),'')
        =nullif(btrim(coalesce(history.booking_id,'')),'')
      and current_row.contract_id is not distinct from history.contract_id
      and current_row.week_ending_date is not distinct from history.week_ending_date
      and current_row.is_current=true
      and current_row.archived_at_utc is null
    join candidate_weeks current_week
      on current_week.timesheet_id=current_row.timesheet_id
    where nullif(btrim(coalesce(history.booking_id,'')),'') is not null
    group by history.timesheet_id
  ), expense_carriers as materialized (
    select expense_row.*,
      abs(coalesce(expense_row.expenses_pay_ex_vat,0))+abs(coalesce(expense_row.expenses_charge_ex_vat,0))+
      abs(coalesce(expense_row.mileage_units,0))+abs(coalesce(expense_row.mileage_pay_ex_vat,0))+
      abs(coalesce(expense_row.mileage_charge_ex_vat,0))+
      abs(coalesce(expense_row.travel_pay_ex_vat,0))+abs(coalesce(expense_row.travel_charge_ex_vat,0))+
      abs(coalesce(expense_row.accommodation_pay_ex_vat,0))+abs(coalesce(expense_row.accommodation_charge_ex_vat,0))+
      abs(coalesce(expense_row.other_pay_ex_vat,0))+abs(coalesce(expense_row.other_charge_ex_vat,0)) as expense_value
    from candidate_weeks expense_row
    where expense_row.capabilities->>'record_role'='EXPENSE_ONLY'
       or upper(coalesce(expense_row.line_type::text,'')) in ('EXPENSES','MILEAGE')
  ), expense_carrier_resolution as materialized (
    select carrier.id as carrier_contract_week_id,carrier.timesheet_id as carrier_timesheet_id,
      carrier.contract_id,carrier.week_ending_date,
      case when workflow_anchor.workflow_count>1 then null::uuid
        when workflow_anchor.workflow_count=1 and workflow_anchor.timesheet_id is null then null::uuid
        when workflow_anchor.timesheet_id is not null then workflow_anchor.timesheet_id
        when carrier.parent_timesheet_id is not null and parent_anchor.timesheet_id is null then null::uuid
        when parent_anchor.timesheet_id is not null then parent_anchor.timesheet_id
        when base_anchor.anchor_count>1 then null::uuid
        when base_anchor.timesheet_id is not null then base_anchor.timesheet_id
        when additional_anchor.anchor_count>1 then null::uuid
        else coalesce(parent_anchor.timesheet_id,additional_anchor.timesheet_id) end as display_timesheet_id,
      case
        when workflow_anchor.workflow_count>1 then 'AMBIGUOUS_WORKFLOW_ANCHOR'
        when workflow_anchor.workflow_count=1 and workflow_anchor.timesheet_id is null then 'INVALID_WORKFLOW_ANCHOR'
        when carrier.parent_timesheet_id is not null and parent_anchor.timesheet_id is null then 'INVALID_PARENT_ANCHOR'
        when base_anchor.anchor_count>1 then 'EXPENSE_DISPLAY_ANCHOR_AMBIGUOUS'
        when base_anchor.timesheet_id is null and additional_anchor.anchor_count>1 then 'EXPENSE_DISPLAY_ANCHOR_AMBIGUOUS'
        when coalesce(workflow_anchor.timesheet_id,parent_anchor.timesheet_id,base_anchor.timesheet_id,additional_anchor.timesheet_id) is null
          and carrier.expense_value<>0 then 'EXPENSE_DISPLAY_ANCHOR_NOT_FOUND'
        else null end as conflict_code,
      carrier.expenses_pay_ex_vat,carrier.mileage_pay_ex_vat,carrier.travel_pay_ex_vat,
      carrier.accommodation_pay_ex_vat,carrier.other_pay_ex_vat,carrier.expense_value
    from expense_carriers carrier
    left join lateral (
      select count(distinct workflow.id)::integer as workflow_count,
        min(anchor_row.timesheet_id::text)::uuid as timesheet_id
      from public.candidate_submission_workflows workflow
      left join current_version_resolution workflow_anchor_family
        on workflow_anchor_family.historical_timesheet_id=workflow.anchor_timesheet_id
      left join candidate_weeks anchor_row
        on anchor_row.timesheet_id=coalesce(
          workflow_anchor_family.current_timesheet_id,workflow.anchor_timesheet_id
        )
        and anchor_row.contract_id=carrier.contract_id
        and anchor_row.week_ending_date=carrier.week_ending_date
        and anchor_row.capabilities->>'record_role'<>'EXPENSE_ONLY'
      where workflow.candidate_id=v_candidate_id
        and workflow.contract_id=carrier.contract_id
        and workflow.week_ending_date=carrier.week_ending_date
        and (workflow.target_timesheet_id=carrier.timesheet_id or workflow.contract_week_id=carrier.id)
        and workflow.state not in ('CANCELLED','SUPERSEDED','REJECTED')
    ) workflow_anchor on true
    left join lateral (
      select parent_row.timesheet_id
      from candidate_weeks parent_row
      left join current_version_resolution parent_family
        on parent_family.historical_timesheet_id=carrier.parent_timesheet_id
      where parent_row.timesheet_id=coalesce(
          parent_family.current_timesheet_id,carrier.parent_timesheet_id
        )
        and parent_row.contract_id=carrier.contract_id
        and parent_row.week_ending_date=carrier.week_ending_date
        and parent_row.capabilities->>'record_role'<>'EXPENSE_ONLY'
      limit 1
    ) parent_anchor on true
    left join lateral (
      select count(*)::integer as anchor_count,
        min(hours_row.timesheet_id::text)::uuid as timesheet_id
      from candidate_weeks hours_row
      where hours_row.contract_id=carrier.contract_id
        and hours_row.week_ending_date=carrier.week_ending_date
        and hours_row.additional_seq=0
        and (
          coalesce(hours_row.total_hours,0)>0
          or private._candidate_json_numeric_sum(coalesce(hours_row.additional_units_json,'{}'::jsonb))>0
          or private._candidate_json_numeric_sum(coalesce(hours_row.additional_units_week,'{}'::jsonb))
            +private._candidate_json_numeric_sum(coalesce(hours_row.additional_units_per_day,'{}'::jsonb))>0
        )
        and hours_row.capabilities->>'record_role'<>'EXPENSE_ONLY'
    ) base_anchor on true
    left join lateral (
      select count(*)::integer as anchor_count,
        min(hours_row.timesheet_id::text)::uuid as timesheet_id
      from candidate_weeks hours_row
      where hours_row.contract_id=carrier.contract_id
        and hours_row.week_ending_date=carrier.week_ending_date
        and hours_row.additional_seq>0
        and (
          coalesce(hours_row.total_hours,0)>0
          or private._candidate_json_numeric_sum(coalesce(hours_row.additional_units_json,'{}'::jsonb))>0
          or private._candidate_json_numeric_sum(coalesce(hours_row.additional_units_week,'{}'::jsonb))
            +private._candidate_json_numeric_sum(coalesce(hours_row.additional_units_per_day,'{}'::jsonb))>0
        )
        and hours_row.capabilities->>'record_role'<>'EXPENSE_ONLY'
    ) additional_anchor on true
  ), expense_anchor_totals as materialized (
    select display_timesheet_id,
      sum(expenses_pay_ex_vat) expenses_pay_ex_vat,
      sum(mileage_pay_ex_vat) mileage_pay_ex_vat,
      sum(travel_pay_ex_vat) travel_pay_ex_vat,
      sum(accommodation_pay_ex_vat) accommodation_pay_ex_vat,
      sum(other_pay_ex_vat) other_pay_ex_vat
    from expense_carrier_resolution
    where display_timesheet_id is not null and conflict_code is null
    group by display_timesheet_id
  ), workflow_overlay as materialized (
    select resolved.display_timesheet_id,
      jsonb_agg(jsonb_build_object(
        'workflow_id',resolved.id,'workflow_kind',resolved.workflow_kind,'state',resolved.state,
        'claim_family',resolved.claim_family,
        'target_timesheet_id',resolved.target_timesheet_id,'anchor_timesheet_id',resolved.anchor_timesheet_id,
        'rejection_reason',resolved.rejection_reason,'rejection_scope',resolved.rejection_scope,
        'required_resubmission_action',case
          when resolved.state<>'REJECTED' or not resolved.rejection_actionable then null
          when resolved.workflow_kind='CONTRACT_EXPENSE'
            or resolved.rejection_scope='COMPLETE_EXPENSE_CLAIM'
            then 'RESUBMIT_EXPENSE_CLAIM'
          when resolved.workflow_kind='CONTRACT_COMBINED'
            then 'RESUBMIT_TIMESHEET_AND_EXPENSES'
          else 'RESUBMIT_TIMESHEET' end,
        'rejection_actionable',resolved.rejection_actionable,
        'updated_at_utc',resolved.updated_at_utc
      ) order by resolved.updated_at_utc desc,resolved.id) as workflows
    from (
      select classified.*,
        case
          -- Rejection rotates the submitted timesheet to a replacement current
          -- version while the immutable workflow continues to reference the
          -- historical submitted target. Resolve rejected workflows through the
          -- current contract-week authority so the Candidate card retains the
          -- rejection reason, scope and server-owned recovery action.
          when classified.state='REJECTED'
            and classified.claim_family='EXPENSES' then (
            select resolution.display_timesheet_id
            from expense_carrier_resolution resolution
            where resolution.carrier_contract_week_id=classified.contract_week_id
              and resolution.conflict_code is null
            limit 1
          )
          when classified.state='REJECTED' then (
            select current_week.timesheet_id
            from candidate_weeks current_week
            where current_week.id=classified.contract_week_id
            limit 1
          )
          when classified.claim_family='EXPENSES' then coalesce(
          (select resolution.display_timesheet_id from expense_carrier_resolution resolution
            where resolution.carrier_timesheet_id=classified.target_timesheet_id limit 1),
          (select family.current_timesheet_id from current_version_resolution family
            where family.historical_timesheet_id=classified.anchor_timesheet_id
              and family.current_count=1),
          (select direct_anchor.timesheet_id from candidate_weeks direct_anchor
            where direct_anchor.timesheet_id=classified.anchor_timesheet_id limit 1)
          )
          else coalesce(
            (select family.current_timesheet_id from current_version_resolution family
              where family.historical_timesheet_id=coalesce(
                classified.target_timesheet_id,classified.anchor_timesheet_id
              ) and family.current_count=1),
            (select direct_target.timesheet_id from candidate_weeks direct_target
              where direct_target.timesheet_id=coalesce(
                classified.target_timesheet_id,classified.anchor_timesheet_id
              ) limit 1)
          )
        end as display_timesheet_id
      from (
        select w.*,
          case when w.workflow_kind='CONTRACT_EXPENSE'
              or w.rejection_scope='COMPLETE_EXPENSE_CLAIM'
            then 'EXPENSES' else 'HOURS' end as claim_family,
          case when w.state<>'REJECTED' then false
            else not private._candidate_rejection_replaced_v1(w.id)
          end as rejection_actionable
        from public.candidate_submission_workflows w
        where w.candidate_id=v_candidate_id and w.state<>'SUPERSEDED'
      ) classified
    ) resolved
    where resolved.display_timesheet_id is not null
    group by resolved.display_timesheet_id
  ), visible as materialized (
    select base.*,
      coalesce(totals.expenses_pay_ex_vat,0) as overlay_expenses_pay_ex_vat,
      coalesce(totals.mileage_pay_ex_vat,0) as overlay_mileage_pay_ex_vat,
      coalesce(totals.travel_pay_ex_vat,0) as overlay_travel_pay_ex_vat,
      coalesce(totals.accommodation_pay_ex_vat,0) as overlay_accommodation_pay_ex_vat,
      coalesce(totals.other_pay_ex_vat,0) as overlay_other_pay_ex_vat,
      coalesce(workflows.workflows,'[]'::jsonb) as workflows,
      null::text as expense_overlay_conflict_code,
      membership.tab_bucket
    from candidate_weeks base
    left join expense_anchor_totals totals on totals.display_timesheet_id=base.timesheet_id
    left join workflow_overlay workflows on workflows.display_timesheet_id=base.timesheet_id
    cross join lateral (
      select case
        when base.paid_at_utc is null or base.paid_at_utc>v_snapshot_utc then 'CURRENT'
        when base.paid_at_utc>=v_snapshot_utc-interval '7 days' then 'CURRENT'
        when base.paid_at_utc<v_snapshot_utc-interval '7 days'
          and base.week_ending_date between base.current_week_ending_date-105
            and base.current_week_ending_date then 'HISTORY'
        else 'EXCLUDED' end as tab_bucket
    ) membership
    where not exists(select 1 from expense_carriers carrier where carrier.id=base.id)
      and base.week_ending_date<=base.current_week_ending_date
      and membership.tab_bucket=v_view
      and (
        v_cursor_date is null
        or (
          base.week_ending_date,
          base.contract_id,
          base.additional_seq,
          base.id
        )<(v_cursor_date,v_cursor_contract_id,v_cursor_additional_seq,v_cursor_id)
      )
  ), page as materialized (
    select * from visible
    order by week_ending_date desc,contract_id desc,additional_seq desc,id desc
    limit v_limit+1
  ), delivered as materialized (
    select page.*,
      (
        select workflow_item->>'state'
        from jsonb_array_elements(page.workflows) workflow_item
        where workflow_item->>'state' in (
          'CREATED','WORKER_DRAFT','WORKER_SUBMITTED',
          'WORKER_SUBMITTED_PENDING_REVIEW_DOCUMENT','READY_FOR_MANAGER_APPROVAL',
          'AWAITING_MANAGER_APPROVAL','MANAGER_APPROVED',
          'MANAGER_APPROVED_PENDING_FINAL_DOCUMENT','READY_TO_FINALISE',
          'AWAITING_PAPER_RETURN','RECEIVED','REFUSED'
        )
        limit 1
      ) as active_workflow_state,
      (
        select workflow_item
        from jsonb_array_elements(page.workflows) workflow_item
        where workflow_item->>'state'='REJECTED'
          and coalesce((workflow_item->>'rejection_actionable')::boolean,false)
        limit 1
      ) as rejected_workflow,
      (
        select coalesce(jsonb_agg(workflow_item order by
          workflow_item->>'updated_at_utc' desc,workflow_item->>'workflow_id'),'[]'::jsonb)
        from jsonb_array_elements(page.workflows) workflow_item
        where workflow_item->>'state'='REJECTED'
          and coalesce((workflow_item->>'rejection_actionable')::boolean,false)
      ) as actionable_rejections
    from page
    order by week_ending_date desc,contract_id desc,additional_seq desc,id desc
    limit v_limit
  )
  select
    coalesce(jsonb_agg(jsonb_build_object(
      'contract_week_id',d.id,
      'contract_id',d.contract_id,
      'timesheet_id',d.timesheet_id,
      'client_name',d.client_name,
      'job_title',d.display_job_title,
      'band',d.display_band,
      'week_ending_date',d.week_ending_date,
      'week_ending_label',private._candidate_week_ending_label_v1(d.week_ending_date),
      'week_ending_weekday',btrim(to_char(d.week_ending_date,'FMDay')),
      'additional_seq',d.additional_seq,
      'tab_bucket',d.tab_bucket,
      'effective_current_week_ending_date',d.current_week_ending_date,
      'paid_at_utc',case when d.paid_at_utc<=v_snapshot_utc then d.paid_at_utc else null end,
      'contract_week_status',d.status,
      'timesheet_status',d.timesheet_status,
      'processing_status',d.processing_status,
      'paid',d.paid_at_utc is not null and d.paid_at_utc<=v_snapshot_utc,
      'authorised',d.authorised_at_utc is not null,
      'total_hours',coalesce(d.total_hours,0),
      'expenses',jsonb_build_object(
        'expenses_pay_ex_vat',coalesce(d.overlay_expenses_pay_ex_vat,0),
        'mileage_pay_ex_vat',coalesce(d.overlay_mileage_pay_ex_vat,0),
        'travel_pay_ex_vat',coalesce(d.overlay_travel_pay_ex_vat,0),
        'accommodation_pay_ex_vat',coalesce(d.overlay_accommodation_pay_ex_vat,0),
        'other_pay_ex_vat',coalesce(d.overlay_other_pay_ex_vat,0)
      ),
      'expense_overlay_conflict_code',d.expense_overlay_conflict_code,
      'workflows',d.workflows,
      'rejections',d.actionable_rejections,
      'record_role',d.capabilities->'record_role',
      'route_family',d.capabilities->'route_family',
      'candidate_status_code',private._candidate_status_code_v1(
        d.paid_at_utc is not null and d.paid_at_utc<=v_snapshot_utc,
        d.authorised_at_utc is not null,
        d.locked_by_invoice_id is not null
          or upper(coalesce(d.timesheet_status::text,''))='INVOICED',
        d.active_workflow_state,d.rejected_workflow is not null,
        d.processing_status::text,d.status::text
      ),
      'payment_state',case when d.paid_at_utc is not null and d.paid_at_utc<=v_snapshot_utc
        then 'PAID' else 'UNPAID' end,
      'invoice_state',case
        when d.paid_at_utc is not null and d.paid_at_utc<=v_snapshot_utc then 'PAID'
        when d.locked_by_invoice_id is not null or upper(coalesce(d.timesheet_status::text,''))='INVOICED'
          then 'INVOICED_NOT_PAID'
        else 'NOT_INVOICED' end,
      'manager_approval_state',(
        select workflow_item->>'state'
        from jsonb_array_elements(d.workflows) workflow_item
        where workflow_item->>'state' in (
          'READY_FOR_MANAGER_APPROVAL','AWAITING_MANAGER_APPROVAL','MANAGER_APPROVED',
          'MANAGER_APPROVED_PENDING_FINAL_DOCUMENT','READY_TO_FINALISE','FINALISED','REFUSED'
        )
        limit 1
      ),
      'rejection_reason',case
        when (d.paid_at_utc is not null and d.paid_at_utc<=v_snapshot_utc) or d.authorised_at_utc is not null
          or d.locked_by_invoice_id is not null
          or upper(coalesce(d.timesheet_status::text,''))='INVOICED' then null
        else nullif(d.rejected_workflow->>'rejection_reason','') end,
      'rejection_scope',case
        when (d.paid_at_utc is not null and d.paid_at_utc<=v_snapshot_utc) or d.authorised_at_utc is not null
          or d.locked_by_invoice_id is not null
          or upper(coalesce(d.timesheet_status::text,''))='INVOICED'
          or d.rejected_workflow is null then d.capabilities->'reject_scope'
        else d.rejected_workflow->'rejection_scope' end,
      'rejection',case
        when (d.paid_at_utc is not null and d.paid_at_utc<=v_snapshot_utc) or d.authorised_at_utc is not null
          or d.locked_by_invoice_id is not null
          or upper(coalesce(d.timesheet_status::text,''))='INVOICED'
          or d.rejected_workflow is null then null
        else jsonb_build_object(
          'workflow_id',d.rejected_workflow->'workflow_id',
          'reason',d.rejected_workflow->'rejection_reason',
          'scope',d.rejected_workflow->'rejection_scope',
          'required_action',d.rejected_workflow->'required_resubmission_action'
        ) end,
      'primary_action',private._candidate_action_invocation_v1(private._candidate_timesheet_primary_action_v1(
        private._candidate_status_code_v1(
          d.paid_at_utc is not null and d.paid_at_utc<=v_snapshot_utc,
          d.authorised_at_utc is not null,
          d.locked_by_invoice_id is not null
            or upper(coalesce(d.timesheet_status::text,''))='INVOICED',
          d.active_workflow_state,d.rejected_workflow is not null,
          d.processing_status::text,d.status::text
        ),
        d.workflows,d.capabilities,d.timesheet_id,d.id
      )),
      'detail_target',case
        when d.rejected_workflow is not null then jsonb_build_object(
          'identity_kind','WORKFLOW','id',d.rejected_workflow->>'workflow_id',
          'path','/candidate-app/v1/workflows/'||(d.rejected_workflow->>'workflow_id')||'/timesheet-detail'
        )
        when d.timesheet_id is not null then jsonb_build_object(
          'identity_kind','TIMESHEET','id',d.timesheet_id,
          'path','/candidate-app/v1/timesheets/'||d.timesheet_id::text
        )
        else jsonb_build_object(
          'identity_kind','CONTRACT_WEEK','id',d.id,
          'path','/candidate-app/v1/contract-weeks/'||d.id::text||'/detail'
        ) end,
      'actions',jsonb_build_object(
        'can_edit_hours',d.capabilities->'can_edit_hours',
        'can_edit_expenses',d.capabilities->'can_edit_expenses',
        'candidate_paper_submission_allowed',d.capabilities->'candidate_paper_submission_allowed',
        'candidate_no_work_allowed',d.capabilities->'candidate_no_work_allowed',
        'can_reject_candidate_submission',d.capabilities->'can_reject_candidate_submission',
        'reject_scope',d.capabilities->'reject_scope'
      )
    ) order by d.week_ending_date desc,d.contract_id desc,d.additional_seq desc,d.id desc),'[]'::jsonb),
    case when (select count(*) from page)>v_limit then
      (select 'v2|'||v_view||'|'||to_char(v_snapshot_utc at time zone 'UTC',
          'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')||'|'||v_candidate_id::text||'|'
          ||p.week_ending_date::text||'|'||p.contract_id::text||'|'
          ||p.additional_seq::text||'|'||p.id::text
       from delivered p
       order by p.week_ending_date asc,p.contract_id asc,p.additional_seq asc,p.id asc limit 1)
    else null end,
    (
      select coalesce(jsonb_agg(jsonb_build_object(
        'contract_id',conflict.contract_id,
        'week_ending_date',conflict.week_ending_date,
        'code',conflict.conflict_code
      ) order by conflict.week_ending_date desc,conflict.contract_id),'[]'::jsonb)
      from expense_carrier_resolution conflict
      where conflict.conflict_code is not null
    )
  into v_rows,v_next_cursor,v_conflicts
  from delivered d;

  return jsonb_build_object(
    'ok',true,
    'view',v_view,
    'default_view','CURRENT',
    'snapshot_utc',v_snapshot_utc,
    'paid_current_cutoff_utc',v_snapshot_utc-interval '7 days',
    'items',v_rows,
    'next_cursor',v_next_cursor,
    'cursor_version','v2',
    'readiness_conflicts',coalesce(v_conflicts,'[]'::jsonb),
    'limit',v_limit
  );
end;
$function$;

-- candidate_auth_account_transition_v1(text,text,uuid,text,uuid,uuid,jsonb,text,timestamp with time zone)
CREATE OR REPLACE FUNCTION public.candidate_auth_account_transition_v1(p_action text, p_environment text, p_account_id uuid DEFAULT NULL::uuid, p_email_normalized text DEFAULT NULL::text, p_session_id uuid DEFAULT NULL::uuid, p_selected_candidate_id uuid DEFAULT NULL::uuid, p_payload jsonb DEFAULT '{}'::jsonb, p_idempotency_key text DEFAULT NULL::text, p_now_utc timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
declare
  v_action text:=upper(btrim(coalesce(p_action,'')));
  v_environment text;
  v_email text:=private._candidate_normalize_email(p_email_normalized);
  v_payload jsonb:=coalesce(p_payload,'{}'::jsonb);
  v_account public.candidate_app_accounts%rowtype;
  v_session public.candidate_app_sessions%rowtype;
  v_new_session public.candidate_app_sessions%rowtype;
  v_challenge public.candidate_auth_challenges%rowtype;
  v_notification public.candidate_notifications%rowtype;
  v_eligibility jsonb;
  v_context jsonb;
  v_candidate_ids jsonb;
  v_match_count integer;
  v_salt bytea;
  v_digest bytea;
  v_refresh_hash bytea;
  v_presented_refresh_hash bytea;
  v_device_hash bytea;
  v_expires timestamptz;
  v_absolute timestamptz;
  v_new_session_id uuid;
  v_preferences jsonb;
  v_audit_action text;
  v_idempotent_action boolean:=false;
  v_replay_probe_only boolean:=false;
  v_reserve_request_key_version boolean:=false;
  v_request_sha256 text;
  v_request_key_version integer;
  v_reservation_identity_sha256 text;
  v_public_credential_versions jsonb;
  v_receipt_metadata jsonb:='{}'::jsonb;
  v_receipt jsonb;
  v_response jsonb;
  v_account_id uuid;
  v_live_session_count integer;
  v_expected_password_authority_sha256 text;
  v_current_password_authority_sha256 text;
  v_presented_password_digest bytea;
  v_password_authority_current boolean:=false;
  v_password_matches_current boolean:=false;
  v_private_login_failed boolean:=false;
  v_failed_login_recorded boolean:=false;
begin
  v_environment:=private._candidate_assert_environment(p_environment);
  perform private._candidate_require_feature_v1(v_environment,'candidate_account_registration');
  if jsonb_typeof(v_payload)<>'object' then
    raise exception 'CANDIDATE_AUTH_PAYLOAD_INVALID' using errcode='22023';
  end if;
  if v_payload ?| array['password','plaintext_password','refresh_token','token'] then
    raise exception 'CANDIDATE_AUTH_PLAINTEXT_SECRET_FORBIDDEN' using errcode='22023';
  end if;
  if v_payload ? 'public_credential_versions' then
    v_public_credential_versions:=v_payload->'public_credential_versions';
    if jsonb_typeof(v_public_credential_versions)<>'object'
       or coalesce(v_public_credential_versions->>'contract_version','')
            <>'CANDIDATE_PUBLIC_CREDENTIAL_VERSIONS_V1'
       or coalesce(v_public_credential_versions->>'access_key_version','') !~ '^[1-9][0-9]{0,4}$'
       or coalesce(v_public_credential_versions->>'refresh_key_version','') !~ '^[1-9][0-9]{0,4}$'
       or coalesce(v_public_credential_versions->>'public_session_key_version','') !~ '^[1-9][0-9]{0,4}$'
       or (v_public_credential_versions->>'access_key_version')::integer>65535
       or (v_public_credential_versions->>'refresh_key_version')::integer>65535
       or (v_public_credential_versions->>'public_session_key_version')::integer>65535 then
      raise exception 'CANDIDATE_BROKER_CREDENTIAL_VERSION_INVALID' using errcode='22023';
    end if;
  end if;

  v_idempotent_action:=v_action in (
    'ACTIVATE_PASSWORD','LOGIN_SUCCESS','REFRESH_SESSION','LOGOUT',
    'SELECT_TEST_CANDIDATE','SET_NOTIFICATION_PREFERENCES',
    'REGISTER_PUSH_TOKEN','CHANGE_PASSWORD','MARK_NOTIFICATION_READ'
  );
  if v_idempotent_action then
    if nullif(btrim(coalesce(p_idempotency_key,'')),'') is null
       or length(btrim(p_idempotency_key))>200 then
      raise exception 'CANDIDATE_IDEMPOTENCY_KEY_REQUIRED' using errcode='22023';
    end if;
    v_replay_probe_only:=coalesce((v_payload->>'replay_probe_only')::boolean,false);
    v_reserve_request_key_version:=coalesce(
      (v_payload->>'reserve_request_key_version')::boolean,false
    );
    v_request_sha256:=nullif(lower(btrim(coalesce(v_payload->>'idempotency_request_sha256',''))),'');
    if v_request_sha256 is not null and v_request_sha256 !~ '^[0-9a-f]{64}$' then
      raise exception 'CANDIDATE_IDEMPOTENCY_RECEIPT_INVALID' using errcode='22023';
    end if;
    v_request_key_version:=coalesce(nullif(v_payload->>'idempotency_key_version','')::integer,1);
    if v_request_key_version<1 or v_request_key_version>32 then
      raise exception 'CANDIDATE_IDEMPOTENCY_RECEIPT_INVALID' using errcode='22023';
    end if;
    v_receipt_metadata:=jsonb_build_object('request_key_version',v_request_key_version);
    if v_replay_probe_only and v_request_sha256 is null
       and v_reserve_request_key_version then
      v_reservation_identity_sha256:=encode(extensions.digest(convert_to(
        jsonb_build_object(
          'contract_version','CANDIDATE_AUTH_REQUEST_VERSION_RESERVATION_V1',
          'action',v_action,
          'environment',v_environment,
          'account_id',p_account_id,
          'email_normalized',lower(nullif(btrim(coalesce(p_email_normalized,'')),'')),
          'session_id',p_session_id,
          'selected_candidate_id',p_selected_candidate_id
        )::text,'UTF8'),'sha256'),'hex');
      v_receipt_metadata:=v_receipt_metadata||jsonb_build_object(
        'reservation_identity_sha256',v_reservation_identity_sha256
      );
    end if;
    if v_action='REGISTER_PUSH_TOKEN'
       and coalesce(v_payload->>'push_token_identity_key_version','') ~ '^[1-9][0-9]{0,4}$'
       and (v_payload->>'push_token_identity_key_version')::integer<=65535 then
      v_receipt_metadata:=v_receipt_metadata||jsonb_build_object(
        'push_token_identity_key_version',
        (v_payload->>'push_token_identity_key_version')::integer
      );
    end if;
    v_receipt:=private._candidate_auth_mutation_receipt_v1(
      v_environment,p_idempotency_key,v_request_sha256,v_action,null,
      v_receipt_metadata||case
        when v_replay_probe_only and v_request_sha256 is null
          and v_reserve_request_key_version
        then jsonb_build_object('reserve_request_key_version',true)
        else '{}'::jsonb end,
      p_now_utc
    );
    if coalesce((v_receipt->>'found')::boolean,false) then
      if v_request_sha256 is null then
        return jsonb_strip_nulls(jsonb_build_object(
          'ok',true,
          'replay_receipt_found',coalesce(
            (v_receipt->>'response_recorded')::boolean,false
          ),
          'request_version_reserved',true,
          'request_key_version',coalesce(
            nullif(v_receipt#>>'{metadata,request_key_version}','')::integer,1
          ),
          'push_token_identity_key_version',
            nullif(v_receipt#>>'{metadata,push_token_identity_key_version}','')::integer
        ));
      end if;
      return coalesce(v_receipt->'response','{}'::jsonb);
    end if;
    if v_replay_probe_only then
      return jsonb_strip_nulls(jsonb_build_object(
        'ok',true,'replay_receipt_found',false,
        'request_version_reserved',coalesce((v_receipt->>'reserved')::boolean,false),
        'request_key_version',coalesce(
          nullif(v_receipt#>>'{metadata,request_key_version}','')::integer,
          v_request_key_version
        ),
        'push_token_identity_key_version',coalesce(
          nullif(v_receipt#>>'{metadata,push_token_identity_key_version}','')::integer,
          nullif(v_receipt_metadata->>'push_token_identity_key_version','')::integer
        )
      ));
    end if;
    if v_request_sha256 is null then
      raise exception 'CANDIDATE_IDEMPOTENCY_RECEIPT_INVALID' using errcode='22023';
    end if;
  end if;

  if v_action in ('ACTIVATE_PASSWORD','CHANGE_PASSWORD') then
    if coalesce(v_payload->>'password_salt_hex','') !~ '^[0-9a-fA-F]{32,128}$'
       or length(v_payload->>'password_salt_hex')%2<>0
       or coalesce(v_payload->>'password_digest_hex','') !~ '^[0-9a-fA-F]+$'
       or length(v_payload->>'password_digest_hex') not between 64 and 256
       or length(v_payload->>'password_digest_hex')%2<>0
       or nullif(btrim(v_payload->>'password_scheme'),'') is null
       or coalesce(v_payload->>'password_scheme_version','') !~ '^[1-9][0-9]{0,4}$' then
      raise exception 'CANDIDATE_PASSWORD_VERIFIER_INVALID' using errcode='22023';
    end if;
    v_salt:=decode(v_payload->>'password_salt_hex','hex');
    v_digest:=decode(v_payload->>'password_digest_hex','hex');
  end if;

  if v_action='ACTIVATE_PASSWORD' then
    if coalesce(v_payload->>'challenge_id','') !~ '^[0-9a-fA-F-]{36}$' then
      raise exception 'CANDIDATE_VERIFIED_CHALLENGE_REQUIRED' using errcode='22023';
    end if;
    select * into v_challenge from public.candidate_auth_challenges
    where id=(v_payload->>'challenge_id')::uuid for update;
    if not found or v_challenge.environment<>v_environment
       or v_challenge.state<>'VERIFIED'
       or v_challenge.expires_at_utc<=p_now_utc
       or v_challenge.purpose not in ('ACTIVATE','RESET','RECOVERY') then
      raise exception 'CANDIDATE_VERIFIED_CHALLENGE_INVALID' using errcode='28000';
    end if;
    v_email:=v_challenge.email_normalized;
    v_eligibility:=private._candidate_email_eligibility_v1(v_environment,v_email);
    if coalesce((v_eligibility->>'eligible')::boolean,false)=false then
      raise exception 'CANDIDATE_ACCOUNT_NOT_ELIGIBLE' using errcode='28000';
    end if;
    if p_session_id is null
       or coalesce(v_payload->>'refresh_token_hash_hex','') !~ '^[0-9a-fA-F]{64}$' then
      raise exception 'CANDIDATE_ACTIVATION_SESSION_REQUIRED' using errcode='22023';
    end if;
    v_refresh_hash:=decode(v_payload->>'refresh_token_hash_hex','hex');
    v_expires:=coalesce(nullif(v_payload->>'expires_at_utc','')::timestamptz,p_now_utc+interval '30 days');
    v_absolute:=coalesce(nullif(v_payload->>'absolute_expires_at_utc','')::timestamptz,p_now_utc+interval '90 days');
    if v_expires>v_absolute or v_expires<=p_now_utc or v_absolute<=p_now_utc then
      raise exception 'CANDIDATE_SESSION_EXPIRY_INVALID' using errcode='22023';
    end if;
    v_candidate_ids:=v_eligibility->'candidate_ids';
    v_match_count:=coalesce((v_eligibility->>'match_count')::integer,0);
    if p_selected_candidate_id is null and v_match_count=1 then
      p_selected_candidate_id:=(v_candidate_ids->>0)::uuid;
    end if;
    if p_selected_candidate_id is not null and not exists(
      select 1 from public.candidates c where c.id=p_selected_candidate_id and c.active=true
        and lower(btrim(coalesce(c.email,'')))=v_email
    ) then raise exception 'CANDIDATE_SELECTION_NOT_ALLOWED' using errcode='28000'; end if;
    if v_environment='TEST' and v_match_count>1 and p_selected_candidate_id is null then
      raise exception 'CANDIDATE_SELECTION_REQUIRED' using errcode='28000';
    end if;
    if coalesce(v_payload->>'device_id_hash_hex','')~'^[0-9a-fA-F]{64}$' then
      v_device_hash:=decode(v_payload->>'device_id_hash_hex','hex');
    end if;

    -- Resolve the stable account identity without a row lock, acquire the
    -- shared account/session lock, then re-read the account authoritatively.
    -- New-account activation has no pre-existing sessions to serialize; once
    -- the row exists it acquires the same lock before creating its first one.
    select * into v_account from public.candidate_app_accounts
    where environment=v_environment and email_normalized=v_email;

    if found then
      v_account_id:=v_account.id;
      perform private._candidate_auth_account_session_lock_v1(
        v_environment,v_account_id
      );
      select * into v_account from public.candidate_app_accounts
      where id=v_account_id for update;
      if not found or v_account.environment<>v_environment
         or v_account.email_normalized<>v_email then
        raise exception 'CANDIDATE_ACCOUNT_NOT_ELIGIBLE' using errcode='28000';
      end if;
    end if;

    if v_account.id is null then
      if v_challenge.purpose<>'ACTIVATE' then
        raise exception 'CANDIDATE_ACCOUNT_NOT_ELIGIBLE' using errcode='28000';
      end if;
      insert into public.candidate_app_accounts(
        environment,email_normalized,status,password_scheme,password_scheme_version,
        password_salt,password_digest,password_params_json,password_changed_at_utc,
        failed_login_count,locked_until_utc,created_at_utc,updated_at_utc
      ) values (
        v_environment,v_email,'ACTIVE',btrim(v_payload->>'password_scheme'),
        (v_payload->>'password_scheme_version')::smallint,v_salt,v_digest,
        coalesce(v_payload->'password_params','{}'::jsonb),p_now_utc,0,null,p_now_utc,p_now_utc
      ) returning * into v_account;
      perform private._candidate_auth_account_session_lock_v1(
        v_environment,v_account.id
      );
      v_audit_action:='CANDIDATE_ACCOUNT_ACTIVATED';
    else
      if v_account.status='DISABLED' then raise exception 'CANDIDATE_ACCOUNT_DISABLED' using errcode='28000'; end if;
      update public.candidate_app_accounts set
        status='ACTIVE',password_scheme=btrim(v_payload->>'password_scheme'),
        password_scheme_version=(v_payload->>'password_scheme_version')::smallint,
        password_salt=v_salt,password_digest=v_digest,
        password_params_json=coalesce(v_payload->'password_params','{}'::jsonb),
        password_changed_at_utc=p_now_utc,failed_login_count=0,locked_until_utc=null,
        session_version=session_version+1,updated_at_utc=p_now_utc
      where id=v_account.id returning * into v_account;
      update public.candidate_app_sessions set status='REVOKED',revoked_at_utc=p_now_utc,
        revoke_reason='PASSWORD_REPLACED',updated_at_utc=p_now_utc
      where account_id=v_account.id and status='ACTIVE';
      v_audit_action:=case when v_challenge.purpose='ACTIVATE' then 'CANDIDATE_ACCOUNT_ACTIVATED' else 'CANDIDATE_PASSWORD_RESET' end;
    end if;

    update public.candidate_auth_challenges set state='CONSUMED',consumed_at_utc=p_now_utc,updated_at_utc=p_now_utc
    where id=v_challenge.id;
    insert into public.candidate_app_sessions(
      id,account_id,environment,selected_candidate_id,status,refresh_token_hash,token_family_id,
      rotation,issued_at_utc,expires_at_utc,absolute_expires_at_utc,last_used_at_utc,
      device_id_hash,platform,created_at_utc,updated_at_utc
    ) values (
      p_session_id,v_account.id,v_environment,p_selected_candidate_id,'ACTIVE',v_refresh_hash,gen_random_uuid(),
      0,p_now_utc,v_expires,v_absolute,p_now_utc,v_device_hash,
      nullif(btrim(v_payload->>'platform'),''),p_now_utc,p_now_utc
    ) returning * into v_new_session;
    select count(*) into v_live_session_count
    from public.candidate_app_sessions
    where account_id=v_account.id and status='ACTIVE';
    if v_live_session_count<>1 or not exists(
      select 1 from public.candidate_app_sessions
      where id=v_new_session.id and account_id=v_account.id and status='ACTIVE'
    ) then
      raise exception 'CANDIDATE_SESSION_INVALIDATION_INCOMPLETE'
        using errcode='40001';
    end if;
    perform private._candidate_audit_v1('candidate_app_account',v_account.id::text,v_audit_action,null,
      jsonb_build_object('status',v_account.status,'session_version',v_account.session_version,
        'session_id',v_new_session.id,'selected_candidate_id',v_new_session.selected_candidate_id),
      v_challenge.purpose,null,p_idempotency_key,p_now_utc);
    v_response:=jsonb_build_object(
      'ok',true,'account_id',v_account.id,'status',v_account.status,
      'session_version',v_account.session_version,'selection_required',v_eligibility->'selection_required',
      'candidate_ids',v_eligibility->'candidate_ids','session_id',v_new_session.id,
      'rotation',v_new_session.rotation,'selected_candidate_id',v_new_session.selected_candidate_id,
      'issued_at_utc',v_new_session.issued_at_utc,
      'expires_at_utc',v_new_session.expires_at_utc,
      'absolute_expires_at_utc',v_new_session.absolute_expires_at_utc,
      'token_key_version',v_request_key_version
    );
    if v_public_credential_versions is not null then
      v_response:=v_response||jsonb_build_object(
        'public_credential_versions',v_public_credential_versions
      );
    end if;
    perform private._candidate_auth_mutation_receipt_v1(
      v_environment,p_idempotency_key,v_request_sha256,v_action,v_response,
      jsonb_build_object('request_key_version',v_request_key_version),p_now_utc
    );
    return v_response;
  end if;

  if p_account_id is not null then
    select * into v_account from public.candidate_app_accounts where id=p_account_id;
  elsif v_email<>'' then
    select * into v_account from public.candidate_app_accounts
    where environment=v_environment and email_normalized=v_email;
  end if;
  if v_account.id is not null and v_action in (
    'LOGIN_SUCCESS','REVOKE_SESSIONS','LOCK','DISABLE'
  ) then
    v_account_id:=v_account.id;
    perform private._candidate_auth_account_session_lock_v1(
      v_environment,v_account_id
    );
    select * into v_account from public.candidate_app_accounts
    where id=v_account_id for update;
  end if;

  if v_action='LOGIN_SUCCESS' and v_account.id is not null then
    v_expected_password_authority_sha256:=lower(nullif(btrim(
      coalesce(v_payload->>'expected_password_authority_sha256','')
    ),''));
    if v_expected_password_authority_sha256 ~ '^[0-9a-f]{64}$'
       and coalesce(v_payload->>'presented_password_digest_hex','') ~ '^[0-9a-fA-F]{64}$' then
      v_presented_password_digest:=decode(v_payload->>'presented_password_digest_hex','hex');
      v_current_password_authority_sha256:=private._candidate_password_authority_sha256_v1(
        v_account.id,v_account.password_scheme,v_account.password_scheme_version,
        v_account.password_salt,v_account.password_digest,v_account.password_params_json
      );
      v_password_authority_current:=
        v_expected_password_authority_sha256=v_current_password_authority_sha256;
      v_password_matches_current:=v_password_authority_current
        and v_account.password_digest is not null
        and v_presented_password_digest=v_account.password_digest;
    end if;
  end if;

  if v_action='LOGIN_SUCCESS' then
    v_private_login_failed:=coalesce((v_payload->>'login_failed')::boolean,false);
    if v_account.id is null or not v_password_authority_current
       or (v_private_login_failed and v_password_matches_current)
       or (not v_private_login_failed and not v_password_matches_current) then
      v_response:=jsonb_build_object(
        'ok',false,'error_code','CANDIDATE_LOGIN_INVALID',
        'failed_login_recorded',false
      );
      perform private._candidate_auth_mutation_receipt_v1(
        v_environment,p_idempotency_key,v_request_sha256,v_action,v_response,
        jsonb_build_object('request_key_version',v_request_key_version),p_now_utc
      );
      return v_response;
    end if;
    if v_private_login_failed then
      if v_account.id is not null and v_account.environment=v_environment and v_account.status<>'DISABLED' then
        update public.candidate_app_accounts set
          failed_login_count=least(failed_login_count+1,1000),
          status=case when failed_login_count+1>=5 then 'LOCKED' else status end,
          locked_until_utc=case when failed_login_count+1>=5 then p_now_utc+interval '15 minutes' else locked_until_utc end,
          updated_at_utc=p_now_utc
        where id=v_account.id returning * into v_account;
        v_failed_login_recorded:=true;
      end if;
      v_response:=jsonb_build_object(
        'ok',false,'error_code','CANDIDATE_LOGIN_INVALID',
        'failed_login_recorded',v_failed_login_recorded
      );
      perform private._candidate_auth_mutation_receipt_v1(
        v_environment,p_idempotency_key,v_request_sha256,v_action,v_response,
        jsonb_build_object('request_key_version',v_request_key_version),p_now_utc
      );
      return v_response;
    end if;
    if v_account.id is null or v_account.environment<>v_environment or v_account.status='DISABLED' then
      raise exception 'CANDIDATE_LOGIN_INVALID' using errcode='28000';
    end if;
    if v_account.status='LOCKED' and coalesce(v_account.locked_until_utc,'infinity'::timestamptz)>p_now_utc then
      raise exception 'CANDIDATE_ACCOUNT_LOCKED' using errcode='28000';
    end if;
    if v_account.password_digest is null then raise exception 'CANDIDATE_PASSWORD_SETUP_REQUIRED' using errcode='28000'; end if;
    if coalesce(v_payload->>'refresh_token_hash_hex','') !~ '^[0-9a-fA-F]{64}$' then
      raise exception 'CANDIDATE_REFRESH_HASH_INVALID' using errcode='22023';
    end if;
    v_refresh_hash:=decode(v_payload->>'refresh_token_hash_hex','hex');
    v_expires:=coalesce(nullif(v_payload->>'expires_at_utc','')::timestamptz,p_now_utc+interval '30 days');
    v_absolute:=coalesce(nullif(v_payload->>'absolute_expires_at_utc','')::timestamptz,p_now_utc+interval '90 days');
    if v_expires>v_absolute or v_expires<=p_now_utc then raise exception 'CANDIDATE_SESSION_EXPIRY_INVALID' using errcode='22023'; end if;
    v_eligibility:=private._candidate_email_eligibility_v1(v_environment,v_account.email_normalized);
    v_candidate_ids:=v_eligibility->'candidate_ids';
    v_match_count:=coalesce((v_eligibility->>'match_count')::integer,0);
    if coalesce((v_eligibility->>'eligible')::boolean,false)=false then raise exception 'CANDIDATE_ACCOUNT_NOT_ELIGIBLE' using errcode='28000'; end if;
    if p_selected_candidate_id is null and v_match_count=1 then
      p_selected_candidate_id:=(v_candidate_ids->>0)::uuid;
    end if;
    if p_selected_candidate_id is not null and not exists(
      select 1 from public.candidates c where c.id=p_selected_candidate_id and c.active=true
        and lower(btrim(coalesce(c.email,'')))=v_account.email_normalized
    ) then raise exception 'CANDIDATE_SELECTION_NOT_ALLOWED' using errcode='28000'; end if;
    if v_environment='TEST' and v_match_count>1 and p_selected_candidate_id is null then
      raise exception 'CANDIDATE_SELECTION_REQUIRED' using errcode='28000';
    end if;

    if coalesce(v_payload->>'device_id_hash_hex','')~'^[0-9a-fA-F]{64}$' then
      v_device_hash:=decode(v_payload->>'device_id_hash_hex','hex');
    end if;
    v_new_session_id:=coalesce(p_session_id,gen_random_uuid());
    insert into public.candidate_app_sessions(
      id,account_id,environment,selected_candidate_id,status,refresh_token_hash,token_family_id,
      rotation,issued_at_utc,expires_at_utc,absolute_expires_at_utc,last_used_at_utc,
      device_id_hash,platform,created_at_utc,updated_at_utc
    ) values (
      v_new_session_id,v_account.id,v_environment,p_selected_candidate_id,'ACTIVE',v_refresh_hash,gen_random_uuid(),
      0,p_now_utc,v_expires,v_absolute,p_now_utc,v_device_hash,nullif(btrim(v_payload->>'platform'),''),p_now_utc,p_now_utc
    ) returning * into v_new_session;

    with ranked as (
      select id,row_number() over(order by last_used_at_utc desc,issued_at_utc desc,id desc) rn
      from public.candidate_app_sessions where account_id=v_account.id and status='ACTIVE'
    )
    update public.candidate_app_sessions s set status='REVOKED',revoked_at_utc=p_now_utc,
      revoke_reason='CONCURRENT_SESSION_LIMIT',updated_at_utc=p_now_utc
    from ranked r where s.id=r.id and r.rn>5;
    select count(*) into v_live_session_count
    from public.candidate_app_sessions
    where account_id=v_account.id and status='ACTIVE';
    if v_live_session_count<1 or v_live_session_count>5 then
      raise exception 'CANDIDATE_SESSION_LIMIT_POSTCONDITION_FAILED'
        using errcode='40001';
    end if;

    update public.candidate_app_accounts set status='ACTIVE',failed_login_count=0,locked_until_utc=null,
      last_login_at_utc=p_now_utc,updated_at_utc=p_now_utc where id=v_account.id returning * into v_account;
    perform private._candidate_audit_v1('candidate_app_session',v_new_session.id::text,'CANDIDATE_LOGIN_SUCCESS',null,
      jsonb_build_object('account_id',v_account.id,'rotation',0,'selected_candidate_id',p_selected_candidate_id),
      null,null,p_idempotency_key,p_now_utc);
    v_response:=jsonb_build_object(
      'ok',true,'account_id',v_account.id,'session_id',v_new_session.id,'rotation',0,
      'selected_candidate_id',p_selected_candidate_id,'expires_at_utc',v_expires,
      'absolute_expires_at_utc',v_absolute,'issued_at_utc',v_new_session.issued_at_utc,
      'session_version',v_account.session_version,'token_key_version',v_request_key_version
    );
    if v_public_credential_versions is not null then
      v_response:=v_response||jsonb_build_object(
        'public_credential_versions',v_public_credential_versions
      );
    end if;
    perform private._candidate_auth_mutation_receipt_v1(
      v_environment,p_idempotency_key,v_request_sha256,v_action,v_response,
      jsonb_build_object('request_key_version',v_request_key_version),p_now_utc
    );
    return v_response;
  end if;

  if v_action='REFRESH_SESSION' then
    -- The first read discovers only the stable account identity.  It is not
    -- authoritative for session state.  Acquire the account lock, lock the
    -- account row, and only then re-read/lock the session.
    select s.account_id into v_account_id
    from public.candidate_app_sessions s
    where s.id=p_session_id and s.environment=v_environment;
    if v_account_id is null then
      raise exception 'CANDIDATE_SESSION_INVALID' using errcode='28000';
    end if;
    perform private._candidate_auth_account_session_lock_v1(
      v_environment,v_account_id
    );
    select * into v_account from public.candidate_app_accounts
    where id=v_account_id for update;
    if not found or v_account.environment<>v_environment
       or v_account.status<>'ACTIVE' then
      raise exception 'CANDIDATE_ACCOUNT_INACTIVE' using errcode='28000';
    end if;
    select * into v_session from public.candidate_app_sessions
    where id=p_session_id and account_id=v_account_id for update;
    if not found or v_session.environment<>v_environment then raise exception 'CANDIDATE_SESSION_INVALID' using errcode='28000'; end if;
    if coalesce(v_payload->>'presented_refresh_token_hash_hex','') !~ '^[0-9a-fA-F]{64}$'
       or coalesce(v_payload->>'new_refresh_token_hash_hex','') !~ '^[0-9a-fA-F]{64}$'
       or coalesce(v_payload->>'new_session_id','') !~ '^[0-9a-fA-F-]{36}$' then
      raise exception 'CANDIDATE_REFRESH_HASH_INVALID' using errcode='22023';
    end if;
    v_presented_refresh_hash:=decode(v_payload->>'presented_refresh_token_hash_hex','hex');
    if v_session.status='ROTATED' then
      if v_presented_refresh_hash is distinct from v_session.refresh_token_hash then
        raise exception 'CANDIDATE_SESSION_INVALID' using errcode='28000';
      end if;
      v_response:=jsonb_build_object(
        'ok',false,
        'error_code','CANDIDATE_REFRESH_TOKEN_REUSE',
        'family_revoked',true
      );
      update public.candidate_app_sessions set status='REVOKED',revoked_at_utc=p_now_utc,
        revoke_reason='REFRESH_TOKEN_REUSE',updated_at_utc=p_now_utc
      where token_family_id=v_session.token_family_id and status in ('ACTIVE','ROTATED');
      if exists(
        select 1 from public.candidate_app_sessions
        where token_family_id=v_session.token_family_id
          and status in ('ACTIVE','ROTATED')
      ) then
        raise exception 'CANDIDATE_SESSION_INVALIDATION_INCOMPLETE'
          using errcode='40001';
      end if;
      perform private._candidate_auth_mutation_receipt_v1(
        v_environment,p_idempotency_key,v_request_sha256,v_action,v_response,
        jsonb_build_object('request_key_version',v_request_key_version),p_now_utc
      );
      return v_response;
    end if;
    if v_session.status<>'ACTIVE' or v_session.expires_at_utc<=p_now_utc or v_session.absolute_expires_at_utc<=p_now_utc then
      raise exception 'CANDIDATE_SESSION_EXPIRED' using errcode='28000';
    end if;
    if v_presented_refresh_hash is distinct from v_session.refresh_token_hash then
      raise exception 'CANDIDATE_SESSION_INVALID' using errcode='28000';
    end if;
    v_refresh_hash:=decode(v_payload->>'new_refresh_token_hash_hex','hex');
    if v_refresh_hash=v_presented_refresh_hash then
      raise exception 'CANDIDATE_REFRESH_HASH_REUSE_FORBIDDEN' using errcode='22023';
    end if;
    v_new_session_id:=(v_payload->>'new_session_id')::uuid;
    v_expires:=least(p_now_utc+interval '30 days',v_session.absolute_expires_at_utc);
    insert into public.candidate_app_sessions(
      id,account_id,environment,selected_candidate_id,status,refresh_token_hash,token_family_id,rotation,
      issued_at_utc,expires_at_utc,absolute_expires_at_utc,last_used_at_utc,device_id_hash,platform,
      push_provider,push_token_ciphertext,push_key_version,created_at_utc,updated_at_utc
    ) values (
      v_new_session_id,v_session.account_id,v_environment,v_session.selected_candidate_id,'ACTIVE',v_refresh_hash,
      v_session.token_family_id,v_session.rotation+1,p_now_utc,v_expires,v_session.absolute_expires_at_utc,p_now_utc,
      v_session.device_id_hash,v_session.platform,v_session.push_provider,v_session.push_token_ciphertext,
      v_session.push_key_version,p_now_utc,p_now_utc
    ) returning * into v_new_session;
    update public.candidate_app_sessions set status='ROTATED',replaced_by_session_id=v_new_session_id,
      last_used_at_utc=p_now_utc,updated_at_utc=p_now_utc where id=v_session.id;
    select count(*) into v_live_session_count
    from public.candidate_app_sessions
    where token_family_id=v_session.token_family_id and status='ACTIVE';
    if v_live_session_count<>1 or not exists(
      select 1 from public.candidate_app_sessions
      where id=v_new_session.id and status='ACTIVE'
    ) then
      raise exception 'CANDIDATE_SESSION_ROTATION_POSTCONDITION_FAILED'
        using errcode='40001';
    end if;
    v_response:=jsonb_build_object('ok',true,'session_id',v_new_session.id,'rotation',v_new_session.rotation,
      'issued_at_utc',v_new_session.issued_at_utc,
      'expires_at_utc',v_new_session.expires_at_utc,'absolute_expires_at_utc',v_new_session.absolute_expires_at_utc,
      'selected_candidate_id',v_new_session.selected_candidate_id,'token_key_version',v_request_key_version);
    if v_public_credential_versions is not null then
      v_response:=v_response||jsonb_build_object(
        'public_credential_versions',v_public_credential_versions
      );
    end if;
    perform private._candidate_auth_mutation_receipt_v1(
      v_environment,p_idempotency_key,v_request_sha256,v_action,v_response,
      jsonb_build_object('request_key_version',v_request_key_version),p_now_utc
    );
    return v_response;
  end if;

  if v_action in (
    'LOGOUT','SELECT_TEST_CANDIDATE','SET_NOTIFICATION_PREFERENCES',
    'REGISTER_PUSH_TOKEN','CHANGE_PASSWORD','MARK_NOTIFICATION_READ'
  ) then
    select s.account_id into v_account_id
    from public.candidate_app_sessions s
    where s.id=p_session_id and s.environment=v_environment;
    if v_account_id is null then
      raise exception 'CANDIDATE_SESSION_INVALID' using errcode='28000';
    end if;
    perform private._candidate_auth_account_session_lock_v1(
      v_environment,v_account_id
    );
    select * into v_account from public.candidate_app_accounts
    where id=v_account_id for update;
    if not found or v_account.environment<>v_environment then
      raise exception 'CANDIDATE_ACCOUNT_INACTIVE' using errcode='28000';
    end if;
    v_context:=private._candidate_session_context_v1(p_session_id,v_environment,null,p_now_utc,true);
    select * into v_session from public.candidate_app_sessions
    where id=p_session_id and account_id=v_account_id;
  end if;

  if v_action='LOGOUT' then
    update public.candidate_app_sessions set status='REVOKED',revoked_at_utc=p_now_utc,
      revoke_reason='LOGOUT',updated_at_utc=p_now_utc where id=v_session.id;
    v_response:=jsonb_build_object('ok',true,'session_id',v_session.id,'status','REVOKED');
  elsif v_action='SELECT_TEST_CANDIDATE' then
    if v_environment<>'TEST' then raise exception 'CANDIDATE_SELECTION_TEST_ONLY' using errcode='28000'; end if;
    if p_selected_candidate_id is null or not exists(
      select 1 from public.candidates c where c.id=p_selected_candidate_id and c.active=true
        and lower(btrim(coalesce(c.email,'')))=v_account.email_normalized
    ) then raise exception 'CANDIDATE_SELECTION_NOT_ALLOWED' using errcode='28000'; end if;
    update public.candidate_app_sessions set selected_candidate_id=p_selected_candidate_id,
      updated_at_utc=p_now_utc where id=v_session.id;
    v_response:=jsonb_build_object('ok',true,'session_id',v_session.id,'selected_candidate_id',p_selected_candidate_id);
  elsif v_action='SET_NOTIFICATION_PREFERENCES' then
    v_preferences:=coalesce(v_payload->'notification_preferences','{}'::jsonb);
    if jsonb_typeof(v_preferences)<>'object' then raise exception 'CANDIDATE_NOTIFICATION_PREFERENCES_INVALID' using errcode='22023'; end if;
    update public.candidate_app_accounts set notification_preferences_json=v_preferences,updated_at_utc=p_now_utc
    where id=v_account.id returning * into v_account;
    v_response:=jsonb_build_object('ok',true,'notification_preferences',v_account.notification_preferences_json);
  elsif v_action='REGISTER_PUSH_TOKEN' then
    if coalesce(v_payload->>'push_token_ciphertext_hex','') !~ '^[0-9a-fA-F]+$'
       or length(v_payload->>'push_token_ciphertext_hex')%2<>0
       or coalesce(v_payload->>'push_key_version','') !~ '^[1-9][0-9]{0,4}$'
       or (v_payload->>'push_key_version')::integer>32767
       or coalesce(v_payload->>'push_token_identity_hmac','') !~ '^[0-9a-f]{64}$'
       or coalesce(v_payload->>'push_token_identity_key_version','') !~ '^[1-9][0-9]{0,4}$'
       or (v_payload->>'push_token_identity_key_version')::integer>65535 then
      raise exception 'CANDIDATE_PUSH_TOKEN_INVALID' using errcode='22023';
    end if;
    update public.candidate_app_sessions set
      push_provider=nullif(btrim(v_payload->>'push_provider'),''),
      push_token_ciphertext=decode(v_payload->>'push_token_ciphertext_hex','hex'),
      push_key_version=(v_payload->>'push_key_version')::smallint,updated_at_utc=p_now_utc
    where id=v_session.id;
    v_response:=jsonb_build_object('ok',true,'session_id',v_session.id,'push_registered',true);
  elsif v_action='CHANGE_PASSWORD' then
    v_expected_password_authority_sha256:=lower(nullif(btrim(
      coalesce(v_payload->>'expected_password_authority_sha256','')
    ),''));
    if v_expected_password_authority_sha256 ~ '^[0-9a-f]{64}$'
       and coalesce(v_payload->>'presented_password_digest_hex','') ~ '^[0-9a-fA-F]{64}$' then
      v_presented_password_digest:=decode(v_payload->>'presented_password_digest_hex','hex');
      v_current_password_authority_sha256:=private._candidate_password_authority_sha256_v1(
        v_account.id,v_account.password_scheme,v_account.password_scheme_version,
        v_account.password_salt,v_account.password_digest,v_account.password_params_json
      );
      v_password_authority_current:=
        v_expected_password_authority_sha256=v_current_password_authority_sha256;
      v_password_matches_current:=v_password_authority_current
        and v_account.password_digest is not null
        and v_presented_password_digest=v_account.password_digest;
    end if;
    if not v_password_matches_current then
      v_response:=jsonb_build_object(
        'ok',false,'error_code','CANDIDATE_LOGIN_INVALID','password_changed',false
      );
    else
      update public.candidate_app_accounts set
        password_scheme=btrim(v_payload->>'password_scheme'),
        password_scheme_version=(v_payload->>'password_scheme_version')::smallint,
        password_salt=v_salt,password_digest=v_digest,
        password_params_json=coalesce(v_payload->'password_params','{}'::jsonb),
        password_changed_at_utc=p_now_utc,failed_login_count=0,locked_until_utc=null,
        session_version=session_version+1,updated_at_utc=p_now_utc
      where id=v_account.id returning * into v_account;
      update public.candidate_app_sessions set status='REVOKED',revoked_at_utc=p_now_utc,
        revoke_reason='PASSWORD_CHANGED',updated_at_utc=p_now_utc
      where account_id=v_account.id and status='ACTIVE' and id<>v_session.id;
      select count(*) into v_live_session_count
      from public.candidate_app_sessions
      where account_id=v_account.id and status='ACTIVE';
      if v_live_session_count<>1 or not exists(
        select 1 from public.candidate_app_sessions
        where id=v_session.id and account_id=v_account.id and status='ACTIVE'
      ) then
        raise exception 'CANDIDATE_SESSION_INVALIDATION_INCOMPLETE'
          using errcode='40001';
      end if;
      v_response:=jsonb_build_object('ok',true,'account_id',v_account.id,'session_version',v_account.session_version);
    end if;
  elsif v_action='MARK_NOTIFICATION_READ' then
    if coalesce(v_payload->>'notification_id','') !~ '^[0-9a-fA-F-]{36}$' then
      raise exception 'CANDIDATE_NOTIFICATION_NOT_FOUND' using errcode='P0002';
    end if;
    select * into v_notification
    from public.candidate_notifications
    where id=(v_payload->>'notification_id')::uuid
      and account_id=v_account.id
    for update;
    if not found then
      raise exception 'CANDIDATE_NOTIFICATION_NOT_FOUND' using errcode='P0002';
    end if;
    if v_notification.state='UNREAD' then
      update public.candidate_notifications
      set state='READ',read_at_utc=p_now_utc
      where id=v_notification.id
      returning * into v_notification;
    end if;
    v_response:=jsonb_build_object(
      'ok',true,
      'notification_id',v_notification.id,
      'state',v_notification.state,
      'read_at_utc',v_notification.read_at_utc
    );
  end if;

  if v_idempotent_action and v_response is not null then
    perform private._candidate_auth_mutation_receipt_v1(
      v_environment,p_idempotency_key,v_request_sha256,v_action,v_response,
      v_receipt_metadata,p_now_utc
    );
    return v_response;
  end if;

  if v_action='REVOKE_SESSIONS' then
    if v_account.id is null or v_account.environment<>v_environment then raise exception 'CANDIDATE_ACCOUNT_NOT_FOUND' using errcode='P0002'; end if;
    update public.candidate_app_sessions set status='REVOKED',revoked_at_utc=p_now_utc,
      revoke_reason=coalesce(nullif(btrim(v_payload->>'reason'),''),'ACCOUNT_SESSION_REVOKE'),updated_at_utc=p_now_utc
    where account_id=v_account.id and status='ACTIVE';
    if exists(
      select 1 from public.candidate_app_sessions
      where account_id=v_account.id and status='ACTIVE'
    ) then
      raise exception 'CANDIDATE_SESSION_INVALIDATION_INCOMPLETE'
        using errcode='40001';
    end if;
    update public.candidate_app_accounts set session_version=session_version+1,updated_at_utc=p_now_utc
    where id=v_account.id returning * into v_account;
    return jsonb_build_object('ok',true,'account_id',v_account.id,'session_version',v_account.session_version);
  elsif v_action in ('LOCK','DISABLE') then
    if v_account.id is null or v_account.environment<>v_environment then raise exception 'CANDIDATE_ACCOUNT_NOT_FOUND' using errcode='P0002'; end if;
    update public.candidate_app_accounts set status=case when v_action='LOCK' then 'LOCKED' else 'DISABLED' end,
      locked_until_utc=case when v_action='LOCK' then coalesce(nullif(v_payload->>'locked_until_utc','')::timestamptz,p_now_utc+interval '15 minutes') else null end,
      session_version=session_version+1,updated_at_utc=p_now_utc where id=v_account.id returning * into v_account;
    update public.candidate_app_sessions set status='REVOKED',revoked_at_utc=p_now_utc,
      revoke_reason=v_action,updated_at_utc=p_now_utc where account_id=v_account.id and status='ACTIVE';
    if exists(
      select 1 from public.candidate_app_sessions
      where account_id=v_account.id and status='ACTIVE'
    ) then
      raise exception 'CANDIDATE_SESSION_INVALIDATION_INCOMPLETE'
        using errcode='40001';
    end if;
    return jsonb_build_object('ok',true,'account_id',v_account.id,'status',v_account.status);
  end if;

  raise exception 'CANDIDATE_AUTH_ACTION_INVALID'
    using errcode='22023',detail=jsonb_build_object('code','CANDIDATE_AUTH_ACTION_INVALID','action',v_action)::text;
end;
$function$;

-- candidate_auth_challenge_transition_v1(text,text,text,text,uuid,bytea,text,timestamp with time zone,integer)
CREATE OR REPLACE FUNCTION public.candidate_auth_challenge_transition_v1(p_action text, p_environment text, p_email_normalized text, p_purpose text, p_challenge_id uuid DEFAULT NULL::uuid, p_token_hash bytea DEFAULT NULL::bytea, p_idempotency_key text DEFAULT NULL::text, p_now_utc timestamp with time zone DEFAULT now(), p_token_key_version integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
declare
  v_action text:=upper(btrim(coalesce(p_action,'')));
  v_environment text;
  v_email text:=private._candidate_normalize_email(p_email_normalized);
  v_purpose text:=upper(btrim(coalesce(p_purpose,'')));
  v_eligibility jsonb;
  v_account public.candidate_app_accounts%rowtype;
  v_challenge public.candidate_auth_challenges%rowtype;
  v_new public.candidate_auth_challenges%rowtype;
  v_allowed boolean:=false;
  v_expiry timestamptz;
  v_outbox_key text;
  v_request_sha256 text;
  v_receipt jsonb;
  v_response jsonb;
  v_receipt_metadata jsonb;
begin
  v_environment:=private._candidate_assert_environment(p_environment);
  perform private._candidate_require_feature_v1(v_environment,'candidate_account_registration');
  if v_purpose not in ('ACTIVATE','RESET','RECOVERY') then raise exception 'CANDIDATE_CHALLENGE_PURPOSE_INVALID' using errcode='22023'; end if;
  if v_action in ('START','RESEND','VERIFY')
     and (nullif(btrim(coalesce(p_idempotency_key,'')),'') is null
       or length(btrim(p_idempotency_key))>200) then
    raise exception 'CANDIDATE_IDEMPOTENCY_KEY_REQUIRED' using errcode='22023';
  end if;
  if v_action in ('START','RESEND','VERIFY') and p_token_hash is null then
    v_receipt:=private._candidate_auth_mutation_receipt_v1(
      v_environment,p_idempotency_key,null,v_action,null,'{}'::jsonb,p_now_utc
    );
    if coalesce((v_receipt->>'found')::boolean,false) then
      return jsonb_build_object(
        'ok',true,'replay_receipt_found',true,
        'token_hash_hex',v_receipt#>>'{metadata,token_hash_hex}',
        'token_key_version',v_receipt#>>'{metadata,token_key_version}'
      );
    end if;
    return jsonb_build_object('ok',true,'replay_receipt_found',false);
  end if;
  if v_action in ('START','RESEND','VERIFY') then
    v_request_sha256:=encode(extensions.digest(convert_to(
      (jsonb_build_object(
        'contract_version','CANDIDATE_AUTH_CHALLENGE_MUTATION_REQUEST_V2',
        'action',v_action,'environment',v_environment,'email',v_email,
        'purpose',v_purpose,'challenge_id',p_challenge_id
      ) || case when v_action='VERIFY'
        then jsonb_build_object('token_hash_hex',encode(p_token_hash,'hex'))
        else '{}'::jsonb end)::text,
      'UTF8'),'sha256'),'hex');
    v_receipt_metadata:=jsonb_build_object('token_hash_hex',encode(p_token_hash,'hex'))
      || case when v_action in ('START','RESEND')
        then jsonb_build_object('token_key_version',p_token_key_version)
        else '{}'::jsonb end;
    v_receipt:=private._candidate_auth_mutation_receipt_v1(
      v_environment,p_idempotency_key,v_request_sha256,v_action,null,
      v_receipt_metadata,p_now_utc
    );
    if coalesce((v_receipt->>'found')::boolean,false) then
      return coalesce(v_receipt->'response','{}'::jsonb);
    end if;
  end if;
  if v_action in ('START','RESEND')
     and (p_token_key_version is null or p_token_key_version<1 or p_token_key_version>32) then
    raise exception 'CANDIDATE_REPLAY_KEY_VERSION_INVALID' using errcode='22023';
  end if;
  if v_action in ('START','RESEND') then
    select * into v_new from public.candidate_auth_challenges
    where deterministic_outbox_key=btrim(p_idempotency_key);
    if found then
      if v_new.environment<>v_environment or v_new.email_normalized<>v_email or v_new.purpose<>v_purpose
         or (p_token_hash is not null and v_new.token_hash is distinct from p_token_hash) then
        raise exception 'IDEMPOTENCY_CONFLICT' using errcode='23505';
      end if;
      v_response:=jsonb_build_object(
        'ok',true,'accepted',true,'deliver_email',false,'idempotent_replay',true,
        'challenge_id',v_new.id,'expires_at_utc',v_new.expires_at_utc,
        'resend_count',v_new.resend_count,'deterministic_outbox_key',v_new.deterministic_outbox_key,
        'token_hash_hex',encode(p_token_hash,'hex'),'token_key_version',p_token_key_version
      );
      perform private._candidate_auth_mutation_receipt_v1(
        v_environment,p_idempotency_key,v_request_sha256,v_action,v_response,
        v_receipt_metadata,p_now_utc
      );
      return v_response;
    end if;
  end if;

  if v_action='START' then
    perform pg_advisory_xact_lock(hashtext(v_environment||'|'||v_email||'|'||v_purpose));
    v_eligibility:=private._candidate_email_eligibility_v1(v_environment,v_email);
    select * into v_account from public.candidate_app_accounts
    where environment=v_environment and email_normalized=v_email;
    v_allowed:=coalesce((v_eligibility->>'eligible')::boolean,false)
      and ((v_purpose='ACTIVATE' and (v_account.id is null or v_account.status='SETUP_REQUIRED'))
        or (v_purpose in ('RESET','RECOVERY') and v_account.id is not null and v_account.status<>'DISABLED'));
    if not v_allowed then
      v_response:=jsonb_build_object('ok',true,'accepted',true,'deliver_email',false);
      perform private._candidate_auth_mutation_receipt_v1(
        v_environment,p_idempotency_key,v_request_sha256,v_action,v_response,
        v_receipt_metadata,p_now_utc
      );
      return v_response;
    end if;
    if p_token_hash is null or octet_length(p_token_hash)<>32 then raise exception 'CANDIDATE_CHALLENGE_TOKEN_HASH_INVALID' using errcode='22023'; end if;
    update public.candidate_auth_challenges set state='SUPERSEDED',superseded_at_utc=p_now_utc,updated_at_utc=p_now_utc
    where environment=v_environment and email_normalized=v_email and purpose=v_purpose and state in ('PENDING','VERIFIED');
    v_expiry:=p_now_utc+case when v_purpose='ACTIVATE' then interval '60 minutes' else interval '30 minutes' end;
    v_outbox_key:=btrim(p_idempotency_key);
    insert into public.candidate_auth_challenges(
      account_id,environment,email_normalized,purpose,state,token_hash,expires_at_utc,
      last_sent_at_utc,deterministic_outbox_key,created_at_utc,updated_at_utc
    ) values (
      v_account.id,v_environment,v_email,v_purpose,'PENDING',p_token_hash,v_expiry,
      p_now_utc,v_outbox_key,p_now_utc,p_now_utc
    ) returning * into v_new;
    v_response:=jsonb_build_object('ok',true,'accepted',true,'deliver_email',true,'idempotent_replay',false,
      'challenge_id',v_new.id,'expires_at_utc',v_new.expires_at_utc,
      'deterministic_outbox_key',v_new.deterministic_outbox_key,
      'token_hash_hex',encode(p_token_hash,'hex'),'token_key_version',p_token_key_version);
    perform private._candidate_auth_mutation_receipt_v1(
      v_environment,p_idempotency_key,v_request_sha256,v_action,v_response,
      v_receipt_metadata,p_now_utc
    );
    return v_response;
  end if;

  if p_challenge_id is not null then
    select * into v_challenge from public.candidate_auth_challenges where id=p_challenge_id for update;
  elsif p_token_hash is not null then
    select * into v_challenge from public.candidate_auth_challenges where token_hash=p_token_hash for update;
  end if;
  if not found or v_challenge.environment<>v_environment or v_challenge.purpose<>v_purpose then
    raise exception 'CANDIDATE_CHALLENGE_INVALID' using errcode='28000';
  end if;

  if v_action='VERIFY' then
    if p_token_hash is null or p_token_hash is distinct from v_challenge.token_hash then
      update public.candidate_auth_challenges set
        attempt_count=least(attempt_count+1,5),
        state=case when attempt_count+1>=5 then 'SUPERSEDED' else state end,
        superseded_at_utc=case when attempt_count+1>=5 then p_now_utc else superseded_at_utc end,
        updated_at_utc=p_now_utc
      where id=v_challenge.id returning * into v_challenge;
      v_response:=jsonb_build_object(
        'ok',false,'error_code','CANDIDATE_CHALLENGE_INVALID',
        'terminal',v_challenge.state='SUPERSEDED','attempt_count',v_challenge.attempt_count
      );
      perform private._candidate_auth_mutation_receipt_v1(
        v_environment,p_idempotency_key,v_request_sha256,v_action,v_response,
        v_receipt_metadata,p_now_utc
      );
      return v_response;
    end if;
    if v_challenge.state<>'PENDING' then raise exception 'CANDIDATE_CHALLENGE_ALREADY_USED' using errcode='28000'; end if;
    if v_challenge.expires_at_utc<=p_now_utc then
      update public.candidate_auth_challenges set state='EXPIRED',updated_at_utc=p_now_utc where id=v_challenge.id;
      v_response:=jsonb_build_object('ok',false,'error_code','CANDIDATE_CHALLENGE_EXPIRED','terminal',true);
      perform private._candidate_auth_mutation_receipt_v1(
        v_environment,p_idempotency_key,v_request_sha256,v_action,v_response,
        v_receipt_metadata,p_now_utc
      );
      return v_response;
    end if;
    update public.candidate_auth_challenges set state='VERIFIED',verified_at_utc=p_now_utc,updated_at_utc=p_now_utc
    where id=v_challenge.id returning * into v_challenge;
    v_response:=jsonb_build_object('ok',true,'challenge_id',v_challenge.id,'state',v_challenge.state,
      'purpose',v_challenge.purpose,'expires_at_utc',v_challenge.expires_at_utc);
    perform private._candidate_auth_mutation_receipt_v1(
      v_environment,p_idempotency_key,v_request_sha256,v_action,v_response,
      v_receipt_metadata,p_now_utc
    );
    return v_response;
  elsif v_action='CONSUME' then
    if v_challenge.state<>'VERIFIED' or v_challenge.expires_at_utc<=p_now_utc then
      raise exception 'CANDIDATE_VERIFIED_CHALLENGE_INVALID' using errcode='28000';
    end if;
    return jsonb_build_object('ok',true,'challenge_id',v_challenge.id,'state','VERIFIED',
      'consume_via_account_transition',true);
  elsif v_action='RESEND' then
    if v_challenge.state not in ('PENDING','VERIFIED') or v_challenge.expires_at_utc<=p_now_utc then
      raise exception 'CANDIDATE_CHALLENGE_NOT_RESENDABLE' using errcode='55000';
    end if;
    if v_challenge.resend_count>=5 then
      v_response:=jsonb_build_object(
        'ok',false,'error_code','CANDIDATE_CHALLENGE_RESEND_LIMIT','terminal',true
      );
      perform private._candidate_auth_mutation_receipt_v1(
        v_environment,p_idempotency_key,v_request_sha256,v_action,v_response,
        v_receipt_metadata,p_now_utc
      );
      return v_response;
    end if;
    if v_challenge.last_sent_at_utc is not null and v_challenge.last_sent_at_utc+interval '60 seconds'>p_now_utc then
      v_response:=jsonb_build_object(
        'ok',false,'error_code','CANDIDATE_CHALLENGE_RESEND_TOO_SOON','terminal',false,
        'retry_after_seconds',greatest(1,ceil(extract(epoch from
          (v_challenge.last_sent_at_utc+interval '60 seconds'-p_now_utc)))::integer)
      );
      perform private._candidate_auth_mutation_receipt_v1(
        v_environment,p_idempotency_key,v_request_sha256,v_action,v_response,
        v_receipt_metadata,p_now_utc
      );
      return v_response;
    end if;
    if p_token_hash is null or octet_length(p_token_hash)<>32 then raise exception 'CANDIDATE_CHALLENGE_TOKEN_HASH_INVALID' using errcode='22023'; end if;
    update public.candidate_auth_challenges set state='SUPERSEDED',superseded_at_utc=p_now_utc,updated_at_utc=p_now_utc
    where id=v_challenge.id;
    v_expiry:=p_now_utc+case when v_purpose='ACTIVATE' then interval '60 minutes' else interval '30 minutes' end;
    v_outbox_key:=btrim(p_idempotency_key);
    insert into public.candidate_auth_challenges(
      account_id,environment,email_normalized,purpose,state,token_hash,expires_at_utc,
      resend_count,last_sent_at_utc,superseded_by_id,deterministic_outbox_key,created_at_utc,updated_at_utc
    ) values (
      v_challenge.account_id,v_environment,v_challenge.email_normalized,v_purpose,'PENDING',p_token_hash,v_expiry,
      v_challenge.resend_count+1,p_now_utc,null,v_outbox_key,p_now_utc,p_now_utc
    ) returning * into v_new;
    update public.candidate_auth_challenges set superseded_by_id=v_new.id where id=v_challenge.id;
    v_response:=jsonb_build_object('ok',true,'accepted',true,'deliver_email',true,'idempotent_replay',false,
      'challenge_id',v_new.id,'expires_at_utc',v_new.expires_at_utc,'resend_count',v_new.resend_count,
      'deterministic_outbox_key',v_new.deterministic_outbox_key,
      'token_hash_hex',encode(p_token_hash,'hex'),'token_key_version',p_token_key_version);
    perform private._candidate_auth_mutation_receipt_v1(
      v_environment,p_idempotency_key,v_request_sha256,v_action,v_response,
      v_receipt_metadata,p_now_utc
    );
    return v_response;
  elsif v_action in ('EXPIRE','SUPERSEDE') then
    update public.candidate_auth_challenges set
      state=case when v_action='EXPIRE' then 'EXPIRED' else 'SUPERSEDED' end,
      superseded_at_utc=case when v_action='SUPERSEDE' then p_now_utc else superseded_at_utc end,
      updated_at_utc=p_now_utc where id=v_challenge.id returning * into v_challenge;
    return jsonb_build_object('ok',true,'challenge_id',v_challenge.id,'state',v_challenge.state);
  end if;
  raise exception 'CANDIDATE_CHALLENGE_ACTION_INVALID' using errcode='22023';
end;
$function$;

-- candidate_contract_week_add_missing_atomic_v1(uuid,text,uuid,date,text,timestamp with time zone)
CREATE OR REPLACE FUNCTION public.candidate_contract_week_add_missing_atomic_v1(p_session_id uuid, p_environment text, p_contract_id uuid, p_week_ending_date date, p_idempotency_key text, p_now_utc timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
declare
  v_context jsonb;
  v_candidate_id uuid;
  v_contract public.contracts%rowtype;
  v_week public.contract_weeks%rowtype;
  v_policy jsonb;
  v_mode public.submission_mode_enum;
  v_import_authority jsonb;
begin
  perform private._candidate_require_feature_v1(p_environment,'candidate_app_writes');
  if p_week_ending_date is null or nullif(btrim(coalesce(p_idempotency_key,'')),'') is null then
    raise exception 'CANDIDATE_MISSING_WEEK_PAYLOAD_INVALID' using errcode='22023';
  end if;
  v_context:=private._candidate_session_context_v1(p_session_id,p_environment,null,p_now_utc,true);
  v_candidate_id:=nullif(v_context->>'selected_candidate_id','')::uuid;
  if v_candidate_id is null then raise exception 'CANDIDATE_SELECTION_REQUIRED' using errcode='28000'; end if;
  select * into v_contract from public.contracts where id=p_contract_id and candidate_id=v_candidate_id for update;
  if not found then raise exception 'CANDIDATE_CONTRACT_NOT_FOUND' using errcode='P0002'; end if;
  if p_week_ending_date not between v_contract.start_date and v_contract.end_date
     or extract(dow from p_week_ending_date)::integer<>v_contract.week_ending_weekday_snapshot then
    raise exception 'CANDIDATE_MISSING_WEEK_DATE_INVALID' using errcode='22023';
  end if;
  v_import_authority:=private._candidate_import_authoritative_v1(
    v_contract.client_id,v_contract.id,null,null,p_week_ending_date
  );
  if coalesce((v_import_authority->>'is_import_authoritative')::boolean,false) then
    raise exception 'CANDIDATE_IMPORT_WEEK_CREATION_FORBIDDEN' using errcode='55000';
  end if;
  v_policy:=private._candidate_policy_resolve_v1(v_contract.client_id,v_contract.id,p_week_ending_date);
  v_mode:=private._candidate_submission_mode_v1(v_contract.client_id,v_contract.id,p_week_ending_date);
  if not (v_mode='ELECTRONIC' or (v_mode='MANUAL'
    and coalesce((v_policy->>'paper_submission_enabled')::boolean,false))) then
    raise exception 'CANDIDATE_MISSING_WEEK_ROUTE_NOT_ALLOWED' using errcode='55000';
  end if;
  perform pg_advisory_xact_lock(hashtext(v_contract.id::text||'|'||p_week_ending_date::text||'|BASE_WEEK'));
  select * into v_week from public.contract_weeks
  where contract_id=v_contract.id and week_ending_date=p_week_ending_date and additional_seq=0 for update;
  if found then
    return jsonb_build_object('ok',true,'idempotent_replay',true,'contract_week_id',v_week.id,
      'week_ending_date',v_week.week_ending_date,'status',v_week.status);
  end if;
  insert into public.contract_weeks(
    contract_id,week_ending_date,additional_seq,status,submission_mode_snapshot,
    day_entries_json,totals_json,planned_schedule_json,created_at,updated_at
  ) values (
    v_contract.id,p_week_ending_date,0,
    case when p_week_ending_date<=(p_now_utc at time zone 'Europe/London')::date then 'OPEN' else 'PLANNED' end,
    v_mode,'[]'::jsonb,'{}'::jsonb,
    private._candidate_week_schedule_from_template_v1(
      v_contract.std_schedule_json,p_week_ending_date,v_contract.start_date,v_contract.end_date
    ),p_now_utc,p_now_utc
  ) returning * into v_week;
  perform private._candidate_audit_v1('contract_week',v_week.id::text,'CANDIDATE_MISSING_WEEK_CREATED',null,
    jsonb_build_object('contract_id',v_contract.id,'week_ending_date',p_week_ending_date,'status',v_week.status),
    null,null,p_idempotency_key,p_now_utc);
  return jsonb_build_object('ok',true,'idempotent_replay',false,'contract_week_id',v_week.id,
    'week_ending_date',v_week.week_ending_date,'status',v_week.status,'submission_mode',v_mode);
exception when unique_violation then
  select * into v_week from public.contract_weeks
  where contract_id=p_contract_id and week_ending_date=p_week_ending_date and additional_seq=0;
  if found then return jsonb_build_object('ok',true,'idempotent_replay',true,'contract_week_id',v_week.id,
    'week_ending_date',v_week.week_ending_date,'status',v_week.status); end if;
  raise;
end;
$function$;

-- candidate_daily_authority_transition_atomic_v1(jsonb,uuid,text,jsonb,uuid,text,text,text)
CREATE OR REPLACE FUNCTION public.candidate_daily_authority_transition_atomic_v1(p_internal_context jsonb, p_batch_request_id uuid, p_idempotency_key text, p_transition_items jsonb, p_independent_approver uuid, p_reason text, p_evidence_sha256 text, p_correlation_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_context jsonb; v_environment text; v_request_hash text;
  v_batch private.candidate_daily_batch_receipts%rowtype; v_batch_id uuid:=gen_random_uuid();
  v_item_keys jsonb; v_item jsonb; v_candidate_id uuid; v_scope private.candidate_daily_authority_scopes%rowtype;
  v_generation public.candidate_daily_rota_generations%rowtype;
  v_sync private.candidate_daily_sync_state%rowtype;
  v_transition_id uuid; v_index integer:=0; v_outcomes jsonb:='[]'::jsonb; v_terminal jsonb;
  v_prior_mode text; v_new_mode text; v_entitlement_before boolean:=false; v_entitlement_after boolean;
  v_actor uuid; v_error text; v_link jsonb; v_link_group uuid; v_link_state text;
  v_now timestamptz:=clock_timestamp(); v_global_enabled boolean:=false;
  v_expected_mode text; v_expected_version bigint; v_expected_entitlement boolean;
  v_expected_generation_id uuid; v_expected_generation_version bigint;
  v_expected_accepted_cursor bigint; v_expected_required_cursor bigint; v_expected_effective_cursor bigint;
  v_requested_disposition text; v_actual_disposition text; v_strict_barrier boolean:=false;
  v_source_primary_count integer:=0; v_source_group_count integer:=0; v_generation_day_count integer:=0;
  v_pending_count integer:=0; v_claimed_count integer:=0; v_retry_count integer:=0;
  v_deferred_count integer:=0; v_terminal_count integer:=0; v_invalid_overlay_count integer:=0;
  v_command_count integer:=0; v_other_batch_count integer:=0; v_effect_count integer:=0; v_unknown_effect_count integer:=0;
  v_latest_fact_at timestamptz; v_source_link_changed boolean:=false;
  v_source_lock_identity text;
begin
  v_context:=private._candidate_daily_context_v1(p_internal_context,'SIGNED_SYSTEM_SYNC',false);
  v_environment:=v_context->>'environment';
  begin v_actor:=nullif(p_internal_context->>'actor_user_id','')::uuid; exception when others then v_actor:=null; end;
  if p_batch_request_id is null or v_actor is null or p_independent_approver is null or p_independent_approver=v_actor
     or p_idempotency_key !~ '^[A-Za-z0-9._~:+/-]{16,128}$'
     or jsonb_typeof(p_transition_items)<>'array' or jsonb_array_length(p_transition_items) not between 1 and 100
     or length(btrim(p_reason)) not between 1 and 500 or p_evidence_sha256 !~ '^[a-f0-9]{64}$'
     or p_correlation_id !~ '^[0-7][0-9A-HJKMNP-TV-Z]{25}$' then
    raise exception using errcode='22023',message='VALIDATION_FAILED';
  end if;
  select jsonb_agg(i->>'candidate_id' order by ord) into v_item_keys
    from jsonb_array_elements(p_transition_items) with ordinality x(i,ord);
  if exists(select 1 from jsonb_array_elements(p_transition_items)i where
    i->>'candidate_id' !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$')
    or jsonb_array_length(v_item_keys)<>(select count(distinct x) from jsonb_array_elements_text(v_item_keys)x) then
    raise exception using errcode='22023',message='VALIDATION_FAILED';
  end if;
  v_request_hash:=private._candidate_daily_json_sha256_v1(jsonb_build_object('operation','AUTHORITY_TRANSITION',
    'batch_request_id',p_batch_request_id,'items',p_transition_items,'independent_approver',p_independent_approver,
    'reason',p_reason,'evidence_sha256',p_evidence_sha256));
  insert into private.candidate_daily_batch_receipts(batch_receipt_id,environment,actor_class,operation_class,
    idempotency_key,request_hash,item_keys_json,item_count,state,correlation_id)
  values(v_batch_id,v_environment,'OFFICE_ADMIN','AUTHORITY_TRANSITION',p_idempotency_key,v_request_hash,
    v_item_keys,jsonb_array_length(p_transition_items),'IN_PROGRESS',p_correlation_id)
  on conflict(environment,actor_class,operation_class,idempotency_key) do nothing;
  select * into v_batch from private.candidate_daily_batch_receipts where environment=v_environment
    and actor_class='OFFICE_ADMIN' and operation_class='AUTHORITY_TRANSITION' and idempotency_key=p_idempotency_key for update;
  if v_batch.request_hash<>v_request_hash then raise exception using errcode='23505',message='IDEMPOTENCY_KEY_REUSED'; end if;
  if v_batch.state<>'IN_PROGRESS' then
    return v_batch.terminal_response_body||jsonb_build_object('_idempotent_replay',true);
  end if;
  select coalesce(sd.candidate_app_feature_flags_json->'candidate_daily_enabled'='true'::jsonb,false)
    into v_global_enabled
  from public.settings_defaults sd where sd.id=1 for update;
  -- R17 effective lock order: every syntactically safe SOURCE identity first,
  -- then Candidate authority scopes. The trigger reacquires this same xact lock.
  for v_source_lock_identity in
    select distinct
      v_environment||':SOURCE:'||(x.source_link->>'hmac_key_version')||':'||
        (x.source_link->>'identifier_hmac') as lock_identity
    from jsonb_array_elements(p_transition_items) as item(value)
    cross join lateral (
      select item.value->'source_link' as source_link
    ) x
    where item.value ? 'source_link'
      and x.source_link is not null
      and jsonb_typeof(x.source_link)='object'
      and x.source_link ?& array['identifier_hmac','hmac_key_version']
      and x.source_link->>'identifier_hmac' ~ '^[a-f0-9]{64}$'
      and x.source_link->>'hmac_key_version' ~ '^[1-9]\d*$'
      and length(x.source_link->>'hmac_key_version')<=10
      and (
        length(x.source_link->>'hmac_key_version')<10
        or x.source_link->>'hmac_key_version'<='2147483647'
      )
    order by lock_identity
  loop
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(v_source_lock_identity,0)
    );
  end loop;

  perform 1 from private.candidate_daily_authority_scopes s where s.environment=v_environment
    and s.candidate_id in (select (i->>'candidate_id')::uuid from jsonb_array_elements(p_transition_items)i)
    order by s.candidate_id for update;
  for v_item in select value from jsonb_array_elements(p_transition_items) loop
    v_error:=null; v_scope:=null; v_generation:=null; v_sync:=null; v_link:=null;
    v_link_group:=null; v_link_state:=null; v_source_link_changed:=false;
    v_prior_mode:=null; v_new_mode:=null; v_entitlement_before:=false; v_entitlement_after:=null;
    v_expected_mode:=null; v_expected_version:=null; v_expected_entitlement:=null;
    v_expected_generation_id:=null; v_expected_generation_version:=null;
    v_expected_accepted_cursor:=null; v_expected_required_cursor:=null; v_expected_effective_cursor:=null;
    v_requested_disposition:=null; v_actual_disposition:=null; v_strict_barrier:=false;
    v_latest_fact_at:=null;
    v_source_primary_count:=0; v_source_group_count:=0; v_generation_day_count:=0;
    v_pending_count:=0; v_claimed_count:=0; v_retry_count:=0; v_deferred_count:=0;
    v_terminal_count:=0; v_invalid_overlay_count:=0; v_command_count:=0;
    v_other_batch_count:=0; v_effect_count:=0; v_unknown_effect_count:=0;
    begin
      v_now:=clock_timestamp();
      v_candidate_id:=(v_item->>'candidate_id')::uuid;
      if not(v_item ?& array['candidate_id','expected_authority_mode','expected_canonical_version',
        'expected_entitlement_enabled','new_authority_mode','entitlement_enabled','in_flight_disposition'])
         or v_item->>'expected_canonical_version' !~ '^\d+$'
         or v_item->'expected_entitlement_enabled' not in ('true'::jsonb,'false'::jsonb)
         or v_item->'entitlement_enabled' not in ('true'::jsonb,'false'::jsonb) then
        raise exception using errcode='22023',message='VALIDATION_FAILED';
      end if;
      v_expected_mode:=upper(v_item->>'expected_authority_mode');
      v_expected_version:=(v_item->>'expected_canonical_version')::bigint;
      v_expected_entitlement:=(v_item->>'expected_entitlement_enabled')::boolean;
      v_new_mode:=upper(v_item->>'new_authority_mode');
      v_entitlement_after:=(v_item->>'entitlement_enabled')::boolean;
      v_requested_disposition:=upper(v_item->>'in_flight_disposition');
      if v_expected_mode not in ('GOOGLE_PRIMARY','ROLLBACK_PENDING','SUPABASE_PRIMARY')
         or v_new_mode not in ('GOOGLE_PRIMARY','ROLLBACK_PENDING','SUPABASE_PRIMARY')
         or v_requested_disposition not in ('DRAINED','CANCELLED','RECONCILED','NONE') then
        raise exception using errcode='22023',message='VALIDATION_FAILED';
      end if;
      select * into v_scope from private.candidate_daily_authority_scopes
        where environment=v_environment and candidate_id=v_candidate_id for update;
      if v_scope.candidate_id is null then
        raise exception using errcode='55000',message='CANDIDATE_DAILY_NOT_READY';
      end if;
      if v_scope.transition_in_progress then
        raise exception using errcode='55000',message='BATCH_IN_PROGRESS';
      end if;
      v_prior_mode:=v_scope.authority_mode;
      if v_expected_mode<>v_prior_mode or v_expected_version<>v_scope.canonical_version then
        raise exception using errcode='40001',message='SEMANTIC_REJECTION';
      end if;
      select coalesce(e.enabled,false) into v_entitlement_before
      from private.candidate_daily_entitlements e
      where e.environment=v_environment and e.candidate_id=v_candidate_id for update;
      v_entitlement_before:=coalesce(v_entitlement_before,false);
      if v_expected_entitlement<>v_entitlement_before then
        raise exception using errcode='40001',message='SEMANTIC_REJECTION';
      end if;
      if not ((v_prior_mode='GOOGLE_PRIMARY' and v_new_mode in ('GOOGLE_PRIMARY','SUPABASE_PRIMARY'))
        or (v_prior_mode='SUPABASE_PRIMARY' and v_new_mode in ('SUPABASE_PRIMARY','ROLLBACK_PENDING'))
        or (v_prior_mode='ROLLBACK_PENDING' and v_new_mode in ('ROLLBACK_PENDING','GOOGLE_PRIMARY'))) then
        raise exception using errcode='22023',message='SEMANTIC_REJECTION';
      end if;
      v_link:=v_item->'source_link';
      if v_prior_mode=v_new_mode and v_entitlement_before=v_entitlement_after and v_link is null then
        if v_requested_disposition<>'NONE' then
          raise exception using errcode='40001',message='SEMANTIC_REJECTION';
        end if;
        v_outcomes:=v_outcomes||jsonb_build_array(jsonb_build_object('index',v_index,'status','NO_CHANGE',
          'candidate_id',v_candidate_id,'authority_mode',v_prior_mode,
          'entitlement_enabled',v_entitlement_before));
        v_index:=v_index+1;
        continue;
      end if;
      if v_new_mode in ('GOOGLE_PRIMARY','ROLLBACK_PENDING') and v_entitlement_after then
        raise exception using errcode='40001',message='SEMANTIC_REJECTION';
      end if;
      if v_entitlement_after and not v_global_enabled then
        raise exception using errcode='40001',message='SEMANTIC_REJECTION';
      end if;
      if v_new_mode in ('ROLLBACK_PENDING','GOOGLE_PRIMARY')
         and v_prior_mode in ('SUPABASE_PRIMARY','ROLLBACK_PENDING') and v_global_enabled then
        raise exception using errcode='40001',message='SEMANTIC_REJECTION';
      end if;
      update private.candidate_daily_authority_scopes set transition_in_progress=true,updated_at_utc=v_now
      where environment=v_environment and candidate_id=v_candidate_id;
      if v_link is not null then
        if jsonb_typeof(v_link)<>'object' or not(v_link ?& array['identifier_hmac','hmac_key_version'])
           or v_link->>'identifier_hmac' !~ '^[a-f0-9]{64}$'
           or v_link->>'hmac_key_version' !~ '^[1-9]\d*$'
           or length(v_link->>'hmac_key_version')>10
           or (length(v_link->>'hmac_key_version')=10
             and v_link->>'hmac_key_version'>'2147483647')
           or (nullif(v_link->>'link_group_id','') is not null and
             v_link->>'link_group_id' !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$') then
          raise exception using errcode='22023',message='VALIDATION_FAILED';
        end if;
        v_link_state:=upper(coalesce(nullif(v_link->>'state',''),'PRIMARY'));
        if v_link_state not in ('PRIMARY','OVERLAP') then
          raise exception using errcode='22023',message='VALIDATION_FAILED';
        end if;
        v_link_group:=coalesce(nullif(v_link->>'link_group_id','')::uuid,gen_random_uuid());
        insert into private.candidate_daily_source_links(environment,candidate_id,source_system,
          canonicalization_version,link_group_id,identifier_hmac,hmac_key_version,state,rotation_receipt_id,
          actor_user_id,independent_approver_user_id,evidence_sha256)
        values(v_environment,v_candidate_id,'GOOGLE_CREDENTIALLY_PUBLIC_ID','SOURCE_IDENTITY_V1',v_link_group,
          v_link->>'identifier_hmac',(v_link->>'hmac_key_version')::integer,
          v_link_state,v_batch.batch_receipt_id,v_actor,
          p_independent_approver,p_evidence_sha256)
        on conflict(environment,source_system,hmac_key_version,identifier_hmac) where state in ('PRIMARY','OVERLAP')
        do nothing;
        if not exists(select 1 from private.candidate_daily_source_links l where l.environment=v_environment
          and l.candidate_id=v_candidate_id and l.identifier_hmac=v_link->>'identifier_hmac'
          and l.hmac_key_version=(v_link->>'hmac_key_version')::integer and l.state in ('PRIMARY','OVERLAP')) then
          raise exception using errcode='23505',message='SOURCE_EVENT_CONFLICT';
        end if;
        v_source_link_changed:=true;
      end if;

      perform 1 from private.candidate_daily_source_links l
      where l.environment=v_environment and l.candidate_id=v_candidate_id
        and l.source_system='GOOGLE_CREDENTIALLY_PUBLIC_ID'
      order by l.link_id for update;
      select count(*) filter(where l.state='PRIMARY' and l.valid_from_utc<=v_now
          and (l.valid_to_utc is null or l.valid_to_utc>v_now)),
        count(distinct l.link_group_id) filter(where l.state in ('PRIMARY','OVERLAP')
          and l.valid_from_utc<=v_now and (l.valid_to_utc is null or l.valid_to_utc>v_now))
      into v_source_primary_count,v_source_group_count
      from private.candidate_daily_source_links l
      where l.environment=v_environment and l.candidate_id=v_candidate_id
        and l.source_system='GOOGLE_CREDENTIALLY_PUBLIC_ID';
      if (v_source_link_changed or v_new_mode='SUPABASE_PRIMARY'
          or (v_prior_mode='ROLLBACK_PENDING' and v_new_mode='GOOGLE_PRIMARY'))
         and v_source_primary_count=0 then
        raise exception using errcode='55000',message='IDENTITY_LINK_MISSING';
      end if;
      if (v_source_link_changed or v_new_mode='SUPABASE_PRIMARY'
          or (v_prior_mode='ROLLBACK_PENDING' and v_new_mode='GOOGLE_PRIMARY'))
         and (v_source_primary_count<>1 or v_source_group_count<>1) then
        raise exception using errcode='55000',message='IDENTITY_LINK_AMBIGUOUS';
      end if;

      perform 1 from public.candidate_daily_command_receipts c
      where c.environment=v_environment and c.candidate_id=v_candidate_id and c.state='IN_PROGRESS'
      order by c.command_id for update;
      select count(*) into v_command_count from public.candidate_daily_command_receipts c
      where c.environment=v_environment and c.candidate_id=v_candidate_id and c.state='IN_PROGRESS';
      perform 1 from private.candidate_daily_batch_receipts b
      where b.environment=v_environment and b.state='IN_PROGRESS'
        and b.batch_receipt_id<>v_batch.batch_receipt_id
        and b.item_keys_json @> jsonb_build_array(v_candidate_id::text)
      order by b.batch_receipt_id for update;
      select count(*) into v_other_batch_count from private.candidate_daily_batch_receipts b
      where b.environment=v_environment and b.state='IN_PROGRESS'
        and b.batch_receipt_id<>v_batch.batch_receipt_id
        and b.item_keys_json @> jsonb_build_array(v_candidate_id::text);
      perform 1 from private.candidate_daily_external_effect_receipts e
      where e.environment=v_environment and e.candidate_id=v_candidate_id and e.state in ('IN_PROGRESS','UNKNOWN')
      order by e.effect_receipt_id for update;
      select count(*),count(*) filter(where e.state='UNKNOWN')
      into v_effect_count,v_unknown_effect_count
      from private.candidate_daily_external_effect_receipts e
      where e.environment=v_environment and e.candidate_id=v_candidate_id and e.state in ('IN_PROGRESS','UNKNOWN');
      perform 1 from public.candidate_daily_sheet_projection_outbox o
      where o.environment=v_environment and o.candidate_id=v_candidate_id
        and o.target='MASTER_AVAILABILITY_SHEET'
      order by o.availability_version,o.outbox_id for update;
      select count(*) filter(where o.state='PENDING'),count(*) filter(where o.state='CLAIMED'),
        count(*) filter(where o.state='RETRY'),count(*) filter(where o.state='DEFERRED_OVERLAY'),
        count(*) filter(where o.state='TERMINAL')
      into v_pending_count,v_claimed_count,v_retry_count,v_deferred_count,v_terminal_count
      from public.candidate_daily_sheet_projection_outbox o
      where o.environment=v_environment and o.candidate_id=v_candidate_id
        and o.target='MASTER_AVAILABILITY_SHEET';
      v_actual_disposition:=case
        when v_pending_count+v_claimed_count+v_retry_count+v_terminal_count+v_command_count
          +v_other_batch_count+v_effect_count>0 then 'NONE'
        when v_deferred_count>0 then 'RECONCILED'
        else 'DRAINED' end;
      if v_requested_disposition<>v_actual_disposition then
        raise exception using errcode='40001',message='SEMANTIC_REJECTION';
      end if;
      if v_prior_mode<>v_new_mode and v_actual_disposition='NONE' then
        raise exception using errcode='55000',message='CANDIDATE_DAILY_NOT_READY';
      end if;

      v_strict_barrier:=v_new_mode='SUPABASE_PRIMARY'
        or (v_prior_mode='ROLLBACK_PENDING' and v_new_mode='GOOGLE_PRIMARY');
      if v_strict_barrier then
        if not(v_item ?& array['expected_generation_id','expected_generation_version',
          'expected_accepted_canonical_cursor','expected_required_visible_cursor','expected_effective_visible_cursor'])
           or v_item->>'expected_generation_id' !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
           or v_item->>'expected_generation_version' !~ '^[1-9]\d*$'
           or v_item->>'expected_accepted_canonical_cursor' !~ '^\d+$'
           or v_item->>'expected_required_visible_cursor' !~ '^\d+$'
           or v_item->>'expected_effective_visible_cursor' !~ '^\d+$' then
          raise exception using errcode='22023',message='VALIDATION_FAILED';
        end if;
        v_expected_generation_id:=(v_item->>'expected_generation_id')::uuid;
        v_expected_generation_version:=(v_item->>'expected_generation_version')::bigint;
        v_expected_accepted_cursor:=(v_item->>'expected_accepted_canonical_cursor')::bigint;
        v_expected_required_cursor:=(v_item->>'expected_required_visible_cursor')::bigint;
        v_expected_effective_cursor:=(v_item->>'expected_effective_visible_cursor')::bigint;
        if v_scope.active_generation_id is null or v_scope.active_generation_id<>v_expected_generation_id then
          raise exception using errcode='40001',message='SEMANTIC_REJECTION';
        end if;
        select * into v_generation from public.candidate_daily_rota_generations g
        where g.generation_id=v_scope.active_generation_id and g.environment=v_environment
          and g.candidate_id=v_candidate_id for update;
        select count(*) into v_generation_day_count from public.candidate_daily_rota_days d
        where d.generation_id=v_scope.active_generation_id and d.environment=v_environment
          and d.candidate_id=v_candidate_id;
        v_now:=clock_timestamp();
        if v_generation.generation_id is null or v_generation.state<>'ACTIVE'
           or v_generation.generation_version<>v_expected_generation_version
           or v_generation.expected_day_count<>14 or v_generation.actual_day_count<>14
           or v_generation_day_count<>14 or v_generation.activated_at_utc is null
           or v_generation.published_at_utc is null then
          raise exception using errcode='55000',message='GENERATION_INCOMPLETE';
        end if;
        if v_generation.published_at_utc<v_now-interval '120 seconds' then
          raise exception using errcode='55000',message='CANDIDATE_DAILY_NOT_READY';
        end if;
        select * into v_sync from private.candidate_daily_sync_state ss
        where ss.environment=v_environment and ss.candidate_id=v_candidate_id
          and ss.target='MASTER_AVAILABILITY_SHEET' for update;
        if v_sync.candidate_id is null then
          raise exception using errcode='55000',message='CANDIDATE_DAILY_NOT_READY';
        end if;
        perform private._candidate_daily_refresh_sync_state_v1(
          v_environment,v_candidate_id,'MASTER_AVAILABILITY_SHEET',v_now);
        select * into v_sync from private.candidate_daily_sync_state ss
        where ss.environment=v_environment and ss.candidate_id=v_candidate_id
          and ss.target='MASTER_AVAILABILITY_SHEET' for update;
        select count(*) into v_invalid_overlay_count
        from public.candidate_daily_sheet_projection_outbox o
        where o.environment=v_environment and o.candidate_id=v_candidate_id
          and o.target='MASTER_AVAILABILITY_SHEET' and o.state='DEFERRED_OVERLAY'
          and not(o.overlay_generation_id=v_generation.generation_id
            and o.overlay_generation_version=v_generation.generation_version
            and exists(select 1 from public.candidate_daily_rota_days d
              where d.generation_id=v_generation.generation_id and d.environment=v_environment
                and d.candidate_id=v_candidate_id and d.rota_date=o.availability_date
                and (d.booked or d.system_blocked) and d.source_row_hash=o.overlay_source_row_hash));
        if v_invalid_overlay_count>0 then
          raise exception using errcode='55000',message='PROJECTION_STALE_COMPLETION';
        end if;
        if v_pending_count+v_claimed_count+v_retry_count+v_terminal_count+v_command_count
             +v_other_batch_count+v_effect_count>0 or v_unknown_effect_count>0 then
          raise exception using errcode='55000',message='CANDIDATE_DAILY_NOT_READY';
        end if;
        if v_sync.accepted_canonical_cursor<>v_expected_accepted_cursor
           or v_sync.required_visible_cursor<>v_expected_required_cursor
           or v_sync.effective_visible_cursor<>v_expected_effective_cursor
           or v_expected_accepted_cursor<>v_scope.canonical_version
           or v_expected_required_cursor<>v_scope.canonical_version
           or v_expected_effective_cursor<>v_scope.canonical_version
           or v_sync.state<>'READY' or v_sync.pending_count<>0 or v_sync.retry_count<>0
           or v_sync.terminal_count<>0 or nullif(v_sync.observed_source_revision,'') is null
           or v_sync.last_reconciled_at_utc is null then
          raise exception using errcode='55000',message='CANDIDATE_DAILY_NOT_READY';
        end if;
        select greatest(v_generation.published_at_utc,
          coalesce(max(a.changed_at_utc),v_generation.published_at_utc),
          coalesce((select max(o.updated_at_utc) from public.candidate_daily_sheet_projection_outbox o
            where o.environment=v_environment and o.candidate_id=v_candidate_id
              and o.target='MASTER_AVAILABILITY_SHEET'),v_generation.published_at_utc))
        into v_latest_fact_at
        from public.candidate_daily_availability_days a
        where a.environment=v_environment and a.candidate_id=v_candidate_id;
        if v_sync.last_reconciled_at_utc<v_latest_fact_at then
          raise exception using errcode='55000',message='CANDIDATE_DAILY_NOT_READY';
        end if;
      elsif v_scope.active_generation_id is not null then
        select * into v_generation from public.candidate_daily_rota_generations g
        where g.generation_id=v_scope.active_generation_id and g.environment=v_environment
          and g.candidate_id=v_candidate_id;
        select * into v_sync from private.candidate_daily_sync_state ss
        where ss.environment=v_environment and ss.candidate_id=v_candidate_id
          and ss.target='MASTER_AVAILABILITY_SHEET';
      end if;
      v_transition_id:=gen_random_uuid();
      insert into private.candidate_daily_authority_transitions(transition_id,batch_receipt_id,environment,
        candidate_id,prior_authority_mode,new_authority_mode,effective_at_utc,canonical_version_snapshot,
        generation_id_snapshot,generation_version_snapshot,sync_snapshot_json,in_flight_disposition,
        entitlement_before,entitlement_after,actor_user_id,independent_approver_user_id,reason,
        evidence_sha256,outcome,correlation_id)
      select v_transition_id,v_batch.batch_receipt_id,v_environment,v_candidate_id,v_prior_mode,v_new_mode,now(),
        v_scope.canonical_version,v_scope.active_generation_id,v_generation.generation_version,
        coalesce(to_jsonb(v_sync),'{}'::jsonb),
        v_actual_disposition,v_entitlement_before,v_entitlement_after,v_actor,
        p_independent_approver,p_reason,p_evidence_sha256,'COMMITTED',p_correlation_id
      from (values(1))x(n);
      insert into private.candidate_daily_entitlements(environment,candidate_id,enabled,valid_from_utc,valid_to_utc,
        actor_user_id,reason,evidence_sha256)
      values(v_environment,v_candidate_id,v_entitlement_after,case when v_entitlement_after then now() else null end,
        case when v_entitlement_after then null else now() end,v_actor,p_reason,p_evidence_sha256)
      on conflict(environment,candidate_id) do update set enabled=excluded.enabled,
        valid_from_utc=excluded.valid_from_utc,valid_to_utc=excluded.valid_to_utc,actor_user_id=excluded.actor_user_id,
        reason=excluded.reason,evidence_sha256=excluded.evidence_sha256,updated_at_utc=now();
      update private.candidate_daily_authority_scopes set authority_mode=v_new_mode,
        last_transition_id=v_transition_id,transition_in_progress=false,updated_at_utc=now()
        where environment=v_environment and candidate_id=v_candidate_id;
      v_outcomes:=v_outcomes||jsonb_build_array(jsonb_build_object('index',v_index,'status','COMMITTED',
        'candidate_id',v_candidate_id,'transition_id',v_transition_id,'authority_mode',v_new_mode,
        'entitlement_enabled',v_entitlement_after));
    exception when others then
      v_error:=sqlerrm;
      if v_error in ('VALIDATION_FAILED','SEMANTIC_REJECTION','SOURCE_EVENT_CONFLICT',
        'CANDIDATE_DAILY_NOT_READY','GENERATION_INCOMPLETE','IDENTITY_LINK_MISSING',
        'IDENTITY_LINK_AMBIGUOUS','IDENTITY_LINK_CONFLICT','BATCH_IN_PROGRESS','COMMAND_IN_PROGRESS',
        'EFFECT_STATUS_UNKNOWN','PROJECTION_STALE_COMPLETION') then
        v_outcomes:=v_outcomes||jsonb_build_array(jsonb_build_object('index',v_index,'status','REJECTED','error_code',v_error));
      else raise; end if;
    end;
    v_index:=v_index+1;
  end loop;
  v_terminal:=jsonb_build_object('batch_receipt_id',v_batch.batch_receipt_id,'outcomes',v_outcomes);
  update private.candidate_daily_batch_receipts set state='COMPLETED',terminal_http_status=200,
    terminal_response_body=v_terminal,terminal_response_sha256=private._candidate_daily_json_sha256_v1(v_terminal),
    completed_at_utc=now(),updated_at_utc=now() where batch_receipt_id=v_batch.batch_receipt_id;
  return v_terminal;
end;
$function$;

-- candidate_daily_availability_apply_atomic_v1(jsonb,text,bigint,jsonb,text)
CREATE OR REPLACE FUNCTION public.candidate_daily_availability_apply_atomic_v1(p_internal_context jsonb, p_idempotency_key text, p_expected_availability_version bigint, p_changes jsonb, p_correlation_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_context jsonb; v_environment text; v_candidate_id uuid;
  v_scope private.candidate_daily_authority_scopes%rowtype; v_generation_id uuid;
  v_generation public.candidate_daily_rota_generations%rowtype; v_freshness jsonb;
  v_request_hash text; v_receipt public.candidate_daily_command_receipts%rowtype;
  v_command_id uuid:=gen_random_uuid(); v_new_version bigint; v_change jsonb; v_dates jsonb;
  v_row public.candidate_daily_rota_days%rowtype; v_terminal jsonb;
begin
  v_context:=private._candidate_daily_context_v1(p_internal_context,'CANDIDATE_SURFACE',true);
  v_environment:=v_context->>'environment'; v_candidate_id:=(v_context->>'candidate_id')::uuid;
  if p_idempotency_key !~ '^[A-Za-z0-9._~:+/-]{16,128}$'
     or p_expected_availability_version<0 or jsonb_typeof(p_changes)<>'array'
     or jsonb_array_length(p_changes) not between 1 and 14
     or p_correlation_id !~ '^[0-7][0-9A-HJKMNP-TV-Z]{25}$' then
    raise exception using errcode='22023',message='VALIDATION_FAILED';
  end if;
  if exists(select 1 from jsonb_array_elements(p_changes) c
    where (select count(*) from jsonb_object_keys(c))<>2
      or not(c ? 'date' and c ? 'availability')
      or c->>'availability' not in ('PENDING','NOT_AVAILABLE','LONG_DAY','NIGHT','LONG_DAY_OR_NIGHT')
      or c->>'date' !~ '^\d{4}-\d{2}-\d{2}$')
     or (select count(*)<>count(distinct c->>'date') from jsonb_array_elements(p_changes)c) then
    raise exception using errcode='22023',message='VALIDATION_FAILED';
  end if;
  v_request_hash:=private._candidate_daily_json_sha256_v1(jsonb_build_object(
    'operation','AVAILABILITY_APPLY','candidate_id',v_candidate_id,
    'expected_availability_version',p_expected_availability_version,'changes',p_changes));
  insert into public.candidate_daily_command_receipts(command_id,environment,candidate_id,actor_class,
    command_class,idempotency_key,request_sha256,canonical_version_before,state,correlation_id)
  values(v_command_id,v_environment,v_candidate_id,'CANDIDATE','AVAILABILITY_APPLY',p_idempotency_key,
    v_request_hash,p_expected_availability_version,'IN_PROGRESS',p_correlation_id)
  on conflict(environment,candidate_id,actor_class,idempotency_key) do nothing;
  select * into v_receipt from public.candidate_daily_command_receipts
    where environment=v_environment and candidate_id=v_candidate_id and actor_class='CANDIDATE'
      and idempotency_key=p_idempotency_key for update;
  if v_receipt.request_sha256<>v_request_hash then
    raise exception using errcode='23505',message='IDEMPOTENCY_KEY_REUSED';
  end if;
  if v_receipt.state<>'IN_PROGRESS' then
    return v_receipt.terminal_body_json||jsonb_build_object('_idempotent_replay',true);
  end if;
  select * into v_scope from private.candidate_daily_authority_scopes
    where environment=v_environment and candidate_id=v_candidate_id for update;
  if v_scope.canonical_version<>p_expected_availability_version then
    v_terminal:=jsonb_build_object('error_code','AVAILABILITY_VERSION_CONFLICT',
      'current_availability_version',v_scope.canonical_version);
    update public.candidate_daily_command_receipts set canonical_version_after=v_scope.canonical_version,
      state='FAILED_FINAL',terminal_http_status=409,terminal_body_json=v_terminal,
      terminal_body_sha256=private._candidate_daily_json_sha256_v1(v_terminal),
      completed_at_utc=now(),updated_at_utc=now() where command_id=v_receipt.command_id;
    return v_terminal;
  end if;
  v_generation_id:=v_scope.active_generation_id;
  select * into v_generation from public.candidate_daily_rota_generations
    where generation_id=v_generation_id and environment=v_environment and candidate_id=v_candidate_id;
  if v_generation.generation_id is null or v_generation.state<>'ACTIVE'
     or v_generation.actual_day_count<>14 or v_generation.expected_day_count<>14 then
    v_terminal:=jsonb_build_object('error_code','GENERATION_INCOMPLETE');
    update public.candidate_daily_command_receipts set canonical_version_after=v_scope.canonical_version,
      state='FAILED_FINAL',terminal_http_status=422,terminal_body_json=v_terminal,
      terminal_body_sha256=private._candidate_daily_json_sha256_v1(v_terminal),
      completed_at_utc=now(),updated_at_utc=now() where command_id=v_receipt.command_id;
    return v_terminal;
  end if;
  v_freshness:=private._candidate_daily_freshness_v1(v_environment,v_candidate_id,now());
  if coalesce((v_freshness->>'ready')::boolean,false) is not true then
    raise exception using errcode='55000',message='CANDIDATE_DAILY_NOT_READY';
  end if;
  for v_change in select value from jsonb_array_elements(p_changes) loop
    select * into v_row from public.candidate_daily_rota_days
      where generation_id=v_generation_id and rota_date=(v_change->>'date')::date;
    if v_row.generation_id is null or v_row.booked or v_row.system_blocked then
      v_terminal:=jsonb_build_object('error_code','AVAILABILITY_DATE_NOT_EDITABLE',
        'date',v_change->>'date');
      update public.candidate_daily_command_receipts set canonical_version_after=v_scope.canonical_version,
        state='FAILED_FINAL',terminal_http_status=422,terminal_body_json=v_terminal,
        terminal_body_sha256=private._candidate_daily_json_sha256_v1(v_terminal),
        completed_at_utc=now(),updated_at_utc=now() where command_id=v_receipt.command_id;
      return v_terminal;
    end if;
  end loop;
  v_new_version:=v_scope.canonical_version+1;
  update private.candidate_daily_authority_scopes set canonical_version=v_new_version,updated_at_utc=now()
    where environment=v_environment and candidate_id=v_candidate_id;
  for v_change in select value from jsonb_array_elements(p_changes) loop
    insert into public.candidate_daily_availability_days(environment,candidate_id,availability_date,
      preference,availability_version,source_class,source_command_id,changed_by_class,row_hash)
    values(v_environment,v_candidate_id,(v_change->>'date')::date,v_change->>'availability',v_new_version,
      'CANDIDATE',v_receipt.command_id,'CANDIDATE',private._candidate_daily_json_sha256_v1(v_change))
    on conflict(environment,candidate_id,availability_date) do update set
      preference=excluded.preference,availability_version=excluded.availability_version,
      source_class=excluded.source_class,source_command_id=excluded.source_command_id,
      changed_at_utc=now(),changed_by_class=excluded.changed_by_class,row_hash=excluded.row_hash;
    insert into public.candidate_daily_sheet_projection_outbox(environment,candidate_id,availability_date,
      availability_version,preference,command_id,correlation_id)
    values(v_environment,v_candidate_id,(v_change->>'date')::date,v_new_version,
      v_change->>'availability',v_receipt.command_id,p_correlation_id);
  end loop;
  insert into private.candidate_daily_sync_state(environment,candidate_id,target,accepted_canonical_cursor,
    required_visible_cursor,effective_visible_cursor,state)
  values(v_environment,v_candidate_id,'MASTER_AVAILABILITY_SHEET',v_new_version,v_new_version,
    greatest(0,v_new_version-1),'LAGGING')
  on conflict(environment,candidate_id,target) do update set
    accepted_canonical_cursor=greatest(private.candidate_daily_sync_state.accepted_canonical_cursor,v_new_version),
    required_visible_cursor=greatest(private.candidate_daily_sync_state.required_visible_cursor,v_new_version),
    state='LAGGING',updated_at_utc=now();
  perform private._candidate_daily_refresh_sync_state_v1(
    v_environment,v_candidate_id,'MASTER_AVAILABILITY_SHEET',now());
  select jsonb_agg(c->>'date' order by ord) into v_dates
    from jsonb_array_elements(p_changes) with ordinality x(c,ord);
  v_terminal:=jsonb_build_object('command_id',v_receipt.command_id,'availability_version',v_new_version,
    'changed_dates',v_dates);
  update public.candidate_daily_command_receipts set canonical_version_after=v_new_version,state='COMPLETED',
    terminal_http_status=200,terminal_body_json=v_terminal,
    terminal_body_sha256=private._candidate_daily_json_sha256_v1(v_terminal),completed_at_utc=now(),updated_at_utc=now()
  where command_id=v_receipt.command_id;
  return v_terminal;
end;
$function$;

-- candidate_daily_external_effect_claim_v1(jsonb,text,text,text,text,text,text,integer,timestamp with time zone,text)
CREATE OR REPLACE FUNCTION public.candidate_daily_external_effect_claim_v1(p_internal_context jsonb, p_effect_key text, p_operation text, p_candidate_source_hmac text, p_request_hash text, p_executor_id text, p_idempotency_key text, p_lease_seconds integer DEFAULT 120, p_now_utc timestamp with time zone DEFAULT now(), p_correlation_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_context jsonb; v_environment text; v_candidate_id uuid;
  v_receipt private.candidate_daily_external_effect_receipts%rowtype;
  v_receipt_id uuid:=gen_random_uuid(); v_lease_token text; v_lease_expiry timestamptz;
begin
  v_context:=private._candidate_daily_context_v1(p_internal_context,'SIGNED_SYSTEM_SYNC',false);
  v_environment:=v_context->>'environment';
  v_candidate_id:=private._candidate_daily_source_candidate_v1(v_environment,p_candidate_source_hmac);
  if length(p_effect_key) not between 16 and 256
     or p_operation not in ('RUNNING_LATE_SEND','CANNOT_ATTEND','LEAVE_EARLY','DNA','MESSAGE_SEEN','ESCALATION_STEP','ACKNOWLEDGEMENT')
     or p_request_hash !~ '^[a-f0-9]{64}$' or length(btrim(p_executor_id)) not between 8 and 128
     or p_idempotency_key !~ '^[A-Za-z0-9._~:+/-]{16,128}$' or p_lease_seconds not between 30 and 600
     or p_correlation_id !~ '^[0-7][0-9A-HJKMNP-TV-Z]{25}$' then
    raise exception using errcode='22023',message='VALIDATION_FAILED';
  end if;
  v_lease_token:=replace(gen_random_uuid()::text,'-','')||replace(gen_random_uuid()::text,'-','');
  v_lease_expiry:=p_now_utc+make_interval(secs=>p_lease_seconds);
  insert into private.candidate_daily_external_effect_receipts(effect_receipt_id,environment,candidate_id,
    effect_key,operation,request_hash,idempotency_key,state,first_claimed_at_utc,lease_owner,lease_token,
    lease_expires_at_utc,stable_provider_request_id,attempt_count,correlation_id,retain_until_utc)
  values(v_receipt_id,v_environment,v_candidate_id,p_effect_key,p_operation,p_request_hash,p_idempotency_key,
    'IN_PROGRESS',p_now_utc,p_executor_id,v_lease_token,v_lease_expiry,p_effect_key,1,p_correlation_id,
    p_now_utc+interval '7 years')
  on conflict do nothing;
  select * into v_receipt from private.candidate_daily_external_effect_receipts where
    (environment=v_environment and effect_key=p_effect_key)
    or (environment=v_environment and candidate_id=v_candidate_id and operation=p_operation
      and idempotency_key=p_idempotency_key)
    order by (effect_key=p_effect_key) desc limit 1 for update;
  if v_receipt.candidate_id<>v_candidate_id or v_receipt.operation<>p_operation
     or v_receipt.request_hash<>p_request_hash or v_receipt.idempotency_key<>p_idempotency_key then
    raise exception using errcode='23505',message='SOURCE_EVENT_CONFLICT';
  end if;
  if v_receipt.state='IN_PROGRESS' and v_receipt.lease_expires_at_utc<=p_now_utc then
    raise exception using errcode='55000',message='EFFECT_STATUS_UNKNOWN';
  end if;
  if v_receipt.state='IN_PROGRESS' then
    return jsonb_build_object('effect_receipt_id',v_receipt.effect_receipt_id,'state','CLAIMED',
      'lease_token',v_receipt.lease_token,'lease_expires_at',v_receipt.lease_expires_at_utc,'safe_result',null);
  end if;
  return jsonb_build_object('effect_receipt_id',v_receipt.effect_receipt_id,'state',v_receipt.state,
    'lease_token',null,'lease_expires_at',null,'safe_result',v_receipt.terminal_result_json,
    '_idempotent_replay',true);
end;
$function$;

-- candidate_daily_external_effect_complete_v1(jsonb,uuid,text,text,text,jsonb,timestamp with time zone,text)
CREATE OR REPLACE FUNCTION public.candidate_daily_external_effect_complete_v1(p_internal_context jsonb, p_effect_receipt_id uuid, p_lease_token text, p_outcome text, p_provider_reference_hash text DEFAULT NULL::text, p_safe_result jsonb DEFAULT NULL::jsonb, p_now_utc timestamp with time zone DEFAULT now(), p_correlation_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_context jsonb; v_environment text; v_receipt private.candidate_daily_external_effect_receipts%rowtype;
  v_terminal jsonb;
begin
  v_context:=private._candidate_daily_context_v1(p_internal_context,'SIGNED_SYSTEM_SYNC',false);
  v_environment:=v_context->>'environment';
  if p_effect_receipt_id is null or length(p_lease_token) not between 16 and 256
     or p_outcome not in ('COMPLETED','FAILED_FINAL','UNKNOWN')
     or (p_provider_reference_hash is not null and p_provider_reference_hash !~ '^[a-f0-9]{64}$')
     or (p_safe_result is not null and (jsonb_typeof(p_safe_result)<>'object' or p_safe_result<>'{}'::jsonb))
     or p_correlation_id !~ '^[0-7][0-9A-HJKMNP-TV-Z]{25}$' then
    raise exception using errcode='22023',message='VALIDATION_FAILED';
  end if;
  select * into v_receipt from private.candidate_daily_external_effect_receipts
    where effect_receipt_id=p_effect_receipt_id and environment=v_environment for update;
  if v_receipt.effect_receipt_id is null then raise exception using errcode='02000',message='EFFECT_NOT_FOUND'; end if;
  if v_receipt.state<>'IN_PROGRESS' then
    if v_receipt.lease_token<>p_lease_token or v_receipt.state<>p_outcome then
      raise exception using errcode='55000',message='LEASE_CONFLICT';
    end if;
    return jsonb_build_object('effect_receipt_id',v_receipt.effect_receipt_id,'state',v_receipt.state,
      '_idempotent_replay',true);
  end if;
  if v_receipt.lease_token<>p_lease_token then raise exception using errcode='55000',message='LEASE_CONFLICT'; end if;
  if v_receipt.lease_expires_at_utc<=p_now_utc then
    raise exception using errcode='55000',message='LEASE_EXPIRED_STATUS_REQUIRED';
  end if;
  v_terminal:=coalesce(p_safe_result,'{}'::jsonb);
  update private.candidate_daily_external_effect_receipts set state=p_outcome,
    provider_reference_hash=p_provider_reference_hash,terminal_result_json=v_terminal,
    terminal_body_sha256=private._candidate_daily_json_sha256_v1(v_terminal),completed_at_utc=p_now_utc,
    updated_at_utc=p_now_utc where effect_receipt_id=v_receipt.effect_receipt_id;
  return jsonb_build_object('effect_receipt_id',v_receipt.effect_receipt_id,'state',p_outcome);
end;
$function$;

-- candidate_daily_external_effect_status_get_v1(jsonb,text,timestamp with time zone,text)
CREATE OR REPLACE FUNCTION public.candidate_daily_external_effect_status_get_v1(p_internal_context jsonb, p_effect_key text, p_now_utc timestamp with time zone DEFAULT now(), p_correlation_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_context jsonb; v_environment text; v_receipt private.candidate_daily_external_effect_receipts%rowtype;
begin
  v_context:=private._candidate_daily_context_v1(p_internal_context,'SIGNED_SYSTEM_SYNC',false);
  v_environment:=v_context->>'environment';
  select * into v_receipt from private.candidate_daily_external_effect_receipts
    where environment=v_environment and effect_key=p_effect_key;
  if v_receipt.effect_receipt_id is null then raise exception using errcode='02000',message='EFFECT_NOT_FOUND'; end if;
  return jsonb_build_object('effect_key',v_receipt.effect_key,'operation',v_receipt.operation,
    'status',v_receipt.state,'created_at',v_receipt.created_at_utc,'updated_at',v_receipt.updated_at_utc);
end;
$function$;

-- candidate_daily_legacy_availability_apply_atomic_v1(jsonb,text,uuid,text,jsonb,text)
CREATE OR REPLACE FUNCTION public.candidate_daily_legacy_availability_apply_atomic_v1(p_internal_context jsonb, p_candidate_source_hmac text, p_request_id uuid, p_idempotency_key text, p_changes jsonb, p_correlation_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_context jsonb; v_environment text; v_candidate_id uuid;
  v_scope private.candidate_daily_authority_scopes%rowtype; v_receipt public.candidate_daily_command_receipts%rowtype;
  v_request_hash text; v_change jsonb; v_preference text; v_outcomes jsonb:='[]'::jsonb;
  v_accepted jsonb:='[]'::jsonb; v_seen text[]:='{}'; v_reason text; v_row public.candidate_daily_rota_days%rowtype;
  v_new_version bigint; v_terminal jsonb;
begin
  v_context:=private._candidate_daily_context_v1(p_internal_context,'LEGACY_COMPAT',false);
  v_environment:=v_context->>'environment';
  v_candidate_id:=private._candidate_daily_source_candidate_v1(v_environment,p_candidate_source_hmac);
  if p_request_id is null or p_idempotency_key !~ '^[A-Za-z0-9._~:+/-]{16,128}$'
     or jsonb_typeof(p_changes)<>'array' or jsonb_array_length(p_changes) not between 1 and 14
     or p_correlation_id !~ '^[0-7][0-9A-HJKMNP-TV-Z]{25}$' then
    raise exception using errcode='22023',message='VALIDATION_FAILED';
  end if;
  v_request_hash:=private._candidate_daily_json_sha256_v1(jsonb_build_object(
    'operation','LEGACY_AVAILABILITY_APPLY','candidate_source_hmac',p_candidate_source_hmac,
    'request_id',p_request_id,'changes',p_changes));
  insert into public.candidate_daily_command_receipts(command_id,environment,candidate_id,actor_class,
    command_class,idempotency_key,request_sha256,canonical_version_before,state,correlation_id)
  select p_request_id,v_environment,v_candidate_id,'LEGACY_ADAPTER','LEGACY_AVAILABILITY_APPLY',
    p_idempotency_key,v_request_hash,s.canonical_version,'IN_PROGRESS',p_correlation_id
  from private.candidate_daily_authority_scopes s
  where s.environment=v_environment and s.candidate_id=v_candidate_id
  on conflict do nothing;
  select * into v_receipt from public.candidate_daily_command_receipts
    where command_id=p_request_id or (environment=v_environment and candidate_id=v_candidate_id
      and actor_class='LEGACY_ADAPTER' and idempotency_key=p_idempotency_key)
    order by (command_id=p_request_id) desc limit 1 for update;
  if v_receipt.command_id is null then raise exception using errcode='55000',message='CANDIDATE_DAILY_NOT_READY'; end if;
  if v_receipt.candidate_id<>v_candidate_id or v_receipt.request_sha256<>v_request_hash then
    raise exception using errcode='23505',message='IDEMPOTENCY_KEY_REUSED';
  end if;
  if v_receipt.state<>'IN_PROGRESS' then
    return v_receipt.terminal_body_json||jsonb_build_object('_idempotent_replay',true);
  end if;
  select * into v_scope from private.candidate_daily_authority_scopes
    where environment=v_environment and candidate_id=v_candidate_id for update;
  for v_change in select value from jsonb_array_elements(p_changes) loop
    v_reason:=null; v_preference:=private._candidate_daily_preference_v1(v_change->>'availability');
    if (select count(*) from jsonb_object_keys(v_change))<>2
       or not(v_change ? 'date' and v_change ? 'availability') or v_preference is null
       or v_change->>'date' !~ '^\d{4}-\d{2}-\d{2}$' then v_reason:='INVALID_VALUE';
    elsif (v_change->>'date')=any(v_seen) then v_reason:='DUPLICATE_DATE';
    else
      v_seen:=array_append(v_seen,v_change->>'date');
      select * into v_row from public.candidate_daily_rota_days
        where generation_id=v_scope.active_generation_id and rota_date=(v_change->>'date')::date;
      if v_row.generation_id is null then v_reason:='OUTSIDE_WINDOW';
      elsif v_row.booked then v_reason:='BOOKED';
      elsif v_row.system_blocked then v_reason:='BLOCKED';
      elsif v_scope.authority_mode not in ('GOOGLE_PRIMARY','ROLLBACK_PENDING','SUPABASE_PRIMARY')
        or v_scope.transition_in_progress then v_reason:='NOT_EDITABLE'; end if;
    end if;
    if v_reason is null then
      v_accepted:=v_accepted||jsonb_build_array(jsonb_build_object('date',v_change->>'date','preference',v_preference));
      v_outcomes:=v_outcomes||jsonb_build_array(jsonb_build_object('date',v_change->>'date','applied',true));
    else
      v_outcomes:=v_outcomes||jsonb_build_array(jsonb_build_object('date',coalesce(v_change->>'date','1970-01-01'),
        'applied',false,'reason',v_reason));
    end if;
  end loop;
  if jsonb_array_length(v_accepted)>0 then
    v_new_version:=v_scope.canonical_version+1;
    update private.candidate_daily_authority_scopes set canonical_version=v_new_version,updated_at_utc=now()
      where environment=v_environment and candidate_id=v_candidate_id;
    for v_change in select value from jsonb_array_elements(v_accepted) loop
      insert into public.candidate_daily_availability_days(environment,candidate_id,availability_date,
        preference,availability_version,source_class,source_command_id,changed_by_class,row_hash)
      values(v_environment,v_candidate_id,(v_change->>'date')::date,v_change->>'preference',v_new_version,
        'LEGACY_ADAPTER',v_receipt.command_id,'LEGACY_ADAPTER',private._candidate_daily_json_sha256_v1(v_change))
      on conflict(environment,candidate_id,availability_date) do update set
        preference=excluded.preference,availability_version=excluded.availability_version,
        source_class=excluded.source_class,source_command_id=excluded.source_command_id,
        changed_at_utc=now(),changed_by_class=excluded.changed_by_class,row_hash=excluded.row_hash;
    end loop;
    insert into private.candidate_daily_sync_state(environment,candidate_id,target,accepted_canonical_cursor,
      required_visible_cursor,delivered_visible_cursor,effective_visible_cursor,state,last_acknowledged_at_utc)
    values(v_environment,v_candidate_id,'MASTER_AVAILABILITY_SHEET',v_new_version,v_new_version,
      v_new_version,v_new_version,'READY',now())
    on conflict(environment,candidate_id,target) do update set
      accepted_canonical_cursor=greatest(private.candidate_daily_sync_state.accepted_canonical_cursor,v_new_version),
      required_visible_cursor=greatest(private.candidate_daily_sync_state.required_visible_cursor,v_new_version),
      delivered_visible_cursor=greatest(private.candidate_daily_sync_state.delivered_visible_cursor,v_new_version),
      effective_visible_cursor=greatest(private.candidate_daily_sync_state.effective_visible_cursor,v_new_version),
      state='READY',last_acknowledged_at_utc=now(),updated_at_utc=now();
  else v_new_version:=null; end if;
  v_terminal:=jsonb_strip_nulls(jsonb_build_object('request_receipt_id',v_receipt.command_id,
    'committed_version',v_new_version,'outcomes',v_outcomes));
  update public.candidate_daily_command_receipts set canonical_version_after=coalesce(v_new_version,canonical_version_before),
    state='COMPLETED',terminal_http_status=200,terminal_body_json=v_terminal,
    terminal_body_sha256=private._candidate_daily_json_sha256_v1(v_terminal),completed_at_utc=now(),updated_at_utc=now()
  where command_id=v_receipt.command_id;
  return v_terminal;
end;
$function$;

-- candidate_daily_legacy_availability_status_get_v1(jsonb,text,uuid,text)
CREATE OR REPLACE FUNCTION public.candidate_daily_legacy_availability_status_get_v1(p_internal_context jsonb, p_candidate_source_hmac text, p_request_id uuid, p_correlation_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_context jsonb; v_environment text; v_candidate_id uuid;
  v_receipt public.candidate_daily_command_receipts%rowtype;
begin
  v_context:=private._candidate_daily_context_v1(p_internal_context,'LEGACY_COMPAT',false);
  v_environment:=v_context->>'environment';
  v_candidate_id:=private._candidate_daily_source_candidate_v1(v_environment,p_candidate_source_hmac);
  select * into v_receipt from public.candidate_daily_command_receipts
  where command_id=p_request_id and environment=v_environment and candidate_id=v_candidate_id
    and actor_class='LEGACY_ADAPTER' and command_class='LEGACY_AVAILABILITY_APPLY';
  if v_receipt.command_id is null then raise exception using errcode='02000',message='NOT_FOUND'; end if;
  return jsonb_build_object('request_id',p_request_id,'state',v_receipt.state,
    'terminal_response',case when v_receipt.state='IN_PROGRESS' then null else
      jsonb_build_object('ok',true,'correlation_id',v_receipt.correlation_id,'result',v_receipt.terminal_body_json) end);
end;
$function$;

-- candidate_daily_projection_claim_v1(jsonb,uuid,text,text,text,integer,integer,text)
CREATE OR REPLACE FUNCTION public.candidate_daily_projection_claim_v1(p_internal_context jsonb, p_claim_request_id uuid, p_idempotency_key text, p_target text, p_claimant text, p_max_items integer DEFAULT 50, p_lease_seconds integer DEFAULT 120, p_correlation_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_context jsonb; v_environment text; v_request_hash text;
  v_batch private.candidate_daily_batch_receipts%rowtype; v_batch_id uuid:=gen_random_uuid();
  v_items jsonb:='[]'::jsonb; v_row public.candidate_daily_sheet_projection_outbox%rowtype;
  v_link text; v_token text; v_expiry timestamptz; v_terminal jsonb;
begin
  v_context:=private._candidate_daily_context_v1(p_internal_context,'SIGNED_SYSTEM_SYNC',false);
  v_environment:=v_context->>'environment';
  if p_claim_request_id is null or p_idempotency_key !~ '^[A-Za-z0-9._~:+/-]{16,128}$'
     or p_target<>'MASTER_AVAILABILITY_SHEET' or length(btrim(p_claimant)) not between 8 and 128
     or p_max_items not between 1 and 100 or p_lease_seconds not between 30 and 600
     or p_correlation_id !~ '^[0-7][0-9A-HJKMNP-TV-Z]{25}$' then
    raise exception using errcode='22023',message='VALIDATION_FAILED';
  end if;
  v_request_hash:=private._candidate_daily_json_sha256_v1(jsonb_build_object(
    'operation','PROJECTION_CLAIM','claim_request_id',p_claim_request_id,'target',p_target,
    'claimant',p_claimant,'max_items',p_max_items,'lease_seconds',p_lease_seconds));
  insert into private.candidate_daily_batch_receipts(batch_receipt_id,environment,actor_class,operation_class,
    idempotency_key,request_hash,item_keys_json,item_count,state,claim_request_id,claim_target,claim_limit,
    correlation_id)
  values(v_batch_id,v_environment,'SIGNED_SYSTEM','PROJECTION_CLAIM',p_idempotency_key,v_request_hash,
    jsonb_build_array('claim:'||p_claim_request_id::text),1,'IN_PROGRESS',p_claim_request_id,p_target,p_max_items,
    p_correlation_id)
  on conflict(environment,actor_class,operation_class,idempotency_key) do nothing;
  select * into v_batch from private.candidate_daily_batch_receipts
    where environment=v_environment and actor_class='SIGNED_SYSTEM' and operation_class='PROJECTION_CLAIM'
      and idempotency_key=p_idempotency_key for update;
  if v_batch.request_hash<>v_request_hash or v_batch.claim_request_id<>p_claim_request_id then
    raise exception using errcode='23505',message='IDEMPOTENCY_KEY_REUSED';
  end if;
  if v_batch.state<>'IN_PROGRESS' then
    if exists(select 1 from jsonb_array_elements(coalesce(v_batch.claimed_items_json,'[]'::jsonb))i
      where (i->>'lease_expires_at')::timestamptz<=now()) then
      raise exception using errcode='55000',message='LEASE_EXPIRED_STATUS_REQUIRED';
    end if;
    return v_batch.terminal_response_body||jsonb_build_object('_idempotent_replay',true);
  end if;
  if exists(select 1 from public.candidate_daily_sheet_projection_outbox o
    where o.environment=v_environment and o.target=p_target and o.state='CLAIMED'
      and o.lease_owner=p_claimant and o.lease_expires_at_utc>now()) then
    raise exception using errcode='55000',message='LEASE_CONFLICT';
  end if;
  v_expiry:=now()+make_interval(secs=>p_lease_seconds);
  for v_row in
    select o.* from public.candidate_daily_sheet_projection_outbox o
    where o.environment=v_environment and o.target=p_target
      and o.state in ('PENDING','RETRY') and o.next_available_at_utc<=now()
    order by o.created_at_utc,o.outbox_id
    for update skip locked limit p_max_items
  loop
    select l.identifier_hmac into v_link from private.candidate_daily_source_links l
      where l.environment=v_environment and l.candidate_id=v_row.candidate_id
        and l.source_system='GOOGLE_CREDENTIALLY_PUBLIC_ID' and l.state='PRIMARY'
        and l.valid_from_utc<=now() and (l.valid_to_utc is null or l.valid_to_utc>now())
      order by l.hmac_key_version desc limit 1;
    if v_link is null then continue; end if;
    v_token:=replace(gen_random_uuid()::text,'-','')||replace(gen_random_uuid()::text,'-','');
    update public.candidate_daily_sheet_projection_outbox set state='CLAIMED',lease_owner=p_claimant,
      lease_token=v_token,lease_expires_at_utc=v_expiry,updated_at_utc=now() where outbox_id=v_row.outbox_id;
    v_items:=v_items||jsonb_build_array(jsonb_build_object('outbox_id',v_row.outbox_id,
      'lease_token',v_token,'lease_expires_at',v_expiry,'candidate_source_hmac',v_link,
      'date',v_row.availability_date,'availability_version',v_row.availability_version,
      'availability',private._candidate_daily_legacy_value_v1(v_row.preference)));
  end loop;
  v_terminal:=jsonb_build_object('claim_request_id',p_claim_request_id,'batch_receipt_id',v_batch.batch_receipt_id,
    'lease_set_expires_at',v_expiry,'items',v_items);
  update private.candidate_daily_batch_receipts set state='COMPLETED',lease_owner=p_claimant,
    lease_expires_at_utc=v_expiry,claimed_items_json=v_items,terminal_http_status=200,
    terminal_response_body=v_terminal,terminal_response_sha256=private._candidate_daily_json_sha256_v1(v_terminal),
    completed_at_utc=now(),updated_at_utc=now() where batch_receipt_id=v_batch.batch_receipt_id;
  return v_terminal;
end;
$function$;

-- candidate_daily_projection_complete_atomic_v1(jsonb,uuid,text,jsonb,text)
CREATE OR REPLACE FUNCTION public.candidate_daily_projection_complete_atomic_v1(p_internal_context jsonb, p_batch_request_id uuid, p_idempotency_key text, p_items jsonb, p_correlation_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_context jsonb; v_environment text; v_request_hash text;
  v_batch private.candidate_daily_batch_receipts%rowtype; v_batch_id uuid:=gen_random_uuid();
  v_item jsonb; v_row public.candidate_daily_sheet_projection_outbox%rowtype;
  v_scope private.candidate_daily_authority_scopes%rowtype;
  v_generation public.candidate_daily_rota_generations%rowtype;
  v_day public.candidate_daily_rota_days%rowtype;
  v_item_keys jsonb; v_index integer:=0; v_state text; v_outcomes jsonb:='[]'::jsonb; v_terminal jsonb;
  v_sync jsonb;
begin
  v_context:=private._candidate_daily_context_v1(p_internal_context,'SIGNED_SYSTEM_SYNC',false);
  v_environment:=v_context->>'environment';
  if p_batch_request_id is null or p_idempotency_key !~ '^[A-Za-z0-9._~:+/-]{16,128}$'
     or jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items) not between 1 and 100
     or p_correlation_id !~ '^[0-7][0-9A-HJKMNP-TV-Z]{25}$' then
    raise exception using errcode='22023',message='VALIDATION_FAILED';
  end if;
  select jsonb_agg(i->>'outbox_id' order by ord) into v_item_keys
    from jsonb_array_elements(p_items) with ordinality x(i,ord);
  v_request_hash:=private._candidate_daily_json_sha256_v1(jsonb_build_object(
    'operation','PROJECTION_COMPLETE','batch_request_id',p_batch_request_id,'items',p_items));
  insert into private.candidate_daily_batch_receipts(batch_receipt_id,environment,actor_class,operation_class,
    idempotency_key,request_hash,item_keys_json,item_count,state,correlation_id)
  values(v_batch_id,v_environment,'SIGNED_SYSTEM','PROJECTION_COMPLETE',p_idempotency_key,v_request_hash,
    v_item_keys,jsonb_array_length(p_items),'IN_PROGRESS',p_correlation_id)
  on conflict(environment,actor_class,operation_class,idempotency_key) do nothing;
  select * into v_batch from private.candidate_daily_batch_receipts
    where environment=v_environment and actor_class='SIGNED_SYSTEM' and operation_class='PROJECTION_COMPLETE'
      and idempotency_key=p_idempotency_key for update;
  if v_batch.request_hash<>v_request_hash then raise exception using errcode='23505',message='IDEMPOTENCY_KEY_REUSED'; end if;
  if v_batch.state<>'IN_PROGRESS' then
    return v_batch.terminal_response_body||jsonb_build_object('_idempotent_replay',true);
  end if;
  for v_item in select value from jsonb_array_elements(p_items) loop
    if not(v_item ?& array['outbox_id','lease_token','outcome'])
       or v_item->>'outcome' not in ('DELIVERED','RETRY','DEFERRED_OVERLAY','TERMINAL') then
      raise exception using errcode='22023',message='VALIDATION_FAILED';
    end if;
    select * into v_row from public.candidate_daily_sheet_projection_outbox
      where outbox_id=(v_item->>'outbox_id')::uuid and environment=v_environment for update;
    if v_row.outbox_id is null or v_row.state<>'CLAIMED' or v_row.lease_token<>v_item->>'lease_token' then
      v_outcomes:=v_outcomes||jsonb_build_array(jsonb_build_object('index',v_index,'accepted',false,'state','LEASE_CONFLICT'));
    elsif v_row.lease_expires_at_utc<=now() then
      raise exception using errcode='55000',message='LEASE_EXPIRED_STATUS_REQUIRED';
    else
      v_state:=v_item->>'outcome';
      if v_state='DELIVERED' then
        if nullif(btrim(v_item->>'observed_sheet_revision'),'') is null
           or length(v_item->>'observed_sheet_revision')>160 then
          raise exception using errcode='22023',message='VALIDATION_FAILED';
        end if;
        update public.candidate_daily_sheet_projection_outbox set state='DELIVERED',
          observed_sheet_revision=nullif(v_item->>'observed_sheet_revision',''),completed_at_utc=now(),
          overlay_generation_id=null,overlay_generation_version=null,overlay_source_row_hash=null,
          lease_owner=null,lease_token=null,lease_expires_at_utc=null,updated_at_utc=now()
        where outbox_id=v_row.outbox_id;
      elsif v_state='RETRY' then
        update public.candidate_daily_sheet_projection_outbox set
          state=case when delivery_attempt_count+1>=12 then 'TERMINAL' else 'RETRY' end,
          delivery_attempt_count=delivery_attempt_count+1,
          next_available_at_utc=now()+least(interval '24 hours',make_interval(secs=>power(2,least(delivery_attempt_count+1,16))::integer)),
          safe_error_code=left(nullif(v_item->>'error_code',''),80),
          completed_at_utc=case when delivery_attempt_count+1>=12 then now() else null end,
          lease_owner=null,lease_token=null,lease_expires_at_utc=null,updated_at_utc=now()
        where outbox_id=v_row.outbox_id returning state into v_state;
      elsif v_state='DEFERRED_OVERLAY' then
        if nullif(btrim(v_item->>'observed_sheet_revision'),'') is null
           or length(v_item->>'observed_sheet_revision')>160 then
          raise exception using errcode='22023',message='PROJECTION_STALE_COMPLETION';
        end if;
        select * into v_scope from private.candidate_daily_authority_scopes
          where environment=v_environment and candidate_id=v_row.candidate_id for update;
        select * into v_generation from public.candidate_daily_rota_generations
          where generation_id=v_scope.active_generation_id and environment=v_environment
            and candidate_id=v_row.candidate_id and state='ACTIVE';
        select * into v_day from public.candidate_daily_rota_days
          where generation_id=v_generation.generation_id and environment=v_environment
            and candidate_id=v_row.candidate_id and rota_date=v_row.availability_date;
        if v_generation.generation_id is null or v_day.generation_id is null
           or not(v_day.booked or v_day.system_blocked) then
          raise exception using errcode='55000',message='PROJECTION_STALE_COMPLETION';
        end if;
        update public.candidate_daily_sheet_projection_outbox set state='DEFERRED_OVERLAY',
          deferral_count=deferral_count+1,observed_sheet_revision=v_item->>'observed_sheet_revision',
          overlay_generation_id=v_generation.generation_id,
          overlay_generation_version=v_generation.generation_version,
          overlay_source_row_hash=v_day.source_row_hash,completed_at_utc=now(),
          lease_owner=null,lease_token=null,lease_expires_at_utc=null,
          updated_at_utc=now() where outbox_id=v_row.outbox_id;
      else
        update public.candidate_daily_sheet_projection_outbox set state='TERMINAL',
          safe_error_code=left(nullif(v_item->>'error_code',''),80),completed_at_utc=now(),
          lease_owner=null,lease_token=null,lease_expires_at_utc=null,updated_at_utc=now()
        where outbox_id=v_row.outbox_id;
      end if;
      v_sync:=private._candidate_daily_refresh_sync_state_v1(
        v_environment,v_row.candidate_id,v_row.target,now());
      v_outcomes:=v_outcomes||jsonb_build_array(jsonb_build_object('index',v_index,'accepted',true,
        'state',v_state,'delivered_visible_cursor',coalesce((v_sync->>'delivered_visible_cursor')::bigint,0)));
    end if;
    v_index:=v_index+1;
  end loop;
  v_terminal:=jsonb_build_object('batch_receipt_id',v_batch.batch_receipt_id,'outcomes',v_outcomes);
  update private.candidate_daily_batch_receipts set state='COMPLETED',terminal_http_status=200,
    terminal_response_body=v_terminal,terminal_response_sha256=private._candidate_daily_json_sha256_v1(v_terminal),
    completed_at_utc=now(),updated_at_utc=now() where batch_receipt_id=v_batch.batch_receipt_id;
  return v_terminal;
end;
$function$;

-- candidate_daily_reconciliation_apply_atomic_v1(jsonb,uuid,text,jsonb,text)
CREATE OR REPLACE FUNCTION public.candidate_daily_reconciliation_apply_atomic_v1(p_internal_context jsonb, p_batch_request_id uuid, p_idempotency_key text, p_observations jsonb, p_correlation_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_context jsonb; v_environment text; v_route_operation text; v_operation_class text;
  v_request_hash text; v_batch private.candidate_daily_batch_receipts%rowtype; v_batch_id uuid:=gen_random_uuid();
  v_item_keys jsonb; v_item jsonb; v_index integer:=0; v_candidate_id uuid;
  v_scope private.candidate_daily_authority_scopes%rowtype; v_day public.candidate_daily_rota_days%rowtype;
  v_availability public.candidate_daily_availability_days%rowtype; v_preference text; v_command_id uuid;
  v_command public.candidate_daily_command_receipts%rowtype; v_item_hash text; v_item_key text;
  v_outcomes jsonb:='[]'::jsonb; v_terminal jsonb; v_classification text; v_error text;
begin
  v_context:=private._candidate_daily_context_v1(p_internal_context,'SIGNED_SYSTEM_SYNC',false);
  v_environment:=v_context->>'environment';
  v_route_operation:=upper(coalesce(nullif(p_internal_context->>'route_operation',''),'RECONCILIATION'));
  if v_route_operation not in ('RECONCILIATION','SHEET_EDIT_INGEST') then
    raise exception using errcode='22023',message='VALIDATION_FAILED';
  end if;
  v_operation_class:=case when v_route_operation='SHEET_EDIT_INGEST' then 'SHEET_EDIT_INGEST' else 'RECONCILIATION' end;
  if p_batch_request_id is null or p_idempotency_key !~ '^[A-Za-z0-9._~:+/-]{16,128}$'
     or jsonb_typeof(p_observations)<>'array' or jsonb_array_length(p_observations) not between 1 and 100
     or p_correlation_id !~ '^[0-7][0-9A-HJKMNP-TV-Z]{25}$' then
    raise exception using errcode='22023',message='VALIDATION_FAILED';
  end if;
  select jsonb_agg(i->>'item_key' order by ord) into v_item_keys
    from jsonb_array_elements(p_observations) with ordinality x(i,ord);
  if exists(select 1 from jsonb_array_elements(p_observations)i where i->>'item_key' !~ '^[A-Za-z0-9._~-]{8,160}$')
     or jsonb_array_length(v_item_keys)<>(select count(distinct x) from jsonb_array_elements_text(v_item_keys)x) then
    raise exception using errcode='22023',message='VALIDATION_FAILED';
  end if;
  v_request_hash:=private._candidate_daily_json_sha256_v1(jsonb_build_object('operation',v_route_operation,
    'batch_request_id',p_batch_request_id,'items',p_observations));
  insert into private.candidate_daily_batch_receipts(batch_receipt_id,environment,actor_class,operation_class,
    idempotency_key,request_hash,item_keys_json,item_count,state,correlation_id)
  values(v_batch_id,v_environment,'SIGNED_SYSTEM',v_operation_class,p_idempotency_key,v_request_hash,
    v_item_keys,jsonb_array_length(p_observations),'IN_PROGRESS',p_correlation_id)
  on conflict(environment,actor_class,operation_class,idempotency_key) do nothing;
  select * into v_batch from private.candidate_daily_batch_receipts where environment=v_environment
    and actor_class='SIGNED_SYSTEM' and operation_class=v_operation_class and idempotency_key=p_idempotency_key for update;
  if v_batch.request_hash<>v_request_hash then raise exception using errcode='23505',message='IDEMPOTENCY_KEY_REUSED'; end if;
  if v_batch.state<>'IN_PROGRESS' then
    return v_batch.terminal_response_body||jsonb_build_object('_idempotent_replay',true);
  end if;
  perform 1 from private.candidate_daily_authority_scopes s where s.environment=v_environment and s.candidate_id in (
    select distinct private._candidate_daily_source_candidate_v1(v_environment,i->>'candidate_source_hmac')
    from jsonb_array_elements(p_observations)i
  ) order by s.candidate_id for update;
  for v_item in select value from jsonb_array_elements(p_observations) loop
    v_error:=null; v_classification:=null;
    begin
      v_candidate_id:=private._candidate_daily_source_candidate_v1(v_environment,v_item->>'candidate_source_hmac');
      if v_route_operation='SHEET_EDIT_INGEST' then
        if not(v_item ?& array['source_event_id','source_revision','editor_hmac','sheet','cell','date',
          'availability','source_event_time','source_hash','item_key'])
          or v_item->>'sheet'<>'Availability' or v_item->>'cell' !~ '^[A-Z]{1,3}[1-9][0-9]{0,5}$'
          or v_item->>'editor_hmac' !~ '^[a-f0-9]{64}$' or v_item->>'source_hash' !~ '^[a-f0-9]{64}$' then
          raise exception using errcode='22023',message='VALIDATION_FAILED';
        end if;
        v_preference:=private._candidate_daily_preference_v1(v_item->>'availability');
        if v_preference is null then raise exception using errcode='22023',message='VALIDATION_FAILED'; end if;
        v_item_hash:=private._candidate_daily_json_sha256_v1(v_item);
        v_item_key:=left(p_idempotency_key||':item:'||v_item->>'item_key',160);
        v_command_id:=gen_random_uuid();
        select * into v_scope from private.candidate_daily_authority_scopes
          where environment=v_environment and candidate_id=v_candidate_id for update;
        insert into public.candidate_daily_command_receipts(command_id,environment,candidate_id,actor_class,
          command_class,idempotency_key,request_sha256,source_system,source_event_id,source_revision,
          source_event_time,item_key,canonical_version_before,state,correlation_id)
        values(v_command_id,v_environment,v_candidate_id,'SIGNED_SYSTEM','SHEET_EDIT_INGEST',v_item_key,
          v_item_hash,'MASTER_AVAILABILITY_SHEET',v_item->>'source_event_id',v_item->>'source_revision',
          (v_item->>'source_event_time')::timestamptz,v_item->>'item_key',v_scope.canonical_version,
          'IN_PROGRESS',p_correlation_id)
        on conflict do nothing;
        select * into v_command from public.candidate_daily_command_receipts where
          (environment=v_environment and source_system='MASTER_AVAILABILITY_SHEET'
            and source_event_id=v_item->>'source_event_id' and item_key=v_item->>'item_key')
          or (environment=v_environment and candidate_id=v_candidate_id and actor_class='SIGNED_SYSTEM'
            and idempotency_key=v_item_key)
          order by (source_event_id=v_item->>'source_event_id') desc limit 1 for update;
        if v_command.request_sha256<>v_item_hash then
          raise exception using errcode='23505',message='SOURCE_EVENT_CONFLICT';
        end if;
        if v_command.state='COMPLETED' then
          v_outcomes:=v_outcomes||jsonb_build_array(jsonb_build_object('index',v_index,'status','REPLAYED',
            'availability_version',v_command.canonical_version_after));
        else
          select * into v_day from public.candidate_daily_rota_days
            where generation_id=v_scope.active_generation_id and rota_date=(v_item->>'date')::date;
          if v_day.generation_id is null or v_day.booked or v_day.system_blocked then
            raise exception using errcode='22023',message='AVAILABILITY_DATE_NOT_EDITABLE';
          end if;
          update private.candidate_daily_authority_scopes set canonical_version=canonical_version+1,updated_at_utc=now()
            where environment=v_environment and candidate_id=v_candidate_id returning canonical_version into v_scope.canonical_version;
          insert into public.candidate_daily_availability_days(environment,candidate_id,availability_date,preference,
            availability_version,source_class,source_command_id,changed_by_class,row_hash)
          values(v_environment,v_candidate_id,(v_item->>'date')::date,v_preference,v_scope.canonical_version,
            'SIGNED_SYSTEM',v_command.command_id,'SIGNED_SYSTEM',v_item_hash)
          on conflict(environment,candidate_id,availability_date) do update set preference=excluded.preference,
            availability_version=excluded.availability_version,source_class=excluded.source_class,
            source_command_id=excluded.source_command_id,changed_by_class=excluded.changed_by_class,
            row_hash=excluded.row_hash,changed_at_utc=now();
          insert into private.candidate_daily_sync_state(environment,candidate_id,target,accepted_canonical_cursor,
            required_visible_cursor,delivered_visible_cursor,overlay_proof_cursor,effective_visible_cursor,
            observed_source_revision,state,last_acknowledged_at_utc)
          values(v_environment,v_candidate_id,'MASTER_AVAILABILITY_SHEET',v_scope.canonical_version,
            v_scope.canonical_version,v_scope.canonical_version,v_scope.canonical_version,v_scope.canonical_version,
            v_item->>'source_revision','READY',now())
          on conflict(environment,candidate_id,target) do update set
            accepted_canonical_cursor=greatest(private.candidate_daily_sync_state.accepted_canonical_cursor,v_scope.canonical_version),
            required_visible_cursor=greatest(private.candidate_daily_sync_state.required_visible_cursor,v_scope.canonical_version),
            delivered_visible_cursor=greatest(private.candidate_daily_sync_state.delivered_visible_cursor,v_scope.canonical_version),
            effective_visible_cursor=greatest(private.candidate_daily_sync_state.effective_visible_cursor,v_scope.canonical_version),
            observed_source_revision=excluded.observed_source_revision,state='READY',last_acknowledged_at_utc=now(),updated_at_utc=now();
          update public.candidate_daily_command_receipts set canonical_version_after=v_scope.canonical_version,
            state='COMPLETED',terminal_http_status=200,
            terminal_body_json=jsonb_build_object('availability_version',v_scope.canonical_version),
            terminal_body_sha256=private._candidate_daily_json_sha256_v1(jsonb_build_object('availability_version',v_scope.canonical_version)),
            completed_at_utc=now(),updated_at_utc=now() where command_id=v_command.command_id;
          v_outcomes:=v_outcomes||jsonb_build_array(jsonb_build_object('index',v_index,'status','COMMITTED',
            'availability_version',v_scope.canonical_version));
        end if;
      else
        if not(v_item ?& array['date','observed_value','observed_sheet_revision','source_event_id',
          'source_revision','source_event_time','source_hash','item_key'])
          or v_item->>'source_hash' !~ '^[a-f0-9]{64}$' then
          raise exception using errcode='22023',message='VALIDATION_FAILED';
        end if;
        v_preference:=private._candidate_daily_preference_v1(v_item->>'observed_value');
        select * into v_availability from public.candidate_daily_availability_days
          where environment=v_environment and candidate_id=v_candidate_id and availability_date=(v_item->>'date')::date;
        if v_preference is null then v_classification:='AMBIGUOUS';
        elsif v_availability.candidate_id is null then v_classification:='CANONICAL_COMMAND_REQUIRED';
        elsif v_availability.preference=v_preference then
          v_classification:='MATCH';
          update public.candidate_daily_sheet_projection_outbox
          set state='DELIVERED',observed_sheet_revision=v_item->>'observed_sheet_revision',
            overlay_generation_id=null,overlay_generation_version=null,overlay_source_row_hash=null,
            completed_at_utc=now(),lease_owner=null,lease_token=null,lease_expires_at_utc=null,
            updated_at_utc=now()
          where environment=v_environment and candidate_id=v_candidate_id
            and target='MASTER_AVAILABILITY_SHEET'
            and availability_date=v_availability.availability_date
            and availability_version=v_availability.availability_version
            and preference=v_availability.preference and state<>'TERMINAL';
        else
          insert into public.candidate_daily_sheet_projection_outbox(environment,candidate_id,availability_date,
            availability_version,preference,command_id,correlation_id)
          values(v_environment,v_candidate_id,v_availability.availability_date,v_availability.availability_version,
            v_availability.preference,v_availability.source_command_id,p_correlation_id)
          on conflict(environment,target,candidate_id,availability_date,availability_version,operation)
          do update set state=case when public.candidate_daily_sheet_projection_outbox.state='TERMINAL'
            then 'TERMINAL' else 'PENDING' end,next_available_at_utc=now(),
            overlay_generation_id=null,overlay_generation_version=null,overlay_source_row_hash=null,
            completed_at_utc=null,updated_at_utc=now();
          v_classification:='REPAIR_PROJECTION';
        end if;
        update private.candidate_daily_sync_state set last_reconciled_at_utc=now(),
          observed_source_revision=v_item->>'observed_sheet_revision',updated_at_utc=now()
          where environment=v_environment and candidate_id=v_candidate_id and target='MASTER_AVAILABILITY_SHEET';
        perform private._candidate_daily_refresh_sync_state_v1(
          v_environment,v_candidate_id,'MASTER_AVAILABILITY_SHEET',now());
        v_outcomes:=v_outcomes||jsonb_build_array(jsonb_build_object('index',v_index,'classification',v_classification));
      end if;
    exception when others then
      v_error:=sqlerrm;
      if v_route_operation='SHEET_EDIT_INGEST' and v_error in ('SOURCE_EVENT_CONFLICT','AVAILABILITY_DATE_NOT_EDITABLE',
        'IDENTITY_LINK_MISSING','IDENTITY_LINK_AMBIGUOUS','VALIDATION_FAILED') then
        v_outcomes:=v_outcomes||jsonb_build_array(jsonb_build_object('index',v_index,'status','REJECTED','error_code',v_error));
      elsif v_route_operation='RECONCILIATION' and v_error in ('IDENTITY_LINK_MISSING','IDENTITY_LINK_AMBIGUOUS','VALIDATION_FAILED') then
        v_outcomes:=v_outcomes||jsonb_build_array(jsonb_build_object('index',v_index,'classification','TERMINAL_CONFLICT','error_code',v_error));
      else raise; end if;
    end;
    v_index:=v_index+1;
  end loop;
  v_terminal:=jsonb_build_object('batch_receipt_id',v_batch.batch_receipt_id,'outcomes',v_outcomes);
  update private.candidate_daily_batch_receipts set state='COMPLETED',terminal_http_status=200,
    terminal_response_body=v_terminal,terminal_response_sha256=private._candidate_daily_json_sha256_v1(v_terminal),
    completed_at_utc=now(),updated_at_utc=now() where batch_receipt_id=v_batch.batch_receipt_id;
  return v_terminal;
end;
$function$;

-- candidate_daily_rota_generation_publish_atomic_v1(jsonb,uuid,text,jsonb,text)
CREATE OR REPLACE FUNCTION public.candidate_daily_rota_generation_publish_atomic_v1(p_internal_context jsonb, p_batch_request_id uuid, p_idempotency_key text, p_items jsonb, p_correlation_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_context jsonb; v_environment text; v_request_hash text;
  v_batch private.candidate_daily_batch_receipts%rowtype; v_batch_id uuid:=gen_random_uuid();
  v_item jsonb; v_day jsonb; v_index integer:=0; v_candidate_id uuid;
  v_scope private.candidate_daily_authority_scopes%rowtype; v_existing public.candidate_daily_rota_generations%rowtype;
  v_generation_id uuid; v_generation_version bigint; v_window_start date; v_outcomes jsonb:='[]'::jsonb;
  v_item_keys jsonb; v_terminal jsonb; v_dates date[]; v_error text;
  v_clear_count integer; v_new_version bigint; v_command_id uuid; v_clear_key text;
  v_clear_dates jsonb; v_command_body jsonb; v_lock_key text;
begin
  v_context:=private._candidate_daily_context_v1(p_internal_context,'SIGNED_SYSTEM_SYNC',false);
  v_environment:=v_context->>'environment';
  if p_batch_request_id is null or p_idempotency_key !~ '^[A-Za-z0-9._~:+/-]{16,128}$'
     or jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items) not between 1 and 50
     or p_correlation_id !~ '^[0-7][0-9A-HJKMNP-TV-Z]{25}$' then
    raise exception using errcode='22023',message='VALIDATION_FAILED';
  end if;
  select jsonb_agg(i->>'item_key' order by ord) into v_item_keys
    from jsonb_array_elements(p_items) with ordinality x(i,ord);
  if exists(select 1 from jsonb_array_elements(p_items)i where i->>'item_key' !~ '^[A-Za-z0-9._~-]{8,160}$')
     or jsonb_array_length(v_item_keys)<>(select count(distinct x) from jsonb_array_elements_text(v_item_keys)x) then
    raise exception using errcode='22023',message='VALIDATION_FAILED';
  end if;
  v_request_hash:=private._candidate_daily_json_sha256_v1(jsonb_build_object(
    'operation','ROTA_GENERATION_PUBLISH','batch_request_id',p_batch_request_id,'items',p_items));
  insert into private.candidate_daily_batch_receipts(batch_receipt_id,environment,actor_class,operation_class,
    idempotency_key,request_hash,item_keys_json,item_count,state,correlation_id)
  values(v_batch_id,v_environment,'SIGNED_SYSTEM','ROTA_GENERATION_PUBLISH',p_idempotency_key,
    v_request_hash,v_item_keys,jsonb_array_length(p_items),'IN_PROGRESS',p_correlation_id)
  on conflict(environment,actor_class,operation_class,idempotency_key) do nothing;
  select * into v_batch from private.candidate_daily_batch_receipts
    where environment=v_environment and actor_class='SIGNED_SYSTEM'
      and operation_class='ROTA_GENERATION_PUBLISH' and idempotency_key=p_idempotency_key for update;
  if v_batch.request_hash<>v_request_hash or v_batch.item_keys_json<>v_item_keys then
    raise exception using errcode='23505',message='IDEMPOTENCY_KEY_REUSED';
  end if;
  if v_batch.state<>'IN_PROGRESS' then
    return v_batch.terminal_response_body||jsonb_build_object('_idempotent_replay',true);
  end if;

  for v_lock_key in
    select distinct q.lock_key
    from (
      select 'GLOBAL:'||upper(btrim(i->>'candidate_global_key')) as lock_key
      from jsonb_array_elements(p_items)i
      where i->>'candidate_global_key' ~ '^CID1-[0-9A-HJKMNP-TV-Z]{5,160}$'
      union all
      select 'SOURCE:'||(i->>'source_hmac_key_version')||':'||(i->>'candidate_source_hmac')
      from jsonb_array_elements(p_items)i
      where i->>'candidate_source_hmac' ~ '^[a-f0-9]{64}$'
        and i->>'source_hmac_key_version' ~ '^[1-9][0-9]*$'
    )q
    order by q.lock_key
  loop
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(v_environment||':'||v_lock_key,0)
    );
  end loop;

  for v_item in select value from jsonb_array_elements(p_items) loop
    v_error:=null; v_generation_id:=null; v_generation_version:=null;
    begin
      if (select count(*) from jsonb_object_keys(v_item))<>10
         or not(v_item ?& array['candidate_global_key','candidate_source_hmac','source_hmac_key_version',
           'source_event_id','source_revision','source_hash','window_start','days','source_event_time','item_key'])
         or v_item->>'candidate_global_key' !~ '^CID1-[0-9A-HJKMNP-TV-Z]{5,160}$'
         or v_item->>'candidate_source_hmac' !~ '^[a-f0-9]{64}$'
         or v_item->>'source_hmac_key_version' !~ '^[1-9][0-9]*$'
         or (v_item->>'source_hmac_key_version')::integer<>1
         or v_item->>'source_hash' !~ '^[a-f0-9]{64}$'
         or length(v_item->>'source_event_id') not between 8 and 160
         or length(v_item->>'source_revision') not between 1 and 160
         or jsonb_typeof(v_item->'days')<>'array' or jsonb_array_length(v_item->'days')<>14 then
        raise exception using errcode='22023',message='GENERATION_INCOMPLETE';
      end if;
      v_candidate_id:=private._candidate_daily_source_candidate_bind_on_generation_v1(
        v_environment,v_item->>'candidate_global_key',v_item->>'candidate_source_hmac',
        (v_item->>'source_hmac_key_version')::integer
      );
      v_window_start:=(v_item->>'window_start')::date;
      select array_agg((d->>'date')::date order by (d->>'date')::date) into v_dates
        from jsonb_array_elements(v_item->'days')d;
      if cardinality(v_dates)<>14 or (select count(distinct x) from unnest(v_dates)x)<>14
         or v_dates[1]<>v_window_start or v_dates[14]<>v_window_start+13
         or exists(select 1 from generate_series(0,13)n where v_dates[n+1]<>v_window_start+n) then
        raise exception using errcode='22023',message='GENERATION_INCOMPLETE';
      end if;
      if exists(select 1 from jsonb_array_elements(v_item->'days')d where
        (select count(*) from jsonb_object_keys(d))<4 or not(d ?& array['date','booked','system_blocked','source_row_hash'])
        or d->>'source_row_hash' !~ '^[a-f0-9]{64}$'
        or (coalesce((d->>'booked')::boolean,false) and (
          nullif(btrim(d->>'booking_id'),'') is null or nullif(d->>'shift_starts_at','') is null
          or nullif(d->>'shift_ends_at','') is null or (d->>'shift_ends_at')::timestamptz<=(d->>'shift_starts_at')::timestamptz))
        or (not coalesce((d->>'booked')::boolean,false) and (
          coalesce(d->'booking_id','null'::jsonb)<>'null'::jsonb
          or coalesce(d->'shift_starts_at','null'::jsonb)<>'null'::jsonb
          or coalesce(d->'shift_ends_at','null'::jsonb)<>'null'::jsonb))) then
        raise exception using errcode='22023',message='GENERATION_INCOMPLETE';
      end if;
      select * into v_existing from public.candidate_daily_rota_generations
      where environment=v_environment and source_system='MASTER_ROTA'
        and source_event_id=v_item->>'source_event_id' and item_key=v_item->>'item_key';
      if v_existing.generation_id is not null then
        if v_existing.candidate_id<>v_candidate_id
           or v_existing.source_hash<>v_item->>'source_hash' then
          raise exception using errcode='23505',message='SOURCE_EVENT_CONFLICT';
        end if;
        v_generation_id:=v_existing.generation_id; v_generation_version:=v_existing.generation_version;
        v_outcomes:=v_outcomes||jsonb_build_array(jsonb_build_object('index',v_index,'status','REPLAYED',
          'generation_id',v_generation_id,'generation_version',v_generation_version));
      else
        select * into v_scope from private.candidate_daily_authority_scopes
          where environment=v_environment and candidate_id=v_candidate_id for update;
        if v_scope.candidate_id is null or v_scope.transition_in_progress then
          raise exception using errcode='55000',message='CANDIDATE_DAILY_NOT_READY';
        end if;
        select coalesce(max(g.generation_version),0)+1 into v_generation_version
          from public.candidate_daily_rota_generations g
          where g.environment=v_environment and g.candidate_id=v_candidate_id;
        v_generation_id:=gen_random_uuid();
        insert into public.candidate_daily_rota_generations(generation_id,environment,candidate_id,
          generation_version,window_start,window_end,state,expected_day_count,actual_day_count,source_system,
          source_event_id,source_revision,source_event_time,item_key,source_hash,generation_row_hash,
          batch_receipt_id,correlation_id)
        values(v_generation_id,v_environment,v_candidate_id,v_generation_version,v_window_start,v_window_start+13,
          'BUILDING',14,0,'MASTER_ROTA',v_item->>'source_event_id',v_item->>'source_revision',
          (v_item->>'source_event_time')::timestamptz,v_item->>'item_key',v_item->>'source_hash',
          private._candidate_daily_json_sha256_v1(v_item),v_batch.batch_receipt_id,p_correlation_id);
        for v_day in select value from jsonb_array_elements(v_item->'days') loop
          insert into public.candidate_daily_rota_days(generation_id,environment,candidate_id,rota_date,
            booked,system_blocked,booking_id,shift_starts_at,shift_ends_at,shift_info,hospital,ward,job_title,
            booking_ref,source_row_hash)
          values(v_generation_id,v_environment,v_candidate_id,(v_day->>'date')::date,
            (v_day->>'booked')::boolean,(v_day->>'system_blocked')::boolean,
            nullif(v_day->>'booking_id',''),nullif(v_day->>'shift_starts_at','')::timestamptz,
            nullif(v_day->>'shift_ends_at','')::timestamptz,nullif(v_day->>'shift_info',''),
            nullif(v_day->>'hospital',''),nullif(v_day->>'ward',''),nullif(v_day->>'job_title',''),
            null,v_day->>'source_row_hash');
        end loop;
        select count(*),jsonb_agg(a.availability_date order by a.availability_date)
          into v_clear_count,v_clear_dates
        from public.candidate_daily_availability_days a
        join public.candidate_daily_rota_days d on d.generation_id=v_generation_id
          and d.environment=a.environment and d.candidate_id=a.candidate_id
          and d.rota_date=a.availability_date
        where a.environment=v_environment and a.candidate_id=v_candidate_id
          and (d.booked or d.system_blocked) and a.preference<>'PENDING';
        if v_clear_count>0 then
          v_command_id:=gen_random_uuid();
          v_clear_key:=left('rota-clear:'||p_batch_request_id::text||':'||v_item->>'item_key',160);
          insert into public.candidate_daily_command_receipts(command_id,environment,candidate_id,actor_class,
            command_class,idempotency_key,request_sha256,source_system,source_event_id,source_revision,
            source_event_time,item_key,canonical_version_before,state,correlation_id)
          values(v_command_id,v_environment,v_candidate_id,'SIGNED_SYSTEM','ROTA_GENERATION_CLEAR',v_clear_key,
            private._candidate_daily_json_sha256_v1(jsonb_build_object('source_hash',v_item->>'source_hash',
              'clear_dates',v_clear_dates)),'MASTER_ROTA_GENERATION',v_item->>'source_event_id',
            v_item->>'source_revision',(v_item->>'source_event_time')::timestamptz,
            left('clear:'||v_item->>'item_key',160),v_scope.canonical_version,'IN_PROGRESS',p_correlation_id);
          update private.candidate_daily_authority_scopes
          set canonical_version=canonical_version+1,updated_at_utc=now()
          where environment=v_environment and candidate_id=v_candidate_id
          returning canonical_version into v_new_version;
          update public.candidate_daily_availability_days a
          set preference='PENDING',availability_version=v_new_version,source_class='SIGNED_SYSTEM',
            source_command_id=v_command_id,changed_at_utc=now(),changed_by_class='SIGNED_SYSTEM',
            row_hash=private._candidate_daily_json_sha256_v1(jsonb_build_object(
              'date',a.availability_date,'preference','PENDING','availability_version',v_new_version,
              'source_event_id',v_item->>'source_event_id'))
          from public.candidate_daily_rota_days d
          where d.generation_id=v_generation_id and d.environment=a.environment
            and d.candidate_id=a.candidate_id and d.rota_date=a.availability_date
            and a.environment=v_environment and a.candidate_id=v_candidate_id
            and (d.booked or d.system_blocked) and a.preference<>'PENDING';
          insert into public.candidate_daily_sheet_projection_outbox(environment,candidate_id,availability_date,
            availability_version,preference,command_id,correlation_id)
          select v_environment,v_candidate_id,(value#>>'{}')::date,v_new_version,'PENDING',v_command_id,p_correlation_id
          from jsonb_array_elements(v_clear_dates);
          v_command_body:=jsonb_build_object('availability_version',v_new_version,'changed_dates',v_clear_dates);
          update public.candidate_daily_command_receipts set canonical_version_after=v_new_version,state='COMPLETED',
            terminal_http_status=200,terminal_body_json=v_command_body,
            terminal_body_sha256=private._candidate_daily_json_sha256_v1(v_command_body),
            completed_at_utc=now(),updated_at_utc=now() where command_id=v_command_id;
          v_scope.canonical_version:=v_new_version;
        end if;
        update public.candidate_daily_rota_generations set state='SUPERSEDED',updated_at_utc=now()
          where environment=v_environment and candidate_id=v_candidate_id and state='ACTIVE';
        update public.candidate_daily_rota_generations set state='ACTIVE',actual_day_count=14,
          activated_at_utc=now(),published_at_utc=now(),updated_at_utc=now()
          where generation_id=v_generation_id;
        update private.candidate_daily_authority_scopes set active_generation_id=v_generation_id,updated_at_utc=now()
          where environment=v_environment and candidate_id=v_candidate_id;
        insert into private.candidate_daily_sync_state(environment,candidate_id,target,accepted_canonical_cursor,
          required_visible_cursor,delivered_visible_cursor,overlay_proof_cursor,effective_visible_cursor,
          observed_source_revision,state,last_pulled_at_utc)
        values(v_environment,v_candidate_id,'MASTER_AVAILABILITY_SHEET',v_scope.canonical_version,
          v_scope.canonical_version,0,0,0,v_item->>'source_revision','LAGGING',now())
        on conflict(environment,candidate_id,target) do update set
          accepted_canonical_cursor=greatest(private.candidate_daily_sync_state.accepted_canonical_cursor,
            v_scope.canonical_version),
          required_visible_cursor=greatest(private.candidate_daily_sync_state.required_visible_cursor,
            v_scope.canonical_version),
          observed_source_revision=excluded.observed_source_revision,last_pulled_at_utc=now(),updated_at_utc=now();

        update public.candidate_daily_sheet_projection_outbox o
        set state='PENDING',next_available_at_utc=now(),overlay_generation_id=null,
          overlay_generation_version=null,overlay_source_row_hash=null,completed_at_utc=null,updated_at_utc=now()
        where o.environment=v_environment and o.candidate_id=v_candidate_id
          and o.target='MASTER_AVAILABILITY_SHEET' and o.state='DEFERRED_OVERLAY'
          and not exists(
            select 1 from public.candidate_daily_rota_days d
            where d.generation_id=v_generation_id and d.environment=o.environment
              and d.candidate_id=o.candidate_id and d.rota_date=o.availability_date
              and (d.booked or d.system_blocked) and d.source_row_hash=o.overlay_source_row_hash
          );
        update public.candidate_daily_sheet_projection_outbox o
        set overlay_generation_id=v_generation_id,overlay_generation_version=v_generation_version,
          updated_at_utc=now()
        where o.environment=v_environment and o.candidate_id=v_candidate_id
          and o.target='MASTER_AVAILABILITY_SHEET' and o.state='DEFERRED_OVERLAY'
          and exists(
            select 1 from public.candidate_daily_rota_days d
            where d.generation_id=v_generation_id and d.environment=o.environment
              and d.candidate_id=o.candidate_id and d.rota_date=o.availability_date
              and (d.booked or d.system_blocked) and d.source_row_hash=o.overlay_source_row_hash
          );
        perform private._candidate_daily_refresh_sync_state_v1(
          v_environment,v_candidate_id,'MASTER_AVAILABILITY_SHEET',now());
        v_outcomes:=v_outcomes||jsonb_build_array(jsonb_build_object('index',v_index,'status','COMMITTED',
          'generation_id',v_generation_id,'generation_version',v_generation_version));
      end if;
    exception when others then
      v_error:=sqlerrm;
      if v_error not in ('GENERATION_INCOMPLETE','SOURCE_EVENT_CONFLICT','IDENTITY_LINK_MISSING',
        'IDENTITY_LINK_AMBIGUOUS','IDENTITY_LINK_CONFLICT','CANDIDATE_DAILY_NOT_READY') then raise; end if;
      v_outcomes:=v_outcomes||jsonb_build_array(jsonb_build_object('index',v_index,'status','REJECTED','error_code',v_error));
    end;
    v_index:=v_index+1;
  end loop;
  v_terminal:=jsonb_build_object('batch_receipt_id',v_batch.batch_receipt_id,'outcomes',v_outcomes);
  update private.candidate_daily_batch_receipts set state='COMPLETED',terminal_http_status=200,
    terminal_response_body=v_terminal,terminal_response_sha256=private._candidate_daily_json_sha256_v1(v_terminal),
    completed_at_utc=now(),updated_at_utc=now() where batch_receipt_id=v_batch.batch_receipt_id;
  return v_terminal;
end;
$function$;

-- candidate_daily_sync_status_get_v1(jsonb,jsonb,text)
CREATE OR REPLACE FUNCTION public.candidate_daily_sync_status_get_v1(p_internal_context jsonb, p_candidate_source_hmacs jsonb, p_correlation_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_context jsonb; v_environment text; v_hmac text; v_candidate_id uuid; v_items jsonb:='[]'::jsonb;
begin
  v_context:=private._candidate_daily_context_v1(p_internal_context,'SIGNED_SYSTEM_SYNC',false);
  v_environment:=v_context->>'environment';
  if jsonb_typeof(p_candidate_source_hmacs)<>'array'
     or jsonb_array_length(p_candidate_source_hmacs) not between 1 and 100 then
    raise exception using errcode='22023',message='VALIDATION_FAILED';
  end if;
  for v_hmac in select value#>>'{}' from jsonb_array_elements(p_candidate_source_hmacs) loop
    v_candidate_id:=private._candidate_daily_source_candidate_v1(v_environment,v_hmac);
    v_items:=v_items||jsonb_build_array(jsonb_build_object('candidate_source_hmac',v_hmac,
      'freshness',private._candidate_daily_freshness_v1(v_environment,v_candidate_id,now())));
  end loop;
  return jsonb_build_object('items',v_items);
end;
$function$;

-- candidate_daily_tiles_get_v1(jsonb,date,integer)
CREATE OR REPLACE FUNCTION public.candidate_daily_tiles_get_v1(p_internal_context jsonb, p_from date DEFAULT NULL::date, p_days integer DEFAULT 14)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_context jsonb; v_environment text; v_candidate_id uuid; v_policy text;
  v_scope private.candidate_daily_authority_scopes%rowtype;
  v_generation public.candidate_daily_rota_generations%rowtype;
  v_tiles jsonb; v_from date; v_freshness jsonb;
begin
  v_policy:=upper(coalesce(nullif(p_internal_context->>'policy',''),'CANDIDATE_SURFACE'));
  if v_policy='LEGACY_COMPAT' then
    v_context:=private._candidate_daily_context_v1(p_internal_context,'LEGACY_COMPAT',false);
    v_environment:=v_context->>'environment';
    v_candidate_id:=private._candidate_daily_source_candidate_v1(
      v_environment,p_internal_context->>'candidate_source_hmac');
  elsif v_policy='CANDIDATE_SURFACE' then
    v_context:=private._candidate_daily_context_v1(p_internal_context,'CANDIDATE_SURFACE',true);
    v_environment:=v_context->>'environment'; v_candidate_id:=(v_context->>'candidate_id')::uuid;
  else
    raise exception using errcode='22023',message='FORBIDDEN';
  end if;
  if p_days<>14 then raise exception using errcode='22023',message='VALIDATION_FAILED'; end if;
  select * into v_scope from private.candidate_daily_authority_scopes
    where environment=v_environment and candidate_id=v_candidate_id;
  select * into v_generation from public.candidate_daily_rota_generations
    where generation_id=v_scope.active_generation_id and state='ACTIVE';
  if v_generation.generation_id is null then
    raise exception using errcode='55000',message='DAILY_GENERATION_UNAVAILABLE';
  end if;
  v_from:=coalesce(p_from,v_generation.window_start);
  if v_from<>v_generation.window_start then
    raise exception using errcode='22023',message='VALIDATION_FAILED';
  end if;
  select jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
    'date',d.rota_date,'display_day',to_char(d.rota_date,'Dy'),'display_date',to_char(d.rota_date,'DD/MM/YYYY'),
    'booked',d.booked,'system_blocked',d.system_blocked,'editable',not(d.booked or d.system_blocked),
    'status',case when d.booked then 'BOOKED' when d.system_blocked then 'BLOCKED'
      else coalesce(a.preference,'PENDING') end,
    'availability',coalesce(a.preference,'PENDING'),'shift_info',d.shift_info,'hospital',d.hospital,
    'ward',d.ward,'job_title',d.job_title,'booking_ref',d.booking_ref,'shift_type',d.shift_type,
    'booking_id',d.booking_id,'timesheet_authorised',d.timesheet_authorised,
    'timesheet_eligible',d.timesheet_eligible,
    'action_target',case d.action_target_kind
      when 'TIMESHEET_DETAIL' then jsonb_strip_nulls(jsonb_build_object('target_kind',d.action_target_kind,
        'timesheet_id',d.action_timesheet_id,'workflow_id',d.action_workflow_id,'row_signature',d.action_row_signature))
      when 'CONTRACT_WEEK_DETAIL' then jsonb_strip_nulls(jsonb_build_object('target_kind',d.action_target_kind,
        'contract_week_id',d.action_contract_week_id,'timesheet_id',d.action_timesheet_id,
        'workflow_id',d.action_workflow_id,'row_signature',d.action_row_signature))
      when 'WORKFLOW_DETAIL' then jsonb_build_object('target_kind',d.action_target_kind,
        'workflow_id',d.action_workflow_id,'workflow_generation',d.action_workflow_generation,
        'row_signature',d.action_row_signature) else null end
  )) order by d.rota_date) into v_tiles
  from public.candidate_daily_rota_days d
  left join public.candidate_daily_availability_days a on a.environment=d.environment
    and a.candidate_id=d.candidate_id and a.availability_date=d.rota_date
  where d.generation_id=v_generation.generation_id;
  if jsonb_array_length(coalesce(v_tiles,'[]'::jsonb))<>14 then
    raise exception using errcode='55000',message='GENERATION_INCOMPLETE';
  end if;
  v_freshness:=private._candidate_daily_freshness_v1(v_environment,v_candidate_id,now());
  if v_policy='CANDIDATE_SURFACE' and coalesce((v_freshness->>'ready')::boolean,false) is not true then
    raise exception using errcode='55000',message='CANDIDATE_DAILY_NOT_READY';
  end if;
  return jsonb_build_object('candidate_id',v_candidate_id,'window_start',v_generation.window_start,
    'window_end',v_generation.window_end,'generation_id',v_generation.generation_id,
    'generation_version',v_generation.generation_version,'availability_version',v_scope.canonical_version,
    'freshness',v_freshness,
    'cohorts','[]'::jsonb,'tiles',v_tiles);
end;
$function$;

-- candidate_delete_apply(uuid,uuid,text)
CREATE OR REPLACE FUNCTION public.candidate_delete_apply(p_candidate_id uuid, p_actor_user_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_elig jsonb;
  v_can boolean;
  v_deleted_rev bigint;
  v_seq bigint;
  v_before jsonb;
  v_delete_operation_id uuid:=gen_random_uuid();
  v_candidate_lock_key bigint;
BEGIN
  IF p_candidate_id IS NULL THEN RAISE EXCEPTION 'candidate_id is required'; END IF;
  v_candidate_lock_key:=pg_catalog.hashtextextended(
    public._pay_workbench_candidate_serial_key(p_candidate_id),24062027);
  PERFORM pg_catalog.pg_advisory_xact_lock(v_candidate_lock_key);

  -- Lock candidate to ensure consistent delete
  SELECT jsonb_build_object(
           'id', c.id::text,
           'tms_ref', c.tms_ref,
           'display_name', c.display_name,
           'active', c.active
         )
    INTO v_before
  FROM public.candidates c
  WHERE c.id = p_candidate_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Candidate not found';
  END IF;

  PERFORM 1 FROM private.banking_pay_workbench_candidate_scope_registry
  WHERE candidate_id=p_candidate_id FOR UPDATE;
  PERFORM 1 FROM private.banking_pay_workbench_economic_builds
  WHERE candidate_id=p_candidate_id ORDER BY id FOR UPDATE;
  PERFORM 1 FROM public.banking_pay_workbench_jobs
  WHERE candidate_id=p_candidate_id ORDER BY id FOR UPDATE;
  PERFORM 1 FROM private.banking_pay_workbench_stage_attempts
  WHERE candidate_id=p_candidate_id ORDER BY id FOR UPDATE;

  v_elig := public.candidate_delete_eligibility(p_candidate_id);
  v_can := COALESCE((v_elig->>'can_delete')::boolean, false);
  IF v_can IS NOT TRUE THEN
    RAISE EXCEPTION '%', COALESCE(v_elig->>'reason', 'Candidate cannot be deleted');
  END IF;

  IF pg_catalog.to_regclass('pg_temp._bpay_candidate_delete_context_v1') IS NOT NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_DELETE_CONTEXT_CONFLICT' USING ERRCODE='23514';
  END IF;
  CREATE TEMP TABLE pg_temp._bpay_candidate_delete_context_v1(
    candidate_id uuid PRIMARY KEY,
    delete_operation_id uuid UNIQUE NOT NULL,
    candidate_lock_key bigint NOT NULL,
    backend_pid integer NOT NULL,
    transaction_id bigint NOT NULL,
    created_at_utc timestamptz NOT NULL,
    suppress boolean NOT NULL CHECK(suppress)
  ) ON COMMIT DROP;
  INSERT INTO pg_temp._bpay_candidate_delete_context_v1 VALUES(
    p_candidate_id,v_delete_operation_id,v_candidate_lock_key,pg_catalog.pg_backend_pid(),
    pg_catalog.txid_current(),clock_timestamp(),true);

  -- Preserve terminal public job diagnostics while severing candidate/build
  -- foreign-key authority before the private graph cascades.
  UPDATE public.banking_pay_workbench_jobs SET candidate_id=NULL,economic_build_id=NULL,
    private_stage=NULL,private_cursor_kind=NULL,private_cursor_json='{}'::jsonb,
    private_stage_version=NULL,
    updated_at_utc=clock_timestamp(),payload_json=COALESCE(payload_json,'{}'::jsonb)
      ||jsonb_build_object('deleted_candidate_id',p_candidate_id,
        'candidate_delete_operation_id',v_delete_operation_id,
        'detached_private_stage',private_stage,
        'detached_private_cursor_kind',private_cursor_kind)
  WHERE candidate_id=p_candidate_id AND status IN ('SUCCEEDED','FAILED','DEAD');

  -- Non-blocking dependents (verified tables)
  DELETE FROM public.candidate_job_titles cjt WHERE cjt.candidate_id = p_candidate_id;
  DELETE FROM public.rates_candidate_overrides rco WHERE rco.candidate_id = p_candidate_id;
  DELETE FROM public.legacy_eclipse_candidate_map lem WHERE lem.candidate_id = p_candidate_id;

  -- Delete candidate
  DELETE FROM public.candidates c WHERE c.id = p_candidate_id;

  IF EXISTS(SELECT 1 FROM private.banking_pay_workbench_candidate_scope_registry WHERE candidate_id=p_candidate_id)
     OR EXISTS(SELECT 1 FROM private.banking_pay_workbench_timesheet_scope_state WHERE candidate_id=p_candidate_id)
     OR EXISTS(SELECT 1 FROM private.banking_pay_workbench_economic_builds WHERE candidate_id=p_candidate_id)
     OR EXISTS(SELECT 1 FROM private.banking_pay_workbench_stage_attempts WHERE candidate_id=p_candidate_id) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_DELETE_PRIVATE_GRAPH_REMAINS' USING ERRCODE='23514';
  END IF;

  -- Bump change counter and record deleted_rev
  PERFORM public._change_bump('candidates');
  SELECT acc.seq INTO v_seq
  FROM public.app_change_counters acc
  WHERE acc.entity_key = 'candidates'
  LIMIT 1;

  v_deleted_rev := COALESCE(v_seq, 0);

  INSERT INTO public.candidates_tombstones (id, deleted_rev, deleted_at)
  VALUES (p_candidate_id, v_deleted_rev, now())
  ON CONFLICT (id) DO UPDATE
    SET deleted_rev = EXCLUDED.deleted_rev,
        deleted_at  = EXCLUDED.deleted_at;

  PERFORM public._audit_insert(
    'candidates',
    p_candidate_id::text,
    'DELETE',
    v_before,
    jsonb_build_object('deleted_rev', v_deleted_rev),
    COALESCE(p_reason, 'DELETE'),
    p_actor_user_id
  );

  RETURN jsonb_build_object('deleted', true, 'candidate_id', p_candidate_id::text, 'deleted_rev', v_deleted_rev);
END;
$function$;

-- candidate_delete_eligibility(uuid)
CREATE OR REPLACE FUNCTION public.candidate_delete_eligibility(p_candidate_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_contracts int;
  v_contract_weeks int;
  v_timesheets int;
  v_invoice_lines int;
  v_pay_batches int;
  v_reason text := null;
  v_can boolean := true;
  v_active_builds int:=0;
  v_current_scale_blocks int:=0;
  v_started_attempts int:=0;
  v_active_workbench_jobs int:=0;
BEGIN
  IF p_candidate_id IS NULL THEN
    RAISE EXCEPTION 'candidate_id is required';
  END IF;

  SELECT COUNT(*) INTO v_contracts
  FROM public.contracts ct
  WHERE ct.candidate_id = p_candidate_id;

  SELECT COUNT(*) INTO v_contract_weeks
  FROM public.contract_weeks cw
  JOIN public.contracts ct ON ct.id = cw.contract_id
  WHERE ct.candidate_id = p_candidate_id;

  SELECT COUNT(*) INTO v_timesheets
  FROM public.timesheets t
  JOIN public.contracts ct ON ct.id = t.contract_id
  WHERE ct.candidate_id = p_candidate_id;

  SELECT COUNT(*) INTO v_invoice_lines
  FROM public.invoice_lines il
  JOIN public.timesheets t ON t.timesheet_id = il.timesheet_id
  JOIN public.contracts ct ON ct.id = t.contract_id
  WHERE ct.candidate_id = p_candidate_id;

  SELECT COUNT(*) INTO v_pay_batches
  FROM public.pay_batch_candidates pbc
  WHERE pbc.candidate_id = p_candidate_id;

  SELECT count(*)::integer INTO v_active_builds
  FROM private.banking_pay_workbench_economic_builds build_row
  WHERE build_row.candidate_id=p_candidate_id
    AND build_row.status IN ('COLLECTING','READY_FOR_RECONCILIATION','RECONCILING',
      'RECONCILED','PUBLISHING','CLEANING');
  SELECT count(*)::integer INTO v_current_scale_blocks
  FROM private.banking_pay_workbench_candidate_scope_registry registry
  JOIN private.banking_pay_workbench_economic_builds build_row ON build_row.id=registry.current_build_id
  WHERE registry.candidate_id=p_candidate_id
    AND build_row.status='BLOCKED_UNVALIDATED_RECONCILIATION_SCALE';
  SELECT count(*)::integer INTO v_started_attempts
  FROM private.banking_pay_workbench_stage_attempts attempt
  WHERE attempt.candidate_id=p_candidate_id AND attempt.attempt_status='STARTED';
  SELECT count(*)::integer INTO v_active_workbench_jobs
  FROM public.banking_pay_workbench_jobs job
  WHERE job.candidate_id=p_candidate_id AND job.status NOT IN ('SUCCEEDED','FAILED','DEAD');

  IF v_contracts > 0 OR v_contract_weeks > 0 OR v_timesheets > 0 OR v_invoice_lines > 0 OR v_pay_batches > 0
     OR v_active_builds>0 OR v_current_scale_blocks>0 OR v_started_attempts>0 OR v_active_workbench_jobs>0 THEN
    v_can := false;
    v_reason := 'Candidate cannot be deleted because related records exist.';
  END IF;

  RETURN jsonb_build_object(
    'candidate_id', p_candidate_id::text,
    'can_delete', v_can,
    'reason', v_reason,
    'blockers', jsonb_build_object(
      'contracts', v_contracts,
      'contract_weeks', v_contract_weeks,
      'timesheets', v_timesheets,
      'invoice_lines', v_invoice_lines,
      'pay_batch_candidates', v_pay_batches,
      'active_banking_pay_builds',v_active_builds,
      'current_scale_blocked_builds',v_current_scale_blocks,
      'started_banking_pay_attempts',v_started_attempts,
      'active_workbench_jobs',v_active_workbench_jobs
    )
  );
END;
$function$;

-- candidate_google_provisioning_match_v1(jsonb,text,text,text,text,text,integer,text)
CREATE OR REPLACE FUNCTION public.candidate_google_provisioning_match_v1(p_internal_context jsonb, p_candidate_code text, p_surname text, p_email text, p_mobile text, p_google_source_identity_hmac text, p_source_hmac_key_version integer, p_correlation_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_candidate_code text:=pg_catalog.upper(pg_catalog.btrim(p_candidate_code));
  v_surname text:=pg_catalog.lower(pg_catalog.btrim(p_surname));
  v_email text:=private._candidate_normalize_email(p_email);
  v_mobile text:=private._candidate_google_mobile_normalize_v1(p_mobile);
  v_count integer:=0;
  v_candidate_id uuid;
begin
  if p_internal_context is null
     or pg_catalog.jsonb_typeof(p_internal_context) is distinct from 'object'
     or p_internal_context->>'route_context_verified' is distinct from 'true'
     or p_internal_context->>'audience' is distinct from 'GOOGLE_PROVISIONING_MATCH'
     or p_internal_context->>'environment' not in ('TEST','LIVE')
     or v_candidate_code !~ '^CID1-[0-9A-HJKMNP-TV-Z]{5,160}$'
     or pg_catalog.char_length(v_surname) not between 1 and 200
     or pg_catalog.char_length(v_email) not between 3 and 320
     or pg_catalog.char_length(v_mobile) not between 7 and 32
     or p_google_source_identity_hmac !~ '^[a-f0-9]{64}$'
     or p_source_hmac_key_version not between 1 and 2147483647
     or pg_catalog.char_length(pg_catalog.btrim(p_correlation_id)) not between 1 and 200 then
    raise exception using errcode='22023',message='GOOGLE_PROVISIONING_MATCH_INVALID';
  end if;

  select pg_catalog.count(*)::integer,
         pg_catalog.min(c.id::text)::uuid
    into v_count,v_candidate_id
  from public.candidates c
  where c.active is true
    and pg_catalog.upper(pg_catalog.btrim(coalesce(c.key_norm,'')))=v_candidate_code
    and pg_catalog.lower(pg_catalog.btrim(coalesce(c.last_name,'')))=v_surname
    and private._candidate_normalize_email(c.email)=v_email
    and private._candidate_google_mobile_normalize_v1(c.phone)=v_mobile;

  if v_count=0 then
    return pg_catalog.jsonb_build_object('ok',true,'match_state','NO_MATCH');
  elsif v_count<>1 then
    return pg_catalog.jsonb_build_object('ok',true,'match_state','AMBIGUOUS');
  end if;

  return pg_catalog.jsonb_build_object(
    'ok',true,
    'match_state','EXACT',
    'local_candidate_id',v_candidate_id,
    'google_source_identity_hmac',p_google_source_identity_hmac,
    'source_hmac_key_version',p_source_hmac_key_version
  );
end;
$function$;

-- candidate_list_ids(jsonb)
CREATE OR REPLACE FUNCTION public.candidate_list_ids(p_filters jsonb)
 RETURNS TABLE(id uuid)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_timezone_id text := null;
  v_first_name text := null;
  v_last_name text := null;
  v_email text := null;
  v_phone text := null;
  v_notes text := null;
  v_pay_method text := null;
  v_active text := null;
  v_created_from date := null;
  v_created_to date := null;
  v_updated_from date := null;
  v_updated_to date := null;
  v_job_title_include_node_ids text[] := null;
  v_job_title_exclude_node_ids text[] := null;
  v_job_title_role_ids uuid[] := null;
  v_job_title_primary_only boolean := false;
  v_prof_reg_number text := null;
  v_prof_reg_type text := null;
  v_dob date := null;
  v_gender text := null;
  v_town_city text := null;
  v_postcode text := null;
  v_sort_code text := null;
  v_account_number text := null;
  v_umbrella_name text := null;
  v_tms_ref text := null;
  v_q text := null;
  v_work_status text := null;
  v_recent_months_raw text := null;
  v_recent_months int := 3;
  v_recent_all boolean := false;
  v_cutoff_ymd date := null;
  v_ids uuid[] := null;
  v_roles_any text[] := null;
  v_roles_all text[] := null;
begin
  if p_filters is null then
    p_filters := '{}'::jsonb;
  end if;

  begin
    select sd.timezone_id
      into v_timezone_id
    from public.settings_defaults as sd
    limit 1;
  exception when others then
    v_timezone_id := null;
  end;

  if nullif(btrim(coalesce(v_timezone_id, '')), '') is null then
    v_timezone_id := 'UTC';
  end if;

  v_first_name := nullif(btrim(coalesce(p_filters->>'first_name', '')), '');
  v_last_name := nullif(btrim(coalesce(p_filters->>'last_name', '')), '');
  v_email := nullif(btrim(coalesce(p_filters->>'email', '')), '');
  v_phone := nullif(btrim(coalesce(p_filters->>'phone', '')), '');
  v_notes := nullif(btrim(coalesce(p_filters->>'notes', '')), '');
  v_pay_method := nullif(upper(btrim(coalesce(p_filters->>'pay_method', ''))), '');
  v_active := nullif(lower(btrim(coalesce(p_filters->>'active', ''))), '');
  v_prof_reg_number := nullif(btrim(coalesce(p_filters->>'prof_reg_number', '')), '');
  v_prof_reg_type := nullif(upper(btrim(coalesce(p_filters->>'prof_reg_type', ''))), '');
  v_gender := nullif(btrim(coalesce(p_filters->>'gender', '')), '');
  v_town_city := nullif(btrim(coalesce(p_filters->>'town_city', '')), '');
  v_postcode := nullif(btrim(coalesce(p_filters->>'postcode', '')), '');
  v_sort_code := nullif(btrim(coalesce(p_filters->>'sort_code', '')), '');
  v_account_number := nullif(btrim(coalesce(p_filters->>'account_number', '')), '');
  v_umbrella_name := nullif(btrim(coalesce(p_filters->>'umbrella_name', '')), '');
  v_tms_ref := nullif(btrim(coalesce(p_filters->>'tms_ref', '')), '');
  v_q := nullif(btrim(coalesce(p_filters->>'q', coalesce(p_filters->>'name', ''))), '');
  v_work_status := nullif(upper(btrim(coalesce(p_filters->>'work_status', ''))), '');
  v_recent_months_raw := nullif(upper(btrim(coalesce(p_filters->>'recent_months', ''))), '');

  begin
    if nullif(btrim(coalesce(p_filters->>'created_from', '')), '') is not null then
      v_created_from := (p_filters->>'created_from')::date;
    end if;
  exception when others then
    v_created_from := null;
  end;

  begin
    if nullif(btrim(coalesce(p_filters->>'created_to', '')), '') is not null then
      v_created_to := (p_filters->>'created_to')::date;
    end if;
  exception when others then
    v_created_to := null;
  end;

  begin
    if nullif(btrim(coalesce(p_filters->>'updated_from', '')), '') is not null then
      v_updated_from := (p_filters->>'updated_from')::date;
    end if;
  exception when others then
    v_updated_from := null;
  end;

  begin
    if nullif(btrim(coalesce(p_filters->>'updated_to', '')), '') is not null then
      v_updated_to := (p_filters->>'updated_to')::date;
    end if;
  exception when others then
    v_updated_to := null;
  end;

  begin
    if nullif(btrim(coalesce(p_filters->>'dob', '')), '') is not null then
      v_dob := (p_filters->>'dob')::date;
    end if;
  exception when others then
    v_dob := null;
  end;

  begin
    if p_filters ? 'job_title_include_node_ids' then
      if jsonb_typeof(p_filters->'job_title_include_node_ids') = 'array' then
        select array_agg(parsed.include_node_id_text order by parsed.include_node_id_text)
        into v_job_title_include_node_ids
        from (
          select distinct nullif(btrim(include_nodes.value), '') as include_node_id_text
          from jsonb_array_elements_text(p_filters->'job_title_include_node_ids') as include_nodes(value)
          where nullif(btrim(include_nodes.value), '') is not null
        ) as parsed;
      elsif nullif(btrim(coalesce(p_filters->>'job_title_include_node_ids', '')), '') is not null then
        select array_agg(parsed.include_node_id_text order by parsed.include_node_id_text)
        into v_job_title_include_node_ids
        from (
          select distinct nullif(btrim(include_tokens.token), '') as include_node_id_text
          from unnest(regexp_split_to_array(p_filters->>'job_title_include_node_ids', '\s*,\s*')) as include_tokens(token)
          where nullif(btrim(include_tokens.token), '') is not null
        ) as parsed;
      end if;
    end if;
  exception when others then
    v_job_title_include_node_ids := null;
  end;

  begin
    if p_filters ? 'job_title_exclude_node_ids' then
      if jsonb_typeof(p_filters->'job_title_exclude_node_ids') = 'array' then
        select array_agg(parsed.exclude_node_id_text order by parsed.exclude_node_id_text)
        into v_job_title_exclude_node_ids
        from (
          select distinct nullif(btrim(exclude_nodes.value), '') as exclude_node_id_text
          from jsonb_array_elements_text(p_filters->'job_title_exclude_node_ids') as exclude_nodes(value)
          where nullif(btrim(exclude_nodes.value), '') is not null
        ) as parsed;
      elsif nullif(btrim(coalesce(p_filters->>'job_title_exclude_node_ids', '')), '') is not null then
        select array_agg(parsed.exclude_node_id_text order by parsed.exclude_node_id_text)
        into v_job_title_exclude_node_ids
        from (
          select distinct nullif(btrim(exclude_tokens.token), '') as exclude_node_id_text
          from unnest(regexp_split_to_array(p_filters->>'job_title_exclude_node_ids', '\s*,\s*')) as exclude_tokens(token)
          where nullif(btrim(exclude_tokens.token), '') is not null
        ) as parsed;
      end if;
    end if;
  exception when others then
    v_job_title_exclude_node_ids := null;
  end;

  begin
    if p_filters ? 'job_title_role_ids' then
      if jsonb_typeof(p_filters->'job_title_role_ids') = 'array' then
        select array_agg(parsed.role_id order by parsed.role_id)
        into v_job_title_role_ids
        from (
          select distinct nullif(btrim(role_nodes.value), '')::uuid as role_id
          from jsonb_array_elements_text(p_filters->'job_title_role_ids') as role_nodes(value)
          where nullif(btrim(role_nodes.value), '') is not null
        ) as parsed;
      elsif nullif(btrim(coalesce(p_filters->>'job_title_role_ids', '')), '') is not null then
        select array_agg(parsed.role_id order by parsed.role_id)
        into v_job_title_role_ids
        from (
          select distinct nullif(btrim(role_tokens.token), '')::uuid as role_id
          from unnest(regexp_split_to_array(p_filters->>'job_title_role_ids', '\s*,\s*')) as role_tokens(token)
          where nullif(btrim(role_tokens.token), '') is not null
        ) as parsed;
      end if;
    end if;
  exception when others then
    v_job_title_role_ids := null;
  end;

  begin
    if p_filters ? 'job_title_primary_only' then
      v_job_title_primary_only := case lower(btrim(coalesce(p_filters->>'job_title_primary_only', '')))
        when 'true' then true
        when '1' then true
        when 'yes' then true
        when 'y' then true
        when 'on' then true
        else false
      end;
    else
      v_job_title_primary_only := false;
    end if;
  exception when others then
    v_job_title_primary_only := false;
  end;

  begin
    if p_filters ? 'ids' then
      if jsonb_typeof(p_filters->'ids') = 'array' then
        select array_agg(parsed.selected_id order by parsed.selected_id)
        into v_ids
        from (
          select distinct nullif(btrim(id_nodes.value), '')::uuid as selected_id
          from jsonb_array_elements_text(p_filters->'ids') as id_nodes(value)
          where nullif(btrim(id_nodes.value), '') is not null
        ) as parsed;
      elsif nullif(btrim(coalesce(p_filters->>'ids', '')), '') is not null then
        select array_agg(parsed.selected_id order by parsed.selected_id)
        into v_ids
        from (
          select distinct nullif(btrim(id_tokens.token), '')::uuid as selected_id
          from unnest(regexp_split_to_array(p_filters->>'ids', '\s*,\s*')) as id_tokens(token)
          where nullif(btrim(id_tokens.token), '') is not null
        ) as parsed;
      end if;
    end if;
  exception when others then
    v_ids := null;
  end;

  begin
    if p_filters ? 'roles_any' then
      if jsonb_typeof(p_filters->'roles_any') = 'array' then
        select array_agg(parsed.role_code order by parsed.role_code)
        into v_roles_any
        from (
          select distinct upper(nullif(btrim(role_any_nodes.value), '')) as role_code
          from jsonb_array_elements_text(p_filters->'roles_any') as role_any_nodes(value)
        ) as parsed
        where parsed.role_code is not null;
      elsif nullif(btrim(coalesce(p_filters->>'roles_any', '')), '') is not null then
        select array_agg(parsed.role_code order by parsed.role_code)
        into v_roles_any
        from (
          select distinct upper(nullif(btrim(role_any_tokens.token), '')) as role_code
          from unnest(regexp_split_to_array(p_filters->>'roles_any', '\s*,\s*')) as role_any_tokens(token)
        ) as parsed
        where parsed.role_code is not null;
      end if;
    end if;
  exception when others then
    v_roles_any := null;
  end;

  begin
    if p_filters ? 'roles_all' then
      if jsonb_typeof(p_filters->'roles_all') = 'array' then
        select array_agg(parsed.role_code order by parsed.role_code)
        into v_roles_all
        from (
          select distinct upper(nullif(btrim(role_all_nodes.value), '')) as role_code
          from jsonb_array_elements_text(p_filters->'roles_all') as role_all_nodes(value)
        ) as parsed
        where parsed.role_code is not null;
      elsif nullif(btrim(coalesce(p_filters->>'roles_all', '')), '') is not null then
        select array_agg(parsed.role_code order by parsed.role_code)
        into v_roles_all
        from (
          select distinct upper(nullif(btrim(role_all_tokens.token), '')) as role_code
          from unnest(regexp_split_to_array(p_filters->>'roles_all', '\s*,\s*')) as role_all_tokens(token)
        ) as parsed
        where parsed.role_code is not null;
      end if;
    end if;
  exception when others then
    v_roles_all := null;
  end;

  if v_recent_months_raw = 'ALL' then
    v_recent_all := true;
    v_recent_months := 3;
  elsif v_recent_months_raw is not null then
    begin
      v_recent_months := greatest(1, least(120, (v_recent_months_raw)::int));
    exception when others then
      v_recent_months := 3;
    end;
  else
    v_recent_months := 3;
  end if;

  if v_work_status in ('RECENT', 'NOT') and not v_recent_all then
    v_cutoff_ymd := ((now() at time zone v_timezone_id)::date - make_interval(months => v_recent_months))::date;
  end if;

  return query
  with recursive job_title_tree as (
    select
      root_job_titles.id,
      root_job_titles.parent_id,
      root_job_titles.is_role,
      case
        when root_job_titles.id::text = any(coalesce(v_job_title_include_node_ids, '{}'::text[])) then true
        when root_job_titles.id::text = any(coalesce(v_job_title_exclude_node_ids, '{}'::text[])) then false
        else false
      end as checked,
      case
        when root_job_titles.id::text = any(coalesce(v_job_title_include_node_ids, '{}'::text[])) then 'included'
        when root_job_titles.id::text = any(coalesce(v_job_title_exclude_node_ids, '{}'::text[])) then 'excluded'
        else 'none'
      end as inherited_mode
    from public.default_job_titles as root_job_titles
    where root_job_titles.parent_id is null
       or not exists (
         select 1
         from public.default_job_titles as parent_job_titles
         where parent_job_titles.id = root_job_titles.parent_id
       )

    union all

    select
      child_job_titles.id,
      child_job_titles.parent_id,
      child_job_titles.is_role,
      case
        when child_job_titles.id::text = any(coalesce(v_job_title_include_node_ids, '{}'::text[])) then true
        when child_job_titles.id::text = any(coalesce(v_job_title_exclude_node_ids, '{}'::text[])) then false
        when job_title_tree.inherited_mode = 'included' then true
        when job_title_tree.inherited_mode = 'excluded' then false
        else false
      end as checked,
      case
        when child_job_titles.id::text = any(coalesce(v_job_title_include_node_ids, '{}'::text[])) then 'included'
        when child_job_titles.id::text = any(coalesce(v_job_title_exclude_node_ids, '{}'::text[])) then 'excluded'
        when job_title_tree.inherited_mode = 'included' then 'included'
        when job_title_tree.inherited_mode = 'excluded' then 'excluded'
        else 'none'
      end as inherited_mode
    from public.default_job_titles as child_job_titles
    join job_title_tree
      on job_title_tree.id = child_job_titles.parent_id
  ),
  tree_selected_roles as (
    select distinct
      job_title_tree.id as role_id
    from job_title_tree
    where job_title_tree.is_role = true
      and job_title_tree.checked = true
  ),
  effective_role_ids as (
    select distinct
      tree_selected_roles.role_id
    from tree_selected_roles
    where (
      coalesce(array_length(v_job_title_include_node_ids, 1), 0) > 0
      or coalesce(array_length(v_job_title_exclude_node_ids, 1), 0) > 0
    )
      and (
        coalesce(array_length(v_job_title_role_ids, 1), 0) = 0
        or tree_selected_roles.role_id = any(coalesce(v_job_title_role_ids, '{}'::uuid[]))
      )

    union

    select distinct
      direct_role_ids.role_id
    from unnest(coalesce(v_job_title_role_ids, '{}'::uuid[])) as direct_role_ids(role_id)
    where coalesce(array_length(v_job_title_include_node_ids, 1), 0) = 0
      and coalesce(array_length(v_job_title_exclude_node_ids, 1), 0) = 0
      and coalesce(array_length(v_job_title_role_ids, 1), 0) > 0
  ),
  candidate_filter_flags as (
    select
      (
        coalesce(array_length(v_job_title_include_node_ids, 1), 0) > 0
        or coalesce(array_length(v_job_title_exclude_node_ids, 1), 0) > 0
        or coalesce(array_length(v_job_title_role_ids, 1), 0) > 0
      ) as has_job_title_filter,
      v_job_title_primary_only as primary_only
  ),
  filtered as (
    select csa.id
    from public.candidates_summary_activity as csa
    cross join candidate_filter_flags as candidate_flags
    where (v_ids is null or csa.id = any(v_ids))
      and (v_first_name is null or csa.first_name ilike ('%' || v_first_name || '%'))
      and (v_last_name is null or csa.last_name ilike ('%' || v_last_name || '%'))
      and (v_email is null or csa.email ilike ('%' || v_email || '%'))
      and (v_phone is null or csa.phone ilike ('%' || v_phone || '%'))
      and (
        v_notes is null
        or csa.notes ilike ('%' || replace(replace(replace(v_notes, E'\\', E'\\\\'), '%', E'\\%'), '_', E'\\_') || '%') escape '\\'
      )
      and (
        v_pay_method is null
        or (v_pay_method = 'BLANK' and csa.pay_method is null)
        or (v_pay_method <> 'BLANK' and upper(coalesce(csa.pay_method::text, '')) = v_pay_method)
      )
      and (
        v_active is null
        or (v_active = 'true' and csa.active = true)
        or (v_active = 'false' and csa.active = false)
      )
      and (v_created_from is null or (csa.created_at AT TIME ZONE v_timezone_id)::date >= v_created_from)
      and (v_created_to is null or (csa.created_at AT TIME ZONE v_timezone_id)::date <= v_created_to)
      and (v_updated_from is null or (csa.updated_at AT TIME ZONE v_timezone_id)::date >= v_updated_from)
      and (v_updated_to is null or (csa.updated_at AT TIME ZONE v_timezone_id)::date <= v_updated_to)
      and (
        candidate_flags.has_job_title_filter = false
        or (
          candidate_flags.primary_only = true
          and exists (
            select 1
            from effective_role_ids as effective_roles
            where effective_roles.role_id = csa.primary_job_title_id
          )
        )
        or (
          candidate_flags.primary_only = false
          and (
            exists (
              select 1
              from effective_role_ids as effective_roles
              where effective_roles.role_id = csa.primary_job_title_id
            )
            or exists (
              select 1
              from unnest(coalesce(csa.job_title_ids, '{}'::uuid[])) as candidate_job_titles(job_title_id)
              join effective_role_ids as effective_roles
                on effective_roles.role_id = candidate_job_titles.job_title_id
            )
          )
        )
      )
      and (v_prof_reg_number is null or csa.prof_reg_number ilike ('%' || v_prof_reg_number || '%'))
      and (v_prof_reg_type is null or upper(coalesce(csa.prof_reg_type::text, '')) = v_prof_reg_type)
      and (v_dob is null or csa.date_of_birth = v_dob)
      and (v_gender is null or csa.gender = v_gender)
      and (v_town_city is null or csa.town_city ilike ('%' || v_town_city || '%'))
      and (v_postcode is null or csa.postcode ilike ('%' || v_postcode || '%'))
      and (v_sort_code is null or csa.sort_code ilike ('%' || v_sort_code || '%'))
      and (v_account_number is null or csa.account_number ilike ('%' || v_account_number || '%'))
      and (v_umbrella_name is null or csa.umbrella_name ilike ('%' || v_umbrella_name || '%'))
      and (v_tms_ref is null or csa.tms_ref ilike ('%' || v_tms_ref || '%'))
      and (
        v_q is null
        or (
          csa.first_name ilike ('%' || v_q || '%')
          or csa.last_name ilike ('%' || v_q || '%')
          or csa.display_name ilike ('%' || v_q || '%')
          or csa.email ilike ('%' || v_q || '%')
          or csa.phone ilike ('%' || v_q || '%')
          or csa.tms_ref ilike ('%' || v_q || '%')
          or csa.job_titles_display ilike ('%' || v_q || '%')
        )
      )
      and (
        v_roles_any is null
        or exists (
          select 1
          from jsonb_array_elements(coalesce(csa.roles, '[]'::jsonb)) as roles_any_json(role_elem)
          where upper(coalesce(roles_any_json.role_elem->>'code', '')) = any(v_roles_any)
        )
      )
      and (
        v_roles_all is null
        or not exists (
          select 1
          from unnest(v_roles_all) as required_roles(required_code)
          where not exists (
            select 1
            from jsonb_array_elements(coalesce(csa.roles, '[]'::jsonb)) as roles_all_json(role_elem)
            where upper(coalesce(roles_all_json.role_elem->>'code', '')) = required_roles.required_code
          )
        )
      )
      and (
        v_work_status is null
        or v_work_status = 'ALL'
        or (v_work_status = 'CURRENT' and csa.is_currently_working = true)
        or (
          v_work_status = 'RECENT'
          and (
            csa.is_currently_working = true
            or (
              csa.is_currently_working = false
              and (
                (v_recent_all and csa.last_timesheet_week_ending is not null)
                or (not v_recent_all and v_cutoff_ymd is not null and csa.last_timesheet_week_ending >= v_cutoff_ymd)
              )
            )
          )
        )
        or (
          v_work_status = 'NOT'
          and csa.is_currently_working = false
          and (
            csa.last_timesheet_week_ending is null
            or (v_cutoff_ymd is not null and csa.last_timesheet_week_ending < v_cutoff_ymd)
          )
        )
      )
  )
  select filtered.id
  from filtered
  order by filtered.id;
end;
$function$;

-- candidate_missing_week_options_v1(uuid,text,uuid,date,date,timestamp with time zone)
CREATE OR REPLACE FUNCTION public.candidate_missing_week_options_v1(p_session_id uuid, p_environment text, p_contract_id uuid, p_from date, p_to date, p_now_utc timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
declare
  v_context jsonb;
  v_candidate_id uuid;
  v_contract public.contracts%rowtype;
  v_first date;
  v_options jsonb;
  v_import_authority jsonb;
begin
  perform private._candidate_require_feature_v1(p_environment,'candidate_app_reads');
  if p_from is null or p_to is null or p_from>p_to or p_to-p_from>366 then
    raise exception 'CANDIDATE_MISSING_WEEK_RANGE_INVALID' using errcode='22023';
  end if;
  v_context:=private._candidate_session_context_v1(p_session_id,p_environment,null,p_now_utc,false);
  v_candidate_id:=nullif(v_context->>'selected_candidate_id','')::uuid;
  select * into v_contract from public.contracts where id=p_contract_id and candidate_id=v_candidate_id;
  if not found then raise exception 'CANDIDATE_CONTRACT_NOT_FOUND' using errcode='P0002'; end if;
  v_import_authority:=private._candidate_import_authoritative_v1(
    v_contract.client_id,v_contract.id,null,null,p_from
  );
  if coalesce((v_import_authority->>'is_import_authoritative')::boolean,false) then
    return jsonb_build_object('ok',true,'contract_id',p_contract_id,'options','[]'::jsonb,'route_eligible',false);
  end if;
  v_first:=p_from+mod(v_contract.week_ending_weekday_snapshot-extract(dow from p_from)::integer+7,7);
  select coalesce(jsonb_agg(jsonb_build_object(
    'week_ending_date',g::date,'submission_mode',resolved.submission_mode,
    'route_family',case
      when resolved.submission_mode='ELECTRONIC' then 'ELECTRONIC'
      when coalesce((resolved.policy->>'paper_submission_enabled')::boolean,false) then 'QR'
      else 'MANUAL_NON_QR' end,
    'paper_submission_enabled',coalesce((resolved.policy->>'paper_submission_enabled')::boolean,false)
  ) order by g),'[]'::jsonb) into v_options
  from generate_series(v_first,least(p_to,v_contract.end_date),interval '7 days') g
  cross join lateral (
    select
      private._candidate_policy_resolve_v1(v_contract.client_id,v_contract.id,g::date) as policy,
      private._candidate_submission_mode_v1(v_contract.client_id,v_contract.id,g::date) as submission_mode
  ) resolved
  where g::date between v_contract.start_date and v_contract.end_date
    and (
      resolved.submission_mode='ELECTRONIC'
      or (resolved.submission_mode='MANUAL'
        and coalesce((resolved.policy->>'paper_submission_enabled')::boolean,false))
    )
    and not exists(select 1 from public.contract_weeks cw where cw.contract_id=v_contract.id and cw.week_ending_date=g::date and cw.additional_seq=0);
  return jsonb_build_object('ok',true,'contract_id',p_contract_id,'options',v_options,
    'route_eligible',jsonb_array_length(v_options)>0);
end;
$function$;

-- candidate_no_work_atomic_v1(uuid,text,uuid,text,text,timestamp with time zone)
CREATE OR REPLACE FUNCTION public.candidate_no_work_atomic_v1(p_session_id uuid, p_environment text, p_contract_week_id uuid, p_expected_row_signature text, p_idempotency_key text, p_now_utc timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
declare
  v_environment text;
  v_context jsonb;
  v_candidate_id uuid;
  v_week public.contract_weeks%rowtype;
  v_contract public.contracts%rowtype;
  v_system_actor uuid;
  v_preview jsonb;
  v_result jsonb;
  v_response jsonb;
  v_signature text;
  v_route_authority jsonb;
begin
  v_environment:=private._candidate_assert_environment(p_environment);
  perform private._candidate_require_feature_v1(v_environment,'candidate_app_writes');
  v_context:=private._candidate_session_context_v1(p_session_id,v_environment,null,p_now_utc,true);
  v_candidate_id:=nullif(v_context->>'selected_candidate_id','')::uuid;
  if v_candidate_id is null or p_contract_week_id is null or nullif(btrim(coalesce(p_idempotency_key,'')),'') is null then
    raise exception 'CANDIDATE_NO_WORK_PAYLOAD_INVALID' using errcode='22023';
  end if;
  select ae.after_json into v_response
  from public.audit_events ae
  where ae.object_type='contract_week'
    and ae.object_id_text=p_contract_week_id::text
    and ae.action='CANDIDATE_NO_WORK'
    and ae.correlation_id=p_idempotency_key
  order by ae.ts_utc desc,ae.id desc
  limit 1;
  if found then
    return coalesce(v_response,'{}'::jsonb)||jsonb_build_object('idempotent_replay',true);
  end if;
  select * into v_week from public.contract_weeks where id=p_contract_week_id for update;
  if not found then raise exception 'CANDIDATE_CONTRACT_WEEK_NOT_FOUND' using errcode='P0002'; end if;
  select * into v_contract from public.contracts where id=v_week.contract_id and candidate_id=v_candidate_id for update;
  if not found then raise exception 'CANDIDATE_WORKFLOW_OWNERSHIP_MISMATCH' using errcode='28000'; end if;
  select candidate_app_system_actor_user_id into v_system_actor from public.settings_defaults where id=1;
  if v_system_actor is null then raise exception 'CANDIDATE_SYSTEM_ACTOR_NOT_CONFIGURED' using errcode='55000'; end if;
  v_route_authority:=private._candidate_route_family_v1(v_week.timesheet_id,v_week.id);
  if not coalesce((v_route_authority->>'candidate_no_work_allowed')::boolean,false) then
    raise exception 'CANDIDATE_NO_WORK_NOT_ALLOWED' using errcode='55000',detail=v_route_authority::text;
  end if;

  if v_week.timesheet_id is null then
    if v_week.status not in ('PLANNED','OPEN') then raise exception 'CANDIDATE_NO_WORK_NOT_ALLOWED' using errcode='55000'; end if;
    select to_jsonb(x) into v_result from public.contract_week_delete_planned(v_week.id,v_system_actor) x;
    v_response:=jsonb_build_object('ok',true,'action','DELETE_PLANNED','contract_week_id',v_week.id,
      'result',v_result,'candidate_hidden',true,'idempotency_key',p_idempotency_key,'idempotent_replay',false);
    perform private._candidate_audit_v1('contract_week',v_week.id::text,'CANDIDATE_NO_WORK',
      jsonb_build_object('timesheet_id',null),v_response,null,v_system_actor,p_idempotency_key,p_now_utc);
    return v_response;
  end if;

  v_signature:=coalesce(nullif(btrim(p_expected_row_signature),''),
    public.timesheet_lifecycle_guard_signature_v1(v_week.timesheet_id,v_week.id,false)->>'row_signature');
  if v_signature is null then raise exception 'CANDIDATE_ROW_SIGNATURE_REQUIRED' using errcode='22023'; end if;
  v_preview:=public.timesheet_standard_delete_preview_v1(
    v_week.timesheet_id,v_system_actor,v_week.timesheet_id,v_signature
  );
  if v_preview->>'decision'='PERMANENT_DELETE' then
    v_result:=public.timesheet_standard_delete_apply_v1(
      v_week.timesheet_id,v_system_actor,v_week.timesheet_id,v_signature
    );
  elsif v_preview->>'decision'='ARCHIVE_REQUIRED' then
    v_result:=public.timesheet_archive_transition_v1(
      v_week.timesheet_id,'ARCHIVE','STANDARD_DELETE',v_system_actor,v_week.timesheet_id,v_signature,p_now_utc
    );
  else
    raise exception 'CANDIDATE_NO_WORK_BLOCKED' using errcode='55000',detail=v_preview::text;
  end if;
  if coalesce((v_result->>'ok')::boolean,false)=false then
    raise exception 'CANDIDATE_NO_WORK_BLOCKED' using errcode='55000',detail=v_result::text;
  end if;
  v_response:=jsonb_build_object('ok',true,'contract_week_id',v_week.id,'timesheet_id',v_week.timesheet_id,
    'decision',v_preview->>'decision','result',v_result,'candidate_hidden',true,
    'idempotency_key',p_idempotency_key,'idempotent_replay',false);
  perform private._candidate_audit_v1('contract_week',v_week.id::text,'CANDIDATE_NO_WORK',
    jsonb_build_object('timesheet_id',v_week.timesheet_id),v_response,null,v_system_actor,p_idempotency_key,p_now_utc);
  return v_response;
end;
$function$;

-- candidate_pay_method_change_apply(uuid,text,jsonb,uuid,text)
CREATE OR REPLACE FUNCTION public.candidate_pay_method_change_apply(p_candidate_id uuid, p_new_method text, p_plan jsonb, p_actor_user_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_uuid_re text := '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
  v_new_method text := UPPER(BTRIM(COALESCE(p_new_method, '')));
  v_expected_old_method text;
  v_old_method text;
  v_operation_id uuid;
  v_preview_source_change_seq bigint;
  v_current_source_change_seq bigint := 0;
  v_destination_patch jsonb := '{}'::jsonb;
  v_operation_request_json jsonb := '{}'::jsonb;
  v_unknown_plan_keys text[] := ARRAY[]::text[];
  v_unknown_destination_keys text[] := ARRAY[]::text[];
  v_effective_umbrella_id uuid;
  v_account_holder text;
  v_bank_name text;
  v_sort_code text;
  v_account_number text;
  v_actor_role text;
  v_scope_result jsonb := '{}'::jsonb;
  v_post_scope_result jsonb := '{}'::jsonb;
  v_expected_targeted_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_post_targeted_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_enqueued_targeted_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_missing_targeted_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_extra_targeted_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_enqueued_raw_count integer := 0;
  v_enqueued_invalid_count integer := 0;
  v_effective_duplicate_count integer := 0;
  v_scope_exact boolean := false;
  v_scope_complete boolean := false;
  v_job_id uuid;
  v_job_status text;
  v_job_payload jsonb := '{}'::jsonb;
  v_job_source_change_seq bigint := 0;
  v_before_json jsonb := '{}'::jsonb;
  v_after_json jsonb := '{}'::jsonb;
  v_result jsonb := '{}'::jsonb;
  v_audit_after_json jsonb := '{}'::jsonb;
  v_existing_operation_audit_id uuid := NULL::uuid;
  v_existing_operation_before_json jsonb := '{}'::jsonb;
  v_existing_operation_after_json jsonb := '{}'::jsonb;
  v_existing_operation_result jsonb := '{}'::jsonb;
  v_existing_operation_source_method text := NULL::text;
  v_existing_operation_target_method text := NULL::text;
  v_existing_operation_job_id uuid := NULL::uuid;
  v_existing_operation_job_status text := NULL::text;
  v_existing_operation_source_change_seq bigint := 0;
  v_existing_operation_superseded boolean := false;
BEGIN
  IF p_candidate_id IS NULL THEN
    RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_CANDIDATE_REQUIRED'
      USING ERRCODE = '22023';
  END IF;

  IF v_new_method NOT IN ('PAYE', 'UMBRELLA') THEN
    RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_TARGET_METHOD_INVALID'
      USING ERRCODE = '22023', DETAIL = COALESCE(p_new_method, '');
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_ACTOR_REQUIRED'
      USING ERRCODE = '22023';
  END IF;

  SELECT LOWER(BTRIM(COALESCE(user_row.role, '')))
  INTO v_actor_role
  FROM public.tms_users AS user_row
  WHERE user_row.id = p_actor_user_id
    AND user_row.is_active IS TRUE;

  IF NOT FOUND OR v_actor_role <> 'admin' THEN
    RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_ADMIN_REQUIRED'
      USING ERRCODE = '42501', DETAIL = p_actor_user_id::text;
  END IF;

  IF p_plan IS NULL OR jsonb_typeof(p_plan) <> 'object' THEN
    RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_PLAN_OBJECT_REQUIRED'
      USING ERRCODE = '22023';
  END IF;

  IF p_plan ?| ARRAY[
    'contract_ids',
    'contracts',
    'migrations',
    'successor_start',
    'successor_contract_id',
    'new_contract_id',
    'new_rates_json',
    'new_additional_rates_json',
    'rates_json',
    'timesheet_ids',
    'affected_timesheet_ids',
    'move_contract_weeks',
    'delete_old_contracts'
  ] THEN
    RAISE EXCEPTION 'LEGACY_CONTRACT_MIGRATION_PLAN_REJECTED'
      USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(array_agg(plan_key ORDER BY plan_key), ARRAY[]::text[])
  INTO v_unknown_plan_keys
  FROM jsonb_object_keys(p_plan) AS plan_keys(plan_key)
  WHERE plan_key NOT IN (
    'operation_id',
    'expected_old_method',
    'preview_source_change_seq',
    'destination_patch'
  );

  IF COALESCE(array_length(v_unknown_plan_keys, 1), 0) > 0 THEN
    RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_PLAN_FIELDS_UNSUPPORTED'
      USING ERRCODE = '22023', DETAIL = array_to_string(v_unknown_plan_keys, ',');
  END IF;

  IF COALESCE(p_plan->>'operation_id', '') !~* v_uuid_re THEN
    RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_OPERATION_ID_REQUIRED'
      USING ERRCODE = '22023';
  END IF;
  v_operation_id := (p_plan->>'operation_id')::uuid;

  v_expected_old_method := UPPER(BTRIM(COALESCE(p_plan->>'expected_old_method', '')));
  IF v_expected_old_method NOT IN ('PAYE', 'UMBRELLA') THEN
    RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_EXPECTED_OLD_METHOD_INVALID'
      USING ERRCODE = '22023';
  END IF;

  IF COALESCE(p_plan->>'preview_source_change_seq', '') !~ '^[0-9]{1,18}$' THEN
    RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_PREVIEW_SEQUENCE_REQUIRED'
      USING ERRCODE = '22023';
  END IF;
  v_preview_source_change_seq := (p_plan->>'preview_source_change_seq')::bigint;

  IF p_plan ? 'destination_patch' THEN
    IF jsonb_typeof(p_plan->'destination_patch') <> 'object' THEN
      RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_DESTINATION_PATCH_INVALID'
        USING ERRCODE = '22023';
    END IF;
    v_destination_patch := p_plan->'destination_patch';
  END IF;

  SELECT COALESCE(array_agg(destination_key ORDER BY destination_key), ARRAY[]::text[])
  INTO v_unknown_destination_keys
  FROM jsonb_object_keys(v_destination_patch) AS destination_keys(destination_key)
  WHERE destination_key NOT IN (
    'umbrella_id',
    'account_holder',
    'bank_name',
    'sort_code',
    'account_number'
  );

  IF COALESCE(array_length(v_unknown_destination_keys, 1), 0) > 0 THEN
    RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_DESTINATION_FIELDS_UNSUPPORTED'
      USING ERRCODE = '22023', DETAIL = array_to_string(v_unknown_destination_keys, ',');
  END IF;

  v_operation_request_json := jsonb_build_object(
    'candidate_id', p_candidate_id::text,
    'expected_old_method', v_expected_old_method,
    'new_method', v_new_method,
    'preview_source_change_seq', v_preview_source_change_seq,
    'destination_patch', v_destination_patch
  );

  SELECT
    UPPER(BTRIM(COALESCE(candidate_row.pay_method, ''))),
    candidate_row.umbrella_id,
    candidate_row.account_holder,
    candidate_row.bank_name,
    candidate_row.sort_code,
    candidate_row.account_number,
    jsonb_build_object(
      'id', candidate_row.id::text,
      'pay_method', candidate_row.pay_method,
      'umbrella_id', CASE WHEN candidate_row.umbrella_id IS NULL THEN NULL ELSE candidate_row.umbrella_id::text END,
      'account_holder', candidate_row.account_holder,
      'bank_name', candidate_row.bank_name,
      'sort_code', candidate_row.sort_code,
      'account_number', candidate_row.account_number,
      'updated_at', candidate_row.updated_at,
      'rev', candidate_row.rev
    )
  INTO
    v_old_method,
    v_effective_umbrella_id,
    v_account_holder,
    v_bank_name,
    v_sort_code,
    v_account_number,
    v_before_json
  FROM public.candidates AS candidate_row
  WHERE candidate_row.id = p_candidate_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_CANDIDATE_NOT_FOUND'
      USING ERRCODE = 'P0002', DETAIL = p_candidate_id::text;
  END IF;

  SELECT
    audit_row.id,
    COALESCE(audit_row.before_json, '{}'::jsonb),
    COALESCE(audit_row.after_json, '{}'::jsonb)
  INTO
    v_existing_operation_audit_id,
    v_existing_operation_before_json,
    v_existing_operation_after_json
  FROM public.audit_events AS audit_row
  WHERE audit_row.object_type = 'candidate'
    AND audit_row.object_id_text = p_candidate_id::text
    AND audit_row.action = 'PAY_METHOD_CHANGE_PROSPECTIVE_ONLY'
    AND audit_row.after_json->>'operation_id' = v_operation_id::text
  ORDER BY audit_row.ts_utc DESC, audit_row.id DESC
  LIMIT 1;

  IF v_existing_operation_audit_id IS NOT NULL THEN
    v_existing_operation_result := CASE
      WHEN jsonb_typeof(v_existing_operation_after_json->'operation_result') = 'object'
        THEN v_existing_operation_after_json->'operation_result'
      ELSE '{}'::jsonb
    END;

    v_existing_operation_source_method := UPPER(BTRIM(COALESCE(
      v_existing_operation_result->>'original_method',
      v_existing_operation_after_json->>'original_method',
      v_existing_operation_before_json->>'pay_method',
      ''
    )));
    v_existing_operation_target_method := UPPER(BTRIM(COALESCE(
      v_existing_operation_result->>'new_method',
      v_existing_operation_after_json->>'new_method',
      v_existing_operation_after_json->>'pay_method',
      ''
    )));

    IF v_existing_operation_source_method NOT IN ('PAYE', 'UMBRELLA')
       OR v_existing_operation_target_method NOT IN ('PAYE', 'UMBRELLA')
       OR v_existing_operation_source_method = v_existing_operation_target_method THEN
      RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_OPERATION_AUDIT_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = format(
                'operation=%s audit=%s source=%s target=%s',
                v_operation_id,
                v_existing_operation_audit_id,
                COALESCE(v_existing_operation_source_method, ''),
                COALESCE(v_existing_operation_target_method, '')
              );
    END IF;

    IF v_existing_operation_source_method <> v_expected_old_method
       OR v_existing_operation_target_method <> v_new_method THEN
      RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_OPERATION_ID_CONFLICT'
        USING ERRCODE = '40001',
              DETAIL = format(
                'operation=%s committed=%s_to_%s requested=%s_to_%s',
                v_operation_id,
                v_existing_operation_source_method,
                v_existing_operation_target_method,
                v_expected_old_method,
                v_new_method
              );
    END IF;

    IF jsonb_typeof(v_existing_operation_after_json->'operation_request') = 'object' THEN
      IF (v_existing_operation_after_json->'operation_request') IS DISTINCT FROM v_operation_request_json THEN
        RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_OPERATION_ID_CONFLICT'
          USING ERRCODE = '40001',
                DETAIL = format('operation=%s request_payload_mismatch', v_operation_id);
      END IF;
    ELSIF v_new_method = 'UMBRELLA' THEN
      IF v_destination_patch ? 'account_holder'
         OR v_destination_patch ? 'bank_name'
         OR v_destination_patch ? 'sort_code'
         OR v_destination_patch ? 'account_number'
         OR (
           v_destination_patch ? 'umbrella_id'
           AND NULLIF(BTRIM(COALESCE(v_destination_patch->>'umbrella_id', '')), '')
             IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_existing_operation_after_json->>'umbrella_id', '')), '')
         ) THEN
        RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_OPERATION_ID_CONFLICT'
          USING ERRCODE = '40001',
                DETAIL = format('operation=%s legacy_destination_payload_mismatch', v_operation_id);
      END IF;
    ELSE
      IF NULLIF(BTRIM(COALESCE(v_destination_patch->>'umbrella_id', '')), '') IS NOT NULL
         OR (
           v_destination_patch ? 'account_holder'
           AND NULLIF(BTRIM(COALESCE(v_destination_patch->>'account_holder', '')), '')
             IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_existing_operation_after_json->>'account_holder', '')), '')
         )
         OR (
           v_destination_patch ? 'bank_name'
           AND NULLIF(BTRIM(COALESCE(v_destination_patch->>'bank_name', '')), '')
             IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_existing_operation_after_json->>'bank_name', '')), '')
         )
         OR (
           v_destination_patch ? 'sort_code'
           AND NULLIF(BTRIM(COALESCE(v_destination_patch->>'sort_code', '')), '')
             IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_existing_operation_after_json->>'sort_code', '')), '')
         )
         OR (
           v_destination_patch ? 'account_number'
           AND NULLIF(BTRIM(COALESCE(v_destination_patch->>'account_number', '')), '')
             IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_existing_operation_after_json->>'account_number', '')), '')
         ) THEN
        RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_OPERATION_ID_CONFLICT'
          USING ERRCODE = '40001',
                DETAIL = format('operation=%s legacy_destination_payload_mismatch', v_operation_id);
      END IF;
    END IF;

    IF COALESCE(
         v_existing_operation_result->>'job_id',
         v_existing_operation_after_json->>'job_id',
         ''
       ) ~* v_uuid_re THEN
      v_existing_operation_job_id := COALESCE(
        v_existing_operation_result->>'job_id',
        v_existing_operation_after_json->>'job_id'
      )::uuid;
    END IF;

    IF v_existing_operation_job_id IS NOT NULL THEN
      SELECT
        job_row.status,
        COALESCE(job_row.payload_json, '{}'::jsonb)
      INTO
        v_existing_operation_job_status,
        v_job_payload
      FROM public.banking_pay_workbench_jobs AS job_row
      WHERE job_row.id = v_existing_operation_job_id
        AND job_row.candidate_id = p_candidate_id
      LIMIT 1;
    END IF;

    v_existing_operation_job_status := COALESCE(
      v_existing_operation_job_status,
      NULLIF(BTRIM(COALESCE(v_existing_operation_result->>'job_status', '')), ''),
      NULLIF(BTRIM(COALESCE(v_existing_operation_after_json->>'job_status', '')), '')
    );
    v_existing_operation_source_change_seq := COALESCE(
      CASE
        WHEN COALESCE(v_existing_operation_result->>'source_change_seq', '') ~ '^[0-9]{1,18}$'
          THEN (v_existing_operation_result->>'source_change_seq')::bigint
        WHEN COALESCE(v_existing_operation_after_json->>'source_change_seq', '') ~ '^[0-9]{1,18}$'
          THEN (v_existing_operation_after_json->>'source_change_seq')::bigint
      END,
      0
    );

    IF v_existing_operation_job_id IS NULL
       OR v_existing_operation_job_status IS NULL
       OR jsonb_typeof(v_existing_operation_result->'expected_targeted_timesheet_ids') IS DISTINCT FROM 'array'
       OR LOWER(BTRIM(COALESCE(v_existing_operation_result->>'exact_set_equality', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on') THEN
      RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_OPERATION_EXACT_SCOPE_PROOF_MISSING'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'operation_id', v_operation_id::text,
                'audit_id', v_existing_operation_audit_id,
                'job_id', CASE WHEN v_existing_operation_job_id IS NULL THEN NULL ELSE v_existing_operation_job_id::text END
              )::text;
    END IF;

    IF COALESCE(v_job_payload->>'candidate_id', '') <> p_candidate_id::text
       OR COALESCE(v_job_payload->>'route_change_operation_id', '') <> v_operation_id::text
       OR UPPER(BTRIM(COALESCE(v_job_payload->>'route_change_source_method', ''))) <> v_existing_operation_source_method
       OR UPPER(BTRIM(COALESCE(v_job_payload->>'route_change_target_method', ''))) <> v_existing_operation_target_method
       OR LOWER(BTRIM(COALESCE(v_job_payload->>'exact_target_scope', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
       OR UPPER(BTRIM(COALESCE(v_job_payload->>'refresh_scope_kind', ''))) <> 'TARGETED_TIMESHEETS' THEN
      RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_OPERATION_QUEUE_AUTHORITY_MISMATCH'
        USING ERRCODE = 'P0001', DETAIL = v_existing_operation_job_id::text;
    END IF;

    IF EXISTS (
      SELECT 1
      FROM jsonb_array_elements_text(v_existing_operation_result->'expected_targeted_timesheet_ids') AS expected_raw(value)
      WHERE expected_raw.value !~* v_uuid_re
    ) THEN
      RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_OPERATION_EXPECTED_SCOPE_INVALID'
        USING ERRCODE = 'P0001', DETAIL = v_operation_id::text;
    END IF;

    SELECT COALESCE(array_agg(DISTINCT expected_raw.value::uuid ORDER BY expected_raw.value::uuid), ARRAY[]::uuid[])
    INTO v_expected_targeted_timesheet_ids
    FROM jsonb_array_elements_text(v_existing_operation_result->'expected_targeted_timesheet_ids') AS expected_raw(value);

    SELECT
      COUNT(*)::integer,
      COUNT(*) FILTER (WHERE persisted_raw.value !~* v_uuid_re)::integer,
      COALESCE(
        array_agg(DISTINCT persisted_raw.value::uuid ORDER BY persisted_raw.value::uuid)
          FILTER (WHERE persisted_raw.value ~* v_uuid_re),
        ARRAY[]::uuid[]
      )
    INTO
      v_enqueued_raw_count,
      v_enqueued_invalid_count,
      v_enqueued_targeted_timesheet_ids
    FROM jsonb_array_elements_text(
      CASE
        WHEN jsonb_typeof(v_job_payload->'targeted_timesheet_ids') = 'array'
          THEN v_job_payload->'targeted_timesheet_ids'
        ELSE '[]'::jsonb
      END
    ) AS persisted_raw(value);

    v_effective_duplicate_count := GREATEST(
      COALESCE(v_enqueued_raw_count, 0)
        - COALESCE(v_enqueued_invalid_count, 0)
        - COALESCE(array_length(v_enqueued_targeted_timesheet_ids, 1), 0),
      0
    );

    SELECT COALESCE(array_agg(missing_id ORDER BY missing_id), ARRAY[]::uuid[])
    INTO v_missing_targeted_timesheet_ids
    FROM (
      SELECT unnest(v_expected_targeted_timesheet_ids) AS missing_id
      EXCEPT
      SELECT unnest(v_enqueued_targeted_timesheet_ids) AS missing_id
    ) AS missing_scope;

    SELECT COALESCE(array_agg(extra_id ORDER BY extra_id), ARRAY[]::uuid[])
    INTO v_extra_targeted_timesheet_ids
    FROM (
      SELECT unnest(v_enqueued_targeted_timesheet_ids) AS extra_id
      EXCEPT
      SELECT unnest(v_expected_targeted_timesheet_ids) AS extra_id
    ) AS extra_scope;

    IF COALESCE(v_enqueued_invalid_count, 0) <> 0
       OR COALESCE(v_effective_duplicate_count, 0) <> 0
       OR COALESCE(array_length(v_missing_targeted_timesheet_ids, 1), 0) <> 0
       OR COALESCE(array_length(v_extra_targeted_timesheet_ids, 1), 0) <> 0 THEN
      RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_OPERATION_QUEUE_SET_MISMATCH'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'operation_id', v_operation_id::text,
                'job_id', v_existing_operation_job_id::text,
                'expected_targeted_timesheet_ids', to_jsonb(v_expected_targeted_timesheet_ids),
                'persisted_targeted_timesheet_ids', to_jsonb(v_enqueued_targeted_timesheet_ids),
                'missing_targeted_timesheet_ids', to_jsonb(v_missing_targeted_timesheet_ids),
                'extra_targeted_timesheet_ids', to_jsonb(v_extra_targeted_timesheet_ids),
                'effective_duplicate_count', v_effective_duplicate_count,
                'invalid_target_count', v_enqueued_invalid_count
              )::text;
    END IF;

    IF v_existing_operation_source_change_seq > 0 THEN
      SELECT EXISTS (
        SELECT 1
        FROM public.audit_events AS later_audit
        WHERE later_audit.object_type = 'candidate'
          AND later_audit.object_id_text = p_candidate_id::text
          AND later_audit.action = 'PAY_METHOD_CHANGE_PROSPECTIVE_ONLY'
          AND later_audit.id <> v_existing_operation_audit_id
          AND CASE
            WHEN COALESCE(later_audit.after_json#>>'{operation_result,source_change_seq}', '') ~ '^[0-9]{1,18}$'
              THEN (later_audit.after_json#>>'{operation_result,source_change_seq}')::bigint
            WHEN COALESCE(later_audit.after_json->>'source_change_seq', '') ~ '^[0-9]{1,18}$'
              THEN (later_audit.after_json->>'source_change_seq')::bigint
            ELSE 0
          END > v_existing_operation_source_change_seq
      )
      INTO v_existing_operation_superseded;
    END IF;

    v_existing_operation_superseded := COALESCE(v_existing_operation_superseded, false)
      OR v_old_method <> v_existing_operation_target_method;

    v_result := jsonb_strip_nulls(
      COALESCE(v_existing_operation_result, '{}'::jsonb)
      || jsonb_build_object(
        'ok', true,
        'idempotent_replay', true,
        'operation_committed', true,
        'operation_superseded_by_later_change', v_existing_operation_superseded,
        'operation_id', v_operation_id::text,
        'candidate_id', p_candidate_id::text,
        'original_method', v_existing_operation_source_method,
        'new_method', v_existing_operation_target_method,
        'current_method', v_old_method,
        'candidate', v_before_json,
        'job_id', CASE WHEN v_existing_operation_job_id IS NULL THEN NULL ELSE v_existing_operation_job_id::text END,
        'job_status', v_existing_operation_job_status
      )
      || jsonb_build_object(
        'targeted_timesheet_ids', to_jsonb(v_enqueued_targeted_timesheet_ids),
        'expected_targeted_timesheet_ids', to_jsonb(v_expected_targeted_timesheet_ids),
        'persisted_targeted_timesheet_ids', to_jsonb(v_enqueued_targeted_timesheet_ids),
        'missing_targeted_timesheet_ids', to_jsonb(v_missing_targeted_timesheet_ids),
        'extra_targeted_timesheet_ids', to_jsonb(v_extra_targeted_timesheet_ids),
        'effective_duplicate_count', v_effective_duplicate_count,
        'invalid_target_count', v_enqueued_invalid_count,
        'exact_set_equality', true,
        'coverage_basis', COALESCE(
          NULLIF(v_job_payload->>'coverage_basis', ''),
          NULLIF(v_existing_operation_result->>'coverage_basis', ''),
          'CANONICAL_TIMESHEETS_WITH_RETAINED_FINANCE_AUTHORITY'
        ),
        'coverage_complete', true,
        'exact_target_scope', true,
        'authorised_timesheet_ids', CASE
          WHEN jsonb_typeof(v_existing_operation_result->'authorised_timesheet_ids') = 'array'
            THEN v_existing_operation_result->'authorised_timesheet_ids'
          WHEN jsonb_typeof(v_existing_operation_after_json->'authorised_timesheet_ids') = 'array'
            THEN v_existing_operation_after_json->'authorised_timesheet_ids'
          ELSE '[]'::jsonb
        END,
        'active_advance_timesheet_ids', CASE
          WHEN jsonb_typeof(v_existing_operation_result->'active_advance_timesheet_ids') = 'array'
            THEN v_existing_operation_result->'active_advance_timesheet_ids'
          WHEN jsonb_typeof(v_existing_operation_after_json->'active_advance_timesheet_ids') = 'array'
            THEN v_existing_operation_after_json->'active_advance_timesheet_ids'
          ELSE '[]'::jsonb
        END,
        'retained_finance_timesheet_ids', CASE
          WHEN jsonb_typeof(v_existing_operation_result->'retained_finance_timesheet_ids') = 'array'
            THEN v_existing_operation_result->'retained_finance_timesheet_ids'
          WHEN jsonb_typeof(v_existing_operation_after_json->'retained_finance_timesheet_ids') = 'array'
            THEN v_existing_operation_after_json->'retained_finance_timesheet_ids'
          WHEN jsonb_typeof(v_job_payload->'retained_finance_timesheet_ids') = 'array'
            THEN v_job_payload->'retained_finance_timesheet_ids'
          ELSE '[]'::jsonb
        END,
        'authoritative_sessions', CASE
          WHEN jsonb_typeof(v_existing_operation_result->'authoritative_sessions') = 'array'
            THEN v_existing_operation_result->'authoritative_sessions'
          WHEN jsonb_typeof(v_existing_operation_after_json->'authoritative_sessions') = 'array'
            THEN v_existing_operation_after_json->'authoritative_sessions'
          ELSE '[]'::jsonb
        END,
        'replaced_source_session_ids', CASE
          WHEN jsonb_typeof(v_existing_operation_result->'replaced_source_session_ids') = 'array'
            THEN v_existing_operation_result->'replaced_source_session_ids'
          WHEN jsonb_typeof(v_existing_operation_after_json->'replaced_source_session_ids') = 'array'
            THEN v_existing_operation_after_json->'replaced_source_session_ids'
          ELSE '[]'::jsonb
        END,
        'target_details', CASE
          WHEN jsonb_typeof(v_existing_operation_result->'target_details') = 'array'
            THEN v_existing_operation_result->'target_details'
          WHEN jsonb_typeof(v_existing_operation_after_json->'target_details') = 'array'
            THEN v_existing_operation_after_json->'target_details'
          ELSE '[]'::jsonb
        END
      )
      || jsonb_build_object(
        'targeted_timesheet_count', COALESCE(
          CASE
            WHEN COALESCE(v_existing_operation_result->>'targeted_timesheet_count', '') ~ '^[0-9]{1,10}$'
              THEN (v_existing_operation_result->>'targeted_timesheet_count')::integer
            WHEN jsonb_typeof(v_existing_operation_after_json->'targeted_timesheet_ids') = 'array'
              THEN jsonb_array_length(v_existing_operation_after_json->'targeted_timesheet_ids')
          END,
          0
        ),
        'authorised_timesheet_count', COALESCE(
          CASE
            WHEN COALESCE(v_existing_operation_result->>'authorised_timesheet_count', '') ~ '^[0-9]{1,10}$'
              THEN (v_existing_operation_result->>'authorised_timesheet_count')::integer
            WHEN jsonb_typeof(v_existing_operation_after_json->'authorised_timesheet_ids') = 'array'
              THEN jsonb_array_length(v_existing_operation_after_json->'authorised_timesheet_ids')
          END,
          0
        ),
        'active_advance_timesheet_count', COALESCE(
          CASE
            WHEN COALESCE(v_existing_operation_result->>'active_advance_timesheet_count', '') ~ '^[0-9]{1,10}$'
              THEN (v_existing_operation_result->>'active_advance_timesheet_count')::integer
            WHEN jsonb_typeof(v_existing_operation_after_json->'active_advance_timesheet_ids') = 'array'
              THEN jsonb_array_length(v_existing_operation_after_json->'active_advance_timesheet_ids')
          END,
          0
        ),
        'retained_finance_timesheet_count', COALESCE(
          CASE
            WHEN COALESCE(v_existing_operation_result->>'retained_finance_timesheet_count', '') ~ '^[0-9]{1,10}$'
              THEN (v_existing_operation_result->>'retained_finance_timesheet_count')::integer
            WHEN jsonb_typeof(v_existing_operation_after_json->'retained_finance_timesheet_ids') = 'array'
              THEN jsonb_array_length(v_existing_operation_after_json->'retained_finance_timesheet_ids')
            WHEN jsonb_typeof(v_job_payload->'retained_finance_timesheet_ids') = 'array'
              THEN jsonb_array_length(v_job_payload->'retained_finance_timesheet_ids')
          END,
          0
        ),
        'source_target_mismatch_count', COALESCE(
          CASE
            WHEN COALESCE(v_existing_operation_result->>'source_target_mismatch_count', '') ~ '^[0-9]{1,10}$'
              THEN (v_existing_operation_result->>'source_target_mismatch_count')::integer
            WHEN COALESCE(v_existing_operation_after_json->>'source_target_mismatch_count', '') ~ '^[0-9]{1,10}$'
              THEN (v_existing_operation_after_json->>'source_target_mismatch_count')::integer
          END,
          0
        ),
        'source_change_seq', COALESCE(
          CASE
            WHEN COALESCE(v_existing_operation_result->>'source_change_seq', '') ~ '^[0-9]{1,18}$'
              THEN (v_existing_operation_result->>'source_change_seq')::bigint
            WHEN COALESCE(v_existing_operation_after_json->>'source_change_seq', '') ~ '^[0-9]{1,18}$'
              THEN (v_existing_operation_after_json->>'source_change_seq')::bigint
          END,
          0
        ),
        'preview_source_change_seq', COALESCE(
          CASE
            WHEN COALESCE(v_existing_operation_result->>'preview_source_change_seq', '') ~ '^[0-9]{1,18}$'
              THEN (v_existing_operation_result->>'preview_source_change_seq')::bigint
            WHEN COALESCE(v_existing_operation_after_json->>'preview_source_change_seq', '') ~ '^[0-9]{1,18}$'
              THEN (v_existing_operation_after_json->>'preview_source_change_seq')::bigint
          END,
          v_preview_source_change_seq
        )
      )
      || jsonb_build_object(
        'contracts_changed', 0,
        'contract_weeks_changed', 0,
        'timesheets_changed', 0,
        'rates_changed', 0,
        'tsfin_repricing_rows', 0,
        'refresh_accepted', true,
        'refresh_completed', CASE
          WHEN v_existing_operation_superseded IS TRUE THEN false
          WHEN UPPER(BTRIM(COALESCE(v_existing_operation_job_status, ''))) = 'SUCCEEDED' THEN true
          ELSE COALESCE((v_existing_operation_result->>'refresh_completed')::boolean, false)
        END,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
        'policy_x_dirtying_only', true,
        'economic_truth_mutation_allowed', false
      )
    );

    RETURN v_result;
  END IF;

  IF v_old_method = v_new_method THEN
    RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_ALREADY_APPLIED_OR_STALE'
      USING ERRCODE = '40001',
            DETAIL = format('candidate=%s current=%s operation=%s', p_candidate_id, v_old_method, v_operation_id);
  END IF;

  IF v_old_method <> v_expected_old_method THEN
    RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_STALE_EXPECTED_METHOD'
      USING ERRCODE = '40001', DETAIL = format('expected=%s actual=%s', v_expected_old_method, v_old_method);
  END IF;

  IF v_old_method = v_new_method THEN
    RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_METHODS_MUST_DIFFER'
      USING ERRCODE = '22023';
  END IF;

  v_scope_result := public.candidate_pay_method_change_refresh_scope_v1(
    p_candidate_id,
    v_old_method,
    v_new_method
  );

  v_scope_exact := LOWER(BTRIM(COALESCE(v_scope_result->>'exact_scope', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_scope_complete := LOWER(BTRIM(COALESCE(v_scope_result->>'coverage_complete', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');

  IF COALESCE(v_scope_result->>'ok', 'false') <> 'true'
     OR v_scope_exact IS NOT TRUE
     OR v_scope_complete IS NOT TRUE
     OR UPPER(BTRIM(COALESCE(v_scope_result->>'coverage_basis', ''))) <> 'CANONICAL_TIMESHEETS_WITH_RETAINED_FINANCE_AUTHORITY'
     OR jsonb_typeof(v_scope_result->'targeted_timesheet_ids') IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_EXACT_SCOPE_UNAVAILABLE'
      USING ERRCODE = 'P0001', DETAIL = COALESCE(v_scope_result, '{}'::jsonb)::text;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements_text(v_scope_result->'targeted_timesheet_ids') AS raw_target(value)
    WHERE raw_target.value !~* v_uuid_re
  ) THEN
    RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_TARGET_SCOPE_INVALID'
      USING ERRCODE = 'P0001';
  END IF;

  v_current_source_change_seq := COALESCE(
    CASE
      WHEN COALESCE(v_scope_result->>'latest_source_change_seq', '') ~ '^[0-9]{1,18}$'
        THEN (v_scope_result->>'latest_source_change_seq')::bigint
      ELSE 0
    END,
    0
  );

  IF v_preview_source_change_seq <> v_current_source_change_seq THEN
    RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_PREVIEW_STALE'
      USING ERRCODE = '40001', DETAIL = format('preview_seq=%s current_seq=%s', v_preview_source_change_seq, v_current_source_change_seq);
  END IF;

  SELECT COALESCE(array_agg(DISTINCT target_value::uuid ORDER BY target_value::uuid), ARRAY[]::uuid[])
  INTO v_expected_targeted_timesheet_ids
  FROM jsonb_array_elements_text(
    CASE
      WHEN jsonb_typeof(v_scope_result->'targeted_timesheet_ids') = 'array'
        THEN v_scope_result->'targeted_timesheet_ids'
      ELSE '[]'::jsonb
    END
  ) AS target_values(target_value)
  WHERE target_value ~* v_uuid_re;

  IF v_new_method = 'UMBRELLA' THEN
    IF v_destination_patch ? 'account_holder'
       OR v_destination_patch ? 'bank_name'
       OR v_destination_patch ? 'sort_code'
       OR v_destination_patch ? 'account_number' THEN
      RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_PAYE_BANK_FIELDS_NOT_ALLOWED_FOR_UMBRELLA'
        USING ERRCODE = '22023';
    END IF;

    IF v_destination_patch ? 'umbrella_id' THEN
      IF NULLIF(BTRIM(COALESCE(v_destination_patch->>'umbrella_id', '')), '') IS NULL THEN
        v_effective_umbrella_id := NULL::uuid;
      ELSIF v_destination_patch->>'umbrella_id' ~* v_uuid_re THEN
        v_effective_umbrella_id := (v_destination_patch->>'umbrella_id')::uuid;
      ELSE
        RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_UMBRELLA_ID_INVALID'
          USING ERRCODE = '22023';
      END IF;
    END IF;

    v_account_holder := NULL::text;
    v_bank_name := NULL::text;
    v_sort_code := NULL::text;
    v_account_number := NULL::text;

    IF v_effective_umbrella_id IS NULL THEN
      RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_UMBRELLA_REQUIRED'
        USING ERRCODE = '23502';
    END IF;

    PERFORM 1
    FROM public.umbrellas AS umbrella_row
    WHERE umbrella_row.id = v_effective_umbrella_id
      AND umbrella_row.enabled IS TRUE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_UMBRELLA_NOT_FOUND_OR_DISABLED'
        USING ERRCODE = '23503', DETAIL = v_effective_umbrella_id::text;
    END IF;
  ELSE
    IF NULLIF(BTRIM(COALESCE(v_destination_patch->>'umbrella_id', '')), '') IS NOT NULL THEN
      RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_UMBRELLA_ID_NOT_ALLOWED_FOR_PAYE'
        USING ERRCODE = '22023';
    END IF;

    v_effective_umbrella_id := NULL::uuid;

    IF v_destination_patch ? 'account_holder' THEN
      v_account_holder := NULLIF(BTRIM(COALESCE(v_destination_patch->>'account_holder', '')), '');
    END IF;
    IF v_destination_patch ? 'bank_name' THEN
      v_bank_name := NULLIF(BTRIM(COALESCE(v_destination_patch->>'bank_name', '')), '');
    END IF;
    IF v_destination_patch ? 'sort_code' THEN
      v_sort_code := NULLIF(BTRIM(COALESCE(v_destination_patch->>'sort_code', '')), '');
    END IF;
    IF v_destination_patch ? 'account_number' THEN
      v_account_number := NULLIF(BTRIM(COALESCE(v_destination_patch->>'account_number', '')), '');
    END IF;
  END IF;

  PERFORM set_config('cloudtms.candidate_pay_method_change_operation_id', v_operation_id::text, true);
  PERFORM set_config('cloudtms.candidate_pay_method_change_actor_user_id', p_actor_user_id::text, true);
  PERFORM set_config('cloudtms.candidate_pay_method_change_reason', COALESCE(NULLIF(BTRIM(p_reason), ''), 'PAY_METHOD_CHANGE'), true);

  UPDATE public.candidates AS candidate_row
  SET pay_method = v_new_method,
      umbrella_id = v_effective_umbrella_id,
      account_holder = v_account_holder,
      bank_name = v_bank_name,
      sort_code = v_sort_code,
      account_number = v_account_number,
      updated_at = v_now
  WHERE candidate_row.id = p_candidate_id
  RETURNING jsonb_build_object(
    'id', candidate_row.id::text,
    'pay_method', candidate_row.pay_method,
    'umbrella_id', CASE WHEN candidate_row.umbrella_id IS NULL THEN NULL ELSE candidate_row.umbrella_id::text END,
    'account_holder', candidate_row.account_holder,
    'bank_name', candidate_row.bank_name,
    'sort_code', candidate_row.sort_code,
    'account_number', candidate_row.account_number,
    'updated_at', candidate_row.updated_at,
    'rev', candidate_row.rev
  )
  INTO v_after_json;

  SELECT
    job_row.id,
    job_row.status,
    COALESCE(job_row.payload_json, '{}'::jsonb)
  INTO v_job_id, v_job_status, v_job_payload
  FROM public.banking_pay_workbench_jobs AS job_row
  WHERE job_row.candidate_id = p_candidate_id
    AND UPPER(BTRIM(COALESCE(job_row.job_type, ''))) = 'WORKBENCH_CANDIDATE_DIRTY_APPLY'
    AND job_row.payload_json->>'route_change_operation_id' = v_operation_id::text
    AND UPPER(BTRIM(COALESCE(job_row.payload_json->>'route_change_source_method', ''))) = v_old_method
    AND UPPER(BTRIM(COALESCE(job_row.payload_json->>'route_change_target_method', ''))) = v_new_method
  ORDER BY job_row.updated_at_utc DESC, job_row.id DESC
  LIMIT 1;

  IF v_job_id IS NULL THEN
    RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_DURABLE_QUEUE_MISSING'
      USING ERRCODE = 'P0001', DETAIL = v_operation_id::text;
  END IF;

  IF COALESCE(v_job_payload->>'route_change_operation_id', '') <> v_operation_id::text
     OR UPPER(BTRIM(COALESCE(v_job_payload->>'route_change_source_method', ''))) <> v_old_method
     OR UPPER(BTRIM(COALESCE(v_job_payload->>'route_change_target_method', ''))) <> v_new_method
     OR COALESCE(v_job_payload->>'candidate_id', '') <> p_candidate_id::text THEN
    RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_DURABLE_QUEUE_AUTHORITY_MISMATCH'
      USING ERRCODE = 'P0001', DETAIL = v_job_id::text;
  END IF;

  SELECT
    COUNT(*)::integer,
    COUNT(*) FILTER (WHERE target_value !~* v_uuid_re)::integer,
    COALESCE(
      array_agg(DISTINCT target_value::uuid ORDER BY target_value::uuid)
        FILTER (WHERE target_value ~* v_uuid_re),
      ARRAY[]::uuid[]
    )
  INTO
    v_enqueued_raw_count,
    v_enqueued_invalid_count,
    v_enqueued_targeted_timesheet_ids
  FROM jsonb_array_elements_text(
    CASE
      WHEN jsonb_typeof(v_job_payload->'targeted_timesheet_ids') = 'array'
        THEN v_job_payload->'targeted_timesheet_ids'
      ELSE '[]'::jsonb
    END
  ) AS target_values(target_value);

  v_effective_duplicate_count := GREATEST(
    COALESCE(v_enqueued_raw_count, 0)
      - COALESCE(v_enqueued_invalid_count, 0)
      - COALESCE(array_length(v_enqueued_targeted_timesheet_ids, 1), 0),
    0
  );

  SELECT COALESCE(array_agg(missing_id ORDER BY missing_id), ARRAY[]::uuid[])
  INTO v_missing_targeted_timesheet_ids
  FROM (
    SELECT unnest(v_expected_targeted_timesheet_ids) AS missing_id
    EXCEPT
    SELECT unnest(v_enqueued_targeted_timesheet_ids) AS missing_id
  ) AS missing_scope;

  SELECT COALESCE(array_agg(extra_id ORDER BY extra_id), ARRAY[]::uuid[])
  INTO v_extra_targeted_timesheet_ids
  FROM (
    SELECT unnest(v_enqueued_targeted_timesheet_ids) AS extra_id
    EXCEPT
    SELECT unnest(v_expected_targeted_timesheet_ids) AS extra_id
  ) AS extra_scope;

  IF COALESCE(v_enqueued_invalid_count, 0) <> 0
     OR COALESCE(v_effective_duplicate_count, 0) <> 0
     OR COALESCE(array_length(v_missing_targeted_timesheet_ids, 1), 0) <> 0
     OR COALESCE(array_length(v_extra_targeted_timesheet_ids, 1), 0) <> 0
     OR LOWER(BTRIM(COALESCE(v_job_payload->>'exact_target_scope', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
     OR UPPER(BTRIM(COALESCE(v_job_payload->>'coverage_basis', ''))) <> 'CANONICAL_TIMESHEETS_WITH_RETAINED_FINANCE_AUTHORITY'
     OR UPPER(BTRIM(COALESCE(v_job_payload->>'refresh_scope_kind', ''))) <> 'TARGETED_TIMESHEETS' THEN
    RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_QUEUE_SET_MISMATCH'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'expected_targeted_timesheet_ids', to_jsonb(v_expected_targeted_timesheet_ids),
              'persisted_targeted_timesheet_ids', to_jsonb(v_enqueued_targeted_timesheet_ids),
              'missing_targeted_timesheet_ids', to_jsonb(v_missing_targeted_timesheet_ids),
              'extra_targeted_timesheet_ids', to_jsonb(v_extra_targeted_timesheet_ids),
              'effective_duplicate_count', v_effective_duplicate_count,
              'invalid_target_count', v_enqueued_invalid_count,
              'job_id', v_job_id::text
            )::text;
  END IF;

  v_post_scope_result := public.candidate_pay_method_change_refresh_scope_v1(
    p_candidate_id,
    v_old_method,
    v_new_method
  );

  IF COALESCE(v_post_scope_result->>'ok', 'false') <> 'true'
     OR LOWER(BTRIM(COALESCE(v_post_scope_result->>'exact_scope', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
     OR LOWER(BTRIM(COALESCE(v_post_scope_result->>'coverage_complete', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
     OR UPPER(BTRIM(COALESCE(v_post_scope_result->>'coverage_basis', ''))) <> 'CANONICAL_TIMESHEETS_WITH_RETAINED_FINANCE_AUTHORITY'
     OR jsonb_typeof(v_post_scope_result->'targeted_timesheet_ids') IS DISTINCT FROM 'array'
     OR EXISTS (
       SELECT 1
       FROM jsonb_array_elements_text(
         CASE
           WHEN jsonb_typeof(v_post_scope_result->'targeted_timesheet_ids') = 'array'
             THEN v_post_scope_result->'targeted_timesheet_ids'
           ELSE '[]'::jsonb
         END
       ) AS post_target(value)
       WHERE post_target.value !~* v_uuid_re
     ) THEN
    RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_POST_COMMIT_SCOPE_UNAVAILABLE'
      USING ERRCODE = 'P0001', DETAIL = COALESCE(v_post_scope_result, '{}'::jsonb)::text;
  END IF;

  SELECT COALESCE(array_agg(DISTINCT post_target.value::uuid ORDER BY post_target.value::uuid), ARRAY[]::uuid[])
  INTO v_post_targeted_timesheet_ids
  FROM jsonb_array_elements_text(v_post_scope_result->'targeted_timesheet_ids') AS post_target(value);

  IF v_post_targeted_timesheet_ids IS DISTINCT FROM v_expected_targeted_timesheet_ids THEN
    RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_CANONICAL_SCOPE_CHANGED'
      USING ERRCODE = '40001',
            DETAIL = jsonb_build_object(
              'expected_targeted_timesheet_ids', to_jsonb(v_expected_targeted_timesheet_ids),
              'post_update_targeted_timesheet_ids', to_jsonb(v_post_targeted_timesheet_ids)
            )::text;
  END IF;

  v_job_source_change_seq := COALESCE(
    CASE
      WHEN COALESCE(v_job_payload->>'source_change_seq', '') ~ '^[0-9]{1,18}$'
        THEN (v_job_payload->>'source_change_seq')::bigint
      ELSE 0
    END,
    0
  );

  v_result := jsonb_strip_nulls(
    jsonb_build_object(
      'ok', true,
      'idempotent_replay', false,
      'operation_committed', true,
      'operation_superseded_by_later_change', false,
      'operation_id', v_operation_id::text,
      'candidate_id', p_candidate_id::text,
      'original_method', v_old_method,
      'new_method', v_new_method,
      'current_method', v_new_method,
      'candidate', v_after_json,
      'job_id', v_job_id::text,
      'job_status', v_job_status,
      'source_change_seq', v_job_source_change_seq,
      'preview_source_change_seq', v_preview_source_change_seq
    )
    || jsonb_build_object(
      'targeted_timesheet_ids', to_jsonb(v_enqueued_targeted_timesheet_ids),
      'targeted_timesheet_count', COALESCE(array_length(v_enqueued_targeted_timesheet_ids, 1), 0),
      'expected_targeted_timesheet_ids', to_jsonb(v_expected_targeted_timesheet_ids),
      'persisted_targeted_timesheet_ids', to_jsonb(v_enqueued_targeted_timesheet_ids),
      'missing_targeted_timesheet_ids', to_jsonb(v_missing_targeted_timesheet_ids),
      'extra_targeted_timesheet_ids', to_jsonb(v_extra_targeted_timesheet_ids),
      'effective_duplicate_count', v_effective_duplicate_count,
      'invalid_target_count', v_enqueued_invalid_count,
      'exact_set_equality', true,
      'coverage_basis', COALESCE(v_scope_result->>'coverage_basis', 'CANONICAL_TIMESHEETS_WITH_RETAINED_FINANCE_AUTHORITY'),
      'coverage_complete', true,
      'exact_target_scope', true,
      'authorised_timesheet_ids', CASE
        WHEN jsonb_typeof(v_job_payload->'authorised_timesheet_ids') = 'array'
          THEN v_job_payload->'authorised_timesheet_ids'
        ELSE '[]'::jsonb
      END,
      'authorised_timesheet_count', COALESCE(
        CASE
          WHEN COALESCE(v_job_payload->>'authorised_timesheet_count', '') ~ '^[0-9]{1,10}$'
            THEN (v_job_payload->>'authorised_timesheet_count')::integer
        END,
        0
      ),
      'active_advance_timesheet_ids', CASE
        WHEN jsonb_typeof(v_job_payload->'active_advance_timesheet_ids') = 'array'
          THEN v_job_payload->'active_advance_timesheet_ids'
        ELSE '[]'::jsonb
      END,
      'active_advance_timesheet_count', COALESCE(
        CASE
          WHEN COALESCE(v_job_payload->>'active_advance_timesheet_count', '') ~ '^[0-9]{1,10}$'
            THEN (v_job_payload->>'active_advance_timesheet_count')::integer
        END,
        0
      ),
      'retained_finance_timesheet_ids', CASE
        WHEN jsonb_typeof(v_job_payload->'retained_finance_timesheet_ids') = 'array'
          THEN v_job_payload->'retained_finance_timesheet_ids'
        ELSE '[]'::jsonb
      END,
      'retained_finance_timesheet_count', COALESCE(
        CASE
          WHEN COALESCE(v_job_payload->>'retained_finance_timesheet_count', '') ~ '^[0-9]{1,10}$'
            THEN (v_job_payload->>'retained_finance_timesheet_count')::integer
        END,
        0
      ),
      'authoritative_sessions', CASE
        WHEN jsonb_typeof(v_job_payload->'authoritative_sessions') = 'array'
          THEN v_job_payload->'authoritative_sessions'
        ELSE '[]'::jsonb
      END,
      'replaced_source_session_ids', CASE
        WHEN jsonb_typeof(v_job_payload->'replaced_source_session_ids') = 'array'
          THEN v_job_payload->'replaced_source_session_ids'
        ELSE '[]'::jsonb
      END,
      'target_details', CASE
        WHEN jsonb_typeof(v_job_payload->'target_details') = 'array'
          THEN v_job_payload->'target_details'
        ELSE '[]'::jsonb
      END,
      'source_target_mismatch_count', COALESCE(
        CASE
          WHEN COALESCE(v_job_payload->>'source_target_mismatch_count', '') ~ '^[0-9]{1,10}$'
            THEN (v_job_payload->>'source_target_mismatch_count')::integer
        END,
        0
      )
    )
    || jsonb_build_object(
      'contracts_changed', 0,
      'contract_weeks_changed', 0,
      'timesheets_changed', 0,
      'rates_changed', 0,
      'tsfin_repricing_rows', 0,
      'refresh_accepted', true,
      'refresh_completed', UPPER(BTRIM(COALESCE(v_job_status, ''))) = 'SUCCEEDED',
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
      'policy_x_dirtying_only', true,
      'economic_truth_mutation_allowed', false
    )
  );

  v_audit_after_json := v_after_json
    || jsonb_build_object(
      'operation_id', v_operation_id::text,
      'original_method', v_old_method,
      'new_method', v_new_method,
      'job_id', v_job_id::text,
      'job_status', v_job_status,
      'source_change_seq', v_job_source_change_seq,
      'preview_source_change_seq', v_preview_source_change_seq,
      'operation_request', v_operation_request_json
    )
    || jsonb_build_object(
      'targeted_timesheet_ids', v_result->'targeted_timesheet_ids',
      'expected_targeted_timesheet_ids', v_result->'expected_targeted_timesheet_ids',
      'persisted_targeted_timesheet_ids', v_result->'persisted_targeted_timesheet_ids',
      'missing_targeted_timesheet_ids', v_result->'missing_targeted_timesheet_ids',
      'extra_targeted_timesheet_ids', v_result->'extra_targeted_timesheet_ids',
      'effective_duplicate_count', v_result->'effective_duplicate_count',
      'invalid_target_count', v_result->'invalid_target_count',
      'exact_set_equality', v_result->'exact_set_equality',
      'authorised_timesheet_ids', v_result->'authorised_timesheet_ids',
      'active_advance_timesheet_ids', v_result->'active_advance_timesheet_ids',
      'authoritative_sessions', v_result->'authoritative_sessions',
      'replaced_source_session_ids', v_result->'replaced_source_session_ids',
      'target_details', v_result->'target_details',
      'source_target_mismatch_count', v_result->'source_target_mismatch_count'
    )
    || jsonb_build_object(
      'contracts_changed', 0,
      'contract_weeks_changed', 0,
      'timesheets_changed', 0,
      'rates_changed', 0,
      'tsfin_repricing_rows', 0,
      'operation_result', v_result
    );

  PERFORM public._audit_insert(
    'candidate',
    p_candidate_id::text,
    'PAY_METHOD_CHANGE_PROSPECTIVE_ONLY',
    v_before_json,
    v_audit_after_json,
    COALESCE(NULLIF(BTRIM(p_reason), ''), 'PAY_METHOD_CHANGE'),
    p_actor_user_id
  );

  RETURN v_result;
END;
$function$;

-- candidate_pay_method_change_refresh_scope_v1(uuid,text,text)
CREATE OR REPLACE FUNCTION public.candidate_pay_method_change_refresh_scope_v1(p_candidate_id uuid, p_source_method text, p_target_method text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_source_method text := UPPER(BTRIM(COALESCE(p_source_method, '')));
  v_target_method text := UPPER(BTRIM(COALESCE(p_target_method, '')));
  v_candidate_current_method text;
  v_latest_source_change_seq bigint := 0;
  v_authoritative_sessions_json jsonb := '[]'::jsonb;
  v_replaced_source_session_ids_json jsonb := '[]'::jsonb;
  v_represented_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_authorised_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_active_advance_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_retained_finance_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_targeted_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_target_details_json jsonb := '[]'::jsonb;
  v_preview_row_count integer := 0;
  v_source_target_mismatch_count integer := 0;
  v_uuid_re text := '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
  v_route_operation_id_text text := NULLIF(BTRIM(COALESCE(current_setting('cloudtms.candidate_pay_method_change_operation_id', true), '')), '');
  v_route_actor_user_id_text text := NULLIF(BTRIM(COALESCE(current_setting('cloudtms.candidate_pay_method_change_actor_user_id', true), '')), '');
  v_route_reason text := NULLIF(BTRIM(COALESCE(current_setting('cloudtms.candidate_pay_method_change_reason', true), '')), '');
  v_route_operation_id uuid := NULL::uuid;
  v_route_actor_user_id uuid := NULL::uuid;
  v_route_actor_role text := NULL::text;
  v_route_job_id uuid := NULL::uuid;
  v_route_job_status text := NULL::text;
  v_route_job_payload jsonb := '{}'::jsonb;
  v_route_dedupe_key text := NULL::text;
  v_route_job_count integer := 0;
  v_route_existing_raw_count integer := 0;
  v_route_existing_invalid_count integer := 0;
  v_route_existing_duplicate_count integer := 0;
  v_route_existing_targeted_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_now timestamptz := clock_timestamp();
  v_scope_invalidation_result jsonb := '{}'::jsonb;
BEGIN
  IF p_candidate_id IS NULL THEN
    RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_CANDIDATE_REQUIRED'
      USING ERRCODE = '22023';
  END IF;

  IF v_source_method NOT IN ('PAYE', 'UMBRELLA') THEN
    RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_SOURCE_METHOD_INVALID'
      USING ERRCODE = '22023', DETAIL = COALESCE(p_source_method, '');
  END IF;

  IF v_target_method NOT IN ('PAYE', 'UMBRELLA') THEN
    RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_TARGET_METHOD_INVALID'
      USING ERRCODE = '22023', DETAIL = COALESCE(p_target_method, '');
  END IF;

  IF v_source_method = v_target_method THEN
    RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_METHODS_MUST_DIFFER'
      USING ERRCODE = '22023';
  END IF;

  SELECT UPPER(BTRIM(COALESCE(candidate_row.pay_method, '')))
  INTO v_candidate_current_method
  FROM public.candidates AS candidate_row
  WHERE candidate_row.id = p_candidate_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_CANDIDATE_NOT_FOUND'
      USING ERRCODE = 'P0002', DETAIL = p_candidate_id::text;
  END IF;

  -- Preview/plan calls must be bound to the candidate's current committed
  -- source route.  The dedicated apply transaction is the only exception:
  -- its trigger calls this helper after the candidate row has already moved
  -- to the target route and supplies the operation/actor context through
  -- transaction-local settings.
  IF v_route_operation_id_text IS NULL
     AND v_route_actor_user_id_text IS NULL
     AND v_candidate_current_method IS DISTINCT FROM v_source_method THEN
    RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_SOURCE_METHOD_STALE'
      USING ERRCODE = '40001',
            DETAIL = jsonb_build_object(
              'candidate_id', p_candidate_id::text,
              'expected_source_method', v_source_method,
              'current_candidate_method', v_candidate_current_method,
              'target_method', v_target_method,
              'refresh_required', true
            )::text;
  END IF;

  SELECT COALESCE(change_counter.seq, 0)
  INTO v_latest_source_change_seq
  FROM public.app_change_counters AS change_counter
  WHERE change_counter.entity_key = 'pay_candidate:' || p_candidate_id::text;

  v_latest_source_change_seq := COALESCE(v_latest_source_change_seq, 0);

  WITH candidate_open_scope AS (
    SELECT
      workbench_session.id AS session_id,
      workbench_session.actor_user_id,
      workbench_session.pay_date,
      workbench_session.week_ending_cutoff,
      workbench_session.version AS session_version,
      workbench_session.progress_state,
      workbench_session.progress_counter_version,
      workbench_session.updated_at_utc,
      MAX(workbench_session.pay_date) OVER (
        PARTITION BY workbench_session.actor_user_id
      ) AS latest_actor_open_pay_date
    FROM public.banking_pay_workbench_session_scope AS session_scope
    JOIN public.banking_pay_workbench_sessions AS workbench_session
      ON workbench_session.id = session_scope.session_id
    WHERE UPPER(BTRIM(COALESCE(workbench_session.status, ''))) = 'OPEN'
      AND workbench_session.discarded_at_utc IS NULL
      AND workbench_session.replacement_session_id IS NULL
      AND session_scope.candidate_id = p_candidate_id
  ),
  authoritative_sessions AS (
    SELECT DISTINCT
      candidate_scope.session_id,
      candidate_scope.actor_user_id,
      candidate_scope.pay_date,
      candidate_scope.week_ending_cutoff,
      candidate_scope.session_version,
      candidate_scope.progress_state,
      candidate_scope.progress_counter_version,
      candidate_scope.updated_at_utc
    FROM candidate_open_scope AS candidate_scope
    WHERE candidate_scope.pay_date = candidate_scope.latest_actor_open_pay_date
  ),
  retained_case_scope AS (
    SELECT
      finance_case.id AS finance_case_id,
      finance_case.linked_timesheet_id,
      finance_case.status,
      finance_case.outstanding_amount,
      finance_case.updated_at
    FROM public.pay_advances AS finance_case
    WHERE finance_case.candidate_id = p_candidate_id
      AND finance_case.written_off_at_utc IS NULL
      AND (
        finance_case.advance_kind IN (
          'OVERPAYMENT'::public.pay_advance_kind_enum,
          'UNDERPAYMENT'::public.pay_advance_kind_enum
        )
        OR finance_case.case_type IN (
          'OVERPAYMENT'::public.pay_finance_case_type_enum,
          'UNDERPAYMENT'::public.pay_finance_case_type_enum
        )
      )
  ),
  retained_finance_authority_rows AS (
    -- Current open finance authority.
    SELECT DISTINCT
      COALESCE(finance_component.linked_timesheet_id, retained_case.linked_timesheet_id) AS timesheet_id,
      NULLIF(UPPER(BTRIM(COALESCE(finance_component.source_pay_method, ''))), '') AS source_pay_method,
      10::integer AS authority_priority,
      COALESCE(finance_component.updated_at_utc, retained_case.updated_at) AS authority_at_utc,
      'OPEN_FINANCE_CASE_OR_COMPONENT'::text AS authority_source
    FROM retained_case_scope AS retained_case
    LEFT JOIN public.pay_finance_case_components AS finance_component
      ON finance_component.finance_case_id = retained_case.finance_case_id
     AND finance_component.candidate_id = p_candidate_id
    WHERE retained_case.status IN (
        'ACTIVE'::public.pay_advance_status_enum,
        'PAUSED'::public.pay_advance_status_enum
      )
      AND (
        ROUND(COALESCE(retained_case.outstanding_amount, 0), 2) > 0
        OR (
          finance_component.id IS NOT NULL
          AND finance_component.closed_at_utc IS NULL
          AND ROUND(COALESCE(finance_component.remaining_source_amount, 0), 2) > 0
        )
      )
      AND COALESCE(finance_component.linked_timesheet_id, retained_case.linked_timesheet_id) IS NOT NULL

    UNION ALL

    -- Frozen active Draft authority. SETTLED is deliberately excluded here;
    -- settled authority is proven from the frozen item and settlement evidence
    -- in the next branch, so it cannot be counted as both active and settled.
    SELECT DISTINCT
      COALESCE(finance_component.linked_timesheet_id, retained_case.linked_timesheet_id) AS timesheet_id,
      NULLIF(UPPER(BTRIM(COALESCE(
        active_reservation.frozen_source_pay_method,
        finance_component.source_pay_method,
        ''
      ))), '') AS source_pay_method,
      20::integer AS authority_priority,
      COALESCE(active_reservation.committed_at_utc, active_reservation.created_at_utc) AS authority_at_utc,
      'ACTIVE_FINANCE_RESERVATION'::text AS authority_source
    FROM public.pay_advance_reservations AS active_reservation
    JOIN retained_case_scope AS retained_case
      ON retained_case.finance_case_id = active_reservation.finance_case_id
    LEFT JOIN public.pay_finance_case_components AS finance_component
      ON finance_component.id = active_reservation.finance_component_id
     AND finance_component.finance_case_id = retained_case.finance_case_id
     AND finance_component.candidate_id = p_candidate_id
    WHERE UPPER(BTRIM(COALESCE(active_reservation.status, ''))) IN ('RESERVED', 'COMMITTED')
      AND active_reservation.released_at_utc IS NULL
      AND COALESCE(finance_component.linked_timesheet_id, retained_case.linked_timesheet_id) IS NOT NULL

    UNION ALL

    -- Immutable settled movements that still contribute to projected retained
    -- value. Voided/reversed no-money authority is excluded exactly once.
    SELECT DISTINCT
      COALESCE(batch_item.timesheet_id, finance_component.linked_timesheet_id, retained_case.linked_timesheet_id) AS timesheet_id,
      NULLIF(UPPER(BTRIM(COALESCE(
        batch_item.frozen_source_pay_method,
        finance_component.source_pay_method,
        batch_item.pay_channel,
        ''
      ))), '') AS source_pay_method,
      30::integer AS authority_priority,
      COALESCE(bank_transfer.completed_at_utc, batch_candidate.settled_at_utc, batch_item.created_at) AS authority_at_utc,
      'ACTIVE_SETTLED_FINANCE_MOVEMENT'::text AS authority_source
    FROM public.pay_batch_items AS batch_item
    JOIN public.pay_batch_candidates AS batch_candidate
      ON batch_candidate.id = batch_item.pay_batch_candidate_id
     AND batch_candidate.candidate_id = p_candidate_id
    JOIN retained_case_scope AS retained_case
      ON retained_case.finance_case_id = batch_item.finance_case_id
    LEFT JOIN public.pay_finance_case_components AS finance_component
      ON finance_component.id = batch_item.finance_component_id
     AND finance_component.finance_case_id = retained_case.finance_case_id
     AND finance_component.candidate_id = p_candidate_id
    LEFT JOIN public.pay_bank_transfers AS bank_transfer
      ON bank_transfer.id = batch_item.pay_bank_transfer_id
    WHERE batch_item.is_voided IS NOT TRUE
      AND UPPER(BTRIM(COALESCE(batch_item.item_type, ''))) IN ('OVERPAYMENT_RECOVERY', 'UNDERPAYMENT_PAYMENT')
      AND (
        UPPER(BTRIM(COALESCE(batch_candidate.settlement_status, ''))) = 'SETTLED'
        OR batch_candidate.settled_at_utc IS NOT NULL
        OR UPPER(BTRIM(COALESCE(bank_transfer.status, ''))) = 'COMPLETED'
        OR bank_transfer.completed_at_utc IS NOT NULL
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.pay_payment_correction_items AS applied_reversal
        WHERE applied_reversal.pay_batch_item_id = batch_item.id
          AND applied_reversal.status = 'APPLIED'
          AND applied_reversal.correction_item_kind IN ('PRE_BANK_CANCEL', 'NO_MONEY_UNWIND', 'SETTLED_REVERSAL')
      )
      AND COALESCE(batch_item.timesheet_id, finance_component.linked_timesheet_id, retained_case.linked_timesheet_id) IS NOT NULL

    UNION ALL

    -- Applied corrections are retained only where they are one of the exact
    -- authority-changing correction kinds and remain linked to this finance
    -- lineage. Generic historic events do not broaden route-change scope.
    SELECT DISTINCT
      COALESCE(correction_item.timesheet_id, finance_component.linked_timesheet_id, retained_case.linked_timesheet_id) AS timesheet_id,
      NULLIF(UPPER(BTRIM(COALESCE(finance_component.source_pay_method, ''))), '') AS source_pay_method,
      40::integer AS authority_priority,
      COALESCE(correction_item.applied_at_utc, correction_item.created_at_utc) AS authority_at_utc,
      'APPLIED_FINANCE_CORRECTION'::text AS authority_source
    FROM public.pay_payment_correction_items AS correction_item
    JOIN retained_case_scope AS retained_case
      ON retained_case.finance_case_id = correction_item.finance_case_id
    LEFT JOIN public.pay_finance_case_components AS finance_component
      ON finance_component.id = correction_item.finance_component_id
     AND finance_component.finance_case_id = retained_case.finance_case_id
     AND finance_component.candidate_id = p_candidate_id
    WHERE correction_item.candidate_id = p_candidate_id
      AND correction_item.status = 'APPLIED'
      AND correction_item.correction_item_kind IN ('PRE_BANK_CANCEL', 'NO_MONEY_UNWIND', 'SETTLED_REVERSAL')
      AND COALESCE(correction_item.timesheet_id, finance_component.linked_timesheet_id, retained_case.linked_timesheet_id) IS NOT NULL
  ),
  canonical_seed_ids AS (
    SELECT COALESCE(
      array_agg(DISTINCT seed.timesheet_id ORDER BY seed.timesheet_id),
      ARRAY[]::uuid[]
    ) AS timesheet_ids
    FROM (
      -- Ordinary pay-method invalidation begins from bounded active economic
      -- state.  It never rediscovers the candidate's lifetime timesheet set.
      SELECT scope_state.timesheet_id
      FROM private.banking_pay_workbench_timesheet_scope_state AS scope_state
      WHERE scope_state.candidate_id=p_candidate_id
        AND scope_state.economic_state IN ('DIRTY','LIVE')

      UNION

      SELECT source_owner.timesheet_id
      FROM public.banking_pay_workbench_candidate_source_lines AS source_owner
      WHERE source_owner.candidate_id=p_candidate_id
        AND source_owner.status IN ('CURRENT','DIRTY')
        AND source_owner.timesheet_id IS NOT NULL

      UNION

      SELECT payment_override.timesheet_id
      FROM public.timesheet_payment_overrides AS payment_override
      WHERE payment_override.candidate_id = p_candidate_id
        AND UPPER(BTRIM(COALESCE(payment_override.override_type, ''))) = 'ADVANCE_THIS_PAYMENT'
        AND payment_override.cleared_at_utc IS NULL
        AND payment_override.consumed_at_utc IS NULL
        AND payment_override.consumed_by_pay_batch_id IS NULL
        AND payment_override.timesheet_id IS NOT NULL

      UNION

      SELECT retained_authority.timesheet_id
      FROM retained_finance_authority_rows AS retained_authority
      WHERE retained_authority.timesheet_id IS NOT NULL
    ) AS seed
  ),
  rotation_scope AS (
    SELECT
      rotation_row.requested_timesheet_id,
      rotation_row.booking_id,
      rotation_row.canonical_timesheet_id,
      rotation_row.family_timesheet_id,
      rotation_row.family_is_current,
      rotation_row.family_version,
      rotation_row.requested_is_canonical
    FROM public._pay_timesheet_rotation_scope(
      COALESCE((SELECT canonical_seed_ids.timesheet_ids FROM canonical_seed_ids), ARRAY[]::uuid[])
    ) AS rotation_row
  ),
  canonical_ids AS (
    SELECT DISTINCT
      COALESCE(rotation_row.canonical_timesheet_id, seed_id.timesheet_id) AS timesheet_id
    FROM unnest(
      COALESCE((SELECT canonical_seed_ids.timesheet_ids FROM canonical_seed_ids), ARRAY[]::uuid[])
    ) AS seed_id(timesheet_id)
    LEFT JOIN rotation_scope AS rotation_row
      ON rotation_row.requested_timesheet_id = seed_id.timesheet_id
    WHERE COALESCE(rotation_row.canonical_timesheet_id, seed_id.timesheet_id) IS NOT NULL
  ),
  canonical_qualification AS (
    SELECT
      canonical_id.timesheet_id,
      (
        current_timesheet.archived_at_utc IS NULL
        AND current_timesheet.revoked_at IS NULL
        AND current_timesheet.is_current IS TRUE
        AND current_timesheet.authorised_at_server IS NOT NULL
      ) AS is_authorised,
      EXISTS (
        SELECT 1
        FROM public.timesheet_payment_overrides AS payment_override
        WHERE payment_override.candidate_id = p_candidate_id
          AND UPPER(BTRIM(COALESCE(payment_override.override_type, ''))) = 'ADVANCE_THIS_PAYMENT'
          AND payment_override.cleared_at_utc IS NULL
          AND payment_override.consumed_at_utc IS NULL
          AND payment_override.consumed_by_pay_batch_id IS NULL
          AND (
            payment_override.timesheet_id = canonical_id.timesheet_id
            OR payment_override.timesheet_id IN (
              SELECT family_row.family_timesheet_id
              FROM rotation_scope AS family_row
              WHERE family_row.canonical_timesheet_id = canonical_id.timesheet_id
            )
          )
      ) AS has_active_advance,
      EXISTS (
        SELECT 1
        FROM retained_finance_authority_rows AS retained_authority
        WHERE retained_authority.timesheet_id = canonical_id.timesheet_id
           OR retained_authority.timesheet_id IN (
             SELECT family_row.family_timesheet_id
             FROM rotation_scope AS family_row
             WHERE family_row.canonical_timesheet_id = canonical_id.timesheet_id
           )
      ) AS has_retained_finance_authority,
      UPPER(BTRIM(COALESCE(
        current_financial.pay_method,
        retained_finance_authority.source_pay_method,
        current_contract.pay_method_snapshot,
        ''
      ))) AS source_pay_method
    FROM canonical_ids AS canonical_id
    LEFT JOIN public.timesheets AS current_timesheet
      ON current_timesheet.timesheet_id = canonical_id.timesheet_id
     AND current_timesheet.is_current IS TRUE
    LEFT JOIN LATERAL (
      SELECT financial_row.pay_method
      FROM public.timesheets_financials AS financial_row
      WHERE financial_row.timesheet_id = canonical_id.timesheet_id
        AND financial_row.is_current IS TRUE
        AND financial_row.candidate_id = p_candidate_id
      ORDER BY financial_row.timesheet_version DESC, financial_row.id DESC
      LIMIT 1
    ) AS current_financial ON TRUE
    LEFT JOIN LATERAL (
      SELECT retained_authority.source_pay_method
      FROM retained_finance_authority_rows AS retained_authority
      WHERE (
          retained_authority.timesheet_id = canonical_id.timesheet_id
          OR retained_authority.timesheet_id IN (
            SELECT family_row.family_timesheet_id
            FROM rotation_scope AS family_row
            WHERE family_row.canonical_timesheet_id = canonical_id.timesheet_id
          )
        )
        AND retained_authority.source_pay_method IN ('PAYE', 'UMBRELLA')
      ORDER BY
        retained_authority.authority_priority,
        retained_authority.authority_at_utc DESC NULLS LAST,
        retained_authority.source_pay_method
      LIMIT 1
    ) AS retained_finance_authority ON TRUE
    LEFT JOIN public.contracts AS current_contract
      ON current_contract.id = current_timesheet.contract_id
     AND current_contract.candidate_id = p_candidate_id
  ),
  qualifying_timesheets AS (
    SELECT
      qualification.timesheet_id,
      qualification.is_authorised,
      qualification.has_active_advance,
      qualification.has_retained_finance_authority,
      qualification.source_pay_method
    FROM canonical_qualification AS qualification
    WHERE qualification.is_authorised IS TRUE
       OR qualification.has_active_advance IS TRUE
       OR qualification.has_retained_finance_authority IS TRUE
  ),
  current_preview_rows AS (
    SELECT DISTINCT
      authoritative_session.session_id,
      authoritative_session.session_version,
      preview_row.id AS preview_row_id,
      preview_row.timesheet_id AS requested_timesheet_id,
      COALESCE(current_preview_timesheet.timesheet_id, preview_row.timesheet_id) AS canonical_timesheet_id
    FROM authoritative_sessions AS authoritative_session
    JOIN public.banking_pay_workbench_preview_rows AS preview_row
      ON preview_row.session_id = authoritative_session.session_id
     AND preview_row.candidate_id = p_candidate_id
     AND preview_row.session_version = authoritative_session.session_version
    LEFT JOIN public.timesheets AS requested_preview_timesheet
      ON requested_preview_timesheet.timesheet_id = preview_row.timesheet_id
    LEFT JOIN LATERAL (
      SELECT candidate_current_timesheet.timesheet_id
      FROM public.timesheets AS candidate_current_timesheet
      WHERE requested_preview_timesheet.booking_id IS NOT NULL
        AND candidate_current_timesheet.booking_id = requested_preview_timesheet.booking_id
        AND candidate_current_timesheet.is_current IS TRUE
      ORDER BY candidate_current_timesheet.version DESC NULLS LAST,
               candidate_current_timesheet.updated_at DESC NULLS LAST,
               candidate_current_timesheet.created_at DESC NULLS LAST,
               candidate_current_timesheet.timesheet_id DESC
      LIMIT 1
    ) AS current_preview_timesheet ON TRUE
    WHERE preview_row.timesheet_id IS NOT NULL
  ),
  represented_ids AS (
    SELECT COALESCE(
      array_agg(DISTINCT preview_row.canonical_timesheet_id ORDER BY preview_row.canonical_timesheet_id),
      ARRAY[]::uuid[]
    ) AS timesheet_ids
    FROM current_preview_rows AS preview_row
    WHERE preview_row.canonical_timesheet_id IS NOT NULL
  ),
  session_rollup AS (
    SELECT
      authoritative_session.session_id,
      authoritative_session.actor_user_id,
      authoritative_session.pay_date,
      authoritative_session.week_ending_cutoff,
      authoritative_session.session_version,
      authoritative_session.progress_state,
      authoritative_session.progress_counter_version,
      authoritative_session.updated_at_utc,
      COUNT(DISTINCT current_preview.preview_row_id)::integer AS preview_row_count,
      COALESCE(
        array_agg(DISTINCT current_preview.canonical_timesheet_id ORDER BY current_preview.canonical_timesheet_id)
          FILTER (WHERE current_preview.canonical_timesheet_id IS NOT NULL),
        ARRAY[]::uuid[]
      ) AS represented_timesheet_ids,
      COALESCE(
        (SELECT array_agg(qualifying.timesheet_id ORDER BY qualifying.timesheet_id) FROM qualifying_timesheets AS qualifying),
        ARRAY[]::uuid[]
      ) AS qualifying_timesheet_ids
    FROM authoritative_sessions AS authoritative_session
    LEFT JOIN current_preview_rows AS current_preview
      ON current_preview.session_id = authoritative_session.session_id
     AND current_preview.session_version = authoritative_session.session_version
    GROUP BY
      authoritative_session.session_id,
      authoritative_session.actor_user_id,
      authoritative_session.pay_date,
      authoritative_session.week_ending_cutoff,
      authoritative_session.session_version,
      authoritative_session.progress_state,
      authoritative_session.progress_counter_version,
      authoritative_session.updated_at_utc
  )
  SELECT
    COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'session_id', session_row.session_id::text,
          'actor_user_id', session_row.actor_user_id::text,
          'pay_date', session_row.pay_date::text,
          'week_ending_cutoff', session_row.week_ending_cutoff::text,
          'session_version', session_row.session_version,
          'progress_state', session_row.progress_state,
          'progress_counter_version', session_row.progress_counter_version,
          'preview_row_count', session_row.preview_row_count,
          'represented_timesheet_ids', to_jsonb(session_row.represented_timesheet_ids),
          'qualifying_timesheet_ids', to_jsonb(session_row.qualifying_timesheet_ids),
          'updated_at_utc', session_row.updated_at_utc::text
        )
        ORDER BY session_row.updated_at_utc DESC, session_row.session_id
      )
      FROM session_rollup AS session_row
    ), '[]'::jsonb),
    COALESCE((SELECT COUNT(*)::integer FROM current_preview_rows), 0),
    COALESCE((SELECT represented_ids.timesheet_ids FROM represented_ids), ARRAY[]::uuid[]),
    COALESCE((
      SELECT array_agg(qualification.timesheet_id ORDER BY qualification.timesheet_id)
      FROM canonical_qualification AS qualification
      WHERE qualification.is_authorised IS TRUE
    ), ARRAY[]::uuid[]),
    COALESCE((
      SELECT array_agg(qualification.timesheet_id ORDER BY qualification.timesheet_id)
      FROM canonical_qualification AS qualification
      WHERE qualification.has_active_advance IS TRUE
    ), ARRAY[]::uuid[]),
    COALESCE((
      SELECT array_agg(qualification.timesheet_id ORDER BY qualification.timesheet_id)
      FROM canonical_qualification AS qualification
      WHERE qualification.has_retained_finance_authority IS TRUE
    ), ARRAY[]::uuid[]),
    COALESCE((
      SELECT array_agg(qualifying.timesheet_id ORDER BY qualifying.timesheet_id)
      FROM qualifying_timesheets AS qualifying
    ), ARRAY[]::uuid[]),
    COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'timesheet_id', qualifying.timesheet_id::text,
          'is_authorised', qualifying.is_authorised,
          'has_active_advance', qualifying.has_active_advance,
          'has_retained_finance_authority', qualifying.has_retained_finance_authority,
          'source_pay_method', NULLIF(qualifying.source_pay_method, ''),
          'target_pay_method', v_target_method,
          'source_target_mismatch', (
            qualifying.source_pay_method IN ('PAYE', 'UMBRELLA')
            AND qualifying.source_pay_method <> v_target_method
          )
        )
        ORDER BY qualifying.timesheet_id
      )
      FROM qualifying_timesheets AS qualifying
    ), '[]'::jsonb),
    COALESCE((
      SELECT COUNT(*)::integer
      FROM qualifying_timesheets AS qualifying
      WHERE qualifying.source_pay_method IN ('PAYE', 'UMBRELLA')
        AND qualifying.source_pay_method <> v_target_method
    ), 0)
  INTO
    v_authoritative_sessions_json,
    v_preview_row_count,
    v_represented_timesheet_ids,
    v_authorised_timesheet_ids,
    v_active_advance_timesheet_ids,
    v_retained_finance_timesheet_ids,
    v_targeted_timesheet_ids,
    v_target_details_json,
    v_source_target_mismatch_count;

  v_scope_invalidation_result:=private.pay_workbench_scope_invalidate_v1(
    CASE WHEN cardinality(v_targeted_timesheet_ids)=0 THEN ARRAY[p_candidate_id]
      ELSE array_fill(p_candidate_id,ARRAY[cardinality(v_targeted_timesheet_ids)]) END,
    CASE WHEN cardinality(v_targeted_timesheet_ids)=0 THEN ARRAY[NULL::uuid]
      ELSE v_targeted_timesheet_ids END,
    'CANDIDATE_PAY_METHOD_CHANGED',NULL,
    jsonb_build_object('source_pay_method',v_source_method,'target_pay_method',v_target_method)
  );

  WITH authoritative_session_ids AS (
    SELECT (session_value->>'session_id')::uuid AS session_id
    FROM jsonb_array_elements(v_authoritative_sessions_json) AS session_values(session_value)
    WHERE COALESCE(session_value->>'session_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  )
  SELECT COALESCE(
    jsonb_agg(source_session.id::text ORDER BY source_session.updated_at_utc DESC, source_session.id),
    '[]'::jsonb
  )
  INTO v_replaced_source_session_ids_json
  FROM public.banking_pay_workbench_sessions AS source_session
  WHERE source_session.replacement_session_id IN (
    SELECT authoritative_session.session_id
    FROM authoritative_session_ids AS authoritative_session
  )
    AND (
      EXISTS (
        SELECT 1
        FROM public.banking_pay_workbench_session_scope AS source_scope
        WHERE source_scope.session_id = source_session.id
          AND source_scope.candidate_id = p_candidate_id
      )
      OR EXISTS (
        SELECT 1
        FROM public.banking_pay_workbench_preview_rows AS source_preview
        WHERE source_preview.session_id = source_session.id
          AND source_preview.candidate_id = p_candidate_id
      )
    );

  IF v_route_operation_id_text IS NOT NULL OR v_route_actor_user_id_text IS NOT NULL THEN
    IF v_route_operation_id_text IS NULL OR v_route_operation_id_text !~* v_uuid_re THEN
      RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_OPERATION_CONTEXT_REQUIRED'
        USING ERRCODE = '22023';
    END IF;

    IF v_route_actor_user_id_text IS NULL OR v_route_actor_user_id_text !~* v_uuid_re THEN
      RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_ACTOR_CONTEXT_REQUIRED'
        USING ERRCODE = '22023';
    END IF;

    v_route_operation_id := v_route_operation_id_text::uuid;
    v_route_actor_user_id := v_route_actor_user_id_text::uuid;

    SELECT LOWER(BTRIM(COALESCE(actor_row.role, '')))
    INTO v_route_actor_role
    FROM public.tms_users AS actor_row
    WHERE actor_row.id = v_route_actor_user_id
      AND actor_row.is_active IS TRUE;

    IF NOT FOUND OR v_route_actor_role <> 'admin' THEN
      RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_ADMIN_REQUIRED'
        USING ERRCODE = '42501', DETAIL = v_route_actor_user_id::text;
    END IF;

    IF v_candidate_current_method IS DISTINCT FROM v_target_method THEN
      RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_TARGET_NOT_COMMITTED'
        USING ERRCODE = '40001',
              DETAIL = jsonb_build_object(
                'candidate_id', p_candidate_id::text,
                'candidate_current_method', v_candidate_current_method,
                'expected_target_method', v_target_method,
                'operation_id', v_route_operation_id::text
              )::text;
    END IF;

    v_route_dedupe_key := 'CANDIDATE_PAY_METHOD_CHANGE:' || p_candidate_id::text || ':' || v_route_operation_id::text;
    PERFORM pg_advisory_xact_lock(hashtext('candidate_pay_method_change_job:' || v_route_operation_id::text));

    SELECT COUNT(*)::integer
    INTO v_route_job_count
    FROM public.banking_pay_workbench_jobs AS existing_job
    WHERE existing_job.dedupe_key = v_route_dedupe_key;

    IF v_route_job_count > 1 THEN
      RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_DURABLE_QUEUE_DUPLICATED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'candidate_id', p_candidate_id::text,
                'operation_id', v_route_operation_id::text,
                'dedupe_key', v_route_dedupe_key,
                'job_count', v_route_job_count
              )::text;
    END IF;

    SELECT
      existing_job.id,
      existing_job.status,
      COALESCE(existing_job.payload_json, '{}'::jsonb)
    INTO
      v_route_job_id,
      v_route_job_status,
      v_route_job_payload
    FROM public.banking_pay_workbench_jobs AS existing_job
    WHERE existing_job.dedupe_key = v_route_dedupe_key
    ORDER BY existing_job.updated_at_utc DESC, existing_job.id DESC
    LIMIT 1
    FOR UPDATE;

    IF v_route_job_id IS NOT NULL THEN
      IF COALESCE(v_route_job_payload->>'candidate_id', '') <> p_candidate_id::text
         OR COALESCE(v_route_job_payload->>'route_change_operation_id', '') <> v_route_operation_id::text
         OR UPPER(BTRIM(COALESCE(v_route_job_payload->>'route_change_source_method', ''))) <> v_source_method
         OR UPPER(BTRIM(COALESCE(v_route_job_payload->>'route_change_target_method', ''))) <> v_target_method THEN
        RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_DURABLE_QUEUE_AUTHORITY_MISMATCH'
          USING ERRCODE = 'P0001', DETAIL = v_route_job_id::text;
      END IF;

      SELECT
        COUNT(*)::integer,
        COUNT(*) FILTER (WHERE raw_target.value !~* v_uuid_re)::integer,
        COALESCE(
          array_agg(DISTINCT raw_target.value::uuid ORDER BY raw_target.value::uuid)
            FILTER (WHERE raw_target.value ~* v_uuid_re),
          ARRAY[]::uuid[]
        )
      INTO
        v_route_existing_raw_count,
        v_route_existing_invalid_count,
        v_route_existing_targeted_timesheet_ids
      FROM jsonb_array_elements_text(
        CASE
          WHEN jsonb_typeof(v_route_job_payload->'targeted_timesheet_ids') = 'array'
            THEN v_route_job_payload->'targeted_timesheet_ids'
          ELSE '[]'::jsonb
        END
      ) AS raw_target(value);

      v_route_existing_duplicate_count := GREATEST(
        COALESCE(v_route_existing_raw_count, 0)
          - COALESCE(v_route_existing_invalid_count, 0)
          - COALESCE(array_length(v_route_existing_targeted_timesheet_ids, 1), 0),
        0
      );

      IF COALESCE(v_route_existing_invalid_count, 0) <> 0
         OR COALESCE(v_route_existing_duplicate_count, 0) <> 0
         OR v_route_existing_targeted_timesheet_ids IS DISTINCT FROM v_targeted_timesheet_ids
         OR LOWER(BTRIM(COALESCE(v_route_job_payload->>'exact_target_scope', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
         OR UPPER(BTRIM(COALESCE(v_route_job_payload->>'refresh_scope_kind', ''))) <> 'TARGETED_TIMESHEETS' THEN
        RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_DURABLE_QUEUE_SET_MISMATCH'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'job_id', v_route_job_id::text,
                  'expected_targeted_timesheet_ids', to_jsonb(v_targeted_timesheet_ids),
                  'persisted_targeted_timesheet_ids', to_jsonb(v_route_existing_targeted_timesheet_ids),
                  'invalid_target_count', v_route_existing_invalid_count,
                  'effective_duplicate_count', v_route_existing_duplicate_count
                )::text;
      END IF;

      v_latest_source_change_seq := COALESCE(
        CASE
          WHEN COALESCE(v_route_job_payload->>'source_change_seq', '') ~ '^[0-9]{1,18}$'
            THEN (v_route_job_payload->>'source_change_seq')::bigint
          ELSE v_latest_source_change_seq
        END,
        v_latest_source_change_seq,
        0
      );
    ELSE
      PERFORM public._change_bump('pay_candidate:' || p_candidate_id::text);

      SELECT COALESCE(change_counter.seq, 0)
      INTO v_latest_source_change_seq
      FROM public.app_change_counters AS change_counter
      WHERE change_counter.entity_key = 'pay_candidate:' || p_candidate_id::text;

      v_latest_source_change_seq := COALESCE(v_latest_source_change_seq, 0);

      v_route_job_payload := (
        jsonb_build_object(
          'job_type', 'WORKBENCH_CANDIDATE_DIRTY_APPLY',
          'scope_kind', 'CANDIDATE',
          'scope_id', p_candidate_id::text,
          'candidate_id', p_candidate_id::text,
          'reason', COALESCE(v_route_reason, 'PAY_METHOD_CHANGE'),
          'dirty_reason', COALESCE(v_route_reason, 'PAY_METHOD_CHANGE'),
          'candidate_pay_method_change', true,
          'candidate_payment_status_changed', true,
          'pay_method_changed', true,
          'prospective_only', true,
          'old_pay_method', v_source_method,
          'new_pay_method', v_target_method,
          'route_change_operation_id', v_route_operation_id::text,
          'route_change_actor_user_id', v_route_actor_user_id::text,
          'actor_user_id', v_route_actor_user_id::text,
          'route_change_reason', COALESCE(v_route_reason, 'PAY_METHOD_CHANGE'),
          'route_change_source_method', v_source_method,
          'route_change_target_method', v_target_method,
          'latest_source_change_seq', v_latest_source_change_seq,
          'source_change_seq', v_latest_source_change_seq,
          'source_change_sequence', v_latest_source_change_seq
        )
        || jsonb_build_object(
          'refresh_scope_kind', 'TARGETED_TIMESHEETS',
          'targeted_timesheet_ids', to_jsonb(v_targeted_timesheet_ids),
          'targeted_scope_is_empty', COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) = 0,
          'exact_target_scope', true,
          'coverage_basis', 'CANONICAL_TIMESHEETS_WITH_RETAINED_FINANCE_AUTHORITY',
          'coverage_complete', true,
          'authorised_timesheet_ids', to_jsonb(v_authorised_timesheet_ids),
          'authorised_timesheet_count', COALESCE(array_length(v_authorised_timesheet_ids, 1), 0),
          'active_advance_timesheet_ids', to_jsonb(v_active_advance_timesheet_ids),
          'active_advance_timesheet_count', COALESCE(array_length(v_active_advance_timesheet_ids, 1), 0),
          'retained_finance_timesheet_ids', to_jsonb(v_retained_finance_timesheet_ids),
          'retained_finance_timesheet_count', COALESCE(array_length(v_retained_finance_timesheet_ids, 1), 0),
          'authoritative_sessions', v_authoritative_sessions_json,
          'replaced_source_session_ids', v_replaced_source_session_ids_json,
          'target_details', v_target_details_json,
          'source_target_mismatch_count', COALESCE(v_source_target_mismatch_count, 0),
          'source_build_required', COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) > 0,
          'line_work_required', COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) > 0,
          'line_work_only', false,
          'line_work_action', 'SOURCE_BUILD',
          'rerun_required', false
        )
        || jsonb_build_object(
          'contracts_changed', 0,
          'contract_weeks_changed', 0,
          'timesheets_changed', 0,
          'rates_changed', 0,
          'tsfin_repricing_rows', 0,
          'source_records_mutated', false,
          'economic_truth_mutation_allowed', false,
          'refresh_completion_requires_terminal_exact_scope', true,
          'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
          'policy_x_dirtying_only', true
        )
      );

      INSERT INTO public.banking_pay_workbench_jobs (
        job_type,
        status,
        priority,
        run_at_utc,
        attempt_count,
        max_attempts,
        dedupe_key,
        snapshot_run_id,
        session_id,
        candidate_id,
        payload_json,
        created_at_utc,
        updated_at_utc,
        started_at_utc,
        completed_at_utc,
        failed_at_utc,
        last_error_json
      )
      VALUES (
        'WORKBENCH_CANDIDATE_DIRTY_APPLY',
        CASE WHEN COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) = 0 THEN 'SUCCEEDED' ELSE 'QUEUED' END,
        -1000,
        v_now,
        0,
        8,
        v_route_dedupe_key,
        NULL,
        NULL,
        p_candidate_id,
        v_route_job_payload,
        v_now,
        v_now,
        NULL,
        CASE WHEN COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) = 0 THEN v_now ELSE NULL END,
        NULL,
        NULL
      )
      RETURNING id, status, payload_json
      INTO v_route_job_id, v_route_job_status, v_route_job_payload;
    END IF;
  END IF;

  RETURN (
    jsonb_build_object(
      'ok', true,
      'candidate_id', p_candidate_id::text,
      'candidate_current_method', v_candidate_current_method,
      'source_method', v_source_method,
      'target_method', v_target_method,
      'latest_source_change_seq', v_latest_source_change_seq,
      'source_change_seq', v_latest_source_change_seq,
      'durable_job_id', CASE WHEN v_route_job_id IS NULL THEN NULL ELSE v_route_job_id::text END,
      'durable_job_status', v_route_job_status,
      'durable_job_dedupe_key', v_route_dedupe_key,
      'durable_scope_persisted', v_route_job_id IS NOT NULL,
      'coverage_basis', 'CANONICAL_TIMESHEETS_WITH_RETAINED_FINANCE_AUTHORITY',
      'coverage_complete', true,
      'exact_scope', true,
      'authoritative_sessions', v_authoritative_sessions_json,
      'replaced_source_session_ids', v_replaced_source_session_ids_json,
      'represented_timesheet_ids', to_jsonb(v_represented_timesheet_ids),
      'authorised_timesheet_ids', to_jsonb(v_authorised_timesheet_ids),
      'active_advance_timesheet_ids', to_jsonb(v_active_advance_timesheet_ids),
      'retained_finance_timesheet_ids', to_jsonb(v_retained_finance_timesheet_ids)
    )
    || jsonb_build_object(
      'targeted_timesheet_ids', to_jsonb(v_targeted_timesheet_ids),
      'targeted_scope_is_empty', COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) = 0,
      'authoritative_session_count', jsonb_array_length(v_authoritative_sessions_json),
      'preview_row_count', v_preview_row_count,
      'represented_timesheet_count', COALESCE(array_length(v_represented_timesheet_ids, 1), 0),
      'authorised_timesheet_count', COALESCE(array_length(v_authorised_timesheet_ids, 1), 0),
      'active_advance_timesheet_count', COALESCE(array_length(v_active_advance_timesheet_ids, 1), 0),
      'retained_finance_timesheet_count', COALESCE(array_length(v_retained_finance_timesheet_ids, 1), 0),
      'targeted_timesheet_count', COALESCE(array_length(v_targeted_timesheet_ids, 1), 0),
      'source_target_mismatch_count', COALESCE(v_source_target_mismatch_count, 0),
      'target_details', v_target_details_json,
      'contracts_changed', 0,
      'contract_weeks_changed', 0,
      'timesheets_changed', 0,
      'rates_changed', 0,
      'tsfin_repricing_rows', 0,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
      'policy_x_dirtying_only', true
    )
  );
END;
$function$;

-- candidate_picker_search(text,integer,integer,boolean)
CREATE OR REPLACE FUNCTION public.candidate_picker_search(p_query text, p_limit integer DEFAULT 25, p_offset integer DEFAULT 0, p_include_inactive boolean DEFAULT false)
 RETURNS TABLE(id uuid, display_name text, first_name text, last_name text, email text, phone text, tms_ref text, roles jsonb, job_titles_display text, active boolean, match_rank integer)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_query_raw text := coalesce(p_query, '');
  v_query text := btrim(v_query_raw);
  v_query_lc text := lower(btrim(v_query_raw));
  v_limit integer := greatest(1, least(coalesce(p_limit, 25), 100));
  v_offset integer := greatest(coalesce(p_offset, 0), 0);
  v_q_digits text := regexp_replace(coalesce(p_query, ''), '[^0-9]+', '', 'g');
begin
  if v_query = '' or char_length(v_query) < 2 then
    return;
  end if;

  return query
  with base as (
    select
      cs.id,
      cs.display_name,
      cs.first_name,
      cs.last_name,
      cs.email,
      cs.phone,
      cs.tms_ref,
      cs.roles,
      cs.job_titles_display,
      cs.active,
      concat_ws(
        ' ',
        coalesce(cs.first_name, ''),
        coalesce(cs.last_name, '')
      ) as full_name
    from public.candidates_summary as cs
    where
      (p_include_inactive is true or cs.active is true)
      and (
        lower(coalesce(cs.tms_ref, '')) = v_query_lc
        or lower(coalesce(cs.email, '')) = v_query_lc
        or lower(coalesce(cs.display_name, '')) = v_query_lc
        or lower(
          concat_ws(
            ' ',
            coalesce(cs.first_name, ''),
            coalesce(cs.last_name, '')
          )
        ) = v_query_lc
        or lower(coalesce(cs.first_name, '')) = v_query_lc
        or lower(coalesce(cs.last_name, '')) = v_query_lc
        or lower(coalesce(cs.phone, '')) = v_query_lc
        or (
          v_q_digits <> ''
          and regexp_replace(coalesce(cs.phone, ''), '[^0-9]+', '', 'g') = v_q_digits
        )
        or lower(coalesce(cs.tms_ref, '')) like v_query_lc || '%'
        or lower(coalesce(cs.email, '')) like v_query_lc || '%'
        or lower(coalesce(cs.display_name, '')) like v_query_lc || '%'
        or lower(coalesce(cs.first_name, '')) like v_query_lc || '%'
        or lower(coalesce(cs.last_name, '')) like v_query_lc || '%'
        or lower(
          concat_ws(
            ' ',
            coalesce(cs.first_name, ''),
            coalesce(cs.last_name, '')
          )
        ) like v_query_lc || '%'
        or lower(coalesce(cs.phone, '')) like v_query_lc || '%'
        or (
          v_q_digits <> ''
          and regexp_replace(coalesce(cs.phone, ''), '[^0-9]+', '', 'g') like v_q_digits || '%'
        )
        or position(v_query_lc in lower(coalesce(cs.tms_ref, ''))) > 0
        or position(v_query_lc in lower(coalesce(cs.email, ''))) > 0
        or position(v_query_lc in lower(coalesce(cs.display_name, ''))) > 0
        or position(v_query_lc in lower(coalesce(cs.first_name, ''))) > 0
        or position(v_query_lc in lower(coalesce(cs.last_name, ''))) > 0
        or position(
          v_query_lc in lower(
            concat_ws(
              ' ',
              coalesce(cs.first_name, ''),
              coalesce(cs.last_name, '')
            )
          )
        ) > 0
        or position(v_query_lc in lower(coalesce(cs.job_titles_display, ''))) > 0
        or (
          cs.roles is not null
          and position(v_query_lc in lower(cs.roles::text)) > 0
        )
        or position(v_query_lc in lower(coalesce(cs.phone, ''))) > 0
        or (
          v_q_digits <> ''
          and position(v_q_digits in regexp_replace(coalesce(cs.phone, ''), '[^0-9]+', '', 'g')) > 0
        )
      )
  ),
  ranked as (
    select
      b.id,
      b.display_name,
      b.first_name,
      b.last_name,
      b.email,
      b.phone,
      b.tms_ref,
      b.roles,
      b.job_titles_display,
      b.active,
      case
        when lower(coalesce(b.tms_ref, '')) = v_query_lc then 10
        when lower(coalesce(b.email, '')) = v_query_lc then 20
        when lower(coalesce(b.display_name, '')) = v_query_lc then 30
        when lower(coalesce(b.full_name, '')) = v_query_lc then 40
        when lower(coalesce(b.first_name, '')) = v_query_lc then 50
        when lower(coalesce(b.last_name, '')) = v_query_lc then 60
        when lower(coalesce(b.tms_ref, '')) like v_query_lc || '%' then 70
        when lower(coalesce(b.email, '')) like v_query_lc || '%' then 80
        when lower(coalesce(b.display_name, '')) like v_query_lc || '%' then 90
        when lower(coalesce(b.full_name, '')) like v_query_lc || '%' then 100
        when lower(coalesce(b.first_name, '')) like v_query_lc || '%' then 110
        when lower(coalesce(b.last_name, '')) like v_query_lc || '%' then 120
        when position(v_query_lc in lower(coalesce(b.tms_ref, ''))) > 0 then 130
        when position(v_query_lc in lower(coalesce(b.email, ''))) > 0 then 140
        when position(v_query_lc in lower(coalesce(b.display_name, ''))) > 0 then 150
        when position(v_query_lc in lower(coalesce(b.full_name, ''))) > 0 then 160
        when position(v_query_lc in lower(coalesce(b.job_titles_display, ''))) > 0 then 170
        when b.roles is not null and position(v_query_lc in lower(b.roles::text)) > 0 then 180
        when v_q_digits <> '' and regexp_replace(coalesce(b.phone, ''), '[^0-9]+', '', 'g') = v_q_digits then 190
        when v_q_digits <> '' and regexp_replace(coalesce(b.phone, ''), '[^0-9]+', '', 'g') like v_q_digits || '%' then 200
        when v_q_digits <> '' and position(v_q_digits in regexp_replace(coalesce(b.phone, ''), '[^0-9]+', '', 'g')) > 0 then 210
        when position(v_query_lc in lower(coalesce(b.phone, ''))) > 0 then 220
        else 999
      end as match_rank
    from base as b
  )
  select
    r.id,
    r.display_name,
    r.first_name,
    r.last_name,
    r.email,
    r.phone,
    r.tms_ref,
    r.roles,
    r.job_titles_display,
    r.active,
    r.match_rank
  from ranked as r
  order by
    r.match_rank asc,
    lower(coalesce(r.display_name, '')) asc,
    r.id asc
  offset v_offset
  limit v_limit;
end;
$function$;

-- candidate_submission_finalize_atomic_v1(uuid,text,uuid,integer,text,text,timestamp with time zone,jsonb)
CREATE OR REPLACE FUNCTION public.candidate_submission_finalize_atomic_v1(p_session_id uuid, p_environment text, p_workflow_id uuid, p_expected_generation integer, p_expected_row_signature text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text, p_now_utc timestamp with time zone DEFAULT now(), p_daily_materialisation_json jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
declare
  v_environment text;
  v_context jsonb;
  v_candidate_id uuid;
  v_workflow public.candidate_submission_workflows%rowtype;
  v_hours_component public.candidate_submission_components%rowtype;
  v_candidate_signature public.candidate_submission_components%rowtype;
  v_manager_signature public.candidate_submission_components%rowtype;
  v_approved_request public.candidate_approval_requests%rowtype;
  v_paper_hours_return public.candidate_submission_components%rowtype;
  v_contract public.contracts%rowtype;
  v_week public.contract_weeks%rowtype;
  v_anchor_week public.contract_weeks%rowtype;
  v_anchor_timesheet public.timesheets%rowtype;
  v_daily_timesheet public.timesheets%rowtype;
  v_daily_fin public.timesheets_financials%rowtype;
  v_current_policy jsonb;
  v_system_actor uuid;
  v_input jsonb;
  v_electronic_patch jsonb:='{}'::jsonb;
  v_render_input jsonb;
  v_result jsonb;
  v_authorise_result jsonb;
  v_expense_authorise_result jsonb;
  v_response jsonb;
  v_target_timesheet_id uuid;
  v_hours_timesheet_id uuid;
  v_expense_timesheet_id uuid;
  v_evidence_component_ids uuid[];
  v_placement jsonb;
  v_hours_result jsonb;
  v_hours_input jsonb;
  v_expense_input jsonb;
  v_effective_separation boolean:=false;
  v_after_signature text;
  v_auto_requested boolean:=false;
  v_auto_blocked boolean:=false;
  v_auto_blockers jsonb:='[]'::jsonb;
  v_constraint_name text;
  v_target_capabilities jsonb;
  v_route_authority jsonb;
  v_daily_save_input jsonb;
  v_daily_patch jsonb;
  v_daily_signature jsonb;
  v_daily_save_receipt jsonb;
  v_canonical_financials_id uuid;
  v_canonical_financial_sha256 bytea;
  v_service_finalisation jsonb;
  v_is_office_service boolean:=false;
  v_replay_probe_only boolean:=false;
  v_key_replay_probe_only boolean:=false;
  v_mutation_channel text;
  v_mutation_actor_identity text;
  v_mutation_request_hash text;
  v_mutation_receipt jsonb;
  v_prior_receipt_before jsonb;
  v_prior_receipt_after jsonb;
  v_finalisation_identity jsonb;
  v_finalisation_identity_hash text;
  v_completion_before jsonb;
  v_completion_after jsonb;
begin
  v_environment:=private._candidate_assert_environment(p_environment);
  v_service_finalisation:=coalesce(p_daily_materialisation_json->'service_finalisation','{}'::jsonb);
  v_is_office_service:=p_session_id is null
    and private._candidate_office_service_context_valid_v1(
      v_environment,nullif(v_service_finalisation->>'actor_user_id','')::uuid,'RETRY_FINALISATION'
    );
  v_replay_probe_only:=p_session_id is null
    and coalesce((v_service_finalisation->>'replay_probe_only')::boolean,false);
  v_key_replay_probe_only:=p_session_id is null
    and coalesce((v_service_finalisation->>'replay_key_probe_only')::boolean,false);
  if not v_is_office_service then
    perform private._candidate_require_feature_v1(v_environment,'candidate_app_writes');
  end if;
  if nullif(btrim(coalesce(p_idempotency_key,'')),'') is null then raise exception 'CANDIDATE_IDEMPOTENCY_KEY_REQUIRED' using errcode='22023'; end if;

  select * into v_workflow from public.candidate_submission_workflows where id=p_workflow_id for update;
  if not found or v_workflow.environment<>v_environment then
    raise exception 'CANDIDATE_WORKFLOW_NOT_FOUND' using errcode='P0002';
  end if;
  if p_session_id is null then
    v_candidate_id:=v_workflow.candidate_id;
  else
    v_context:=private._candidate_session_context_v1(p_session_id,v_environment,null,p_now_utc,true);
    v_candidate_id:=nullif(v_context->>'selected_candidate_id','')::uuid;
    if v_candidate_id is null then raise exception 'CANDIDATE_SELECTION_REQUIRED' using errcode='28000'; end if;
  end if;
  if v_workflow.candidate_id<>v_candidate_id then
    raise exception 'CANDIDATE_WORKFLOW_NOT_FOUND' using errcode='P0002';
  end if;
  if nullif(btrim(coalesce(v_workflow.idempotency_key,'')),'')=btrim(p_idempotency_key) then
    raise exception 'CANDIDATE_IDEMPOTENCY_CONFLICT'
      using errcode='40001',detail=jsonb_build_object(
        'code','CANDIDATE_IDEMPOTENCY_CONFLICT','workflow_id',v_workflow.id,
        'idempotency_key',btrim(p_idempotency_key),
        'reason','CREATION_KEY_REUSED_FOR_MUTATION'
      )::text;
  end if;
  v_mutation_channel:=case when v_is_office_service then 'OFFICE'
    when p_session_id is null then 'SERVICE' else 'CANDIDATE_CLIENT' end;
  v_mutation_actor_identity:=case when v_is_office_service
    then v_service_finalisation->>'actor_user_id' else coalesce(p_session_id::text,'SERVICE') end;
  if v_key_replay_probe_only then
    select ae.before_json,ae.after_json
    into v_prior_receipt_before,v_prior_receipt_after
    from public.audit_events ae
    where ae.object_type='candidate_workflow_mutation_receipt'
      and ae.object_id_text=v_workflow.id::text
      and ae.correlation_id=btrim(p_idempotency_key)
    order by ae.ts_utc desc,ae.id desc
    limit 1;
    if found then
      if upper(coalesce(v_prior_receipt_before->>'workflow_action',''))<>'RETRY_FINALISATION'
         or upper(coalesce(v_prior_receipt_before->>'channel',''))<>v_mutation_channel
         or coalesce(v_prior_receipt_before->>'actor_identity','')
              is distinct from coalesce(v_mutation_actor_identity,'')
         or nullif(v_prior_receipt_after->>'generation','')::integer
              is distinct from p_expected_generation+1 then
        raise exception 'CANDIDATE_IDEMPOTENCY_CONFLICT'
          using errcode='40001',detail=jsonb_build_object(
            'code','CANDIDATE_IDEMPOTENCY_CONFLICT','workflow_id',v_workflow.id,
            'idempotency_key',btrim(p_idempotency_key)
          )::text;
      end if;
      return coalesce(v_prior_receipt_after,'{}'::jsonb)
        ||jsonb_build_object('idempotent_replay',true);
    end if;
    return jsonb_build_object(
      'ok',true,'replay_found',false,'workflow_id',v_workflow.id,
      'expected_generation',p_expected_generation
    );
  end if;
  -- Candidate-session calls retain their established lifecycle errors before
  -- an immutable approval identity exists. Service replay/finalisation calls
  -- continue through the receipt path below before mutable lifecycle checks.
  if p_session_id is not null then
    if v_workflow.route='PAPER' and v_workflow.state<>'RECEIVED' then
      raise exception 'CANDIDATE_PAPER_RETURN_INCOMPLETE' using errcode='55000';
    elsif v_workflow.route<>'PAPER' and v_workflow.state<>'READY_TO_FINALISE' then
      raise exception 'FINAL_SIGNED_DOCUMENT_NOT_READY' using errcode='55000';
    end if;
  end if;
  v_finalisation_identity:=v_service_finalisation->'finalisation_identity';
  if jsonb_typeof(v_finalisation_identity) is distinct from 'object' then
    if v_workflow.route='PAPER' then
      v_finalisation_identity:=jsonb_build_object(
        'contract_version','CANDIDATE_FINALISATION_IDENTITY_V1',
        'workflow_id',v_workflow.id,'workflow_generation',p_expected_generation,
        'approval_method','PAPER','approval_request_id',null,
        'approval_request_generation',null,'review_manifest_sha256_hex',null,
        'paper_return_manifest_sha256_hex',case when v_workflow.paper_return_manifest_sha256 is null
          then null else encode(v_workflow.paper_return_manifest_sha256,'hex') end
      );
    else
      select approved.* into v_approved_request
      from public.candidate_approval_requests approved
      where approved.workflow_id=v_workflow.id
        and approved.workflow_generation=p_expected_generation
        and approved.state='APPROVED'
        and (nullif(v_service_finalisation->>'approval_request_id','') is null
          or approved.id=(v_service_finalisation->>'approval_request_id')::uuid)
      order by approved.approved_at_utc desc,approved.id desc
      limit 1;
      v_finalisation_identity:=jsonb_build_object(
        'contract_version','CANDIDATE_FINALISATION_IDENTITY_V1',
        'workflow_id',v_workflow.id,'workflow_generation',p_expected_generation,
        'approval_method',coalesce(v_approved_request.method,v_service_finalisation->>'approval_method'),
        'approval_request_id',coalesce(v_approved_request.id,
          nullif(v_service_finalisation->>'approval_request_id','')::uuid),
        'approval_request_generation',v_approved_request.request_generation,
        'review_manifest_sha256_hex',case when v_approved_request.review_manifest_sha256 is null
          then null else encode(v_approved_request.review_manifest_sha256,'hex') end,
        'paper_return_manifest_sha256_hex',null
      );
    end if;
    v_service_finalisation:=v_service_finalisation||jsonb_build_object(
      'contract_version','CANDIDATE_MANAGER_FINALISATION_V1',
      'workflow_generation',p_expected_generation,
      'approval_method',v_finalisation_identity->>'approval_method',
      'approval_request_id',v_finalisation_identity->'approval_request_id',
      'approval_request_generation',v_finalisation_identity->'approval_request_generation',
      'review_manifest_sha256_hex',coalesce(v_finalisation_identity->>'review_manifest_sha256_hex',''),
      'paper_return_manifest_sha256_hex',coalesce(v_finalisation_identity->>'paper_return_manifest_sha256_hex',''),
      'finalisation_identity',v_finalisation_identity
    );
  end if;
  if jsonb_typeof(v_finalisation_identity) is distinct from 'object'
     or coalesce(v_finalisation_identity->>'contract_version','')
          <>'CANDIDATE_FINALISATION_IDENTITY_V1'
     or nullif(v_finalisation_identity->>'workflow_id','')::uuid is distinct from v_workflow.id
     or coalesce((v_finalisation_identity->>'workflow_generation')::integer,0)
          <>p_expected_generation
     or upper(coalesce(v_finalisation_identity->>'approval_method','')) not in ('EMAIL','PHONE','PAPER') then
    raise exception 'CANDIDATE_SERVICE_FINALISATION_INVALID'
      using errcode='28000',detail=jsonb_build_object('stage','IDENTITY')::text;
  end if;
  v_finalisation_identity_hash:=encode(extensions.digest(convert_to(
    v_finalisation_identity::text,'UTF8'
  ),'sha256'),'hex');
  v_mutation_request_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'contract_version','CANDIDATE_FINALISATION_MUTATION_REQUEST_V3',
    'workflow_id',v_workflow.id,
    'action','RETRY_FINALISATION',
    'expected_generation',p_expected_generation,
    'service_finalisation',v_service_finalisation-'replay_probe_only',
    'channel',v_mutation_channel,
    'actor_identity',v_mutation_actor_identity
  )::text,'UTF8'),'sha256'),'hex');
  if v_replay_probe_only then
    if p_session_id is null and (
      coalesce(v_service_finalisation->>'contract_version','')
        <>'CANDIDATE_MANAGER_FINALISATION_V1'
       or coalesce((v_service_finalisation->>'workflow_generation')::integer,0)
         <>p_expected_generation
    ) then
      raise exception 'CANDIDATE_SERVICE_FINALISATION_INVALID'
        using errcode='28000',detail=jsonb_build_object('stage','REPLAY_ENVELOPE')::text;
    end if;
    select ae.before_json,ae.after_json
    into v_prior_receipt_before,v_prior_receipt_after
    from public.audit_events ae
    where ae.object_type='candidate_workflow_mutation_receipt'
      and ae.object_id_text=v_workflow.id::text
      and ae.correlation_id=btrim(p_idempotency_key)
    order by ae.ts_utc desc,ae.id desc
    limit 1;
    if found then
      if v_prior_receipt_before->>'request_sha256' is distinct from v_mutation_request_hash
         or upper(coalesce(v_prior_receipt_before->>'workflow_action',''))<>'RETRY_FINALISATION'
         or upper(coalesce(v_prior_receipt_before->>'channel',''))<>v_mutation_channel
         or coalesce(v_prior_receipt_before->>'actor_identity','')
              is distinct from coalesce(v_mutation_actor_identity,'')
         or nullif(v_prior_receipt_after->>'generation','')::integer
              is distinct from p_expected_generation+1 then
        raise exception 'CANDIDATE_IDEMPOTENCY_CONFLICT'
          using errcode='40001',detail=jsonb_build_object(
            'code','CANDIDATE_IDEMPOTENCY_CONFLICT','workflow_id',v_workflow.id,
            'idempotency_key',btrim(p_idempotency_key)
          )::text;
      end if;
      return coalesce(v_prior_receipt_after,'{}'::jsonb)
        ||jsonb_build_object('idempotent_replay',true);
    end if;
    select ae.before_json,ae.after_json
    into v_completion_before,v_completion_after
    from public.audit_events ae
    where ae.object_type='candidate_workflow_finalisation_completion'
      and ae.object_id_text=v_workflow.id::text
      and ae.correlation_id=p_expected_generation::text||':'||v_finalisation_identity_hash
    order by ae.ts_utc desc,ae.id desc
    limit 1;
    if found then
      if v_completion_before->>'finalisation_identity_sha256'
           is distinct from v_finalisation_identity_hash
         or nullif(v_completion_after->>'generation','')::integer
           is distinct from p_expected_generation+1 then
        raise exception 'CANDIDATE_IDEMPOTENCY_CONFLICT' using errcode='40001';
      end if;
      return coalesce(v_completion_after,'{}'::jsonb)
        ||jsonb_build_object('idempotent_replay',true);
    end if;
    return jsonb_build_object('ok',true,'replay_found',false,'workflow_id',v_workflow.id,
      'expected_generation',p_expected_generation);
  end if;
  v_mutation_receipt:=private._candidate_workflow_mutation_receipt_v1(
    v_workflow.id,p_idempotency_key,v_mutation_request_hash,'RETRY_FINALISATION',
    v_mutation_channel,v_mutation_actor_identity,
    null,p_now_utc
  );
  if coalesce((v_mutation_receipt->>'found')::boolean,false) then
    return coalesce(v_mutation_receipt->'response','{}'::jsonb)||jsonb_build_object('idempotent_replay',true);
  end if;
  select ae.before_json,ae.after_json
  into v_completion_before,v_completion_after
  from public.audit_events ae
  where ae.object_type='candidate_workflow_finalisation_completion'
    and ae.object_id_text=v_workflow.id::text
    and ae.correlation_id=p_expected_generation::text||':'||v_finalisation_identity_hash
  order by ae.ts_utc desc,ae.id desc
  limit 1;
  if found then
    return coalesce(v_completion_after,'{}'::jsonb)
      ||jsonb_build_object('idempotent_replay',true);
  end if;
  if p_session_id is null then
    if coalesce(v_service_finalisation->>'contract_version','')<>'CANDIDATE_MANAGER_FINALISATION_V1'
       or coalesce((v_service_finalisation->>'workflow_generation')::integer,0)<>v_workflow.generation
       or upper(coalesce(v_service_finalisation->>'approval_method',''))<>v_workflow.route then
      raise exception 'CANDIDATE_SERVICE_FINALISATION_INVALID'
        using errcode='28000',detail=jsonb_build_object('stage','SERVICE_ENVELOPE')::text;
    end if;
    if v_workflow.route='PAPER' then
      if nullif(v_service_finalisation->>'approval_request_id','') is not null
         or nullif(v_finalisation_identity->>'approval_request_id','') is not null
         or upper(v_finalisation_identity->>'approval_method')<>'PAPER'
         or lower(coalesce(v_finalisation_identity->>'paper_return_manifest_sha256_hex',''))
              <>encode(v_workflow.paper_return_manifest_sha256,'hex') then
        raise exception 'CANDIDATE_SERVICE_FINALISATION_INVALID'
          using errcode='28000',detail=jsonb_build_object('stage','PAPER_IDENTITY')::text;
      end if;
    else
      select * into v_approved_request
      from public.candidate_approval_requests a
      where a.id=nullif(v_service_finalisation->>'approval_request_id','')::uuid
        and a.workflow_id=v_workflow.id
        and a.workflow_generation=p_expected_generation
        and a.request_generation=coalesce(
          nullif(v_service_finalisation->>'approval_request_generation','')::integer,0
        )
        and a.method=upper(coalesce(v_service_finalisation->>'approval_method',''))
        and a.state='APPROVED'
        and encode(a.review_manifest_sha256,'hex')=lower(coalesce(v_service_finalisation->>'review_manifest_sha256_hex',''))
        and v_finalisation_identity->>'approval_request_id'=a.id::text
        and coalesce((v_finalisation_identity->>'approval_request_generation')::integer,0)=a.request_generation
        and upper(v_finalisation_identity->>'approval_method')=a.method
        and lower(coalesce(v_finalisation_identity->>'review_manifest_sha256_hex',''))
              =encode(a.review_manifest_sha256,'hex')
      for update;
      if not found then
        raise exception 'CANDIDATE_SERVICE_FINALISATION_INVALID'
          using errcode='28000',detail=jsonb_build_object('stage','APPROVAL_IDENTITY')::text;
      end if;
    end if;
  end if;
  if v_workflow.generation<>p_expected_generation then
    raise exception 'WORKFLOW_VERSION_MISMATCH'
      using errcode='40001',detail=jsonb_build_object('code','WORKFLOW_VERSION_MISMATCH','current_generation',v_workflow.generation)::text;
  end if;
  if v_workflow.workflow_kind='DAILY' then
    if v_workflow.scope<>'DAILY' or v_workflow.route not in ('PHONE','EMAIL')
       or v_workflow.contract_week_id is not null or v_workflow.week_ending_date is not null
       or v_workflow.target_timesheet_id is null
       or v_workflow.anchor_timesheet_id is distinct from v_workflow.target_timesheet_id then
      raise exception 'CANDIDATE_DAILY_IDENTITY_INVALID' using errcode='22023';
    end if;
    select * into v_daily_timesheet
    from public.timesheets
    where timesheet_id=v_workflow.target_timesheet_id
      and is_current=true and archived_at_utc is null
      and sheet_scope='DAILY'::public.timesheet_scope_enum
      and nullif(btrim(coalesce(booking_id,'')),'') is not null
    for update;
    if not found then raise exception 'CANDIDATE_DAILY_SHIFT_NOT_FOUND' using errcode='P0002'; end if;
    if not private._candidate_daily_entitled_v1(v_candidate_id) then
      raise exception 'CANDIDATE_DAILY_ENTITLEMENT_REQUIRED' using errcode='55000';
    end if;
    select * into v_daily_fin
    from public.timesheets_financials
    where timesheet_id=v_daily_timesheet.timesheet_id
      and is_current=true and candidate_id=v_candidate_id
    order by computed_at_utc desc nulls last,updated_at desc,id desc
    limit 1
    for update;
    if not found
       or v_workflow.work_date is distinct from private._candidate_daily_work_date_v1(
         coalesce(v_daily_fin.worked_start_iso,v_daily_timesheet.worked_start_iso),
         v_daily_timesheet.scheduled_start_iso,
         v_daily_timesheet.week_ending_date
       ) then
      raise exception 'CANDIDATE_DAILY_SHIFT_IDENTITY_MISMATCH' using errcode='40001';
    end if;
    if v_daily_fin.authorised_at_utc is not null
       or v_daily_fin.paid_at_utc is not null
       or v_daily_fin.locked_by_invoice_id is not null
       or v_daily_timesheet.archived_at_utc is not null then
      raise exception 'CANDIDATE_RECORD_MUTATION_LOCKED' using errcode='55000';
    end if;
    if v_daily_timesheet.contract_id is not null then
      select * into v_contract
      from public.contracts
      where id=v_daily_timesheet.contract_id and candidate_id=v_candidate_id
      for update;
      if not found then raise exception 'CANDIDATE_WORKFLOW_OWNERSHIP_MISMATCH' using errcode='28000'; end if;
    end if;
    if coalesce(v_daily_fin.client_id,v_contract.client_id) is null then
      raise exception 'CANDIDATE_DAILY_CLIENT_NOT_FOUND' using errcode='P0002';
    end if;
    v_current_policy:=private._candidate_policy_resolve_v1(
      coalesce(v_daily_fin.client_id,v_contract.client_id),v_contract.id,v_workflow.work_date
    );
    if (v_workflow.route='PHONE' and not coalesce((v_current_policy->>'allow_daily_manager_authorise_on_phone')::boolean,false))
       or (v_workflow.route='EMAIL' and not coalesce((v_current_policy->>'allow_daily_manager_authorise_by_email')::boolean,false)) then
      raise exception 'CANDIDATE_DAILY_APPROVAL_ROUTE_NOT_ALLOWED' using errcode='55000';
    end if;
  else
    if v_workflow.workflow_kind not in ('CONTRACT_HOURS','CONTRACT_EXPENSE','CONTRACT_COMBINED')
       or v_workflow.scope<>'WEEKLY' or v_workflow.contract_id is null
       or v_workflow.contract_week_id is null or v_workflow.week_ending_date is null then
      raise exception 'CANDIDATE_CONTRACT_WORKFLOW_IDENTITY_INVALID' using errcode='22023';
    end if;
    select * into v_contract
    from public.contracts
    where id=v_workflow.contract_id and candidate_id=v_candidate_id
    for update;
    if not found then raise exception 'CANDIDATE_WORKFLOW_OWNERSHIP_MISMATCH' using errcode='28000'; end if;
    select * into v_week
    from public.contract_weeks
    where id=v_workflow.contract_week_id
      and contract_id=v_contract.id
      and week_ending_date=v_workflow.week_ending_date
    for update;
    if not found then raise exception 'CANDIDATE_CONTRACT_WEEK_IDENTITY_MISMATCH' using errcode='40001'; end if;
    if v_workflow.anchor_timesheet_id is not null then
      select cw.* into v_anchor_week
      from public.contract_weeks cw
      join public.timesheets t on t.timesheet_id=cw.timesheet_id
        and t.is_current=true and t.archived_at_utc is null
      where cw.timesheet_id=v_workflow.anchor_timesheet_id
        and cw.contract_id=v_contract.id
        and cw.week_ending_date=v_workflow.week_ending_date;
      if not found then raise exception 'CANDIDATE_WORKFLOW_ANCHOR_MISMATCH' using errcode='40001'; end if;
    end if;
    if v_workflow.workflow_kind='CONTRACT_EXPENSE' then
      if v_workflow.anchor_timesheet_id is null
         or coalesce((private._candidate_record_capabilities_v1(
           v_workflow.anchor_timesheet_id,v_anchor_week.id,'{}'::jsonb
         )->>'hours_value')::numeric,0)<=0
            and coalesce((private._candidate_record_capabilities_v1(
              v_workflow.anchor_timesheet_id,v_anchor_week.id,'{}'::jsonb
            )->>'additional_units_value')::numeric,0)<=0 then
        raise exception 'NO_POSITIVE_WORKED_TIME' using errcode='55000';
      end if;
    end if;
    if v_workflow.workflow_kind='CONTRACT_EXPENSE' and v_workflow.target_timesheet_id is not null then
      raise exception 'CANDIDATE_EXPENSE_TARGET_SERVER_RESOLVED' using errcode='40001';
    elsif v_workflow.workflow_kind in ('CONTRACT_HOURS','CONTRACT_COMBINED')
       and v_workflow.target_timesheet_id is distinct from v_week.timesheet_id then
      raise exception 'CANDIDATE_WORKFLOW_TARGET_MISMATCH' using errcode='40001';
    end if;
    if v_workflow.workflow_kind in ('CONTRACT_HOURS','CONTRACT_COMBINED')
       and v_week.timesheet_id is not null then
      v_target_capabilities:=private._candidate_record_capabilities_v1(
        v_week.timesheet_id,v_week.id,'{}'::jsonb
      );
      if coalesce((v_target_capabilities->>'candidate_mutation_locked')::boolean,false)
         or coalesce((v_target_capabilities->>'protected')::boolean,false)
         or not coalesce((v_target_capabilities->>'can_edit_hours')::boolean,false) then
        raise exception 'CANDIDATE_RECORD_MUTATION_LOCKED' using errcode='55000';
      end if;
    end if;
    v_route_authority:=private._candidate_route_family_v1(
      case when v_workflow.workflow_kind='CONTRACT_EXPENSE' then v_workflow.anchor_timesheet_id
        else v_week.timesheet_id end,
      case when v_workflow.workflow_kind='CONTRACT_EXPENSE' then v_anchor_week.id else v_week.id end
    );
    if v_route_authority->>'route_family'='MANUAL_NON_QR'
       or (v_route_authority->>'route_family'='IMPORT_AUTHORITATIVE'
         and v_workflow.workflow_kind<>'CONTRACT_EXPENSE')
       or (v_workflow.route='PAPER' and not coalesce((v_route_authority->>'candidate_paper_submission_allowed')::boolean,false))
       or (v_workflow.route<>'PAPER' and v_route_authority->>'route_family'='QR') then
      raise exception 'CANDIDATE_ROUTE_FAMILY_MISMATCH' using errcode='55000',detail=v_route_authority::text;
    end if;
    v_current_policy:=private._candidate_policy_resolve_v1(
      v_contract.client_id,v_contract.id,v_workflow.week_ending_date
    );
    if v_workflow.route='PAPER'
       and not coalesce((v_current_policy->>'paper_submission_enabled')::boolean,false) then
      raise exception 'CANDIDATE_PAPER_ROUTE_NOT_ALLOWED' using errcode='55000';
    end if;
  end if;
  if v_workflow.route='PAPER' then
    if v_workflow.state<>'RECEIVED'
       or v_workflow.paper_return_manifest_sha256 is null
       or private._candidate_sha256_jsonb_v1(v_workflow.paper_return_manifest_json)
          is distinct from v_workflow.paper_return_manifest_sha256
       or exists(
         select 1
         from jsonb_array_elements(v_workflow.paper_return_manifest_json->'pages') expected_page
         where (
           select count(*)
           from public.candidate_submission_components returned_page
           where returned_page.workflow_id=v_workflow.id
             and returned_page.workflow_generation=v_workflow.generation
             and returned_page.component_kind='SIGNED_RETURN'
             and returned_page.paper_return_page_key=expected_page->>'page_key'
             and returned_page.state='IMMUTABLE'
             and returned_page.source_content_sha256 is not null
         )<>1
       )
       or exists(
         select 1
         from public.candidate_submission_components returned_page
         where returned_page.workflow_id=v_workflow.id
           and returned_page.workflow_generation=v_workflow.generation
           and returned_page.component_kind='SIGNED_RETURN'
           and returned_page.state='IMMUTABLE'
           and not exists(
             select 1
             from jsonb_array_elements(v_workflow.paper_return_manifest_json->'pages') expected_page
             where expected_page->>'page_key'=returned_page.paper_return_page_key
           )
       ) then
      raise exception 'CANDIDATE_PAPER_RETURN_INCOMPLETE' using errcode='55000';
    end if;
  else
    if v_workflow.state<>'READY_TO_FINALISE' then
      raise exception 'FINAL_SIGNED_DOCUMENT_NOT_READY' using errcode='55000';
    end if;
    select * into v_approved_request
    from public.candidate_approval_requests a
      where a.workflow_id=v_workflow.id and a.workflow_generation=v_workflow.generation
        and a.state='APPROVED' and a.review_manifest_sha256=v_workflow.review_manifest_sha256
    for update;
    if not found then raise exception 'FINAL_SIGNED_DOCUMENT_NOT_READY' using errcode='55000'; end if;

    if not exists(
      select 1 from public.candidate_submission_components c
      where c.workflow_id=v_workflow.id and c.workflow_generation=v_workflow.generation
        and c.required=true and c.state<>'SUPERSEDED'
    ) or exists(
      select 1 from public.candidate_submission_components c
      where c.workflow_id=v_workflow.id and c.workflow_generation=v_workflow.generation
        and c.required=true and c.state<>'SUPERSEDED'
        and (c.state<>'IMMUTABLE' or c.review_render_state<>'READY'
          or c.final_signed_render_state<>'READY'
          or c.review_render_input_sha256 is distinct from c.final_signed_render_input_sha256)
    ) then
      raise exception 'FINAL_SIGNED_DOCUMENT_NOT_READY' using errcode='55000';
    end if;
    select * into v_hours_component from public.candidate_submission_components c
    where c.workflow_id=v_workflow.id and c.workflow_generation=v_workflow.generation
      and c.component_kind='HOURS_TIMESHEET' and c.required=true and c.state='IMMUTABLE'
    for update;
    if v_workflow.workflow_kind in ('CONTRACT_HOURS','CONTRACT_COMBINED','DAILY') and not found then
      raise exception 'FINAL_SIGNED_DOCUMENT_NOT_READY' using errcode='55000';
    elsif v_workflow.workflow_kind='CONTRACT_EXPENSE' and found then
      raise exception 'CONTRACT_EXPENSE_HOURS_COMPONENT_FORBIDDEN' using errcode='55000';
    end if;
    if v_hours_component.id is not null and v_hours_component.review_render_input_sha256
       is distinct from v_hours_component.final_signed_render_input_sha256 then
      raise exception 'FINAL_RENDER_INPUT_MISMATCH' using errcode='40001';
    end if;
    if v_workflow.workflow_kind<>'CONTRACT_EXPENSE' then
      select * into v_candidate_signature from public.candidate_submission_components c
      where c.id=v_workflow.candidate_signature_component_id and c.workflow_id=v_workflow.id
        and c.document_role='CANDIDATE_SIGNATURE' and c.state='IMMUTABLE' for update;
    elsif v_workflow.candidate_signature_component_id is not null
       or v_workflow.candidate_signature_sha256 is not null then
      raise exception 'CONTRACT_EXPENSE_CANDIDATE_SIGNATURE_FORBIDDEN' using errcode='55000';
    end if;
    select * into v_manager_signature from public.candidate_submission_components c
    where c.id=v_workflow.manager_signature_component_id and c.workflow_id=v_workflow.id
      and c.document_role='MANAGER_SIGNATURE' and c.state='IMMUTABLE'
      and c.approval_request_id=v_approved_request.id for update;
    if (v_workflow.workflow_kind<>'CONTRACT_EXPENSE' and (
          v_candidate_signature.id is null
          or v_candidate_signature.source_content_sha256 is distinct from v_workflow.candidate_signature_sha256))
       or v_manager_signature.id is null
       or v_manager_signature.source_content_sha256 is distinct from v_workflow.manager_signature_sha256
       or v_workflow.manager_approved_at_utc is null then
      raise exception 'ELECTRONIC_SIGNATURE_PAIR_INCOMPLETE' using errcode='55000';
    end if;
    v_render_input:=private._candidate_render_input_v1(v_workflow.id,v_workflow.generation);
    if v_hours_component.id is not null and decode(v_render_input->>'render_input_sha256','hex')
       is distinct from decode(
         private._candidate_component_render_input_v1(
           v_workflow.id,v_workflow.generation,v_hours_component.id
         )->>'workflow_render_input_sha256','hex'
       ) then
      raise exception 'FINAL_RENDER_INPUT_MISMATCH' using errcode='40001';
    end if;
    v_electronic_patch:=jsonb_build_object(
      'submission_mode','ELECTRONIC',
      'auth_name',v_workflow.manager_name,
      'auth_job_title',v_workflow.manager_position,
      'r2_nurse_key',v_candidate_signature.storage_key,
      'r2_auth_key',v_manager_signature.storage_key,
      'img_sha256_nurse',case when v_candidate_signature.source_content_sha256 is null then null
        else encode(v_candidate_signature.source_content_sha256,'hex') end,
      'img_sha256_auth',encode(v_manager_signature.source_content_sha256,'hex'),
      'candidate_workflow_id',v_workflow.id,
      'candidate_workflow_generation',v_workflow.generation,
      'candidate_manager_approved_at_utc',v_workflow.manager_approved_at_utc
    );
  end if;
  if v_workflow.route='PAPER' then
    v_electronic_patch:=jsonb_build_object(
      'submission_mode','MANUAL',
      'r2_nurse_key',null,
      'r2_auth_key',null,
      'candidate_workflow_id',v_workflow.id,
      'candidate_workflow_generation',v_workflow.generation,
      'candidate_manager_approved_at_utc',null
    );
  end if;

  if coalesce(v_current_policy->>'policy_fingerprint','')
     is distinct from coalesce(v_workflow.policy_snapshot_json->>'policy_fingerprint','') then
    update public.candidate_approval_requests set state='SUPERSEDED',superseded_at_utc=p_now_utc,updated_at_utc=p_now_utc
    where workflow_id=v_workflow.id and state='PENDING';
    v_response:=jsonb_build_object('ok',false,'error_code','CANDIDATE_POLICY_CHANGED','workflow_id',v_workflow.id,
      'state','SUPERSEDED','generation',v_workflow.generation+1,'current_policy',v_current_policy);
    update public.candidate_submission_workflows set state='SUPERSEDED',generation=generation+1,
      policy_snapshot_json=v_current_policy,policy_snapshot_sha256=private._candidate_sha256_jsonb_v1(v_current_policy),
      last_mutation_idempotency_key=p_idempotency_key,
      last_mutation_response_json=v_response,updated_at_utc=p_now_utc where id=v_workflow.id;
    perform private._candidate_workflow_mutation_receipt_v1(
      v_workflow.id,p_idempotency_key,v_mutation_request_hash,'RETRY_FINALISATION',
      case when v_is_office_service then 'OFFICE' when p_session_id is null then 'SERVICE' else 'CANDIDATE_CLIENT' end,
      case when v_is_office_service then v_service_finalisation->>'actor_user_id' else coalesce(p_session_id::text,'SERVICE') end,
      v_response,p_now_utc
    );
    return v_response;
  end if;

  select candidate_app_system_actor_user_id into v_system_actor from public.settings_defaults where id=1;
  if v_system_actor is null then raise exception 'CANDIDATE_SYSTEM_ACTOR_NOT_CONFIGURED' using errcode='55000'; end if;
  v_input:=v_workflow.immutable_submission_json;
  if v_input is null or private._candidate_sha256_jsonb_v1(v_input)
     is distinct from v_workflow.immutable_submission_sha256 then
    raise exception 'CANDIDATE_IMMUTABLE_SUBMISSION_MISMATCH' using errcode='40001';
  end if;
  v_workflow.issue_codes:=private._candidate_submission_issue_codes_v1(
    v_workflow.id,v_input,v_current_policy
  );
  v_effective_separation:=coalesce((v_current_policy->>'expenses_require_separate_timesheet')::boolean,false);
  if v_workflow.workflow_kind in ('CONTRACT_EXPENSE','CONTRACT_COMBINED')
     and coalesce((v_current_policy->>'import_expense_separation_mandatory')::boolean,false)
     and not coalesce((v_current_policy->>'expense_invoice_email_ready')::boolean,false) then
    raise exception 'EXPENSE_INVOICE_EMAIL_REQUIRED' using errcode='55000';
  end if;

  if v_workflow.scope='WEEKLY' then
    select * into v_week from public.contract_weeks where id=v_workflow.contract_week_id for update;
    if not found then raise exception 'CANDIDATE_CONTRACT_WEEK_NOT_FOUND' using errcode='P0002'; end if;
    if v_workflow.workflow_kind='CONTRACT_COMBINED' then
      v_hours_input:=coalesce(v_input->'hours_submission',v_input);
      v_expense_input:=coalesce(v_input->'expense_submission',v_input);
      if jsonb_typeof(v_hours_input)<>'object' or jsonb_typeof(v_expense_input)<>'object' then
        raise exception 'CANDIDATE_COMBINED_SNAPSHOTS_REQUIRED' using errcode='22023';
      end if;
    elsif v_workflow.workflow_kind='CONTRACT_EXPENSE' then
      v_expense_input:=v_input;
    else
      v_hours_input:=v_input;
    end if;

    if v_hours_input is not null then
      if v_hours_input->'canonical_tsfin_snapshot' is null then
        raise exception 'CANDIDATE_CANONICAL_TSFIN_SNAPSHOT_REQUIRED' using errcode='22023';
      end if;
      perform set_config('cloudtms.candidate_electronic_finalise',v_workflow.id::text||':'||v_workflow.generation::text,true);
      v_hours_result:=public.contract_week_manual_upsert_atomic(
        p_week_id=>v_week.id,
        p_expected_timesheet_id=>v_workflow.target_timesheet_id,
        p_timesheet_create_json=>case when v_workflow.target_timesheet_id is null
          then coalesce(v_hours_input->'timesheet_create_json','{}'::jsonb)||v_electronic_patch else null end,
        p_timesheet_patch_json=>coalesce(v_hours_input->'timesheet_patch_json','{}'::jsonb)||v_electronic_patch,
        p_contract_week_patch_json=>coalesce(v_hours_input->'contract_week_patch_json','{}'::jsonb),
        p_tsfin_snapshot_json=>v_hours_input->'canonical_tsfin_snapshot',
        p_rotation_json=>null,p_actor_user_id=>v_system_actor,p_materialise_staged_evidence=>false,
        p_now_utc=>p_now_utc,p_expected_row_signature=>coalesce(p_expected_row_signature,v_workflow.expected_row_signature),
        p_queue_timesheet_materialisation_json=>jsonb_build_object('suppress_timesheet_evidence_materialisation',true)
      );
      if coalesce((v_hours_result->>'ok')::boolean,false)=false then
        raise exception 'CANDIDATE_FINALISE_CANONICAL_APPLY_FAILED' using errcode='55000',detail=v_hours_result::text;
      end if;
      v_hours_timesheet_id:=coalesce(nullif(v_hours_result->>'timesheet_id','')::uuid,
        nullif(v_hours_result#>>'{timesheet,timesheet_id}','')::uuid);
      v_after_signature:=coalesce(v_hours_result->>'row_signature',v_hours_result->>'backend_row_signature',
        v_hours_result#>>'{timesheet,row_signature}');
    end if;

    if v_expense_input is not null then
      if v_workflow.workflow_kind='CONTRACT_EXPENSE' or v_effective_separation then
        v_placement:=public.expense_carrier_resolve_or_create_atomic_v1(
          v_candidate_id,v_environment,coalesce(v_hours_timesheet_id,v_workflow.anchor_timesheet_id),
          coalesce(v_after_signature,p_expected_row_signature,v_workflow.expected_row_signature),
          p_idempotency_key||':carrier',p_now_utc);
      else
        v_placement:=jsonb_build_object(
          'placement','SAME_RECORD','target_timesheet_id',coalesce(v_hours_timesheet_id,v_workflow.target_timesheet_id),
          'target_contract_week_id',v_week.id);
      end if;
      if v_workflow.route='PAPER' then
        select array_agg(c.id order by c.component_no,c.id) into v_evidence_component_ids
        from public.candidate_submission_components c
        where c.workflow_id=v_workflow.id and c.workflow_generation=v_workflow.generation
          and c.component_kind='SIGNED_RETURN' and c.state='IMMUTABLE'
          and c.paper_return_page_key<>'HOURS_TIMESHEET';
      else
        select array_agg(c.id order by c.review_ordinal,c.id) into v_evidence_component_ids
        from public.candidate_submission_components c
        where c.workflow_id=v_workflow.id and c.workflow_generation=v_workflow.generation
          and c.required=true and c.state<>'SUPERSEDED' and c.component_kind<>'HOURS_TIMESHEET';
      end if;
      update public.candidate_submission_workflows set
        contract_week_id=nullif(v_placement->>'target_contract_week_id','')::uuid,
        target_timesheet_id=nullif(v_placement->>'target_timesheet_id','')::uuid,
        updated_at_utc=p_now_utc
      where id=v_workflow.id;
      perform set_config('cloudtms.candidate_finalize_workflow',v_workflow.id::text||':'||v_workflow.generation::text,true);
      v_result:=public.timesheet_expense_apply_atomic_v1(
        v_candidate_id,v_environment,nullif(v_placement->>'target_timesheet_id','')::uuid,
        v_workflow.id,v_workflow.generation,
        case when v_placement->>'placement'='SAME_RECORD' then coalesce(v_after_signature,p_expected_row_signature,v_workflow.expected_row_signature)
          else null end,
        v_expense_input,v_evidence_component_ids,p_idempotency_key||':expense',p_now_utc);
      v_expense_timesheet_id:=nullif(v_result->>'target_timesheet_id','')::uuid;
      v_target_timesheet_id:=coalesce(v_expense_timesheet_id,v_hours_timesheet_id);
      if v_hours_result is not null then
        v_result:=jsonb_build_object('ok',true,'hours_result',v_hours_result,'expense_result',v_result,
          'hours_timesheet_id',v_hours_timesheet_id,'expense_timesheet_id',v_expense_timesheet_id);
      end if;
    else
      v_result:=v_hours_result;
      v_target_timesheet_id:=v_hours_timesheet_id;
    end if;
  else
    if not v_is_office_service then
      perform private._candidate_require_feature_v1(v_environment,'candidate_daily_finalisation');
    end if;
    v_target_timesheet_id:=v_workflow.target_timesheet_id;
    if v_target_timesheet_id is null then
      raise exception 'CANDIDATE_DAILY_TIMESHEET_REQUIRED' using errcode='22023';
    end if;
    v_daily_save_input:=private._candidate_daily_canonical_save_input_v1(
      v_workflow.id,v_workflow.generation
    );
    v_daily_patch:=v_daily_save_input->'timesheet_patch_json';
    if jsonb_typeof(p_daily_materialisation_json)<>'object' then
      raise exception 'CANDIDATE_DAILY_MATERIALISATION_REQUIRED' using errcode='22023';
    end if;
    -- This private composition performs the pre-write row-signature check,
    -- factual save and bounded TSFIN write in this same finalisation transaction.
    -- Any later Process/Authorise error rolls the factual and financial write back.
    v_daily_save_receipt:=private._candidate_daily_save_recalculate_atomic_v1(
      v_workflow.id,v_workflow.generation,p_daily_materialisation_json,
      v_system_actor,p_now_utc
    );
    select * into v_daily_timesheet from public.timesheets
    where timesheet_id=v_target_timesheet_id and is_current=true for update;
    select * into v_daily_fin from public.timesheets_financials
    where id=nullif(v_daily_save_receipt->>'financials_id','')::uuid
      and timesheet_id=v_target_timesheet_id and is_current=true
    for update;
    if not found or v_daily_fin.processing_status<>'UNPROCESSED' then
      raise exception 'CANDIDATE_DAILY_CANONICAL_RECALCULATION_NOT_READY' using errcode='55000';
    end if;
    v_after_signature:=nullif(v_daily_save_receipt->>'post_save_row_signature','');
    if v_after_signature is null then
      raise exception 'CANDIDATE_DAILY_CANONICAL_SAVE_RECEIPT_INVALID' using errcode='55000';
    end if;
    perform set_config('cloudtms.candidate_electronic_finalise','on',true);
    v_result:=public.timesheet_daily_manual_process_atomic(
      v_target_timesheet_id,v_target_timesheet_id,v_system_actor,
      v_electronic_patch,'{}'::jsonb,p_now_utc,v_after_signature
    );
    v_result:=jsonb_build_object(
      'ok',coalesce((v_result->>'ok')::boolean,false),
      'canonical_save_receipt',v_daily_save_receipt,
      'process_result',v_result,'timesheet_id',v_target_timesheet_id,
      'row_signature',coalesce(v_result->>'row_signature',v_result->>'backend_row_signature')
    );
    v_hours_timesheet_id:=v_target_timesheet_id;
    v_after_signature:=coalesce(v_result->>'row_signature',v_result->>'backend_row_signature');
  end if;
  if coalesce((v_result->>'ok')::boolean,false)=false then
    raise exception 'CANDIDATE_FINALISE_CANONICAL_APPLY_FAILED'
      using errcode='55000',detail=jsonb_build_object(
        'code',coalesce(v_result->>'error_code','CANDIDATE_FINALISE_CANONICAL_APPLY_FAILED'),
        'canonical_result',v_result)::text;
  end if;
  if v_target_timesheet_id is null then raise exception 'CANDIDATE_FINALISE_TARGET_MISSING' using errcode='55000'; end if;

  if v_workflow.route<>'PAPER' and v_hours_component.id is not null then
    update public.candidate_submission_components set timesheet_id=coalesce(v_hours_timesheet_id,v_target_timesheet_id)
    where id=v_hours_component.id;
    insert into public.timesheet_evidence(
      timesheet_id,kind,display_name,storage_key,created_at,created_by,
      document_role,candidate_component_id,processing_state
    ) values (
      coalesce(v_hours_timesheet_id,v_target_timesheet_id),'TIMESHEET','Official electronically signed timesheet',
      v_hours_component.final_signed_storage_key,p_now_utc,v_system_actor,
      'SIGNED_TIMESHEET',v_hours_component.id,'READY'
    ) on conflict (candidate_component_id) where candidate_component_id is not null do nothing;
  elsif v_workflow.route='PAPER' and v_workflow.workflow_kind<>'CONTRACT_EXPENSE' then
    select * into v_paper_hours_return
    from public.candidate_submission_components c
    where c.workflow_id=v_workflow.id and c.workflow_generation=v_workflow.generation
      and c.component_kind='SIGNED_RETURN' and c.paper_return_page_key='HOURS_TIMESHEET'
      and c.state='IMMUTABLE' and c.source_content_sha256 is not null
    for update;
    if not found then raise exception 'CANDIDATE_PAPER_RETURN_INCOMPLETE' using errcode='55000'; end if;
    update public.candidate_submission_components set
      timesheet_id=coalesce(v_hours_timesheet_id,v_target_timesheet_id)
    where id=v_paper_hours_return.id;
    insert into public.timesheet_evidence(
      timesheet_id,kind,display_name,storage_key,created_at,created_by,
      document_role,candidate_component_id,processing_state
    ) values (
      coalesce(v_hours_timesheet_id,v_target_timesheet_id),'TIMESHEET','Returned signed paper timesheet',
      v_paper_hours_return.storage_key,p_now_utc,v_system_actor,
      'SIGNED_TIMESHEET',v_paper_hours_return.id,'READY'
    ) on conflict (candidate_component_id) where candidate_component_id is not null do nothing;
  end if;

  v_auto_requested:=coalesce((v_current_policy->>'candidate_electronic_auto_authorise')::boolean,false)
    and v_workflow.route<>'PAPER';
  if v_workflow.issue_codes ?| array[
    'UNEXPECTED_HOURS','DAILY_BREAK_UNEXPECTED','DUPLICATE_EXPENSE_REVIEW',
    'HEALTHROSTER_VALIDATION_REQUIRED','EVIDENCE_REVIEW_REQUIRED',
    'ADDITIONAL_UNITS_NEEDS_CHECKING','PLANNED_HOURS_UNRESOLVED'
  ] then
    v_auto_blocked:=true;
    v_auto_blockers:=v_auto_blockers||v_workflow.issue_codes;
  end if;
  if v_workflow.route='PAPER' then
    v_auto_blocked:=true;v_auto_blockers:=v_auto_blockers||'"PAPER_NEVER_AUTO_AUTHORISES"'::jsonb;
  end if;
  if v_auto_requested and not v_auto_blocked then
    if v_hours_timesheet_id is not null then
      v_authorise_result:=public.timesheet_authorise_generic_atomic(
        v_hours_timesheet_id,v_hours_timesheet_id,v_system_actor,p_now_utc,v_after_signature
      );
      if coalesce((v_authorise_result->>'ok')::boolean,false)=false then
        raise exception 'CANDIDATE_AUTO_AUTHORISE_FAILED' using errcode='55000',detail=v_authorise_result::text;
      end if;
    end if;
    if v_expense_timesheet_id is not null and v_expense_timesheet_id is distinct from v_hours_timesheet_id then
      v_expense_authorise_result:=public.timesheet_authorise_generic_atomic(
        v_expense_timesheet_id,v_expense_timesheet_id,v_system_actor,p_now_utc,null);
      if coalesce((v_expense_authorise_result->>'ok')::boolean,false)=false then
        raise exception 'CANDIDATE_AUTO_AUTHORISE_FAILED' using errcode='55000',detail=v_expense_authorise_result::text;
      end if;
      v_authorise_result:=jsonb_build_object(
        'ok',true,'hours',v_authorise_result,'expenses',v_expense_authorise_result);
    end if;
    if coalesce((v_authorise_result->>'ok')::boolean,false)=false then
      v_auto_blocked:=true;
      v_auto_blockers:=v_auto_blockers||jsonb_build_array(coalesce(v_authorise_result->>'error_code','AUTHORISE_NOT_ADVANCED'));
    end if;
  end if;

  select financials.id into v_canonical_financials_id
  from public.timesheets_financials financials
  where financials.timesheet_id=coalesce(v_hours_timesheet_id,v_target_timesheet_id)
    and financials.is_current=true
  order by financials.computed_at_utc desc nulls last,financials.updated_at desc,financials.id desc
  limit 1;
  if v_canonical_financials_id is null then
    raise exception 'CANDIDATE_CANONICAL_FINANCIALS_NOT_FOUND' using errcode='55000';
  end if;
  v_canonical_financial_sha256:=private._candidate_financial_content_sha256_v1(
    v_canonical_financials_id
  );

  v_response:=jsonb_build_object(
    'ok',true,'idempotent_replay',false,'workflow_id',v_workflow.id,
    'state','FINALISED','generation',v_workflow.generation+1,
    'timesheet_id',v_target_timesheet_id,'canonical_result',v_result,
    'candidate_auto_authorise_effective',v_auto_requested,
    'auto_authorised',v_auto_requested and not v_auto_blocked,
    'canonical_financial_sha256_hex',encode(v_canonical_financial_sha256,'hex'),
    'auto_authorise_blockers',v_auto_blockers,
    'authorise_result',v_authorise_result
  );
  update public.candidate_submission_workflows set state='FINALISED',generation=generation+1,
    target_timesheet_id=v_target_timesheet_id,policy_snapshot_json=v_current_policy,
    canonical_financial_sha256=v_canonical_financial_sha256,
    issue_codes=v_workflow.issue_codes,finalised_at_utc=p_now_utc,
    last_mutation_idempotency_key=p_idempotency_key,last_mutation_response_json=v_response,updated_at_utc=p_now_utc
  where id=v_workflow.id;
  perform private._candidate_notification_insert_v1(v_workflow.account_id,v_candidate_id,v_workflow.id,v_target_timesheet_id,
    case when v_auto_requested and not v_auto_blocked then 'AUTHORISED' else 'SUBMISSION_RECEIVED' end,
    'authorisation','candidate-submission-finalised-v1',jsonb_build_object('auto_authorised',v_auto_requested and not v_auto_blocked),
    jsonb_build_object('type','timesheet','timesheet_id',v_target_timesheet_id),
    'CANDIDATE_FINALISED_V1:'||v_workflow.id::text||':'||(v_workflow.generation+1)::text,p_now_utc);
  perform private._candidate_audit_v1('candidate_submission_workflow',v_workflow.id::text,'CANDIDATE_SUBMISSION_FINALISED',
    jsonb_build_object('state',v_workflow.state,'generation',v_workflow.generation),
    jsonb_build_object('state','FINALISED','generation',v_workflow.generation+1,'timesheet_id',v_target_timesheet_id,
      'auto_authorised',v_auto_requested and not v_auto_blocked),null,v_system_actor,p_idempotency_key,p_now_utc);
  insert into public.audit_events(
    actor_user_id,object_type,object_id_text,action,before_json,after_json,
    reason,correlation_id,ts_utc
  ) values (
    case when v_is_office_service then nullif(v_service_finalisation->>'actor_user_id','')::uuid
      else null end,
    'candidate_workflow_finalisation_completion',v_workflow.id::text,
    'CANDIDATE_WORKFLOW_FINALISATION_COMPLETED',jsonb_build_object(
      'contract_version','CANDIDATE_FINALISATION_COMPLETION_V1',
      'workflow_generation',p_expected_generation,
      'finalisation_identity_sha256',v_finalisation_identity_hash,
      'finalisation_identity',v_finalisation_identity
    ),v_response,'Canonical finalisation completion receipt',
    p_expected_generation::text||':'||v_finalisation_identity_hash,p_now_utc
  );
  perform private._candidate_workflow_mutation_receipt_v1(
    v_workflow.id,p_idempotency_key,v_mutation_request_hash,'RETRY_FINALISATION',
    case when v_is_office_service then 'OFFICE' when p_session_id is null then 'SERVICE' else 'CANDIDATE_CLIENT' end,
    case when v_is_office_service then v_service_finalisation->>'actor_user_id' else coalesce(p_session_id::text,'SERVICE') end,
    v_response,p_now_utc
  );
  return v_response;
exception
  when unique_violation then
    get stacked diagnostics v_constraint_name=constraint_name;
    if v_constraint_name='timesheet_evidence_one_active_timesheet_uq' then
      raise exception 'TIMESHEET_EVIDENCE_ALREADY_ATTACHED' using errcode='23505';
    end if;
    raise;
end;
$function$;

-- candidate_submission_reject_atomic_v1(uuid,text,uuid,uuid,text,text,text,timestamp with time zone)
CREATE OR REPLACE FUNCTION public.candidate_submission_reject_atomic_v1(p_actor_user_id uuid, p_environment text, p_timesheet_id uuid, p_expected_timesheet_id uuid, p_expected_row_signature text, p_reason text, p_idempotency_key text, p_now_utc timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
declare
  v_environment text;
  v_timesheet public.timesheets%rowtype;
  v_fin public.timesheets_financials%rowtype;
  v_week public.contract_weeks%rowtype;
  v_signature jsonb;
  v_capabilities jsonb;
  v_qr_result record;
  v_new_timesheet_id uuid;
  v_qr_backed boolean:=false;
  v_reject_scope text;
  v_workflow record;
  v_rejected_workflow_ids uuid[]:='{}'::uuid[];
  v_paper_workflow_ids uuid[]:='{}'::uuid[];
  v_paper_workflow_generations integer[]:='{}'::integer[];
  v_paper_retirement_result jsonb;
  v_rejection_family_contract_id uuid;
  v_rejection_family_week_ending_date date;
  v_rejection_family_key text;
  v_rejection_request_hash text;
  v_rejection_receipt_before jsonb;
  v_response jsonb;
begin
  v_environment:=private._candidate_assert_environment(p_environment);
  if not private._candidate_office_service_context_valid_v1(
    v_environment,p_actor_user_id,'REJECT_CONFIRM'
  ) then
    perform private._candidate_require_feature_v1(v_environment,'candidate_app_writes');
  end if;
  if p_actor_user_id is null or p_timesheet_id is null or p_expected_timesheet_id is null
     or nullif(btrim(coalesce(p_expected_row_signature,'')),'') is null
     or nullif(btrim(coalesce(p_reason,'')),'') is null
     or nullif(btrim(coalesce(p_idempotency_key,'')),'') is null then
    raise exception 'CANDIDATE_REJECT_PAYLOAD_INVALID' using errcode='22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'CANDIDATE_REJECTION_IDEMPOTENCY:'||p_actor_user_id::text||':'||p_idempotency_key,0
  ));
  -- Serialise every Candidate rejection for the same contract/week before
  -- locking either the hours row or a separate expense carrier. This prevents
  -- the inverse target/workflow/source lock order that can deadlock H1/E1.
  select target.contract_id,target.week_ending_date
  into v_rejection_family_contract_id,v_rejection_family_week_ending_date
  from public.timesheets target
  where target.timesheet_id=p_timesheet_id;
  if not found then
    raise exception 'CANDIDATE_REJECT_TARGET_NOT_FOUND' using errcode='P0002';
  end if;
  v_rejection_family_key:='CANDIDATE_PAPER_FAMILY:'||v_environment||':'
    ||coalesce(v_rejection_family_contract_id::text,'-')||':'
    ||coalesce(v_rejection_family_week_ending_date::text,'-');
  perform pg_advisory_xact_lock(hashtextextended(v_rejection_family_key,0));

  v_rejection_request_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'contract_version','CANDIDATE_REJECTION_REQUEST_V2',
    'environment',v_environment,
    'actor_user_id',p_actor_user_id,
    'timesheet_id',p_timesheet_id,
    'expected_timesheet_id',p_expected_timesheet_id,
    'expected_row_signature',btrim(p_expected_row_signature),
    'reason',btrim(p_reason)
  )::text,'UTF8'),'sha256'),'hex');
  select ae.before_json,ae.after_json into v_rejection_receipt_before,v_response
  from public.audit_events ae
  where ae.object_type='candidate_submission_rejection_receipt'
    and ae.actor_user_id=p_actor_user_id
    and ae.correlation_id=p_idempotency_key
  order by ae.ts_utc desc,ae.id desc
  limit 1;
  if found then
    if v_rejection_receipt_before->>'request_sha256' is distinct from v_rejection_request_hash then
      raise exception 'CANDIDATE_IDEMPOTENCY_CONFLICT'
        using errcode='40001',detail=jsonb_build_object(
          'code','CANDIDATE_IDEMPOTENCY_CONFLICT','idempotency_key',p_idempotency_key
        )::text;
    end if;
    return coalesce(v_response,'{}'::jsonb)||jsonb_build_object('idempotent_replay',true);
  end if;

  select * into v_timesheet from public.timesheets where timesheet_id=p_timesheet_id for update;
  if not found then raise exception 'CANDIDATE_REJECT_TARGET_NOT_FOUND' using errcode='P0002'; end if;
  if not v_timesheet.is_current or v_timesheet.timesheet_id<>p_expected_timesheet_id then
    raise exception 'TIMESHEET_MOVED' using errcode='40001';
  end if;
  select * into v_week from public.contract_weeks where timesheet_id=v_timesheet.timesheet_id for update;
  if not found then raise exception 'CANDIDATE_CONTRACT_WEEK_NOT_FOUND' using errcode='P0002'; end if;
  select * into v_fin from public.timesheets_financials
  where timesheet_id=v_timesheet.timesheet_id and is_current=true for update;
  if v_fin.authorised_at_utc is not null or v_timesheet.authorised_at_server is not null then
    raise exception 'CANDIDATE_REJECT_REQUIRES_UNAUTHORISE' using errcode='55000';
  end if;
  if v_fin.paid_at_utc is not null or v_fin.locked_by_invoice_id is not null then
    raise exception 'CANDIDATE_REJECT_PROTECTED_HISTORY' using errcode='55000';
  end if;
  v_signature:=public.timesheet_lifecycle_guard_signature_v1(v_timesheet.timesheet_id,v_week.id,false);
  if coalesce(v_signature->>'row_signature',v_signature->>'backend_row_signature','')<>p_expected_row_signature then
    raise exception 'ROW_SIGNATURE_MISMATCH' using errcode='40001';
  end if;
  v_capabilities:=private._candidate_record_capabilities_v1(v_timesheet.timesheet_id,v_week.id,'{}'::jsonb);
  if coalesce((v_capabilities->>'can_reject_candidate_submission')::boolean,false)=false then
    raise exception 'CANDIDATE_REJECT_NOT_ALLOWED' using errcode='55000',detail=v_capabilities::text;
  end if;
  v_reject_scope:=v_capabilities->>'reject_scope';
  v_qr_backed:=v_timesheet.qr_status is not null or v_timesheet.qr_token is not null or v_timesheet.qr_r2_key is not null
    or exists(select 1 from public.candidate_submission_workflows w where w.target_timesheet_id=v_timesheet.timesheet_id and w.route='PAPER');

  for v_workflow in
    select w.id,w.generation,w.route,w.state
    from public.candidate_submission_workflows w
    where w.environment=v_environment
      and (
        (
          w.state not in ('FINALISED','REFUSED','REJECTED','CANCELLED','EXPIRED','SUPERSEDED')
          and (
            w.target_timesheet_id=v_timesheet.timesheet_id
            or w.anchor_timesheet_id=v_timesheet.timesheet_id
          )
        )
        or (
          w.state='FINALISED'
          and w.target_timesheet_id=v_timesheet.timesheet_id
        )
      )
    order by w.id
    for update
  loop
    v_rejected_workflow_ids:=array_append(v_rejected_workflow_ids,v_workflow.id);
    if v_workflow.route='PAPER'
       and v_workflow.state in ('AWAITING_PAPER_RETURN','RECEIVED','FINALISED') then
      v_paper_workflow_ids:=array_append(v_paper_workflow_ids,v_workflow.id);
      v_paper_workflow_generations:=array_append(
        v_paper_workflow_generations,v_workflow.generation
      );
    end if;
  end loop;

  if cardinality(v_paper_workflow_ids)>0 then
    v_paper_retirement_result:=private._candidate_paper_delivery_retire_set_v1(
      v_paper_workflow_ids,v_paper_workflow_generations,
      'OFFICE_REJECTED',p_now_utc
    );
    if not coalesce((v_paper_retirement_result->>'retired')::boolean,false)
       or not coalesce(
         (v_paper_retirement_result->>'qr_invalidation_proven')::boolean,false
       ) then
      raise exception 'CANDIDATE_PAPER_QR_INVALIDATION_NOT_PROVEN'
        using errcode='40001',detail=jsonb_build_object(
          'code','CANDIDATE_PAPER_QR_INVALIDATION_NOT_PROVEN',
          'workflow_ids',to_jsonb(v_paper_workflow_ids),
          'retirement_receipt',v_paper_retirement_result
        )::text;
    end if;
  end if;

  if v_qr_backed then
    select * into v_qr_result from public.timesheet_qr_refuse_and_reset(
      v_timesheet.timesheet_id,v_timesheet.timesheet_id,btrim(p_reason),p_actor_user_id
    );
    v_new_timesheet_id:=v_qr_result.timesheet_id;
  else
    v_new_timesheet_id:=private._candidate_timesheet_reject_rotate_v1(
      v_timesheet.timesheet_id,v_timesheet.timesheet_id,btrim(p_reason),p_actor_user_id,p_now_utc);
  end if;
  if v_new_timesheet_id is null then raise exception 'CANDIDATE_REJECT_ROTATION_FAILED' using errcode='55000'; end if;

  update public.timesheets set
    authorised_at_server=null,worked_start_iso=null,worked_end_iso=null,break_start_iso=null,break_end_iso=null,
    break_minutes=null,actual_schedule_json=null,additional_units_week='{}'::jsonb,additional_units_per_day='{}'::jsonb,
    manual_pdf_r2_key=null,reference_number=null,day_references_json=null,
    qr_token=null,qr_status=case when v_qr_backed then 'PENDING'::public.timesheet_qr_status_enum else null end,
    qr_payload_json='{}'::jsonb,qr_generated_at=null,qr_scanned_at=null,qr_scan_info_json=null,qr_r2_key=null,
    qr_last_sent_hash=null,qr_last_sent_at_utc=null,qr_signed_hash=null,qr_signed_at_utc=null,
    updated_at=p_now_utc
  where timesheet_id=v_new_timesheet_id;

  update public.timesheets_financials set
    processing_status='UNPROCESSED',worked_start_iso=null,worked_end_iso=null,break_start_iso=null,break_end_iso=null,
    break_minutes=null,hours_day=0,hours_night=0,hours_sat=0,hours_sun=0,hours_bh=0,total_hours=0,
    additional_units_json='{}'::jsonb,additional_pay_ex_vat=0,additional_charge_ex_vat=0,additional_margin_ex_vat=0,
    expenses_pay_ex_vat=0,expenses_charge_ex_vat=0,expenses_description=null,expenses_evidence_r2_key=null,
    expenses_evidence_manifest=null,mileage_units=0,mileage_pay_ex_vat=0,mileage_charge_ex_vat=0,
    mileage_evidence_r2_key=null,mileage_evidence_manifest=null,travel_pay_ex_vat=0,travel_charge_ex_vat=0,
    accommodation_pay_ex_vat=0,accommodation_charge_ex_vat=0,other_pay_ex_vat=0,other_charge_ex_vat=0,
    actual_schedule_json=null,actual_minutes_by_day_json=null,total_pay_ex_vat=0,total_charge_ex_vat=0,margin_ex_vat=0,
    authorised_at_utc=null,authorised_by_user_id=null,updated_at=p_now_utc
  where timesheet_id=v_new_timesheet_id and is_current=true;

  update public.contract_weeks set status='OPEN',day_entries_json='[]'::jsonb,
    totals_json='{}'::jsonb,updated_at=p_now_utc where id=v_week.id;
  update public.timesheet_evidence set processing_state='SUPERSEDED'
  where timesheet_id=v_timesheet.timesheet_id and processing_state<>'SUPERSEDED';
  for v_workflow in
    select w.id,w.account_id,w.candidate_id,w.generation,w.state as captured_state,
      case when w.state='FINALISED' then greatest(w.generation-1,1) else w.generation end as artifact_generation
    from public.candidate_submission_workflows w
    where w.id=any(v_rejected_workflow_ids)
    order by w.id
    for update
  loop
    update public.candidate_approval_requests set
      state='SUPERSEDED',superseded_at_utc=p_now_utc,updated_at_utc=p_now_utc
    where workflow_id=v_workflow.id
      and workflow_generation=v_workflow.artifact_generation
      and state in ('PENDING','APPROVED');
    update public.candidate_submission_components set
      state='REJECTED',superseded_at_utc=p_now_utc
    where workflow_id=v_workflow.id
      and workflow_generation=v_workflow.artifact_generation
      and state not in ('REJECTED','SUPERSEDED','ABANDONED');
    update public.candidate_submission_workflows set
      state='REJECTED',generation=v_workflow.generation+1,
      rejection_reason=btrim(p_reason),rejection_scope=v_reject_scope,updated_at_utc=p_now_utc
    where id=v_workflow.id and generation=v_workflow.generation
      and state=v_workflow.captured_state
      and state not in ('REFUSED','REJECTED','CANCELLED','EXPIRED','SUPERSEDED');
    if not found then
      raise exception 'CANDIDATE_REJECT_WORKFLOW_CONFLICT' using errcode='40001';
    end if;
    perform private._candidate_notification_insert_v1(v_workflow.account_id,v_workflow.candidate_id,v_workflow.id,v_new_timesheet_id,
      'OFFICE_REJECTED','office_rejection','candidate-office-rejected-v1',
      jsonb_build_object('reason',btrim(p_reason),'resubmission_scope',v_reject_scope),
      jsonb_build_object('type','timesheet','timesheet_id',v_new_timesheet_id),
      'CANDIDATE_OFFICE_REJECTED_V1:'||v_workflow.id::text||':'||(v_workflow.generation+1)::text,p_now_utc);
  end loop;
  v_response:=jsonb_build_object(
    'ok',true,'old_timesheet_id',v_timesheet.timesheet_id,'timesheet_id',v_new_timesheet_id,
    'contract_week_id',v_week.id,'contract_week_status','OPEN','processing_status','UNPROCESSED',
    'rejection_scope',v_reject_scope,'qr_reissue_required',v_qr_backed,
    'paper_retirement_receipt',v_paper_retirement_result,
    'idempotency_key',p_idempotency_key
  );
  perform private._candidate_audit_v1('timesheet',v_new_timesheet_id::text,'CANDIDATE_SUBMISSION_REJECTED',
    jsonb_build_object('old_timesheet_id',v_timesheet.timesheet_id),v_response,btrim(p_reason),
    p_actor_user_id,p_idempotency_key,p_now_utc);
  insert into public.audit_events(
    actor_user_id,object_type,object_id_text,action,before_json,after_json,
    reason,correlation_id,ts_utc
  ) values (
    p_actor_user_id,'candidate_submission_rejection_receipt',p_timesheet_id::text,
    'CANDIDATE_SUBMISSION_REJECTION_RECEIPT',jsonb_build_object(
      'request_sha256',v_rejection_request_hash,'contract_version','CANDIDATE_REJECTION_REQUEST_V2'
    ),v_response,btrim(p_reason),p_idempotency_key,p_now_utc
  );
  return v_response;
end;
$function$;

-- candidate_workflow_transition_atomic_v1(uuid,text,uuid,text,integer,jsonb,text,timestamp with time zone)
CREATE OR REPLACE FUNCTION public.candidate_workflow_transition_atomic_v1(p_session_id uuid, p_environment text, p_workflow_id uuid, p_action text, p_expected_generation integer, p_payload jsonb DEFAULT '{}'::jsonb, p_idempotency_key text DEFAULT NULL::text, p_now_utc timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
declare
  v_environment text;
  v_action text:=upper(btrim(coalesce(p_action,'')));
  v_payload jsonb:=coalesce(p_payload,'{}'::jsonb);
  v_context jsonb;
  v_account_id uuid;
  v_candidate_id uuid;
  v_workflow public.candidate_submission_workflows%rowtype;
  v_source_workflow public.candidate_submission_workflows%rowtype;
  v_existing_workflow public.candidate_submission_workflows%rowtype;
  v_contract public.contracts%rowtype;
  v_week public.contract_weeks%rowtype;
  v_anchor_week public.contract_weeks%rowtype;
  v_anchor_timesheet public.timesheets%rowtype;
  v_daily_timesheet public.timesheets%rowtype;
  v_daily_fin public.timesheets_financials%rowtype;
  v_policy jsonb;
  v_approval public.candidate_approval_requests%rowtype;
  v_component public.candidate_submission_components%rowtype;
  v_signature_component public.candidate_submission_components%rowtype;
  v_email_check jsonb;
  v_token_hash bytea;
  v_digest bytea;
  v_submission_hash bytea;
  v_render_input_hash bytea;
  v_manifest_hash bytea;
  v_mail_id uuid;
  v_response jsonb;
  v_manifest jsonb;
  v_render_contract jsonb;
  v_receipt jsonb;
  v_immutable_submission jsonb;
  v_expense_submission jsonb;
  v_component_ids uuid[];
  v_method text;
  v_next_generation integer;
  v_component_no integer;
  v_request_generation integer;
  v_reviewed_count integer;
  v_required_count integer;
  v_constraint_name text;
  v_is_service_action boolean;
  v_is_public_manager_action boolean;
  v_is_electronic boolean;
  v_component_kind text;
  v_document_role text;
  v_expense_category text;
  v_requested_media_type text;
  v_requested_byte_size bigint;
  v_review_ordinal integer;
  v_has_expenses boolean:=false;
  v_has_mileage boolean:=false;
  v_expense_value numeric:=0;
  v_required_categories text[]:=array[]::text[];
  v_required_category text;
  v_paper_manifest jsonb;
  v_paper_source_pages jsonb;
  v_paper_page_key text;
  v_paper_timesheet_id uuid;
  v_paper_pack_result jsonb;
  v_paper_retirement_result jsonb;
  v_paper_mail public.mail_outbox%rowtype;
  v_paper_mail_id uuid;
  v_paper_manifest_sha256 text;
  v_paper_pack_storage_key text;
  v_paper_pack_sha256 text;
  v_paper_pack_media_type text;
  v_paper_pack_byte_size bigint;
  v_paper_pack_page_count integer;
  v_paper_pack_attachment jsonb;
  v_paper_notification_id uuid;
  v_paper_release_idempotent boolean:=false;
  v_paper_outbox_count integer:=0;
  v_paper_base_document_sha256 text;
  v_paper_branding_contract_sha256 text;
  v_paper_renderer_contract_version text;
  v_paper_expected_storage_key text;
  v_provider_lease_token text;
  v_provider_permit_expires_at timestamptz;
  v_manager_mail public.mail_outbox%rowtype;
  v_manager_mail_kind text;
  v_manager_provider_accepted_at timestamptz;
  v_manager_pending_mail_count integer:=0;
  v_manager_request_ids uuid[]:=array[]::uuid[];
  v_manager_withdrawal_request_id uuid;
  v_manager_withdrawal_count integer:=0;
  v_manager_retirement_result jsonb;
  v_cancel_reason text;
  v_cancel_reason_code text;
  v_audit_reason text;
  v_unlocked_workflow_updated_at timestamptz;
  v_paper_family_key text;
  v_source_component public.candidate_submission_components%rowtype;
  v_all_final_ready boolean:=false;
  v_server_issue_codes jsonb:='[]'::jsonb;
  v_request_id uuid;
  v_workflow_kind text;
  v_scope text;
  v_route text;
  v_canonical_work_date date;
  v_canonical_week_ending_date date;
  v_client_id uuid;
  v_anchor_candidate_count integer:=0;
  v_anchor_week_id uuid;
  v_target_capabilities jsonb;
  v_route_authority jsonb;
  v_daily_input jsonb;
  v_daily_patch jsonb;
  v_expected_save_hash bytea;
  v_daily_context jsonb;
  v_daily_context_hash bytea;
  v_current_row_signature text;
  v_insert_workflow_id uuid;
  v_replacement_of_workflow_id uuid;
  v_is_rejected_resubmission boolean:=false;
  v_creation_request_identity jsonb;
  v_creation_identity jsonb;
  v_creation_request_sha256 bytea;
  v_initial_route text;
  v_source_anchor public.timesheets%rowtype;
  v_current_anchor_count integer:=0;
  v_current_anchor_timesheet_id uuid;
  v_paper_failure_code text;
  v_paper_failure_class text;
  v_paper_failure_retryable boolean:=false;
  v_paper_pack_attempt_token text;
  v_paper_pack_attempt_count integer:=0;
  v_paper_pack_attempt_expires_at timestamptz;
  v_paper_pack_next_retry_at timestamptz;
  v_paper_pack_operation_id text;
  v_office_actor_user_id uuid;
  v_is_office_service_action boolean:=false;
  v_is_internal_paper_service_action boolean:=false;
  v_mutation_channel text;
  v_mutation_actor_identity text;
  v_mutation_semantic_payload jsonb;
  v_mutation_request_sha256 text;
  v_mutation_receipt jsonb;
  v_mutation_replay_probe_only boolean:=false;
begin
  v_environment:=private._candidate_assert_environment(p_environment);
  if p_workflow_id is null or jsonb_typeof(v_payload)<>'object' then
    raise exception 'CANDIDATE_WORKFLOW_PAYLOAD_INVALID' using errcode='22023';
  end if;
  if v_payload ?| array['password','refresh_token','token'] then
    raise exception 'CANDIDATE_WORKFLOW_PLAINTEXT_SECRET_FORBIDDEN' using errcode='22023';
  end if;

  if v_action='SELECT_APPROVAL_METHOD' then
    v_method:=upper(coalesce(v_payload->>'method',''));
    v_action:=case v_method
      when 'PHONE' then 'SELECT_PHONE_APPROVAL'
      when 'EMAIL' then 'CREATE_EMAIL_APPROVAL_REQUEST'
      when 'PAPER' then 'PAPER_PREPARE'
      else v_action end;
  elsif v_action='EMAIL_REQUEST' then
    v_action:='CREATE_EMAIL_APPROVAL_REQUEST';
  elsif v_action='MANAGER_REVIEW' then
    v_action:='BEGIN_MANAGER_REVIEW';
  elsif v_action='REGISTER_MANAGER_REVIEW_DOCUMENT' then
    v_action:='REGISTER_REVIEW_COMPONENT';
  end if;
  v_mutation_replay_probe_only:=p_session_id is not null
    and coalesce((v_payload->>'mutation_replay_probe_only')::boolean,false);
  if v_mutation_replay_probe_only
     and jsonb_typeof(v_payload->'mutation_replay_semantic_payload') is distinct from 'object' then
    raise exception 'CANDIDATE_IDEMPOTENCY_RECEIPT_INVALID' using errcode='22023';
  end if;

  if coalesce(v_payload->>'actor_user_id','')
       ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
    v_office_actor_user_id:=(v_payload->>'actor_user_id')::uuid;
  end if;
  v_is_office_service_action:=p_session_id is null
    and coalesce((v_payload->>'service_office_action')::boolean,false)
    and private._candidate_office_service_context_valid_v1(
      v_environment,v_office_actor_user_id,v_action
    );
  v_is_internal_paper_service_action:=p_session_id is null and (
    (v_action='PAPER_PACK_RELEASE'
      and coalesce((v_payload->>'service_paper_pack_release')::boolean,false))
    or (v_action='PAPER_PROVIDER_SUBMIT_PERMIT'
      and coalesce((v_payload->>'service_paper_provider_submit_permit')::boolean,false))
    or (v_action='PAPER_PACK_MARK_FAILURE'
      and coalesce((v_payload->>'service_paper_pack_failure')::boolean,false))
    or (v_action='PAPER_PACK_ATTEMPT_CLAIM'
      and coalesce((v_payload->>'service_paper_pack_attempt')::boolean,false))
  );
  if not v_is_office_service_action and not v_is_internal_paper_service_action then
    perform private._candidate_require_feature_v1(v_environment,'candidate_app_writes');
  end if;

  if v_action in (
    'SELECT_PHONE_APPROVAL','CREATE_EMAIL_APPROVAL_REQUEST','BEGIN_MANAGER_REVIEW',
    'RECORD_REVIEW_PROGRESS','PHONE_APPROVE','EMAIL_APPROVE','MANAGER_REFUSE',
    'REMIND','RENEW','MANAGER_REQUEST_CANCEL','CANCEL_MANAGER_HANDOFF',
    'REGISTER_REVIEW_COMPONENT','REGISTER_FINAL_SIGNED_DOCUMENT',
    'MANAGER_PROVIDER_SUBMIT_PERMIT'
  ) or (p_session_id is null and v_action in ('COMPONENT_PREPARE','COMPONENT_COMPLETE')) then
    if not v_is_office_service_action and not v_is_internal_paper_service_action then
    perform private._candidate_require_feature_v1(v_environment,'candidate_manager_approval');
    end if;
  end if;
  if v_action='BEGIN_CANONICAL_DAILY_SAVE' then
    if not v_is_office_service_action then
    perform private._candidate_require_feature_v1(v_environment,'candidate_daily_finalisation');
    end if;
  end if;
  if v_action in (
    'PAPER_PREPARE','PAPER_RETURN','PAPER_PACK_RELEASE',
    'PAPER_PROVIDER_SUBMIT_PERMIT','PAPER_PACK_MARK_FAILURE','PAPER_PACK_ATTEMPT_CLAIM'
  ) then
    if not v_is_office_service_action and not v_is_internal_paper_service_action then
    perform private._candidate_require_feature_v1(v_environment,'candidate_paper_qr');
    end if;
  end if;
  if v_action='MARK_READ' then
    perform private._candidate_require_feature_v1(v_environment,'candidate_notifications');
  end if;

  v_is_service_action:=v_action in (
    'REGISTER_REVIEW_COMPONENT','REGISTER_FINAL_SIGNED_DOCUMENT',
    'BEGIN_CANONICAL_DAILY_SAVE'
  ) or (p_session_id is null
    and v_action='PAPER_PACK_RELEASE'
    and coalesce((v_payload->>'service_paper_pack_release')::boolean,false)
  ) or (p_session_id is null
    and v_action='PAPER_PROVIDER_SUBMIT_PERMIT'
    and coalesce((v_payload->>'service_paper_provider_submit_permit')::boolean,false)
  ) or (p_session_id is null
    and v_action='PAPER_PACK_MARK_FAILURE'
    and coalesce((v_payload->>'service_paper_pack_failure')::boolean,false)
  ) or (p_session_id is null
    and v_action='PAPER_PACK_ATTEMPT_CLAIM'
    and coalesce((v_payload->>'service_paper_pack_attempt')::boolean,false)
  ) or (p_session_id is null
    and v_action='MANAGER_PROVIDER_SUBMIT_PERMIT'
    and coalesce((v_payload->>'service_manager_provider_submit_permit')::boolean,false)
  ) or (p_session_id is null
    and coalesce((v_payload->>'service_phone_approval')::boolean,false)
    and v_action in ('BEGIN_MANAGER_REVIEW','RECORD_REVIEW_PROGRESS','PHONE_APPROVE','MANAGER_REFUSE',
      'COMPONENT_PREPARE','COMPONENT_COMPLETE'))
  or (v_is_office_service_action
    and v_action in ('REMIND','RENEW','MANAGER_REQUEST_CANCEL','CANCEL_MANAGER_HANDOFF',
      'BEGIN_MANAGER_REVIEW','RECORD_REVIEW_PROGRESS','PHONE_APPROVE','MANAGER_REFUSE',
      'REGISTER_REVIEW_COMPONENT','REGISTER_FINAL_SIGNED_DOCUMENT',
      'BEGIN_CANONICAL_DAILY_SAVE','PAPER_PACK_RELEASE','PAPER_PACK_ATTEMPT_CLAIM',
      'PAPER_PACK_MARK_FAILURE'));
  v_is_public_manager_action:=not v_is_service_action and p_session_id is null and v_action in (
    'BEGIN_MANAGER_REVIEW','RECORD_REVIEW_PROGRESS','PHONE_APPROVE','EMAIL_APPROVE','MANAGER_REFUSE',
    'COMPONENT_PREPARE','COMPONENT_COMPLETE'
  );

  if v_is_service_action then
    if v_action='PAPER_PACK_RELEASE' then
      select * into v_workflow
      from public.candidate_submission_workflows
      where id=p_workflow_id and environment=v_environment;
      if not found then raise exception 'CANDIDATE_WORKFLOW_NOT_FOUND' using errcode='P0002'; end if;
      v_paper_timesheet_id:=coalesce(v_workflow.target_timesheet_id,v_workflow.anchor_timesheet_id);
      if v_paper_timesheet_id is null then
        raise exception 'CANDIDATE_PAPER_TIMESHEET_NOT_READY' using errcode='55000';
      end if;
      perform 1 from public.timesheets
      where timesheet_id=v_paper_timesheet_id and is_current=true and archived_at_utc is null
      for update;
      if not found then raise exception 'CANDIDATE_PAPER_TIMESHEET_NOT_READY' using errcode='55000'; end if;
      select * into v_workflow
      from public.candidate_submission_workflows
      where id=p_workflow_id and environment=v_environment
      for update;
      if not found
         or coalesce(v_workflow.target_timesheet_id,v_workflow.anchor_timesheet_id)
              is distinct from v_paper_timesheet_id then
        raise exception 'CANDIDATE_WORKFLOW_CONTEXT_CONFLICT' using errcode='40001';
      end if;
    else
      select * into v_workflow
      from public.candidate_submission_workflows
      where id=p_workflow_id and environment=v_environment
      for update;
    end if;
    if not found then raise exception 'CANDIDATE_WORKFLOW_NOT_FOUND' using errcode='P0002'; end if;
    if v_is_office_service_action
       and v_action in ('REMIND','RENEW','MANAGER_REQUEST_CANCEL','CANCEL_MANAGER_HANDOFF',
         'BEGIN_MANAGER_REVIEW','RECORD_REVIEW_PROGRESS','PHONE_APPROVE','MANAGER_REFUSE') then
      if coalesce(v_payload->>'approval_request_id','')
           !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
         or coalesce(v_payload->>'approval_request_generation','') !~ '^[1-9][0-9]{0,8}$' then
        raise exception 'CANDIDATE_REQUEST_GENERATION_STALE' using errcode='40001';
      end if;
      perform 1
      from public.candidate_approval_requests office_request
      where office_request.id=(v_payload->>'approval_request_id')::uuid
        and office_request.workflow_id=v_workflow.id
        and office_request.workflow_generation=v_workflow.generation
        and office_request.request_generation=(v_payload->>'approval_request_generation')::integer;
      if not found then
        raise exception 'CANDIDATE_REQUEST_GENERATION_STALE' using errcode='40001';
      end if;
    end if;
    v_account_id:=v_workflow.account_id;
    v_candidate_id:=v_workflow.candidate_id;
  elsif v_is_public_manager_action then
    if coalesce(v_payload->>'approval_token_hash_hex','') !~ '^[0-9a-fA-F]{64}$' then
      raise exception 'MANAGER_APPROVAL_REQUEST_NOT_READY' using errcode='28000';
    end if;
    v_token_hash:=decode(v_payload->>'approval_token_hash_hex','hex');
    select a.id,a.workflow_id into v_request_id,v_workflow.id
    from public.candidate_approval_requests a
    where a.token_hash=v_token_hash and a.workflow_id=p_workflow_id;
    if not found then raise exception 'MANAGER_APPROVAL_REQUEST_NOT_READY' using errcode='28000'; end if;
    select * into v_workflow
    from public.candidate_submission_workflows
    where id=p_workflow_id and environment=v_environment
    for update;
    if not found then raise exception 'MANAGER_APPROVAL_REQUEST_NOT_READY' using errcode='28000'; end if;
    select * into v_approval
    from public.candidate_approval_requests
    where id=v_request_id
      and workflow_id=v_workflow.id
      and workflow_generation=v_workflow.generation
      and method in ('EMAIL','PHONE')
      and state='PENDING'
      and expires_at_utc>p_now_utc
      and review_manifest_sha256=v_workflow.review_manifest_sha256
    for update;
    if not found then raise exception 'MANAGER_APPROVAL_REQUEST_NOT_READY' using errcode='28000'; end if;
    v_account_id:=v_workflow.account_id;
    v_candidate_id:=v_workflow.candidate_id;
  else
    v_context:=private._candidate_session_context_v1(p_session_id,v_environment,null,p_now_utc,true);
    v_account_id:=nullif(v_context->>'account_id','')::uuid;
    v_candidate_id:=nullif(v_context->>'selected_candidate_id','')::uuid;
    if v_candidate_id is null then raise exception 'CANDIDATE_SELECTION_REQUIRED' using errcode='28000'; end if;
  end if;

  if v_action='RESUBMIT_REJECTED' then
    if nullif(btrim(coalesce(p_idempotency_key,'')),'') is null
       or btrim(p_idempotency_key) !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
      raise exception 'CANDIDATE_IDEMPOTENCY_KEY_REQUIRED' using errcode='22023';
    end if;
    if p_expected_generation is null or p_expected_generation<1 then
      raise exception 'WORKFLOW_GENERATION_CONFLICT' using errcode='40001';
    end if;

    v_creation_request_identity:=jsonb_build_object(
      'version','CANDIDATE_WORKFLOW_CREATION_REQUEST_V1',
      'action','RESUBMIT_REJECTED',
      'environment',v_environment,
      'account_id',v_account_id,
      'candidate_id',v_candidate_id,
      'rejected_workflow_id',p_workflow_id,
      'rejected_workflow_generation',p_expected_generation
    );
    v_creation_request_sha256:=private._candidate_workflow_creation_request_sha256_v1(
      v_creation_request_identity
    );

    -- One account/key lock serialises exact retries. The source lock then
    -- serialises every key that attempts to replace the same rejected row.
    perform pg_advisory_xact_lock(hashtextextended(
      'candidate-workflow-idempotency|'||v_account_id::text||'|'||btrim(p_idempotency_key),0
    ));
    perform pg_advisory_xact_lock(hashtextextended(
      'candidate-rejected-source|'||p_workflow_id::text,0
    ));

    select * into v_source_workflow
    from public.candidate_submission_workflows
    where id=p_workflow_id
      and environment=v_environment
      and account_id=v_account_id
      and candidate_id=v_candidate_id
    for update;
    if not found then
      raise exception 'CANDIDATE_WORKFLOW_NOT_FOUND' using errcode='P0002';
    end if;
    if v_source_workflow.generation<>p_expected_generation then
      raise exception 'WORKFLOW_GENERATION_CONFLICT' using errcode='40001';
    end if;
    if v_source_workflow.state<>'REJECTED' then
      raise exception 'CANDIDATE_REJECTED_WORKFLOW_NOT_RESUBMITTABLE' using errcode='40001';
    end if;

    select * into v_existing_workflow
    from public.candidate_submission_workflows
    where account_id=v_account_id
      and idempotency_key=btrim(p_idempotency_key)
    for update;
    if found then
      if v_existing_workflow.replacement_of_workflow_id is distinct from v_source_workflow.id
         or v_existing_workflow.candidate_id is distinct from v_source_workflow.candidate_id
         or v_existing_workflow.creation_request_sha256 is distinct from v_creation_request_sha256 then
        raise exception 'CANDIDATE_IDEMPOTENCY_CONFLICT' using errcode='40001';
      end if;
      return jsonb_build_object(
        'ok',true,'idempotent_replay',true,
        'rejected_workflow_id',v_source_workflow.id,
        'replacement_workflow_id',v_existing_workflow.id,
        'replacement_created',false,
        'workflow_id',v_existing_workflow.id,
        'state',v_existing_workflow.state,
        'generation',v_existing_workflow.generation
      );
    end if;

    select * into v_existing_workflow
    from public.candidate_submission_workflows
    where replacement_of_workflow_id=v_source_workflow.id
    for update;
    if found or private._candidate_rejection_replaced_v1(v_source_workflow.id) then
      raise exception 'CANDIDATE_REJECTED_WORKFLOW_ALREADY_REPLACED'
        using errcode='40001',detail=case when v_existing_workflow.id is null then null
          else jsonb_build_object('replacement_workflow_id',v_existing_workflow.id)::text end;
    end if;

    v_is_rejected_resubmission:=true;
    v_replacement_of_workflow_id:=v_source_workflow.id;
    v_insert_workflow_id:=gen_random_uuid();
    if v_source_workflow.workflow_kind='DAILY' then
      select current_timesheet.* into v_daily_timesheet
      from public.timesheets source_timesheet
      join public.timesheets current_timesheet
        on current_timesheet.booking_id=source_timesheet.booking_id
       and current_timesheet.is_current=true
       and current_timesheet.archived_at_utc is null
       and current_timesheet.sheet_scope='DAILY'::public.timesheet_scope_enum
      where source_timesheet.timesheet_id=coalesce(
        v_source_workflow.target_timesheet_id,v_source_workflow.anchor_timesheet_id
      )
        and nullif(btrim(coalesce(source_timesheet.booking_id,'')),'') is not null;
      if not found then
        raise exception 'CANDIDATE_DAILY_SHIFT_NOT_FOUND' using errcode='P0002';
      end if;
      v_workflow_kind:='DAILY';
      v_scope:='DAILY';
      v_initial_route:=upper(coalesce(
        v_source_workflow.creation_identity_json#>>'{derived,initial_route}',
        v_source_workflow.route
      ));
      if v_initial_route not in ('EMAIL','PHONE') then
        raise exception 'CANDIDATE_REJECTED_REPLACEMENT_ROUTE_INVALID' using errcode='55000';
      end if;
      v_payload:=jsonb_build_object(
        'workflow_kind',v_workflow_kind,
        'scope',v_scope,
        'route',v_initial_route,
        'target_timesheet_id',v_daily_timesheet.timesheet_id
      );
    else
      v_workflow_kind:=case
        when v_source_workflow.rejection_scope='COMPLETE_EXPENSE_CLAIM'
          or v_source_workflow.workflow_kind='CONTRACT_EXPENSE'
          then 'CONTRACT_EXPENSE'
        when v_source_workflow.workflow_kind='CONTRACT_COMBINED'
          then 'CONTRACT_COMBINED'
        else 'CONTRACT_HOURS'
      end;
      v_scope:='WEEKLY';

      select source_timesheet.* into v_source_anchor
      from public.timesheets source_timesheet
      where source_timesheet.timesheet_id=coalesce(
        v_source_workflow.anchor_timesheet_id,v_source_workflow.target_timesheet_id
      );
      if not found then
        raise exception 'CANDIDATE_WORKFLOW_ANCHOR_MISMATCH' using errcode='40001';
      end if;
      select count(distinct current_timesheet.timesheet_id)::integer,
        min(current_timesheet.timesheet_id::text)::uuid
      into v_current_anchor_count,v_current_anchor_timesheet_id
      from public.timesheets current_timesheet
      where current_timesheet.is_current=true
        and current_timesheet.archived_at_utc is null
        and current_timesheet.contract_id is not distinct from v_source_anchor.contract_id
        and current_timesheet.week_ending_date is not distinct from v_source_anchor.week_ending_date
        and (
          (
            nullif(btrim(coalesce(v_source_anchor.booking_id,'')),'') is not null
            and nullif(btrim(coalesce(current_timesheet.booking_id,'')),'')
              =nullif(btrim(v_source_anchor.booking_id),'')
          )
          or (
            nullif(btrim(coalesce(v_source_anchor.booking_id,'')),'') is null
            and current_timesheet.timesheet_id=v_source_anchor.timesheet_id
          )
        );
      if v_current_anchor_count<>1 or v_current_anchor_timesheet_id is null then
        raise exception 'CANDIDATE_WORKFLOW_ANCHOR_MISMATCH' using errcode='40001';
      end if;
      select current_timesheet.* into v_anchor_timesheet
      from public.timesheets current_timesheet
      where current_timesheet.timesheet_id=v_current_anchor_timesheet_id
      for update;
      select current_week.* into v_week
      from public.contract_weeks current_week
      where current_week.timesheet_id=v_anchor_timesheet.timesheet_id
        and current_week.contract_id=v_source_workflow.contract_id
        and current_week.week_ending_date=v_source_workflow.week_ending_date;
      if not found then
        raise exception 'CANDIDATE_WORKFLOW_WEEK_NOT_FOUND' using errcode='P0002';
      end if;

      v_initial_route:=upper(coalesce(
        v_source_workflow.creation_identity_json#>>'{derived,initial_route}',
        case when v_source_workflow.route='PAPER' then 'PAPER' else 'ELECTRONIC' end
      ));
      v_route_authority:=private._candidate_route_family_v1(
        v_anchor_timesheet.timesheet_id,v_week.id
      );
      if v_initial_route='PAPER'
         and (
           v_route_authority->>'route_family'='QR'
           or (
             v_route_authority->>'route_family'='ELECTRONIC'
             and coalesce(
               (v_route_authority->>'candidate_paper_submission_allowed')::boolean,
               false
             )
           )
         ) then
        v_initial_route:='PAPER';
      else
        v_initial_route:='ELECTRONIC';
      end if;
      v_payload:=jsonb_build_object(
        'workflow_kind',v_workflow_kind,
        'scope',v_scope,
        'route',v_initial_route,
        'contract_id',v_source_workflow.contract_id,
        'contract_week_id',v_week.id,
        'week_ending_date',v_week.week_ending_date,
        'anchor_timesheet_id',v_anchor_timesheet.timesheet_id
      );
    end if;
    v_action:='CREATE';
  end if;

  if v_action='CREATE' then
    if nullif(btrim(coalesce(p_idempotency_key,'')),'') is null then
      raise exception 'CANDIDATE_IDEMPOTENCY_KEY_REQUIRED' using errcode='22023';
    end if;
    if not v_is_rejected_resubmission then
      perform pg_advisory_xact_lock(hashtextextended(
        'candidate-workflow-idempotency|'||v_account_id::text||'|'||btrim(p_idempotency_key),0
      ));
      v_insert_workflow_id:=p_workflow_id;
    end if;
    v_workflow_kind:=upper(coalesce(v_payload->>'workflow_kind',''));
    v_scope:=upper(coalesce(v_payload->>'scope',''));
    v_route:=upper(coalesce(v_payload->>'route',''));
    if v_workflow_kind not in ('CONTRACT_HOURS','CONTRACT_EXPENSE','CONTRACT_COMBINED','DAILY')
       or v_scope not in ('WEEKLY','DAILY')
       or v_route not in ('ELECTRONIC','PHONE','EMAIL','PAPER') then
      raise exception 'CANDIDATE_WORKFLOW_TYPE_INVALID' using errcode='22023';
    end if;
    if not v_is_rejected_resubmission then
      if v_workflow_kind='DAILY' then
        select requested_timesheet.* into v_source_anchor
        from public.timesheets requested_timesheet
        where requested_timesheet.timesheet_id=nullif(v_payload->>'target_timesheet_id','')::uuid;
        if not found then
          raise exception 'CANDIDATE_DAILY_SHIFT_NOT_FOUND' using errcode='P0002';
        end if;
      end if;
      v_creation_request_identity:=jsonb_strip_nulls(jsonb_build_object(
        'version','CANDIDATE_WORKFLOW_CREATION_REQUEST_V1',
        'action','CREATE',
        'environment',v_environment,
        'account_id',v_account_id,
        'candidate_id',v_candidate_id,
        'workflow_kind',v_workflow_kind,
        'scope',v_scope,
        'initial_route',v_route,
        'contract_id',nullif(v_payload->>'contract_id','')::uuid,
        'contract_week_id',nullif(v_payload->>'contract_week_id','')::uuid,
        'week_ending_date',nullif(v_payload->>'week_ending_date','')::date,
        'work_date',nullif(v_payload->>'work_date','')::date,
        'daily_booking_id',case when v_workflow_kind='DAILY'
          then nullif(btrim(coalesce(v_source_anchor.booking_id,'')),'') else null end,
        'target_timesheet_id',case when v_workflow_kind='DAILY'
          and nullif(btrim(coalesce(v_source_anchor.booking_id,'')),'') is null
          then v_source_anchor.timesheet_id else null end,
        'requested_anchor_timesheet_id',nullif(v_payload->>'anchor_timesheet_id','')::uuid,
        'input_snapshot',coalesce(v_payload->'input_snapshot','{}'::jsonb),
        'expected_row_signature',nullif(v_payload->>'expected_row_signature','')
      ));
      v_creation_request_sha256:=private._candidate_workflow_creation_request_sha256_v1(
        v_creation_request_identity
      );
      select * into v_existing_workflow
      from public.candidate_submission_workflows
      where account_id=v_account_id
        and idempotency_key=btrim(p_idempotency_key)
      for update;
      if found then
        if v_existing_workflow.candidate_id is distinct from v_candidate_id
           or v_existing_workflow.replacement_of_workflow_id is not null
           or v_existing_workflow.creation_request_sha256 is distinct from v_creation_request_sha256 then
          raise exception 'CANDIDATE_IDEMPOTENCY_CONFLICT' using errcode='40001';
        end if;
        return jsonb_build_object(
          'ok',true,'idempotent_replay',true,
          'workflow_id',v_existing_workflow.id,
          'state',v_existing_workflow.state,
          'generation',v_existing_workflow.generation
        );
      end if;
    end if;
    if v_workflow_kind='DAILY' then
      if v_scope<>'DAILY' or v_route not in ('PHONE','EMAIL')
         or nullif(v_payload->>'target_timesheet_id','') is null
         or nullif(v_payload->>'contract_week_id','') is not null
         or nullif(v_payload->>'week_ending_date','') is not null then
        raise exception 'CANDIDATE_DAILY_IDENTITY_INVALID' using errcode='22023';
      end if;
      select * into v_daily_timesheet
      from public.timesheets
      where timesheet_id=(v_payload->>'target_timesheet_id')::uuid
        and is_current=true
        and archived_at_utc is null
        and sheet_scope='DAILY'::public.timesheet_scope_enum
        and nullif(btrim(coalesce(booking_id,'')),'') is not null
      for update;
      if not found then raise exception 'CANDIDATE_DAILY_SHIFT_NOT_FOUND' using errcode='P0002'; end if;
      if not private._candidate_daily_entitled_v1(v_candidate_id) then
        raise exception 'CANDIDATE_DAILY_ENTITLEMENT_REQUIRED' using errcode='55000';
      end if;
      select * into v_daily_fin
      from public.timesheets_financials
      where timesheet_id=v_daily_timesheet.timesheet_id
        and is_current=true
        and candidate_id=v_candidate_id
      order by computed_at_utc desc nulls last,updated_at desc,id desc
      limit 1
      for update;
      if not found then raise exception 'CANDIDATE_DAILY_SHIFT_NOT_FOUND' using errcode='P0002'; end if;
      if v_daily_fin.authorised_at_utc is not null
         or v_daily_fin.paid_at_utc is not null
         or v_daily_fin.locked_by_invoice_id is not null
         or v_daily_timesheet.archived_at_utc is not null then
        raise exception 'CANDIDATE_RECORD_MUTATION_LOCKED' using errcode='55000';
      end if;
      v_canonical_work_date:=private._candidate_daily_work_date_v1(
        coalesce(v_daily_fin.worked_start_iso,v_daily_timesheet.worked_start_iso),
        v_daily_timesheet.scheduled_start_iso,
        v_daily_timesheet.week_ending_date
      );
      if v_canonical_work_date is null
         or (nullif(v_payload->>'work_date','') is not null
             and (v_payload->>'work_date')::date<>v_canonical_work_date)
         or (nullif(v_payload->>'anchor_timesheet_id','') is not null
             and (v_payload->>'anchor_timesheet_id')::uuid<>v_daily_timesheet.timesheet_id) then
        raise exception 'CANDIDATE_DAILY_SHIFT_IDENTITY_MISMATCH' using errcode='22023';
      end if;
      if v_daily_timesheet.contract_id is not null then
        select * into v_contract
        from public.contracts
        where id=v_daily_timesheet.contract_id and candidate_id=v_candidate_id
        for update;
        if not found then raise exception 'CANDIDATE_DAILY_SHIFT_NOT_FOUND' using errcode='P0002'; end if;
      end if;
      v_client_id:=coalesce(v_daily_fin.client_id,v_contract.client_id);
      if v_client_id is null then raise exception 'CANDIDATE_DAILY_CLIENT_NOT_FOUND' using errcode='P0002'; end if;
      v_route_authority:=private._candidate_route_family_v1(v_daily_timesheet.timesheet_id,null);
      if v_route_authority->>'route_family'<>'ELECTRONIC' then
        raise exception 'CANDIDATE_ROUTE_FAMILY_MISMATCH'
          using errcode='55000',detail=v_route_authority::text;
      end if;
      v_policy:=private._candidate_policy_resolve_v1(v_client_id,v_contract.id,v_canonical_work_date);
      if (v_route='PHONE' and not coalesce((v_policy->>'allow_daily_manager_authorise_on_phone')::boolean,false))
         or (v_route='EMAIL' and not coalesce((v_policy->>'allow_daily_manager_authorise_by_email')::boolean,false)) then
        raise exception 'CANDIDATE_DAILY_APPROVAL_ROUTE_NOT_ALLOWED' using errcode='55000';
      end if;
      v_canonical_week_ending_date:=null;
    else
      if v_scope<>'WEEKLY' or v_route not in ('ELECTRONIC','PAPER')
         or nullif(v_payload->>'contract_id','') is null
         or nullif(v_payload->>'contract_week_id','') is null then
        raise exception 'CANDIDATE_CONTRACT_WORKFLOW_IDENTITY_REQUIRED' using errcode='22023';
      end if;
      select * into v_contract
      from public.contracts
      where id=(v_payload->>'contract_id')::uuid and candidate_id=v_candidate_id
      for update;
      if not found then raise exception 'CANDIDATE_WORKFLOW_CONTRACT_NOT_FOUND' using errcode='P0002'; end if;
      select * into v_week
      from public.contract_weeks
      where id=(v_payload->>'contract_week_id')::uuid and contract_id=v_contract.id
      for update;
      if not found then raise exception 'CANDIDATE_WORKFLOW_WEEK_NOT_FOUND' using errcode='P0002'; end if;
      v_canonical_week_ending_date:=v_week.week_ending_date;
      if nullif(v_payload->>'week_ending_date','') is not null
         and (v_payload->>'week_ending_date')::date<>v_canonical_week_ending_date then
        raise exception 'CANDIDATE_WORKFLOW_WEEK_MISMATCH' using errcode='22023';
      end if;
      v_policy:=private._candidate_policy_resolve_v1(v_contract.client_id,v_contract.id,v_canonical_week_ending_date);
      v_route_authority:=private._candidate_route_family_v1(v_week.timesheet_id,v_week.id);
      if v_route_authority->>'route_family'='MANUAL_NON_QR'
         or (v_route_authority->>'route_family'='IMPORT_AUTHORITATIVE'
           and v_workflow_kind<>'CONTRACT_EXPENSE') then
        raise exception 'CANDIDATE_RECORD_VIEW_ONLY' using errcode='55000',detail=v_route_authority::text;
      end if;
      if (v_route_authority->>'route_family'='QR' and v_route<>'PAPER')
         or (v_route_authority->>'route_family'='ELECTRONIC' and v_route='PAPER'
           and not coalesce((v_route_authority->>'candidate_paper_submission_allowed')::boolean,false))
         or (v_route_authority->>'route_family'='IMPORT_AUTHORITATIVE' and v_route='PAPER') then
        raise exception 'CANDIDATE_ROUTE_FAMILY_MISMATCH' using errcode='55000',detail=v_route_authority::text;
      end if;
      if v_week.timesheet_id is not null then
        select * into v_anchor_timesheet
        from public.timesheets
        where timesheet_id=v_week.timesheet_id
          and is_current=true
          and archived_at_utc is null;
        if not found then raise exception 'CANDIDATE_WORKFLOW_TARGET_NOT_CURRENT' using errcode='55000'; end if;
        if v_workflow_kind in ('CONTRACT_HOURS','CONTRACT_COMBINED') then
          v_target_capabilities:=private._candidate_record_capabilities_v1(
            v_week.timesheet_id,v_week.id,'{}'::jsonb
          );
          if coalesce((v_target_capabilities->>'candidate_mutation_locked')::boolean,false)
             or coalesce((v_target_capabilities->>'protected')::boolean,false)
             or not coalesce((v_target_capabilities->>'can_edit_hours')::boolean,false) then
            raise exception 'CANDIDATE_RECORD_MUTATION_LOCKED' using errcode='55000';
          end if;
        end if;
      end if;
      if nullif(v_payload->>'target_timesheet_id','') is not null then
        if v_workflow_kind='CONTRACT_EXPENSE' then
          raise exception 'CANDIDATE_EXPENSE_TARGET_SERVER_RESOLVED' using errcode='22023';
        end if;
        if v_week.timesheet_id is null
           or (v_payload->>'target_timesheet_id')::uuid<>v_week.timesheet_id then
          raise exception 'CANDIDATE_WORKFLOW_TARGET_MISMATCH' using errcode='22023';
        end if;
      end if;
      if nullif(v_payload->>'anchor_timesheet_id','') is not null then
        select cw.* into v_anchor_week
        from public.contract_weeks cw
        join public.timesheets t on t.timesheet_id=cw.timesheet_id
          and t.is_current=true and t.archived_at_utc is null
        where cw.timesheet_id=(v_payload->>'anchor_timesheet_id')::uuid
          and cw.contract_id=v_contract.id
          and cw.week_ending_date=v_canonical_week_ending_date;
        if not found then raise exception 'CANDIDATE_WORKFLOW_ANCHOR_MISMATCH' using errcode='22023'; end if;
        if v_workflow_kind='CONTRACT_EXPENSE'
           and coalesce((private._candidate_record_capabilities_v1(v_anchor_week.timesheet_id,v_anchor_week.id,'{}'::jsonb)->>'hours_value')::numeric,0)<=0
           and coalesce((private._candidate_record_capabilities_v1(v_anchor_week.timesheet_id,v_anchor_week.id,'{}'::jsonb)->>'additional_units_value')::numeric,0)<=0 then
          raise exception 'CANDIDATE_WORKFLOW_ANCHOR_NOT_WORKED' using errcode='22023';
        end if;
      elsif v_workflow_kind='CONTRACT_EXPENSE' then
        select count(*)::integer,min(worked.id::text)::uuid
        into v_anchor_candidate_count,v_anchor_week_id
        from public.contract_weeks worked
        join public.timesheets t on t.timesheet_id=worked.timesheet_id
          and t.is_current=true and t.archived_at_utc is null
        join public.timesheets_financials tf on tf.timesheet_id=t.timesheet_id and tf.is_current=true
        where worked.contract_id=v_contract.id
          and worked.week_ending_date=v_canonical_week_ending_date
          and (
            coalesce(tf.total_hours,0)>0
            or private._candidate_json_numeric_sum(coalesce(tf.additional_units_json,'{}'::jsonb))>0
            or private._candidate_json_numeric_sum(coalesce(t.additional_units_week,'{}'::jsonb))
              +private._candidate_json_numeric_sum(coalesce(t.additional_units_per_day,'{}'::jsonb))>0
          );
        if v_anchor_candidate_count=0 then raise exception 'NO_POSITIVE_WORKED_TIME' using errcode='55000'; end if;
        if v_anchor_candidate_count>1 then raise exception 'EXPENSE_WORKED_ANCHOR_AMBIGUOUS' using errcode='55000'; end if;
        select * into v_anchor_week from public.contract_weeks where id=v_anchor_week_id;
      elsif v_week.timesheet_id is not null then
        v_anchor_week:=v_week;
      end if;
    end if;

    -- Store the immutable request receipt together with the canonical identity
    -- that the server derived at creation time. Later workflow lifecycle changes
    -- may alter route, target, contract-week and generation fields, but must never
    -- alter this receipt or make an exact creation retry conflict.
    v_creation_identity:=jsonb_build_object(
      'version','CANDIDATE_WORKFLOW_CREATION_IDENTITY_V1',
      'request',v_creation_request_identity,
      'derived',jsonb_strip_nulls(jsonb_build_object(
        'workflow_kind',v_workflow_kind,
        'scope',v_scope,
        'initial_route',v_route,
        'contract_id',v_contract.id,
        'contract_week_id',case when v_workflow_kind='DAILY' then null else v_week.id end,
        'anchor_timesheet_id',case when v_workflow_kind='DAILY'
          then v_daily_timesheet.timesheet_id else v_anchor_week.timesheet_id end,
        'daily_booking_id',case when v_workflow_kind='DAILY'
          then nullif(btrim(coalesce(v_daily_timesheet.booking_id,'')),'') else null end,
        'work_date',v_canonical_work_date,
        'week_ending_date',v_canonical_week_ending_date,
        'replacement_of_workflow_id',v_replacement_of_workflow_id
      ))
    );

    select * into v_existing_workflow
    from public.candidate_submission_workflows
    where account_id=v_account_id
      and idempotency_key=btrim(p_idempotency_key)
    for update;
    if found then
      if v_existing_workflow.candidate_id is distinct from v_candidate_id
         or v_existing_workflow.replacement_of_workflow_id is distinct from v_replacement_of_workflow_id
         or v_existing_workflow.creation_request_sha256 is distinct from v_creation_request_sha256 then
        raise exception 'CANDIDATE_IDEMPOTENCY_CONFLICT' using errcode='40001';
      end if;
      if v_is_rejected_resubmission then
        return jsonb_build_object(
          'ok',true,'idempotent_replay',true,
          'rejected_workflow_id',v_replacement_of_workflow_id,
          'replacement_workflow_id',v_existing_workflow.id,
          'replacement_created',false,
          'workflow_id',v_existing_workflow.id,
          'state',v_existing_workflow.state,
          'generation',v_existing_workflow.generation
        );
      end if;
      return jsonb_build_object('ok',true,'idempotent_replay',true,
        'workflow_id',v_existing_workflow.id,'state',v_existing_workflow.state,
        'generation',v_existing_workflow.generation);
    end if;

    if v_workflow_kind in ('CONTRACT_EXPENSE','CONTRACT_COMBINED') then
      perform pg_advisory_xact_lock(hashtext(
        v_candidate_id::text||'|'||v_contract.id::text||'|'||
        v_canonical_week_ending_date::text||
        '|CANDIDATE_EXPENSE_CLAIM'
      ));
      if exists(
        select 1
        from public.candidate_submission_workflows prior
        where prior.candidate_id=v_candidate_id
          and prior.contract_id=v_contract.id
          and prior.week_ending_date=v_canonical_week_ending_date
          and prior.workflow_kind in ('CONTRACT_EXPENSE','CONTRACT_COMBINED')
          and prior.state not in ('CANCELLED','REJECTED','REFUSED','EXPIRED','SUPERSEDED')
          and (
            prior.state<>'FINALISED'
            or prior.target_timesheet_id is null
            or not exists(
              select 1
              from public.timesheets_financials prior_fin
              where prior_fin.timesheet_id=prior.target_timesheet_id
                and prior_fin.is_current=true
                and prior_fin.authorised_at_utc is not null
            )
          )
      ) or exists(
        select 1
        from public.contract_weeks prior_week
        join public.timesheets prior_timesheet
          on prior_timesheet.timesheet_id=prior_week.timesheet_id
         and prior_timesheet.is_current=true
         and prior_timesheet.archived_at_utc is null
        join public.timesheets_financials prior_fin
          on prior_fin.timesheet_id=prior_timesheet.timesheet_id
         and prior_fin.is_current=true
        where prior_week.contract_id=v_contract.id
          and prior_week.week_ending_date=v_canonical_week_ending_date
          and prior_fin.authorised_at_utc is null
          and (
            abs(coalesce(prior_fin.expenses_pay_ex_vat,0))
            +abs(coalesce(prior_fin.expenses_charge_ex_vat,0))
            +abs(coalesce(prior_fin.mileage_units,0))
            +abs(coalesce(prior_fin.mileage_pay_ex_vat,0))
            +abs(coalesce(prior_fin.mileage_charge_ex_vat,0))
            +abs(coalesce(prior_fin.travel_pay_ex_vat,0))
            +abs(coalesce(prior_fin.travel_charge_ex_vat,0))
            +abs(coalesce(prior_fin.accommodation_pay_ex_vat,0))
            +abs(coalesce(prior_fin.accommodation_charge_ex_vat,0))
            +abs(coalesce(prior_fin.other_pay_ex_vat,0))
            +abs(coalesce(prior_fin.other_charge_ex_vat,0))
          )>0
      ) then
        raise exception 'CANDIDATE_EXPENSE_CLAIM_ALREADY_ACTIVE' using errcode='55000';
      end if;
    end if;
    insert into public.candidate_submission_workflows(
      id,environment,account_id,candidate_id,workflow_kind,scope,route,state,generation,
      contract_id,contract_week_id,anchor_timesheet_id,target_timesheet_id,work_date,week_ending_date,
      policy_snapshot_json,input_snapshot_json,issue_codes,expected_row_signature,idempotency_key,
      replacement_of_workflow_id,creation_request_sha256,creation_identity_json,
      last_mutation_idempotency_key,created_at_utc,updated_at_utc
    ) values (
      v_insert_workflow_id,v_environment,v_account_id,v_candidate_id,v_workflow_kind,
      v_scope,v_route,'WORKER_DRAFT',1,v_contract.id,
      case when v_workflow_kind='DAILY' then null else v_week.id end,
      case when v_workflow_kind='DAILY' then v_daily_timesheet.timesheet_id else v_anchor_week.timesheet_id end,
      case
        when v_workflow_kind='DAILY' then v_daily_timesheet.timesheet_id
        when v_workflow_kind='CONTRACT_EXPENSE' then null
        else v_week.timesheet_id
      end,
      v_canonical_work_date,v_canonical_week_ending_date,
      v_policy,coalesce(v_payload->'input_snapshot','{}'::jsonb),'[]'::jsonb,
      nullif(v_payload->>'expected_row_signature',''),btrim(p_idempotency_key),
      v_replacement_of_workflow_id,v_creation_request_sha256,v_creation_identity,
      btrim(p_idempotency_key),p_now_utc,p_now_utc
    ) returning * into v_workflow;
    perform private._candidate_audit_v1('candidate_submission_workflow',v_workflow.id::text,
      'CANDIDATE_WORKFLOW_CREATED',null,
      jsonb_build_object('kind',v_workflow.workflow_kind,'scope',v_workflow.scope,'route',v_workflow.route),
      null,null,p_idempotency_key,p_now_utc);
    if v_is_rejected_resubmission then
      return jsonb_build_object(
        'ok',true,'idempotent_replay',false,
        'rejected_workflow_id',v_replacement_of_workflow_id,
        'replacement_workflow_id',v_workflow.id,
        'replacement_created',true,
        'workflow_id',v_workflow.id,'state',v_workflow.state,
        'generation',v_workflow.generation,'policy',v_policy
      );
    end if;
    return jsonb_build_object('ok',true,'idempotent_replay',false,
      'workflow_id',v_workflow.id,'state',v_workflow.state,
      'generation',v_workflow.generation,'policy',v_policy);
  end if;

  if v_workflow.id is null then
    if v_action in ('PAPER_PREPARE','PAPER_RETURN','AMEND','CANCEL','SUPERSEDE') then
      -- Keep the canonical route/document lock order used by
      -- timesheet_qr_send_enqueue_v1: current timesheet, then workflow.
      -- The unlocked identity read is rechecked after both locks are held.
      select * into v_workflow
      from public.candidate_submission_workflows
      where id=p_workflow_id
        and environment=v_environment
        and candidate_id=v_candidate_id;
      if not found then
        raise exception 'CANDIDATE_WORKFLOW_NOT_FOUND' using errcode='P0002';
      end if;
      v_unlocked_workflow_updated_at:=v_workflow.updated_at_utc;
      v_paper_timesheet_id:=coalesce(v_workflow.target_timesheet_id,v_workflow.anchor_timesheet_id);
      v_paper_family_key:='CANDIDATE_PAPER_FAMILY:'||v_workflow.environment||':'
        ||coalesce(v_workflow.contract_id::text,'-')||':'
        ||coalesce(v_workflow.week_ending_date::text,v_workflow.work_date::text,'-');
      perform pg_advisory_xact_lock(hashtextextended(v_paper_family_key,0));
      if v_action='PAPER_PREPARE' and v_paper_timesheet_id is null then
        raise exception 'CANDIDATE_PAPER_TIMESHEET_NOT_READY' using errcode='55000';
      end if;
      if v_paper_timesheet_id is not null
         and (v_action in ('PAPER_PREPARE','PAPER_RETURN')
           or (v_workflow.route='PAPER'
             and v_workflow.state in ('AWAITING_PAPER_RETURN','RECEIVED'))) then
        perform 1
        from public.timesheets
        where timesheet_id=v_paper_timesheet_id
          and is_current=true
          and archived_at_utc is null
        for update;
        if not found then
          raise exception 'CANDIDATE_PAPER_TIMESHEET_NOT_READY' using errcode='55000';
        end if;
      end if;
      select * into v_workflow
      from public.candidate_submission_workflows
      where id=p_workflow_id
        and environment=v_environment
        and candidate_id=v_candidate_id
      for update;
      if not found
         or coalesce(v_workflow.target_timesheet_id,v_workflow.anchor_timesheet_id)
              is distinct from v_paper_timesheet_id then
        raise exception 'CANDIDATE_WORKFLOW_CONTEXT_CONFLICT' using errcode='40001';
      end if;
      if v_action in ('PAPER_RETURN','AMEND','CANCEL','SUPERSEDE')
         and v_workflow.updated_at_utc is distinct from v_unlocked_workflow_updated_at then
        raise exception 'CANDIDATE_WORKFLOW_CONTEXT_CONFLICT' using errcode='40001';
      end if;
    else
      select * into v_workflow
      from public.candidate_submission_workflows
      where id=p_workflow_id
      for update;
    end if;
  end if;
  if not found or v_workflow.environment<>v_environment
     or (not v_is_service_action and not v_is_public_manager_action and v_workflow.candidate_id<>v_candidate_id) then
    raise exception 'CANDIDATE_WORKFLOW_NOT_FOUND' using errcode='P0002';
  end if;
  if nullif(btrim(coalesce(p_idempotency_key,'')),'') is not null then
    if nullif(btrim(coalesce(v_workflow.idempotency_key,'')),'')=btrim(p_idempotency_key) then
      raise exception 'CANDIDATE_IDEMPOTENCY_CONFLICT'
        using errcode='40001',detail=jsonb_build_object(
          'code','CANDIDATE_IDEMPOTENCY_CONFLICT',
          'workflow_id',v_workflow.id,
          'idempotency_key',btrim(p_idempotency_key),
          'reason','CREATION_KEY_REUSED_FOR_MUTATION'
        )::text;
    end if;
    v_mutation_channel:=case
      when v_is_office_service_action then 'OFFICE'
      when v_is_public_manager_action then 'MANAGER_PUBLIC'
      when v_is_service_action then 'SERVICE'
      else 'CANDIDATE_CLIENT' end;
    v_mutation_actor_identity:=case
      when v_is_office_service_action then v_office_actor_user_id::text
      when v_is_public_manager_action then 'MANAGER_REQUEST:'||coalesce(v_request_id::text,'UNKNOWN')
      when v_is_service_action then 'SERVICE:'||v_action
      else 'ACCOUNT:'||coalesce(v_account_id::text,'UNKNOWN')
        ||':CANDIDATE:'||coalesce(v_candidate_id::text,'UNKNOWN') end;
    v_mutation_semantic_payload:=case
      when v_mutation_replay_probe_only then
        v_payload->'mutation_replay_semantic_payload'
      when v_action='COMPONENT_PREPARE' then
        v_payload-'service_office_action'-'actor_user_id'-'storage_key'
      when v_action='SELECT_PHONE_APPROVAL' then
        v_payload-'service_office_action'-'actor_user_id'-'expires_at_utc'
          -'approval_token_hash_hex'-'handoff_token_key_version'-'broker_handoff_key_version'
      when v_action='WORKER_SUBMIT' then
        case when jsonb_typeof(v_payload->'submission_request_identity')='object'
          then jsonb_build_object(
            'submission_request_identity',v_payload->'submission_request_identity'
          )
          else (v_payload-'service_office_action'-'actor_user_id'-'renderer_contract_version'-'immutable_submission')
            ||jsonb_build_object(
              'immutable_submission',coalesce(v_payload->'immutable_submission','{}'::jsonb)-'official_presentation'
            )
        end
      when v_action='CREATE_EMAIL_APPROVAL_REQUEST' then
        v_payload-'service_office_action'-'actor_user_id'-'mail'-'approval_token_hash_hex'
      when v_action in ('REMIND','RENEW') then
        v_payload-'service_office_action'-'actor_user_id'-'mail'-'approval_token_hash_hex'-'manager_email'
      else v_payload-'service_office_action'-'actor_user_id'
    end;
    v_mutation_request_sha256:=encode(extensions.digest(convert_to(jsonb_build_object(
      'contract_version','CANDIDATE_WORKFLOW_MUTATION_REQUEST_V1',
      'workflow_id',v_workflow.id,
      'action',v_action,
      'expected_generation',p_expected_generation,
      'payload',v_mutation_semantic_payload,
      'channel',v_mutation_channel,
      'actor_identity',v_mutation_actor_identity
    )::text,'UTF8'),'sha256'),'hex');
    v_mutation_receipt:=private._candidate_workflow_mutation_receipt_v1(
      v_workflow.id,btrim(p_idempotency_key),v_mutation_request_sha256,
      v_action,v_mutation_channel,v_mutation_actor_identity,null,p_now_utc
    );
    if coalesce((v_mutation_receipt->>'found')::boolean,false) then
      return v_mutation_receipt->'response';
    end if;
    if v_mutation_replay_probe_only then
      return jsonb_build_object(
        'ok',true,'replay_found',false,'workflow_id',v_workflow.id,
        'expected_generation',p_expected_generation
      );
    end if;
  end if;
  if p_expected_generation is not null and v_workflow.generation<>p_expected_generation then
    raise exception 'WORKFLOW_GENERATION_CONFLICT'
      using errcode='40001',detail=jsonb_build_object(
        'code','WORKFLOW_GENERATION_CONFLICT','current_generation',v_workflow.generation)::text;
  end if;
  v_next_generation:=v_workflow.generation+1;
  if v_workflow.contract_id is not null then
    select * into v_contract from public.contracts where id=v_workflow.contract_id;
    v_policy:=private._candidate_policy_resolve_v1(v_contract.client_id,v_contract.id,
      coalesce(v_workflow.week_ending_date,v_workflow.work_date,(p_now_utc at time zone 'Europe/London')::date));
  else
    v_policy:=v_workflow.policy_snapshot_json;
  end if;

  if v_action='AMEND' then
    if v_workflow.state not in (
      'WORKER_SUBMITTED','WORKER_SUBMITTED_PENDING_REVIEW_DOCUMENT',
      'READY_FOR_MANAGER_APPROVAL','AWAITING_MANAGER_APPROVAL',
      'AWAITING_PAPER_RETURN','REFUSED'
    ) then
      raise exception 'CANDIDATE_WORKFLOW_AMENDMENT_NOT_ALLOWED' using errcode='55000';
    end if;
    if nullif(btrim(coalesce(p_idempotency_key,'')),'') is null then
      raise exception 'CANDIDATE_IDEMPOTENCY_KEY_REQUIRED' using errcode='22023';
    end if;
    if v_workflow.route='PAPER' and v_workflow.state='AWAITING_PAPER_RETURN' then
      v_paper_retirement_result:=private._candidate_paper_delivery_retire_v1(
        v_workflow.id,v_workflow.generation,'WORKFLOW_AMENDED',p_now_utc
      );
    end if;
    update public.candidate_approval_requests set
      state='SUPERSEDED',superseded_at_utc=p_now_utc,updated_at_utc=p_now_utc
    where workflow_id=v_workflow.id and state in ('PENDING','APPROVED');
    v_component_no:=0;
    for v_source_component in
      select source_component.*
      from public.candidate_submission_components source_component
      where source_component.workflow_id=v_workflow.id
        and source_component.workflow_generation=v_workflow.generation
        and source_component.component_kind in ('MILEAGE_FORM','EXPENSE_EVIDENCE')
        and source_component.state='IMMUTABLE'
        and source_component.source_content_sha256 is not null
      order by source_component.component_no,source_component.id
    loop
      v_component_no:=v_component_no+1;
      insert into public.candidate_submission_components(
        workflow_id,workflow_generation,component_no,timesheet_id,component_kind,expense_category,
        document_role,state,source_component_id,storage_key,media_type,byte_size,source_content_sha256,
        immutable_at_utc,required,review_render_state,final_signed_render_state,created_at_utc
      ) values (
        v_workflow.id,v_next_generation,v_component_no,v_workflow.target_timesheet_id,
        v_source_component.component_kind,v_source_component.expense_category,v_source_component.document_role,
        'IMMUTABLE',coalesce(v_source_component.source_component_id,v_source_component.id),
        v_source_component.storage_key,v_source_component.media_type,v_source_component.byte_size,
        v_source_component.source_content_sha256,p_now_utc,false,'NOT_REQUIRED','NOT_REQUIRED',p_now_utc
      );
    end loop;
    update public.candidate_submission_components set
      state='SUPERSEDED',superseded_at_utc=p_now_utc,
      review_render_state=case when review_render_state='NOT_REQUIRED' then review_render_state else 'SUPERSEDED' end,
      final_signed_render_state=case when final_signed_render_state='NOT_REQUIRED' then final_signed_render_state else 'SUPERSEDED' end
    where workflow_id=v_workflow.id
      and workflow_generation=v_workflow.generation
      and state<>'SUPERSEDED';
    v_response:=jsonb_build_object(
      'ok',true,'workflow_id',v_workflow.id,'state','WORKER_DRAFT',
      'generation',v_next_generation,'preserved_source_component_count',v_component_no
    );
    update public.candidate_submission_workflows set
      state='WORKER_DRAFT',generation=v_next_generation,
      input_snapshot_json=coalesce(v_payload->'input_snapshot',input_snapshot_json),
      candidate_signature_component_id=null,candidate_signature_sha256=null,candidate_signed_at_utc=null,
      review_manifest_json=null,review_manifest_sha256=null,paper_return_manifest_json=null,
      paper_return_manifest_sha256=null,renderer_contract_version=null,
      manager_name=null,manager_position=null,manager_signature_component_id=null,
      manager_signature_sha256=null,manager_approved_at_utc=null,
      issue_codes='[]'::jsonb,worker_submitted_at_utc=null,
      daily_context_sha256=null,canonical_financial_sha256=null,
      canonical_save_input_sha256=null,canonical_save_row_signature=null,
      canonical_save_financials_id=null,canonical_save_receipt_json=null,canonical_saved_at_utc=null,
      last_mutation_idempotency_key=p_idempotency_key,last_mutation_response_json=v_response,
      updated_at_utc=p_now_utc
    where id=v_workflow.id returning * into v_workflow;
    perform private._candidate_audit_v1('candidate_submission_workflow',v_workflow.id::text,
      'CANDIDATE_WORKFLOW_AMENDED',null,
      jsonb_build_object('generation',v_workflow.generation,'preserved_source_component_count',v_component_no),
      null,v_candidate_id,p_idempotency_key,p_now_utc);
    if v_mutation_request_sha256 is not null then
      perform private._candidate_workflow_mutation_receipt_v1(
        v_workflow.id,p_idempotency_key,v_mutation_request_sha256,v_action,
        v_mutation_channel,v_mutation_actor_identity,v_response,p_now_utc
      );
    end if;
    return v_response;
  elsif v_action='COMPONENT_PREPARE' then
    if v_workflow.state in ('FINALISED','CANCELLED','REJECTED','SUPERSEDED') then
      raise exception 'CANDIDATE_WORKFLOW_NOT_MUTABLE' using errcode='55000';
    end if;
    if nullif(btrim(coalesce(p_idempotency_key,'')),'') is null then
      raise exception 'CANDIDATE_IDEMPOTENCY_KEY_REQUIRED' using errcode='22023';
    end if;
    v_component_kind:=upper(btrim(coalesce(v_payload->>'component_kind','')));
    v_document_role:=upper(btrim(coalesce(v_payload->>'document_role','')));
    v_expense_category:=nullif(upper(btrim(coalesce(v_payload->>'expense_category',''))),'');
    v_paper_page_key:=nullif(btrim(coalesce(v_payload->>'paper_return_page_key','')),'');
    v_requested_media_type:=nullif(lower(btrim(coalesce(v_payload->>'media_type',''))),'');
    begin
      v_requested_byte_size:=nullif(v_payload->>'byte_size','')::bigint;
    exception when invalid_text_representation or numeric_value_out_of_range then
      raise exception 'CANDIDATE_COMPONENT_SIZE_INVALID' using errcode='22023';
    end;
    select * into v_component from public.candidate_submission_components
    where workflow_id=v_workflow.id and upload_idempotency_key=p_idempotency_key;
    if found then
      if v_component.workflow_generation is distinct from v_workflow.generation then
        raise exception 'CANDIDATE_COMPONENT_PREPARE_GENERATION_CONFLICT' using errcode='40001';
      end if;
      if v_component.state not in ('PENDING','IMMUTABLE') then
        raise exception 'CANDIDATE_COMPONENT_PREPARE_STATE_CONFLICT' using errcode='55000';
      end if;
      if v_component.component_kind is distinct from v_component_kind
         or v_component.document_role is distinct from v_document_role
         or v_component.expense_category is distinct from v_expense_category
         or lower(v_component.media_type) is distinct from v_requested_media_type
         or v_component.byte_size is distinct from v_requested_byte_size
         or v_component.paper_return_page_key is distinct from v_paper_page_key then
        raise exception 'CANDIDATE_COMPONENT_PREPARE_IDEMPOTENCY_CONFLICT' using errcode='23505';
      end if;
      v_response:=jsonb_build_object('ok',true,'idempotent_replay',true,
        'component_id',v_component.id,'component_no',v_component.component_no,
        'workflow_generation',v_component.workflow_generation,
        'storage_key',v_component.storage_key,'media_type',v_component.media_type,
        'byte_size',v_component.byte_size,'component_kind',v_component.component_kind,
        'document_role',v_component.document_role,'expense_category',v_component.expense_category,
        'paper_return_page_key',v_component.paper_return_page_key,'state',v_component.state);
      if v_mutation_request_sha256 is not null then
        perform private._candidate_workflow_mutation_receipt_v1(
          v_workflow.id,p_idempotency_key,v_mutation_request_sha256,v_action,
          v_mutation_channel,v_mutation_actor_identity,v_response,p_now_utc
        );
      end if;
      return v_response;
    end if;
    select coalesce(max(component_no),0)+1 into v_component_no
    from public.candidate_submission_components
    where workflow_id=v_workflow.id and workflow_generation=v_workflow.generation;
    if v_is_public_manager_action then
      if v_component_kind<>'MANAGER_SIGNATURE' or v_document_role<>'MANAGER_SIGNATURE' then
        raise exception 'MANAGER_SIGNATURE_COMPONENT_REQUIRED' using errcode='28000';
      end if;
      if v_approval.id is null
         or v_approval.state<>'PENDING'
         or v_approval.expires_at_utc<=p_now_utc
         or v_approval.workflow_generation<>v_workflow.generation
         or v_approval.review_manifest_sha256 is distinct from v_workflow.review_manifest_sha256 then
        raise exception 'MANAGER_APPROVAL_REQUEST_NOT_READY' using errcode='28000';
      end if;
    elsif v_component_kind='MANAGER_SIGNATURE' then
      select * into v_approval
      from public.candidate_approval_requests
      where id=nullif(v_payload->>'approval_request_id','')::uuid
        and workflow_id=v_workflow.id
        and workflow_generation=v_workflow.generation
        and method='PHONE'
        and state='PENDING'
        and review_manifest_sha256=v_workflow.review_manifest_sha256
      for update;
      if not found then raise exception 'MANAGER_APPROVAL_REQUEST_NOT_READY' using errcode='28000'; end if;
    elsif not coalesce((
      (v_component_kind='CANDIDATE_SIGNATURE' and v_document_role='CANDIDATE_SIGNATURE' and v_expense_category is null)
      or (v_component_kind='MILEAGE_FORM' and v_document_role='MILEAGE_CLAIM_FORM' and v_expense_category='MILEAGE')
      or (v_component_kind='EXPENSE_EVIDENCE' and v_document_role='SOURCE_EVIDENCE'
          and v_expense_category in ('TRAVEL','ACCOMMODATION','OTHER','MILEAGE'))
      or (v_component_kind='SIGNED_RETURN' and v_document_role='SIGNED_RETURN' and v_expense_category is null)
      or (v_component_kind='MANAGER_SIGNATURE' and v_document_role='MANAGER_SIGNATURE'
          and v_expense_category is null
          and v_workflow.state='AWAITING_MANAGER_APPROVAL'
          and exists(
            select 1 from public.candidate_approval_requests approval
            where approval.workflow_id=v_workflow.id
              and approval.workflow_generation=v_workflow.generation
              and approval.method='PHONE' and approval.state='PENDING'
          ))
    ),false) then
      raise exception 'CANDIDATE_COMPONENT_TYPE_INVALID' using errcode='22023';
    end if;
    if v_component_kind in ('CANDIDATE_SIGNATURE','MILEAGE_FORM','EXPENSE_EVIDENCE')
       and v_workflow.state<>'WORKER_DRAFT' then
      raise exception 'CANDIDATE_COMPONENT_AMENDMENT_REQUIRED' using errcode='55000';
    end if;
    if v_component_kind='SIGNED_RETURN' then
      if v_workflow.route<>'PAPER' or v_workflow.state<>'AWAITING_PAPER_RETURN'
         or v_workflow.paper_return_manifest_sha256 is null
         or not exists(
           select 1
           from jsonb_array_elements(v_workflow.paper_return_manifest_json->'pages') page
           where page->>'page_key'=v_paper_page_key
         ) then
        raise exception 'CANDIDATE_PAPER_RETURN_PAGE_NOT_EXPECTED' using errcode='22023';
      end if;
    elsif v_paper_page_key is not null then
      raise exception 'CANDIDATE_PAPER_RETURN_PAGE_KEY_FORBIDDEN' using errcode='22023';
    end if;
    if nullif(v_payload->>'source_component_id','') is not null then
      select source_component.* into v_source_component
      from public.candidate_submission_components source_component
      join public.candidate_submission_workflows source_workflow on source_workflow.id=source_component.workflow_id
      where source_component.id=(v_payload->>'source_component_id')::uuid
        and source_component.state in ('IMMUTABLE','SUPERSEDED','REJECTED')
        and source_component.immutable_at_utc is not null
        and source_component.source_content_sha256 is not null
        and source_component.source_component_id is null
        and source_workflow.environment=v_environment
        and source_workflow.account_id=v_account_id
        and source_workflow.candidate_id=v_candidate_id
        and (
          source_workflow.id=v_workflow.id
          or (
            source_workflow.contract_id is not distinct from v_workflow.contract_id
            and source_workflow.week_ending_date is not distinct from v_workflow.week_ending_date
            and source_workflow.state in ('CANCELLED','REJECTED','REFUSED','SUPERSEDED')
          )
        );
      if not found or v_source_component.component_kind<>v_component_kind
         or v_source_component.document_role<>v_document_role
         or v_source_component.expense_category is distinct from v_expense_category then
        raise exception 'CANDIDATE_SOURCE_COMPONENT_NOT_ALLOWED' using errcode='28000';
      end if;
    end if;
    insert into public.candidate_submission_components(
      workflow_id,workflow_generation,component_no,approval_request_id,timesheet_id,component_kind,expense_category,
      document_role,state,source_component_id,storage_key,media_type,byte_size,source_content_sha256,
      upload_idempotency_key,immutable_at_utc,
      required,review_ordinal,review_render_state,final_signed_render_state,paper_return_page_key,created_at_utc
    ) values (
      v_workflow.id,v_workflow.generation,v_component_no,
      case when v_component_kind='MANAGER_SIGNATURE' then v_approval.id else null end,
      v_workflow.target_timesheet_id,
      v_component_kind,v_expense_category,v_document_role,
      case when v_source_component.id is null then 'PENDING' else 'IMMUTABLE' end,
      v_source_component.id,
      coalesce(v_source_component.storage_key,nullif(v_payload->>'storage_key','')),
      coalesce(v_source_component.media_type,v_requested_media_type),
      coalesce(v_source_component.byte_size,v_requested_byte_size),
      v_source_component.source_content_sha256,p_idempotency_key,
      case when v_source_component.id is null then null else p_now_utc end,
      false,null,'NOT_REQUIRED','NOT_REQUIRED',v_paper_page_key,
      p_now_utc
    ) returning * into v_component;
    v_response:=jsonb_build_object('ok',true,'idempotent_replay',false,'component_id',v_component.id,
      'component_no',v_component.component_no,'workflow_generation',v_component.workflow_generation,
      'storage_key',v_component.storage_key,'media_type',v_component.media_type,
      'byte_size',v_component.byte_size,'component_kind',v_component.component_kind,
      'document_role',v_component.document_role,'expense_category',v_component.expense_category,
      'paper_return_page_key',v_component.paper_return_page_key,'state',v_component.state);
    perform private._candidate_workflow_mutation_receipt_v1(
      v_workflow.id,p_idempotency_key,v_mutation_request_sha256,v_action,
      v_mutation_channel,v_mutation_actor_identity,v_response,p_now_utc
    );
    return v_response;
  elsif v_action='COMPONENT_COMPLETE' then
    select * into v_component from public.candidate_submission_components
    where id=nullif(v_payload->>'component_id','')::uuid and workflow_id=v_workflow.id
      and workflow_generation=v_workflow.generation for update;
    if not found then raise exception 'CANDIDATE_COMPONENT_NOT_FOUND' using errcode='P0002'; end if;
    if v_is_public_manager_action and v_component.component_kind<>'MANAGER_SIGNATURE' then
      raise exception 'MANAGER_SIGNATURE_COMPONENT_REQUIRED' using errcode='28000';
    end if;
    if v_component.component_kind='MANAGER_SIGNATURE' then
      if v_approval.id is null then
        select * into v_approval
        from public.candidate_approval_requests
        where id=v_component.approval_request_id
          and workflow_id=v_workflow.id
          and workflow_generation=v_workflow.generation
          and method='PHONE'
          and state='PENDING'
          and review_manifest_sha256=v_workflow.review_manifest_sha256
        for update;
      end if;
      if not found or v_component.approval_request_id is distinct from v_approval.id
         or v_approval.state<>'PENDING'
         or v_approval.workflow_generation<>v_workflow.generation
         or v_approval.review_manifest_sha256 is distinct from v_workflow.review_manifest_sha256
         or v_approval.expires_at_utc<=p_now_utc then
        raise exception 'MANAGER_APPROVAL_REQUEST_NOT_READY' using errcode='28000';
      end if;
    elsif v_component.component_kind in ('CANDIDATE_SIGNATURE','MILEAGE_FORM','EXPENSE_EVIDENCE')
          and v_workflow.state<>'WORKER_DRAFT' then
      raise exception 'CANDIDATE_COMPONENT_AMENDMENT_REQUIRED' using errcode='55000';
    elsif v_component.component_kind='SIGNED_RETURN' and v_workflow.state<>'AWAITING_PAPER_RETURN' then
      raise exception 'CANDIDATE_PAPER_RETURN_PAGE_NOT_EXPECTED' using errcode='55000';
    end if;
    if coalesce(v_payload->>'source_content_sha256_hex','') !~ '^[0-9a-fA-F]{64}$' then
      raise exception 'CANDIDATE_COMPONENT_DIGEST_INVALID' using errcode='22023';
    end if;
    v_digest:=decode(v_payload->>'source_content_sha256_hex','hex');
    if (v_component.component_kind in ('CANDIDATE_SIGNATURE','MANAGER_SIGNATURE')
          and lower(coalesce(v_payload->>'verified_media_type',v_component.media_type,''))
            not in ('image/jpeg','image/png','image/webp'))
       or (v_component.component_kind in ('MILEAGE_FORM','SIGNED_RETURN','EXPENSE_EVIDENCE')
          and lower(coalesce(v_payload->>'verified_media_type',v_component.media_type,''))
            not in ('application/pdf','image/jpeg','image/png','image/webp'))
       or coalesce(nullif(v_payload->>'verified_byte_size','')::bigint,v_component.byte_size,0)
          not between 1 and 15728640 then
      raise exception 'CANDIDATE_COMPONENT_MEDIA_INVALID' using errcode='22023';
    end if;
    if v_component.state='IMMUTABLE' then
      if v_component.source_content_sha256=v_digest
         and v_component.byte_size=coalesce(nullif(v_payload->>'verified_byte_size','')::bigint,v_component.byte_size)
         and lower(v_component.media_type)=lower(coalesce(nullif(v_payload->>'verified_media_type',''),v_component.media_type)) then
        v_response:=jsonb_build_object('ok',true,'idempotent_replay',true,
          'component_id',v_component.id,'state',v_component.state);
        if v_mutation_request_sha256 is not null then
          perform private._candidate_workflow_mutation_receipt_v1(
            v_workflow.id,p_idempotency_key,v_mutation_request_sha256,v_action,
            v_mutation_channel,v_mutation_actor_identity,v_response,p_now_utc
          );
        end if;
        return v_response;
      end if;
      raise exception 'CANDIDATE_COMPONENT_IMMUTABLE_CONFLICT' using errcode='40001';
    end if;
    if v_component.state<>'PENDING' then
      raise exception 'CANDIDATE_COMPONENT_COMPLETE_STATE_CONFLICT' using errcode='55000';
    end if;
    update public.candidate_submission_components set
      state='IMMUTABLE',source_content_sha256=v_digest,
      byte_size=coalesce(nullif(v_payload->>'verified_byte_size','')::bigint,byte_size),
      media_type=coalesce(nullif(lower(v_payload->>'verified_media_type'),''),media_type),
      immutable_at_utc=p_now_utc
    where id=v_component.id and state='PENDING' returning * into v_component;
    if not found then
      raise exception 'CANDIDATE_COMPONENT_COMPLETE_STATE_CONFLICT' using errcode='40001';
    end if;
    v_response:=jsonb_build_object('ok',true,'idempotent_replay',false,'component_id',v_component.id,
      'state',v_component.state,'immutable_at_utc',v_component.immutable_at_utc);
    perform private._candidate_workflow_mutation_receipt_v1(
      v_workflow.id,p_idempotency_key,v_mutation_request_sha256,v_action,
      v_mutation_channel,v_mutation_actor_identity,v_response,p_now_utc
    );
    return v_response;
  elsif v_action='COMPONENT_SUPERSEDE' then
    if v_workflow.state<>'WORKER_DRAFT' then
      raise exception 'CANDIDATE_COMPONENT_AMENDMENT_REQUIRED' using errcode='55000';
    end if;
    update public.candidate_submission_components set
      state='SUPERSEDED',superseded_at_utc=p_now_utc,
      review_render_state=case when review_render_state='NOT_REQUIRED' then review_render_state else 'SUPERSEDED' end,
      final_signed_render_state=case when final_signed_render_state='NOT_REQUIRED' then final_signed_render_state else 'SUPERSEDED' end
    where id=nullif(v_payload->>'component_id','')::uuid and workflow_id=v_workflow.id
      and workflow_generation=v_workflow.generation and state<>'SUPERSEDED'
      and component_kind in ('CANDIDATE_SIGNATURE','MILEAGE_FORM','EXPENSE_EVIDENCE')
    returning * into v_component;
    if not found then raise exception 'CANDIDATE_COMPONENT_NOT_FOUND' using errcode='P0002'; end if;
    v_response:=jsonb_build_object('ok',true,'component_id',v_component.id,'state',v_component.state);
    if v_mutation_request_sha256 is not null then
      perform private._candidate_workflow_mutation_receipt_v1(
        v_workflow.id,p_idempotency_key,v_mutation_request_sha256,v_action,
        v_mutation_channel,v_mutation_actor_identity,v_response,p_now_utc
      );
    end if;
    return v_response;
  end if;

  if v_action='WORKER_SUBMIT' then
    if v_workflow.state<>'WORKER_DRAFT' then
      raise exception 'CANDIDATE_WORKFLOW_TRANSITION_INVALID' using errcode='55000';
    end if;
    v_is_electronic:=upper(coalesce(v_payload->>'approval_route',v_workflow.route))<>'PAPER';
    v_immutable_submission:=coalesce(v_payload->'immutable_submission',v_payload->'input_snapshot');
    if jsonb_typeof(v_immutable_submission)<>'object' then
      raise exception 'CANDIDATE_IMMUTABLE_SUBMISSION_REQUIRED' using errcode='22023';
    end if;
    if v_workflow.workflow_kind='DAILY' then
      if not private._candidate_daily_entitled_v1(v_candidate_id) then
        raise exception 'CANDIDATE_DAILY_ENTITLEMENT_REQUIRED' using errcode='55000';
      end if;
      select * into v_daily_timesheet
      from public.timesheets
      where timesheet_id=v_workflow.target_timesheet_id
        and is_current=true and archived_at_utc is null
        and sheet_scope='DAILY'::public.timesheet_scope_enum
      for update;
      if not found then raise exception 'CANDIDATE_DAILY_SHIFT_NOT_FOUND' using errcode='P0002'; end if;
      select * into v_daily_fin
      from public.timesheets_financials
      where timesheet_id=v_daily_timesheet.timesheet_id and is_current=true and candidate_id=v_candidate_id
      order by computed_at_utc desc nulls last,updated_at desc,id desc limit 1 for update;
      if not found then raise exception 'CANDIDATE_DAILY_SHIFT_NOT_FOUND' using errcode='P0002'; end if;
      v_canonical_work_date:=private._candidate_daily_work_date_v1(
        coalesce(
          nullif(v_immutable_submission#>>'{timesheet_patch_json,worked_start_iso}','')::timestamptz,
          nullif(v_immutable_submission->>'worked_start_iso','')::timestamptz,
          v_daily_fin.worked_start_iso,
          v_daily_timesheet.worked_start_iso
        ),
        v_daily_timesheet.scheduled_start_iso,
        v_daily_timesheet.week_ending_date
      );
      if v_canonical_work_date is distinct from v_workflow.work_date then
        raise exception 'CANDIDATE_DAILY_SHIFT_IDENTITY_MISMATCH' using errcode='22023';
      end if;
    elsif v_workflow.workflow_kind in ('CONTRACT_HOURS','CONTRACT_COMBINED') then
      select * into v_week from public.contract_weeks where id=v_workflow.contract_week_id for update;
      v_target_capabilities:=private._candidate_record_capabilities_v1(v_workflow.target_timesheet_id,v_week.id,'{}'::jsonb);
      v_route_authority:=private._candidate_route_family_v1(v_workflow.target_timesheet_id,v_week.id);
      if not coalesce((v_target_capabilities->>'can_edit_hours')::boolean,false)
         or (v_workflow.route='PAPER' and not coalesce((v_route_authority->>'candidate_paper_submission_allowed')::boolean,false))
         or (v_workflow.route<>'PAPER' and v_route_authority->>'route_family'<>'ELECTRONIC') then
        raise exception 'CANDIDATE_ROUTE_FAMILY_MISMATCH' using errcode='55000',detail=v_route_authority::text;
      end if;
    elsif v_workflow.workflow_kind='CONTRACT_EXPENSE' then
      select week_row.* into v_anchor_week
      from public.contract_weeks week_row
      where week_row.timesheet_id=v_workflow.anchor_timesheet_id
        and week_row.contract_id=v_workflow.contract_id
        and week_row.week_ending_date=v_workflow.week_ending_date
      for update;
      if not found then raise exception 'CANDIDATE_WORKFLOW_ANCHOR_MISMATCH' using errcode='40001'; end if;
      v_route_authority:=private._candidate_route_family_v1(v_workflow.anchor_timesheet_id,v_anchor_week.id);
      if not coalesce((v_route_authority->>'candidate_expenses_allowed')::boolean,false)
         or (v_workflow.route='PAPER' and not coalesce((v_route_authority->>'candidate_paper_submission_allowed')::boolean,false))
         or (v_workflow.route<>'PAPER' and v_route_authority->>'route_family' not in ('ELECTRONIC','IMPORT_AUTHORITATIVE')) then
        raise exception 'CANDIDATE_ROUTE_FAMILY_MISMATCH' using errcode='55000',detail=v_route_authority::text;
      end if;
    end if;
    if exists(
      select 1
      from (values
        (v_immutable_submission#>>'{canonical_tsfin_snapshot,candidate_id}'),
        (v_immutable_submission#>>'{hours_submission,canonical_tsfin_snapshot,candidate_id}'),
        (v_immutable_submission#>>'{expense_submission,canonical_tsfin_snapshot,candidate_id}')
      ) supplied(candidate_id_text)
      where nullif(supplied.candidate_id_text,'') is not null
        and supplied.candidate_id_text::uuid<>v_workflow.candidate_id
    ) or exists(
      select 1
      from (values
        (v_immutable_submission#>>'{canonical_tsfin_snapshot,client_id}'),
        (v_immutable_submission#>>'{hours_submission,canonical_tsfin_snapshot,client_id}'),
        (v_immutable_submission#>>'{expense_submission,canonical_tsfin_snapshot,client_id}')
      ) supplied(client_id_text)
      where nullif(supplied.client_id_text,'') is not null
        and supplied.client_id_text::uuid<>coalesce(v_contract.client_id,v_daily_fin.client_id)
    ) then
      raise exception 'CANDIDATE_IMMUTABLE_SUBMISSION_IDENTITY_MISMATCH' using errcode='22023';
    end if;
    if v_workflow.workflow_kind='DAILY' and exists(
      select 1
      from jsonb_array_elements(coalesce(
        v_immutable_submission#>'{timesheet_patch_json,actual_schedule_json}',
        v_immutable_submission#>'{hours_submission,timesheet_patch_json,actual_schedule_json}',
        '[]'::jsonb
      )) schedule_row
      where nullif(schedule_row->>'date','') is null
         or (schedule_row->>'date')::date<>v_workflow.work_date
    ) then
      raise exception 'CANDIDATE_DAILY_SHIFT_IDENTITY_MISMATCH' using errcode='22023';
    elsif v_workflow.scope='WEEKLY' and exists(
      select 1
      from jsonb_array_elements(coalesce(
        v_immutable_submission#>'{timesheet_patch_json,actual_schedule_json}',
        v_immutable_submission#>'{hours_submission,timesheet_patch_json,actual_schedule_json}',
        '[]'::jsonb
      )) schedule_row
      where nullif(schedule_row->>'date','') is null
         or (schedule_row->>'date')::date not between v_workflow.week_ending_date-6 and v_workflow.week_ending_date
    ) then
      raise exception 'CANDIDATE_WEEK_DATE_OUT_OF_RANGE' using errcode='22023';
    end if;
    v_submission_hash:=private._candidate_sha256_jsonb_v1(v_immutable_submission);
    v_expense_submission:=case
      when v_workflow.workflow_kind='CONTRACT_COMBINED'
        and jsonb_typeof(v_immutable_submission->'expense_submission')='object'
        then v_immutable_submission->'expense_submission'
      else v_immutable_submission
    end;
    begin
      v_expense_value:=
        abs(coalesce(nullif(v_expense_submission#>>'{canonical_tsfin_snapshot,expenses_pay_ex_vat}','')::numeric,0))+
        abs(coalesce(nullif(v_expense_submission#>>'{canonical_tsfin_snapshot,expenses_charge_ex_vat}','')::numeric,0))+
        abs(coalesce(nullif(v_expense_submission#>>'{canonical_tsfin_snapshot,mileage_pay_ex_vat}','')::numeric,0))+
        abs(coalesce(nullif(v_expense_submission#>>'{canonical_tsfin_snapshot,mileage_charge_ex_vat}','')::numeric,0))+
        abs(coalesce(nullif(v_expense_submission#>>'{canonical_tsfin_snapshot,mileage_units}','')::numeric,0))+
        abs(coalesce(nullif(v_expense_submission#>>'{canonical_tsfin_snapshot,travel_pay_ex_vat}','')::numeric,0))+
        abs(coalesce(nullif(v_expense_submission#>>'{canonical_tsfin_snapshot,travel_charge_ex_vat}','')::numeric,0))+
        abs(coalesce(nullif(v_expense_submission#>>'{canonical_tsfin_snapshot,accommodation_pay_ex_vat}','')::numeric,0))+
        abs(coalesce(nullif(v_expense_submission#>>'{canonical_tsfin_snapshot,accommodation_charge_ex_vat}','')::numeric,0))+
        abs(coalesce(nullif(v_expense_submission#>>'{canonical_tsfin_snapshot,other_pay_ex_vat}','')::numeric,0))+
        abs(coalesce(nullif(v_expense_submission#>>'{canonical_tsfin_snapshot,other_charge_ex_vat}','')::numeric,0));
      v_has_mileage:=
        abs(coalesce(nullif(v_expense_submission#>>'{canonical_tsfin_snapshot,mileage_units}','')::numeric,0))>0
        or abs(coalesce(nullif(v_expense_submission#>>'{canonical_tsfin_snapshot,mileage_pay_ex_vat}','')::numeric,0))>0
        or abs(coalesce(nullif(v_expense_submission#>>'{canonical_tsfin_snapshot,mileage_charge_ex_vat}','')::numeric,0))>0;
      v_required_categories:=array[]::text[];
      if abs(coalesce(nullif(v_expense_submission#>>'{canonical_tsfin_snapshot,travel_pay_ex_vat}','')::numeric,0))>0
         or abs(coalesce(nullif(v_expense_submission#>>'{canonical_tsfin_snapshot,travel_charge_ex_vat}','')::numeric,0))>0 then
        v_required_categories:=array_append(v_required_categories,'TRAVEL');
      end if;
      if abs(coalesce(nullif(v_expense_submission#>>'{canonical_tsfin_snapshot,accommodation_pay_ex_vat}','')::numeric,0))>0
         or abs(coalesce(nullif(v_expense_submission#>>'{canonical_tsfin_snapshot,accommodation_charge_ex_vat}','')::numeric,0))>0 then
        v_required_categories:=array_append(v_required_categories,'ACCOMMODATION');
      end if;
      if abs(coalesce(nullif(v_expense_submission#>>'{canonical_tsfin_snapshot,other_pay_ex_vat}','')::numeric,0))>0
         or abs(coalesce(nullif(v_expense_submission#>>'{canonical_tsfin_snapshot,other_charge_ex_vat}','')::numeric,0))>0
         or abs(coalesce(nullif(v_expense_submission#>>'{canonical_tsfin_snapshot,expenses_pay_ex_vat}','')::numeric,0))>0
         or abs(coalesce(nullif(v_expense_submission#>>'{canonical_tsfin_snapshot,expenses_charge_ex_vat}','')::numeric,0))>0 then
        v_required_categories:=array_append(v_required_categories,'OTHER');
      end if;
      if v_has_mileage then
        v_required_categories:=array_append(v_required_categories,'MILEAGE');
      end if;
    exception when invalid_text_representation or numeric_value_out_of_range then
      raise exception 'CANDIDATE_EXPENSE_VALUE_INVALID' using errcode='22023';
    end;
    v_has_expenses:=v_expense_value>0;
    if v_workflow.workflow_kind in ('CONTRACT_HOURS','DAILY') and v_has_expenses then
      raise exception 'CANDIDATE_WORKFLOW_KIND_ECONOMICS_MISMATCH' using errcode='22023';
    end if;
    if v_workflow.workflow_kind in ('CONTRACT_COMBINED','CONTRACT_EXPENSE') and not v_has_expenses then
      raise exception 'CANDIDATE_EXPENSE_CLAIM_REQUIRED' using errcode='22023';
    end if;
    v_server_issue_codes:=private._candidate_submission_issue_codes_v1(
      v_workflow.id,v_immutable_submission,v_policy
    );
    update public.candidate_approval_requests set
      state='SUPERSEDED',superseded_at_utc=p_now_utc,updated_at_utc=p_now_utc
    where workflow_id=v_workflow.id and state in ('PENDING','APPROVED');

    if v_is_electronic then
      v_component_no:=0;
      v_review_ordinal:=0;
      if v_workflow.workflow_kind<>'CONTRACT_EXPENSE' then
        select * into v_source_component
        from public.candidate_submission_components
        where id=nullif(v_payload->>'candidate_signature_component_id','')::uuid
          and workflow_id=v_workflow.id and component_kind='CANDIDATE_SIGNATURE'
          and document_role='CANDIDATE_SIGNATURE' and state='IMMUTABLE'
          and source_content_sha256 is not null
          and (
            v_workflow.immutable_submission_sha256 is null
            or v_workflow.immutable_submission_sha256=v_submission_hash
            or (
              source_component_id is null
              and created_at_utc>=coalesce(v_workflow.worker_submitted_at_utc,'-infinity'::timestamptz)
            )
          )
        for update;
        if not found then
          if v_workflow.immutable_submission_sha256 is not null
             and v_workflow.immutable_submission_sha256<>v_submission_hash then
            raise exception 'CANDIDATE_SIGNATURE_REQUIRED_AFTER_AMENDMENT' using errcode='55000';
          end if;
          raise exception 'CANDIDATE_SIGNATURE_REQUIRED' using errcode='55000';
        end if;
        v_component_no:=v_component_no+1;
        insert into public.candidate_submission_components(
          workflow_id,workflow_generation,component_no,timesheet_id,component_kind,document_role,state,
          source_component_id,storage_key,media_type,byte_size,source_content_sha256,immutable_at_utc,
          required,review_ordinal,review_render_state,final_signed_render_state,created_at_utc
        ) values (
          v_workflow.id,v_next_generation,v_component_no,v_workflow.target_timesheet_id,
          'CANDIDATE_SIGNATURE','CANDIDATE_SIGNATURE','IMMUTABLE',
          coalesce(v_source_component.source_component_id,v_source_component.id),v_source_component.storage_key,
          v_source_component.media_type,v_source_component.byte_size,v_source_component.source_content_sha256,p_now_utc,
          false,null,'NOT_REQUIRED','NOT_REQUIRED',p_now_utc
        ) returning * into v_signature_component;
        v_component_no:=v_component_no+1;
        v_review_ordinal:=v_review_ordinal+1;
        insert into public.candidate_submission_components(
          workflow_id,workflow_generation,component_no,timesheet_id,component_kind,document_role,state,
          immutable_at_utc,required,review_ordinal,review_render_state,final_signed_render_state,created_at_utc
        ) values (
          v_workflow.id,v_next_generation,v_component_no,v_workflow.target_timesheet_id,'HOURS_TIMESHEET',
          'ELECTRONIC_TIMESHEET_MANAGER_REVIEW','IMMUTABLE',p_now_utc,true,v_review_ordinal,
          'PENDING','PENDING',p_now_utc
        ) returning * into v_component;
      elsif nullif(v_payload->>'candidate_signature_component_id','') is not null then
        raise exception 'CONTRACT_EXPENSE_CANDIDATE_SIGNATURE_FORBIDDEN' using errcode='22023';
      end if;

      if v_workflow.workflow_kind in ('CONTRACT_COMBINED','CONTRACT_EXPENSE') then
        foreach v_required_category in array v_required_categories loop
          if not exists(
            select 1 from public.candidate_submission_components source_component
            where source_component.workflow_id=v_workflow.id
              and source_component.workflow_generation=v_workflow.generation
              and source_component.component_kind in ('EXPENSE_EVIDENCE','MILEAGE_FORM')
              and source_component.expense_category=v_required_category
              and source_component.state='IMMUTABLE'
              and source_component.source_content_sha256 is not null
          ) then raise exception 'EXPENSE_EVIDENCE_REQUIRED'
            using errcode='22023',detail=jsonb_build_object('category',v_required_category)::text; end if;
        end loop;
        if v_has_mileage and not exists(
          select 1 from public.candidate_submission_components source_component
          where source_component.workflow_id=v_workflow.id
            and source_component.workflow_generation=v_workflow.generation
            and source_component.component_kind='MILEAGE_FORM'
            and source_component.state='IMMUTABLE'
            and source_component.source_content_sha256 is not null
        ) then raise exception 'EXPENSE_EVIDENCE_REQUIRED'
          using errcode='22023',detail=jsonb_build_object('category','MILEAGE')::text; end if;

        v_component_no:=v_component_no+1;
        v_review_ordinal:=v_review_ordinal+1;
        insert into public.candidate_submission_components(
          workflow_id,workflow_generation,component_no,timesheet_id,component_kind,document_role,state,
          immutable_at_utc,required,review_ordinal,review_render_state,final_signed_render_state,created_at_utc
        ) values (
          v_workflow.id,v_next_generation,v_component_no,v_workflow.target_timesheet_id,'EXPENSE_SUMMARY',
          'EXPENSE_MILEAGE_APPROVAL_SUMMARY','IMMUTABLE',p_now_utc,true,v_review_ordinal,
          'PENDING','PENDING',p_now_utc
        );

        for v_source_component in
          select source_component.*
          from public.candidate_submission_components source_component
          where source_component.workflow_id=v_workflow.id
            and source_component.workflow_generation=v_workflow.generation
            and source_component.component_kind in ('MILEAGE_FORM','EXPENSE_EVIDENCE')
            and source_component.state='IMMUTABLE'
            and source_component.source_content_sha256 is not null
          order by case source_component.component_kind when 'MILEAGE_FORM' then 0 else 1 end,
            case source_component.expense_category
              when 'ACCOMMODATION' then 1 when 'TRAVEL' then 2 when 'MILEAGE' then 3
              when 'OTHER' then 4 else 5 end,
            source_component.component_no,source_component.id
        loop
          v_component_no:=v_component_no+1;
          v_review_ordinal:=v_review_ordinal+1;
          insert into public.candidate_submission_components(
            workflow_id,workflow_generation,component_no,timesheet_id,component_kind,expense_category,
            document_role,state,source_component_id,storage_key,media_type,byte_size,source_content_sha256,
            immutable_at_utc,required,review_ordinal,review_render_state,final_signed_render_state,created_at_utc
          ) values (
            v_workflow.id,v_next_generation,v_component_no,v_workflow.target_timesheet_id,
            v_source_component.component_kind,v_source_component.expense_category,v_source_component.document_role,
            'IMMUTABLE',coalesce(v_source_component.source_component_id,v_source_component.id),
            v_source_component.storage_key,v_source_component.media_type,v_source_component.byte_size,
            v_source_component.source_content_sha256,p_now_utc,true,v_review_ordinal,'PENDING','PENDING',p_now_utc
          );
        end loop;
      end if;

      update public.candidate_submission_components set
        state='SUPERSEDED',superseded_at_utc=p_now_utc,
        review_render_state=case when review_render_state='NOT_REQUIRED' then review_render_state else 'SUPERSEDED' end,
        final_signed_render_state=case when final_signed_render_state='NOT_REQUIRED' then final_signed_render_state else 'SUPERSEDED' end
      where workflow_id=v_workflow.id and workflow_generation=v_workflow.generation
        and (required=true or document_role='MANAGER_SIGNATURE') and state<>'SUPERSEDED';

      update public.candidate_submission_workflows set
        state='WORKER_SUBMITTED_PENDING_REVIEW_DOCUMENT',generation=v_next_generation,
        route=case when upper(coalesce(v_payload->>'approval_route',route)) in ('PHONE','EMAIL')
          then upper(coalesce(v_payload->>'approval_route',route)) else 'ELECTRONIC' end,
        input_snapshot_json=v_immutable_submission,immutable_submission_json=v_immutable_submission,
        immutable_submission_sha256=v_submission_hash,
        policy_snapshot_json=v_policy,policy_snapshot_sha256=private._candidate_sha256_jsonb_v1(v_policy),
        candidate_signature_component_id=case when workflow_kind='CONTRACT_EXPENSE' then null else v_signature_component.id end,
        candidate_signature_sha256=case when workflow_kind='CONTRACT_EXPENSE' then null else v_signature_component.source_content_sha256 end,
        candidate_signed_at_utc=case when workflow_kind='CONTRACT_EXPENSE' then null
          else coalesce(nullif(v_payload->>'candidate_signed_at_utc','')::timestamptz,p_now_utc) end,
        renderer_contract_version=coalesce(nullif(btrim(v_payload->>'renderer_contract_version'),''),'TIMESHEET_OFFICIAL_PDF_V1'),
        review_manifest_json=null,review_manifest_sha256=null,
        manager_name=null,manager_position=null,manager_signature_component_id=null,
        manager_signature_sha256=null,manager_approved_at_utc=null,
        issue_codes=v_server_issue_codes,worker_submitted_at_utc=p_now_utc,
        daily_context_sha256=null,canonical_financial_sha256=null,
        canonical_save_input_sha256=null,canonical_save_row_signature=null,
        canonical_save_financials_id=null,canonical_save_receipt_json=null,canonical_saved_at_utc=null,
        last_mutation_idempotency_key=p_idempotency_key,updated_at_utc=p_now_utc
      where id=v_workflow.id returning * into v_workflow;
      v_render_contract:=private._candidate_render_contract_v1(
        v_workflow.id,v_workflow.generation,'ELECTRONIC_MANAGER_REVIEW');
      v_response:=jsonb_build_object('ok',true,'workflow_id',v_workflow.id,
        'state',v_workflow.state,'generation',v_workflow.generation,
        'review_document_component_id',case when v_workflow.workflow_kind='CONTRACT_EXPENSE' then null else v_component.id end,
        'render_contract',v_render_contract,'idempotent_replay',false);
    else
      v_component_no:=0;
      if v_workflow.workflow_kind in ('CONTRACT_COMBINED','CONTRACT_EXPENSE') then
        foreach v_required_category in array v_required_categories loop
          if not exists(
            select 1 from public.candidate_submission_components source_component
            where source_component.workflow_id=v_workflow.id
              and source_component.workflow_generation=v_workflow.generation
              and source_component.component_kind in ('EXPENSE_EVIDENCE','MILEAGE_FORM')
              and source_component.expense_category=v_required_category
              and source_component.state='IMMUTABLE'
              and source_component.source_content_sha256 is not null
          ) then raise exception 'EXPENSE_EVIDENCE_REQUIRED'
            using errcode='22023',detail=jsonb_build_object('category',v_required_category)::text; end if;
        end loop;
        if v_has_mileage and not exists(
          select 1 from public.candidate_submission_components source_component
          where source_component.workflow_id=v_workflow.id
            and source_component.workflow_generation=v_workflow.generation
            and source_component.component_kind='MILEAGE_FORM'
            and source_component.expense_category='MILEAGE'
            and source_component.state='IMMUTABLE'
            and source_component.source_content_sha256 is not null
        ) then raise exception 'EXPENSE_EVIDENCE_REQUIRED'
          using errcode='22023',detail=jsonb_build_object('category','MILEAGE')::text; end if;

        for v_source_component in
          select source_component.*
          from public.candidate_submission_components source_component
          where source_component.workflow_id=v_workflow.id
            and source_component.workflow_generation=v_workflow.generation
            and source_component.component_kind in ('MILEAGE_FORM','EXPENSE_EVIDENCE')
            and source_component.state='IMMUTABLE'
            and source_component.source_content_sha256 is not null
          order by case source_component.component_kind when 'MILEAGE_FORM' then 0 else 1 end,
            source_component.component_no,source_component.id
        loop
          v_component_no:=v_component_no+1;
          insert into public.candidate_submission_components(
            workflow_id,workflow_generation,component_no,timesheet_id,component_kind,expense_category,
            document_role,state,source_component_id,storage_key,media_type,byte_size,source_content_sha256,
            immutable_at_utc,required,review_ordinal,review_render_state,final_signed_render_state,created_at_utc
          ) values (
            v_workflow.id,v_next_generation,v_component_no,v_workflow.target_timesheet_id,
            v_source_component.component_kind,v_source_component.expense_category,v_source_component.document_role,
            'IMMUTABLE',coalesce(v_source_component.source_component_id,v_source_component.id),
            v_source_component.storage_key,v_source_component.media_type,v_source_component.byte_size,
            v_source_component.source_content_sha256,p_now_utc,false,null,'NOT_REQUIRED','NOT_REQUIRED',p_now_utc
          );
        end loop;
      end if;
      update public.candidate_submission_components set
        state='SUPERSEDED',superseded_at_utc=p_now_utc,
        review_render_state=case when review_render_state='NOT_REQUIRED' then review_render_state else 'SUPERSEDED' end,
        final_signed_render_state=case when final_signed_render_state='NOT_REQUIRED' then final_signed_render_state else 'SUPERSEDED' end
      where workflow_id=v_workflow.id and workflow_generation=v_workflow.generation
        and (required=true or document_role='MANAGER_SIGNATURE') and state<>'SUPERSEDED';
      update public.candidate_submission_workflows set
        state='WORKER_SUBMITTED',generation=v_next_generation,route='PAPER',
        input_snapshot_json=v_immutable_submission,immutable_submission_json=v_immutable_submission,
        immutable_submission_sha256=private._candidate_sha256_jsonb_v1(v_immutable_submission),
        policy_snapshot_json=v_policy,policy_snapshot_sha256=private._candidate_sha256_jsonb_v1(v_policy),
        paper_return_manifest_json=null,paper_return_manifest_sha256=null,
        issue_codes=v_server_issue_codes,worker_submitted_at_utc=p_now_utc,
        daily_context_sha256=null,canonical_financial_sha256=null,
        canonical_save_input_sha256=null,canonical_save_row_signature=null,
        canonical_save_financials_id=null,canonical_save_receipt_json=null,canonical_saved_at_utc=null,
        last_mutation_idempotency_key=p_idempotency_key,updated_at_utc=p_now_utc
      where id=v_workflow.id returning * into v_workflow;
      v_response:=jsonb_build_object('ok',true,'workflow_id',v_workflow.id,
        'state',v_workflow.state,'generation',v_workflow.generation,'idempotent_replay',false);
    end if;
    update public.candidate_submission_workflows
    set last_mutation_response_json=v_response where id=v_workflow.id;

  elsif v_action='REGISTER_REVIEW_COMPONENT' then
    if v_workflow.state not in ('WORKER_SUBMITTED_PENDING_REVIEW_DOCUMENT','READY_FOR_MANAGER_APPROVAL') then
      raise exception 'MANAGER_REVIEW_DOCUMENT_STALE' using errcode='55000';
    end if;
    select * into v_component from public.candidate_submission_components
    where id=nullif(v_payload->>'component_id','')::uuid
      and workflow_id=v_workflow.id and workflow_generation=v_workflow.generation
      and required=true and state<>'SUPERSEDED' for update;
    if not found then raise exception 'MANAGER_REVIEW_DOCUMENT_STALE' using errcode='55000'; end if;
    if coalesce(v_payload->>'content_sha256_hex','') !~ '^[0-9a-fA-F]{64}$'
       or coalesce(v_payload->>'render_input_sha256_hex','') !~ '^[0-9a-fA-F]{64}$' then
      raise exception 'MANAGER_REVIEW_RENDER_FAILED' using errcode='22023',
        detail=jsonb_build_object(
          'component_id',v_component.id,
          'expected_contract',v_render_contract,
          'received_receipt',v_receipt,
          'received_render_input_sha256',lower(coalesce(v_payload->>'render_input_sha256_hex',''))
        )::text;
    end if;
    v_digest:=decode(v_payload->>'content_sha256_hex','hex');
    v_render_input_hash:=decode(v_payload->>'render_input_sha256_hex','hex');
    v_receipt:=coalesce(v_payload->'renderer_receipt','{}'::jsonb);
    v_render_contract:=private._candidate_component_render_contract_v1(
      v_workflow.id,v_workflow.generation,v_component.id,'REVIEW');
    if v_render_input_hash<>decode(v_render_contract->>'render_input_sha256','hex')
       or nullif(btrim(v_payload->>'storage_key'),'') is null
       or lower(coalesce(v_payload->>'media_type','')) not in ('application/pdf','image/jpeg','image/png','image/webp')
       or coalesce((v_payload->>'page_count')::integer,0)<>1
       or coalesce((v_payload->>'byte_size')::bigint,0)<=0
       or upper(coalesce(v_receipt->>'form_variant',''))<>v_render_contract->>'form_variant'
       or nullif(v_receipt->>'workflow_id','')::uuid is distinct from v_workflow.id
       or coalesce((v_receipt->>'workflow_generation')::integer,0)<>v_workflow.generation
       or nullif(v_receipt->>'component_id','')::uuid is distinct from v_component.id
       or upper(coalesce(v_receipt->>'component_kind',''))<>v_component.component_kind
       or upper(coalesce(v_receipt->>'document_role',''))<>v_component.document_role
       or coalesce((v_receipt->>'review_ordinal')::integer,0)<>v_component.review_ordinal
       or upper(coalesce(v_receipt->>'scope',''))<>v_workflow.scope
       or coalesce((v_receipt->>'candidate_signature_embedded')::boolean,false)
          is distinct from (v_component.component_kind='HOURS_TIMESHEET')
       or coalesce((v_receipt->>'manager_signature_embedded')::boolean,false)=true
       or coalesce((v_receipt->>'manager_approval_date_embedded')::boolean,false)=true
       or coalesce((v_receipt->>'page_count')::integer,0)<>1
       or lower(coalesce(v_receipt->>'render_input_sha256',''))<>encode(v_render_input_hash,'hex') then
      raise exception 'MANAGER_REVIEW_RENDER_FAILED' using errcode='22023',
        detail=jsonb_build_object(
          'component_id',v_component.id,
          'expected_contract',v_render_contract,
          'received_receipt',v_receipt,
          'received_render_input_sha256',lower(coalesce(v_payload->>'render_input_sha256_hex',''))
        )::text;
    end if;
    if v_component.review_render_state='READY' then
      if v_component.review_storage_key=v_payload->>'storage_key'
         and v_component.review_content_sha256=v_digest
         and v_component.review_render_input_sha256=v_render_input_hash then
        v_response:=jsonb_build_object('ok',true,'idempotent_replay',true,
          'workflow_id',v_workflow.id,'generation',v_workflow.generation,
          'component_id',v_component.id,'state',v_workflow.state);
        if v_mutation_request_sha256 is not null then
          perform private._candidate_workflow_mutation_receipt_v1(
            v_workflow.id,p_idempotency_key,v_mutation_request_sha256,v_action,
            v_mutation_channel,v_mutation_actor_identity,v_response,p_now_utc
          );
        end if;
        return v_response;
      end if;
      raise exception 'MANAGER_REVIEW_DOCUMENT_STALE' using errcode='55000';
    end if;
    update public.candidate_submission_components set
      review_storage_key=v_payload->>'storage_key',review_content_sha256=v_digest,
      review_media_type=lower(v_payload->>'media_type'),review_byte_size=(v_payload->>'byte_size')::bigint,
      review_page_count=1,review_render_input_sha256=v_render_input_hash,
      review_renderer_contract_version=coalesce(nullif(v_payload->>'renderer_contract_version',''),v_workflow.renderer_contract_version),
      review_renderer_receipt_json=v_receipt,review_generated_at_utc=p_now_utc,
      review_render_state='READY'
    where id=v_component.id returning * into v_component;
    v_manifest:=private._candidate_review_manifest_v1(v_workflow.id,v_workflow.generation);
    if coalesce((v_manifest->>'all_ready')::boolean,false) then
      update public.candidate_submission_workflows set
        state='READY_FOR_MANAGER_APPROVAL',review_manifest_json=v_manifest,
        review_manifest_sha256=decode(v_manifest->>'manifest_sha256','hex'),
        last_mutation_idempotency_key=p_idempotency_key,updated_at_utc=p_now_utc
      where id=v_workflow.id returning * into v_workflow;
    end if;
    v_response:=jsonb_build_object('ok',true,'idempotent_replay',false,
      'workflow_id',v_workflow.id,'state',v_workflow.state,'generation',v_workflow.generation,
      'component_id',v_component.id,'review_document_ready',v_component.review_render_state='READY',
      'review_manifest',v_manifest);
    update public.candidate_submission_workflows set last_mutation_response_json=v_response where id=v_workflow.id;

  elsif v_action in ('SELECT_PHONE_APPROVAL','CREATE_EMAIL_APPROVAL_REQUEST') then
    if v_workflow.state not in ('READY_FOR_MANAGER_APPROVAL','AWAITING_MANAGER_APPROVAL') then
      raise exception 'MANAGER_REVIEW_DOCUMENT_NOT_READY' using errcode='55000';
    end if;
    v_manifest:=private._candidate_review_manifest_v1(v_workflow.id,v_workflow.generation);
    if coalesce((v_manifest->>'all_ready')::boolean,false)=false
       or decode(v_manifest->>'manifest_sha256','hex') is distinct from v_workflow.review_manifest_sha256 then
      raise exception 'MANAGER_REVIEW_DOCUMENT_NOT_READY' using errcode='55000';
    end if;
    select array_agg(c.id order by c.review_ordinal,c.id) into v_component_ids
    from public.candidate_submission_components c
    where c.workflow_id=v_workflow.id and c.workflow_generation=v_workflow.generation
      and c.required=true and c.state<>'SUPERSEDED';
    select coalesce(max(request_generation),0)+1 into v_request_generation
    from public.candidate_approval_requests where workflow_id=v_workflow.id;
    update public.candidate_approval_requests set
      state='SUPERSEDED',superseded_at_utc=p_now_utc,updated_at_utc=p_now_utc
    where workflow_id=v_workflow.id and state='PENDING';
    if v_action='CREATE_EMAIL_APPROVAL_REQUEST' then
      if coalesce(v_payload->>'approval_token_hash_hex','') !~ '^[0-9a-fA-F]{64}$' then
        raise exception 'CANDIDATE_APPROVAL_TOKEN_INVALID' using errcode='22023';
      end if;
      v_token_hash:=decode(v_payload->>'approval_token_hash_hex','hex');
      v_email_check:=private._candidate_manager_email_allowed_v1(
        v_policy->'manager_approval_policy',v_payload->>'manager_email',
        v_policy->'barred_manager_email_domains');
      if coalesce((v_email_check->>'allowed')::boolean,false)=false then
        raise exception 'MANAGER_EMAIL_NOT_ALLOWED' using errcode='22023',detail=v_email_check::text;
      end if;
      insert into public.candidate_approval_requests(
        workflow_id,workflow_generation,request_generation,method,state,manager_email_normalized,
        token_hash,expires_at_utc,initial_sent_at_utc,last_sent_at_utc,next_reminder_at_utc,
        review_manifest_sha256,required_component_ids,required_component_manifest_json,
        manager_review_timesheet_component_id,manager_review_timesheet_sha256,
        idempotency_key,created_at_utc,updated_at_utc
      ) values (
        v_workflow.id,v_workflow.generation,v_request_generation,'EMAIL','PENDING',
        v_email_check->>'email_normalized',v_token_hash,p_now_utc+interval '7 days',
        null,null,null,
        decode(v_manifest->>'manifest_sha256','hex'),v_component_ids,v_manifest->'required_components',
        nullif(v_manifest->>'manager_review_timesheet_component_id','')::uuid,
        case when nullif(v_manifest->>'manager_review_timesheet_sha256','') is null then null
          else decode(v_manifest->>'manager_review_timesheet_sha256','hex') end,
        p_idempotency_key,p_now_utc,p_now_utc
      ) returning * into v_approval;
      v_mail_id:=private._candidate_queue_mail_v1(
        coalesce(v_payload->'mail','{}'::jsonb)||jsonb_build_object(
          'payment_scope_json',jsonb_build_object(
            'candidate_mail_authority','MANAGER_APPROVAL_V1',
            'candidate_manager_mail_kind','INITIAL',
            'candidate_manager_workflow_id',v_workflow.id,
            'candidate_manager_workflow_generation',v_workflow.generation,
            'candidate_approval_request_id',v_approval.id,
            'candidate_approval_request_generation',v_approval.request_generation,
            'candidate_manager_mail_retired',false
          )
        ),v_approval.manager_email_normalized,
        'CANDIDATE_MANAGER_APPROVAL_V1:'||v_approval.id::text||':0',
        'candidate-manager-approval:'||v_approval.id::text,v_workflow.id,p_now_utc);
    else
      if coalesce(v_payload->>'approval_token_hash_hex','') !~ '^[0-9a-fA-F]{64}$'
         or nullif(v_payload->>'expires_at_utc','')::timestamptz<=p_now_utc
         or nullif(v_payload->>'expires_at_utc','')::timestamptz>p_now_utc+interval '2 hours' then
        raise exception 'CANDIDATE_APPROVAL_TOKEN_INVALID' using errcode='22023';
      end if;
      v_token_hash:=decode(v_payload->>'approval_token_hash_hex','hex');
      insert into public.candidate_approval_requests(
        workflow_id,workflow_generation,request_generation,method,state,token_hash,expires_at_utc,
        review_manifest_sha256,required_component_ids,required_component_manifest_json,
        manager_review_timesheet_component_id,manager_review_timesheet_sha256,
        idempotency_key,created_at_utc,updated_at_utc
      ) values (
        v_workflow.id,v_workflow.generation,v_request_generation,'PHONE','PENDING',v_token_hash,
        nullif(v_payload->>'expires_at_utc','')::timestamptz,
        decode(v_manifest->>'manifest_sha256','hex'),v_component_ids,v_manifest->'required_components',
        nullif(v_manifest->>'manager_review_timesheet_component_id','')::uuid,
        case when nullif(v_manifest->>'manager_review_timesheet_sha256','') is null then null
          else decode(v_manifest->>'manager_review_timesheet_sha256','hex') end,
        p_idempotency_key,p_now_utc,p_now_utc
      ) returning * into v_approval;
    end if;
    v_response:=jsonb_build_object('ok',true,'workflow_id',v_workflow.id,
      'state','AWAITING_MANAGER_APPROVAL','generation',v_workflow.generation,
      'approval_request_id',v_approval.id,'method',v_approval.method,
      'review_manifest_sha256',encode(v_approval.review_manifest_sha256,'hex'),
      'issued_at_utc',v_approval.created_at_utc,
      'expires_at_utc',v_approval.expires_at_utc,'mail_outbox_id',v_mail_id);
    if v_action='SELECT_PHONE_APPROVAL' then
      if coalesce(v_payload->>'handoff_token_key_version','') !~ '^[1-9][0-9]{0,2}$'
         or (v_payload->>'handoff_token_key_version')::integer>32 then
        raise exception 'CANDIDATE_REPLAY_KEY_VERSION_INVALID' using errcode='22023';
      end if;
      if jsonb_typeof(v_payload->'public_broker_binding')<>'object'
         or coalesce(v_payload#>>'{public_broker_binding,contract_version}','')
              <>'CANDIDATE_PUBLIC_PHONE_BINDING_V1'
         or coalesce(v_payload#>>'{public_broker_binding,public_session_binding_sha256}','')
              !~ '^[0-9a-f]{64}$'
         or (v_payload#>'{public_broker_binding,device_binding_sha256}') is not null
            and jsonb_typeof(v_payload#>'{public_broker_binding,device_binding_sha256}')<>'null'
            and coalesce(v_payload#>>'{public_broker_binding,device_binding_sha256}','')
                  !~ '^[0-9a-f]{64}$'
         or coalesce(v_payload->>'broker_handoff_key_version','') !~ '^[1-9][0-9]{0,4}$'
         or (v_payload->>'broker_handoff_key_version')::integer>65535 then
        raise exception 'CANDIDATE_PHONE_HANDOFF_BINDING_INVALID' using errcode='22023';
      end if;
      v_response:=v_response||jsonb_build_object(
        'approval_token_hash_hex',encode(v_approval.token_hash,'hex'),
        'handoff_token_key_version',(v_payload->>'handoff_token_key_version')::integer,
        'public_broker_binding',v_payload->'public_broker_binding',
        'broker_handoff_key_version',(v_payload->>'broker_handoff_key_version')::integer
      );
    end if;
    update public.candidate_submission_workflows set
      state='AWAITING_MANAGER_APPROVAL',route=v_approval.method,policy_snapshot_json=v_policy,
      last_mutation_idempotency_key=p_idempotency_key,last_mutation_response_json=v_response,
      updated_at_utc=p_now_utc where id=v_workflow.id;

  elsif v_action='BEGIN_MANAGER_REVIEW' then
    if v_is_public_manager_action then
      select * into v_approval from public.candidate_approval_requests
      where workflow_id=v_workflow.id and token_hash=v_token_hash for update;
    else
      select * into v_approval from public.candidate_approval_requests
      where workflow_id=v_workflow.id and workflow_generation=v_workflow.generation
        and method='PHONE' and state='PENDING'
        and (not coalesce((v_payload->>'service_office_action')::boolean,false)
          or (id=(v_payload->>'approval_request_id')::uuid
            and request_generation=(v_payload->>'approval_request_generation')::integer))
      for update;
    end if;
    if not found or v_approval.state<>'PENDING' then
      raise exception 'MANAGER_APPROVAL_REQUEST_NOT_READY' using errcode='28000';
    end if;
    if v_approval.expires_at_utc<=p_now_utc then
      raise exception 'MANAGER_APPROVAL_REQUEST_EXPIRED' using errcode='28000';
    end if;
    if v_approval.workflow_generation<>v_workflow.generation
       or v_approval.review_manifest_sha256 is distinct from v_workflow.review_manifest_sha256 then
      raise exception 'MANAGER_APPROVAL_REQUEST_SUPERSEDED' using errcode='40001';
    end if;
    update public.candidate_approval_requests set
      review_started_at_utc=coalesce(review_started_at_utc,p_now_utc),updated_at_utc=p_now_utc
    where id=v_approval.id;
    v_response:=jsonb_build_object('ok',true,'workflow_id',v_workflow.id,
      'workflow_generation',v_workflow.generation,'approval_request_id',v_approval.id,
      'method',v_approval.method,'expires_at_utc',v_approval.expires_at_utc,
      'manifest_sha256',encode(v_approval.review_manifest_sha256,'hex'),
      'page_count',coalesce((select sum(coalesce(c.review_page_count,1))
        from public.candidate_submission_components c where c.id=any(v_approval.required_component_ids)),0),
      'ordered_components',v_approval.required_component_manifest_json,
      'manager_identity_requirements',jsonb_build_object('name_required',true,'position_required',true,'signature_required',true),
      'can_approve',true,'can_refuse',true);
    if v_mutation_request_sha256 is not null then
      perform private._candidate_workflow_mutation_receipt_v1(
        v_workflow.id,p_idempotency_key,v_mutation_request_sha256,v_action,
        v_mutation_channel,v_mutation_actor_identity,v_response,p_now_utc
      );
    end if;
    return v_response;

  elsif v_action='RECORD_REVIEW_PROGRESS' then
    if v_is_public_manager_action then
      select * into v_approval from public.candidate_approval_requests
      where workflow_id=v_workflow.id and token_hash=v_token_hash for update;
    else
      select * into v_approval from public.candidate_approval_requests
      where workflow_id=v_workflow.id and workflow_generation=v_workflow.generation
        and method='PHONE' and state='PENDING'
        and (not coalesce((v_payload->>'service_office_action')::boolean,false)
          or (id=(v_payload->>'approval_request_id')::uuid
            and request_generation=(v_payload->>'approval_request_generation')::integer))
      for update;
    end if;
    if not found or v_approval.state<>'PENDING' then
      raise exception 'MANAGER_APPROVAL_REQUEST_NOT_READY' using errcode='28000';
    end if;
    if v_approval.expires_at_utc<=p_now_utc then
      raise exception 'MANAGER_APPROVAL_REQUEST_EXPIRED' using errcode='28000';
    end if;
    if lower(coalesce(v_payload->>'manifest_sha256_hex',''))<>encode(v_approval.review_manifest_sha256,'hex') then
      raise exception 'MANAGER_REVIEW_MANIFEST_MISMATCH' using errcode='40001';
    end if;
    select * into v_component from public.candidate_submission_components
    where id=nullif(v_payload->>'component_id','')::uuid
      and id=any(v_approval.required_component_ids)
      and workflow_id=v_workflow.id and workflow_generation=v_workflow.generation
      and review_render_state='READY' for update;
    if not found or lower(coalesce(v_payload->>'component_sha256_hex',''))<>encode(v_component.review_content_sha256,'hex') then
      raise exception 'MANAGER_REVIEW_MANIFEST_MISMATCH' using errcode='40001';
    end if;
    update public.candidate_approval_requests set
      review_progress_json=review_progress_json||jsonb_build_object(v_component.id::text,jsonb_build_object(
        'component_id',v_component.id,'component_sha256',encode(v_component.review_content_sha256,'hex'),
        'manifest_sha256',encode(v_approval.review_manifest_sha256,'hex'),
        'viewed_receipt',coalesce(v_payload->'viewed_receipt','{}'::jsonb),
        'reviewed_at_utc',p_now_utc)),
      review_started_at_utc=coalesce(review_started_at_utc,p_now_utc),updated_at_utc=p_now_utc
    where id=v_approval.id returning * into v_approval;
    update public.candidate_submission_components set manager_reviewed_at_utc=p_now_utc
    where id=v_component.id;
    select count(*) into v_reviewed_count from unnest(v_approval.required_component_ids) u(id)
    where v_approval.review_progress_json ? u.id::text;
    v_response:=jsonb_build_object('ok',true,'workflow_id',v_workflow.id,
      'generation',v_workflow.generation,'approval_request_id',v_approval.id,
      'component_id',v_component.id,'reviewed_count',v_reviewed_count,
      'required_count',cardinality(v_approval.required_component_ids));
    update public.candidate_submission_workflows set
      last_mutation_idempotency_key=p_idempotency_key,last_mutation_response_json=v_response,
      updated_at_utc=p_now_utc where id=v_workflow.id;

  elsif v_action in ('PHONE_APPROVE','EMAIL_APPROVE') then
    if v_is_public_manager_action then
      select * into v_approval from public.candidate_approval_requests
      where workflow_id=v_workflow.id and token_hash=v_token_hash for update;
    else
      select * into v_approval from public.candidate_approval_requests
      where workflow_id=v_workflow.id and workflow_generation=v_workflow.generation
        and method='PHONE' and state='PENDING'
        and (not coalesce((v_payload->>'service_office_action')::boolean,false)
          or (id=(v_payload->>'approval_request_id')::uuid
            and request_generation=(v_payload->>'approval_request_generation')::integer))
      for update;
    end if;
    if not found or v_approval.state<>'PENDING' then
      raise exception 'MANAGER_APPROVAL_REQUEST_NOT_READY' using errcode='28000';
    end if;
    if v_approval.expires_at_utc<=p_now_utc then
      raise exception 'MANAGER_APPROVAL_REQUEST_EXPIRED' using errcode='28000';
    end if;
    if (v_action='EMAIL_APPROVE' and v_approval.method<>'EMAIL')
       or (v_action='PHONE_APPROVE' and v_approval.method<>'PHONE') then
      raise exception 'MANAGER_APPROVAL_METHOD_MISMATCH' using errcode='28000';
    end if;
    if lower(coalesce(v_payload->>'manifest_sha256_hex',''))<>encode(v_approval.review_manifest_sha256,'hex')
       or v_approval.workflow_generation<>v_workflow.generation
       or v_approval.review_manifest_sha256 is distinct from v_workflow.review_manifest_sha256 then
      raise exception 'MANAGER_REVIEW_MANIFEST_MISMATCH' using errcode='40001';
    end if;
    if exists(
      select 1 from unnest(v_approval.required_component_ids) u(id)
      join public.candidate_submission_components c on c.id=u.id
      where not (v_approval.review_progress_json ? u.id::text)
         or v_approval.review_progress_json#>>array[u.id::text,'component_sha256']
            is distinct from encode(c.review_content_sha256,'hex')
    ) then
      raise exception 'MANAGER_REVIEW_COMPONENT_NOT_REVIEWED' using errcode='55000';
    end if;
    if nullif(btrim(coalesce(v_payload->>'manager_name','')),'') is null
       or nullif(btrim(coalesce(v_payload->>'manager_position','')),'') is null then
      raise exception 'MANAGER_SIGNATURE_REQUIRED' using errcode='22023';
    end if;
    select * into v_signature_component from public.candidate_submission_components
    where id=nullif(v_payload->>'signature_component_id','')::uuid
      and workflow_id=v_workflow.id and workflow_generation=v_workflow.generation
      and document_role='MANAGER_SIGNATURE' and state='IMMUTABLE'
      and approval_request_id=v_approval.id
      and source_content_sha256 is not null for update;
    if not found then raise exception 'MANAGER_SIGNATURE_REQUIRED' using errcode='22023'; end if;
    update public.candidate_approval_requests set
      state='APPROVED',manager_name=btrim(v_payload->>'manager_name'),
      manager_position=btrim(v_payload->>'manager_position'),signature_component_id=v_signature_component.id,
      approved_at_utc=p_now_utc,review_completed_at_utc=p_now_utc,updated_at_utc=p_now_utc
    where id=v_approval.id returning * into v_approval;
    update public.candidate_approval_requests set
      state='SUPERSEDED',superseded_at_utc=p_now_utc,updated_at_utc=p_now_utc
    where workflow_id=v_workflow.id and id<>v_approval.id and state='PENDING';
    update public.candidate_submission_components set manager_approved_at_utc=p_now_utc
    where id=any(v_approval.required_component_ids);
    update public.candidate_submission_workflows set
      state='MANAGER_APPROVED_PENDING_FINAL_DOCUMENT',route=v_approval.method,
      manager_name=v_approval.manager_name,manager_position=v_approval.manager_position,
      manager_signature_component_id=v_signature_component.id,
      manager_signature_sha256=v_signature_component.source_content_sha256,
      manager_approved_at_utc=p_now_utc,last_mutation_idempotency_key=p_idempotency_key,
      updated_at_utc=p_now_utc
    where id=v_workflow.id returning * into v_workflow;
    v_render_contract:=private._candidate_render_contract_v1(
      v_workflow.id,v_workflow.generation,'FINAL_SIGNED');
    v_response:=jsonb_build_object('ok',true,'workflow_id',v_workflow.id,
      'state',v_workflow.state,'generation',v_workflow.generation,
      'approval_request_id',v_approval.id,'approved_at_utc',v_approval.approved_at_utc,
      'final_render_contract',v_render_contract);
    update public.candidate_submission_workflows set last_mutation_response_json=v_response
    where id=v_workflow.id;
    perform private._candidate_notification_insert_v1(v_account_id,v_candidate_id,v_workflow.id,
      v_workflow.target_timesheet_id,'MANAGER_APPROVED','manager_approval',
      'candidate-manager-approved-v1','{}'::jsonb,
      jsonb_build_object('type','workflow','workflow_id',v_workflow.id),
      'CANDIDATE_MANAGER_APPROVED_V1:'||v_workflow.id::text||':'||v_workflow.generation::text,p_now_utc);

  elsif v_action='REGISTER_FINAL_SIGNED_DOCUMENT' then
    if v_workflow.state not in ('MANAGER_APPROVED_PENDING_FINAL_DOCUMENT','READY_TO_FINALISE') then
      raise exception 'FINAL_SIGNED_DOCUMENT_STALE' using errcode='55000';
    end if;
    select * into v_component from public.candidate_submission_components
    where id=nullif(v_payload->>'component_id','')::uuid
      and workflow_id=v_workflow.id and workflow_generation=v_workflow.generation
      and required=true and state='IMMUTABLE'
      and review_render_state='READY' for update;
    if not found then raise exception 'FINAL_SIGNED_DOCUMENT_STALE' using errcode='55000'; end if;
    if coalesce(v_payload->>'content_sha256_hex','') !~ '^[0-9a-fA-F]{64}$'
       or coalesce(v_payload->>'render_input_sha256_hex','') !~ '^[0-9a-fA-F]{64}$' then
      raise exception 'FINAL_SIGNED_DOCUMENT_NOT_READY' using errcode='22023';
    end if;
    v_digest:=decode(v_payload->>'content_sha256_hex','hex');
    v_render_input_hash:=decode(v_payload->>'render_input_sha256_hex','hex');
    v_receipt:=coalesce(v_payload->'renderer_receipt','{}'::jsonb);
    v_render_contract:=private._candidate_component_render_contract_v1(
      v_workflow.id,v_workflow.generation,v_component.id,'FINAL');
    if v_render_input_hash<>decode(v_render_contract->>'render_input_sha256','hex')
       or v_render_input_hash is distinct from v_component.review_render_input_sha256
       or nullif(btrim(v_payload->>'storage_key'),'') is null
       or lower(coalesce(v_payload->>'media_type',''))<>'application/pdf'
       or coalesce((v_payload->>'page_count')::integer,0)<>1
       or coalesce((v_payload->>'byte_size')::bigint,0)<=0
       or upper(coalesce(v_receipt->>'form_variant',''))<>v_render_contract->>'form_variant'
       or nullif(v_receipt->>'workflow_id','')::uuid is distinct from v_workflow.id
       or coalesce((v_receipt->>'workflow_generation')::integer,0)<>v_workflow.generation
       or nullif(v_receipt->>'component_id','')::uuid is distinct from v_component.id
       or upper(coalesce(v_receipt->>'component_kind',''))<>v_component.component_kind
       or upper(coalesce(v_receipt->>'document_role',''))<>v_component.document_role
       or coalesce((v_receipt->>'review_ordinal')::integer,0)<>v_component.review_ordinal
       or upper(coalesce(v_receipt->>'scope',''))<>v_workflow.scope
       or coalesce((v_receipt->>'candidate_signature_embedded')::boolean,false)
          is distinct from (v_component.component_kind='HOURS_TIMESHEET')
       or coalesce((v_receipt->>'manager_signature_embedded')::boolean,false)=false
       or coalesce((v_receipt->>'manager_approval_date_embedded')::boolean,false)=false
       or coalesce((v_receipt->>'page_count')::integer,0)<>1
       or lower(coalesce(v_receipt->>'render_input_sha256',''))<>encode(v_render_input_hash,'hex')
       or (v_component.component_kind='HOURS_TIMESHEET' and
          lower(coalesce(v_receipt->>'candidate_signature_sha256',''))<>encode(v_workflow.candidate_signature_sha256,'hex'))
       or lower(coalesce(v_receipt->>'manager_signature_sha256',''))<>encode(v_workflow.manager_signature_sha256,'hex')
       or btrim(coalesce(v_receipt->>'manager_name',''))<>v_workflow.manager_name
       or btrim(coalesce(v_receipt->>'manager_position',''))<>v_workflow.manager_position
       or nullif(v_receipt->>'manager_approved_at_utc','')::timestamptz is distinct from v_workflow.manager_approved_at_utc then
      raise exception 'FINAL_RENDER_INPUT_MISMATCH' using errcode='40001';
    end if;
    if v_component.final_signed_render_state='READY' then
      if v_component.final_signed_storage_key=v_payload->>'storage_key'
         and v_component.final_signed_content_sha256=v_digest
         and v_component.final_signed_render_input_sha256=v_render_input_hash then
        v_response:=jsonb_build_object('ok',true,'idempotent_replay',true,
          'workflow_id',v_workflow.id,'generation',v_workflow.generation,
          'component_id',v_component.id,'state',v_workflow.state);
        if v_mutation_request_sha256 is not null then
          perform private._candidate_workflow_mutation_receipt_v1(
            v_workflow.id,p_idempotency_key,v_mutation_request_sha256,v_action,
            v_mutation_channel,v_mutation_actor_identity,v_response,p_now_utc
          );
        end if;
        return v_response;
      end if;
      raise exception 'FINAL_SIGNED_DOCUMENT_STALE' using errcode='55000';
    end if;
    update public.candidate_submission_components set
      final_signed_storage_key=v_payload->>'storage_key',final_signed_content_sha256=v_digest,
      final_signed_media_type='application/pdf',final_signed_byte_size=(v_payload->>'byte_size')::bigint,
      final_signed_page_count=1,final_signed_render_input_sha256=v_render_input_hash,
      final_signed_renderer_contract_version=coalesce(nullif(v_payload->>'renderer_contract_version',''),v_workflow.renderer_contract_version),
      final_signed_renderer_receipt_json=v_receipt,final_signed_generated_at_utc=p_now_utc,
      final_signed_render_state='READY'
    where id=v_component.id returning * into v_component;
    select exists(
      select 1 from public.candidate_submission_components c
      where c.workflow_id=v_workflow.id and c.workflow_generation=v_workflow.generation
        and c.required=true and c.state<>'SUPERSEDED'
    ) and not exists(
      select 1 from public.candidate_submission_components c
      where c.workflow_id=v_workflow.id and c.workflow_generation=v_workflow.generation
        and c.required=true and c.state<>'SUPERSEDED'
        and c.final_signed_render_state<>'READY'
    ) into v_all_final_ready;
    v_response:=jsonb_build_object('ok',true,'idempotent_replay',false,
      'workflow_id',v_workflow.id,
      'state',case when v_all_final_ready then 'READY_TO_FINALISE' else 'MANAGER_APPROVED_PENDING_FINAL_DOCUMENT' end,
      'generation',v_workflow.generation,'component_id',v_component.id,
      'component_final_signed_document_ready',true,'all_final_signed_documents_ready',v_all_final_ready);
    update public.candidate_submission_workflows set
      state=case when v_all_final_ready then 'READY_TO_FINALISE' else 'MANAGER_APPROVED_PENDING_FINAL_DOCUMENT' end,
      last_mutation_idempotency_key=p_idempotency_key,
      last_mutation_response_json=v_response,updated_at_utc=p_now_utc where id=v_workflow.id;

  elsif v_action='BEGIN_CANONICAL_DAILY_SAVE' then
    if v_workflow.workflow_kind<>'DAILY' or v_workflow.scope<>'DAILY'
       or v_workflow.state<>'READY_TO_FINALISE' or v_workflow.route not in ('PHONE','EMAIL') then
      raise exception 'CANDIDATE_DAILY_CANONICAL_SAVE_NOT_READY' using errcode='55000';
    end if;
    if not private._candidate_daily_entitled_v1(v_workflow.candidate_id) then
      raise exception 'CANDIDATE_DAILY_ENTITLEMENT_REQUIRED' using errcode='55000';
    end if;
    v_daily_input:=private._candidate_daily_canonical_save_input_v1(v_workflow.id,v_workflow.generation);
    v_expected_save_hash:=private._candidate_sha256_jsonb_v1(v_daily_input);
    v_daily_context:=private._candidate_daily_context_contract_v1(
      v_workflow.id,v_workflow.generation
    );
    v_daily_context_hash:=private._candidate_sha256_jsonb_v1(v_daily_context);
    if v_workflow.canonical_saved_at_utc is not null
       and v_workflow.canonical_save_input_sha256=v_expected_save_hash
       and v_workflow.canonical_save_financials_id is not null
       and nullif(btrim(coalesce(v_workflow.canonical_save_row_signature,'')),'') is not null then
      v_response:=jsonb_build_object(
        'ok',true,'idempotent_replay',true,'workflow_id',v_workflow.id,
        'generation',v_workflow.generation,'state',v_workflow.state,
        'canonical_save_registered',true,
        'canonical_save_input_sha256_hex',encode(v_expected_save_hash,'hex'),
        'canonical_context_sha256_hex',encode(v_workflow.daily_context_sha256,'hex'),
        'canonical_save_row_signature',v_workflow.canonical_save_row_signature,
        'canonical_save_financials_id',v_workflow.canonical_save_financials_id
      );
      if v_mutation_request_sha256 is not null then
        perform private._candidate_workflow_mutation_receipt_v1(
          v_workflow.id,p_idempotency_key,v_mutation_request_sha256,v_action,
          v_mutation_channel,v_mutation_actor_identity,v_response,p_now_utc
        );
      end if;
      return v_response;
    end if;
    v_current_row_signature:=nullif(btrim(v_daily_context->>'pre_save_row_signature'),'');
    if v_current_row_signature is null then
      raise exception 'CANDIDATE_DAILY_ROW_SIGNATURE_REQUIRED' using errcode='55000';
    end if;
    v_response:=jsonb_build_object(
      'ok',true,'idempotent_replay',false,'workflow_id',v_workflow.id,
      'generation',v_workflow.generation,'state',v_workflow.state,
      'canonical_save_registered',false,'canonical_save_input',v_daily_input,
      'canonical_save_input_sha256_hex',encode(v_expected_save_hash,'hex'),
      'canonical_context',v_daily_context,
      'canonical_context_sha256_hex',encode(v_daily_context_hash,'hex'),
      'expected_row_signature',v_current_row_signature
    );
    update public.candidate_submission_workflows set
      daily_context_sha256=v_daily_context_hash,canonical_financial_sha256=null,
      canonical_save_input_sha256=null,canonical_save_row_signature=null,
      canonical_save_financials_id=null,canonical_save_receipt_json=null,canonical_saved_at_utc=null,
      last_mutation_idempotency_key=p_idempotency_key,last_mutation_response_json=v_response,
      updated_at_utc=p_now_utc
    where id=v_workflow.id returning * into v_workflow;

  elsif v_action='MANAGER_REFUSE' then
    if v_is_public_manager_action then
      select * into v_approval from public.candidate_approval_requests
      where workflow_id=v_workflow.id and token_hash=v_token_hash for update;
    else
      select * into v_approval from public.candidate_approval_requests
      where workflow_id=v_workflow.id and workflow_generation=v_workflow.generation
        and state='PENDING'
        and (not coalesce((v_payload->>'service_office_action')::boolean,false)
          or (id=(v_payload->>'approval_request_id')::uuid
            and request_generation=(v_payload->>'approval_request_generation')::integer))
      for update;
    end if;
    if not found or v_approval.state<>'PENDING' then
      raise exception 'MANAGER_APPROVAL_REQUEST_NOT_READY' using errcode='28000';
    end if;
    if v_approval.expires_at_utc<=p_now_utc then
      raise exception 'MANAGER_APPROVAL_REQUEST_EXPIRED' using errcode='28000';
    end if;
    if nullif(btrim(coalesce(v_payload->>'reason','')),'') is null then
      raise exception 'MANAGER_REFUSAL_REASON_REQUIRED' using errcode='22023';
    end if;
    update public.candidate_approval_requests set
      state='REFUSED',refusal_reason=btrim(v_payload->>'reason'),refused_at_utc=p_now_utc,
      updated_at_utc=p_now_utc where id=v_approval.id;
    update public.candidate_approval_requests set
      state='SUPERSEDED',superseded_at_utc=p_now_utc,updated_at_utc=p_now_utc
    where workflow_id=v_workflow.id and id<>v_approval.id and state='PENDING';
    v_response:=jsonb_build_object('ok',true,'workflow_id',v_workflow.id,'state','REFUSED',
      'generation',v_workflow.generation,'rejection_scope','COMPLETE_ELECTRONIC_TRANSACTION');
    update public.candidate_submission_workflows set
      state='REFUSED',rejection_reason=btrim(v_payload->>'reason'),
      rejection_scope='COMPLETE_ELECTRONIC_TRANSACTION',last_mutation_idempotency_key=p_idempotency_key,
      last_mutation_response_json=v_response,updated_at_utc=p_now_utc where id=v_workflow.id;
    perform private._candidate_notification_insert_v1(v_account_id,v_candidate_id,v_workflow.id,
      v_workflow.target_timesheet_id,'MANAGER_REFUSED','manager_refusal','candidate-manager-refused-v1',
      jsonb_build_object('reason',btrim(v_payload->>'reason')),
      jsonb_build_object('type','workflow','workflow_id',v_workflow.id),
      'CANDIDATE_MANAGER_REFUSED_V1:'||v_workflow.id::text||':'||v_workflow.generation::text,p_now_utc);

  elsif v_action='REMIND' then
    if nullif(v_payload->>'approval_request_id','') is null
       or nullif(v_payload->>'approval_request_generation','') is null then
      raise exception 'CANDIDATE_REQUEST_GENERATION_STALE' using errcode='40001';
    end if;
    select * into v_approval from public.candidate_approval_requests
    where workflow_id=v_workflow.id and workflow_generation=v_workflow.generation
      and method='EMAIL' and state='PENDING'
      and id=(v_payload->>'approval_request_id')::uuid
      and request_generation=(v_payload->>'approval_request_generation')::integer
    for update skip locked;
    if not found or v_approval.review_manifest_sha256 is distinct from v_workflow.review_manifest_sha256 then
      raise exception 'MANAGER_REMINDER_NOT_ELIGIBLE' using errcode='55000';
    end if;
    if coalesce(v_payload->>'approval_token_hash_hex','') !~ '^[0-9a-fA-F]{64}$' then
      raise exception 'CANDIDATE_APPROVAL_TOKEN_INVALID' using errcode='22023';
    end if;
    select max(manager_mail.sent_at),count(*) filter (
      where manager_mail.status='QUEUED' and manager_mail.sent_at is null
        and lower(coalesce(manager_mail.payment_scope_json->>'candidate_manager_mail_retired','false'))
              in ('false','f','0','no')
    )::integer
    into v_manager_provider_accepted_at,v_manager_pending_mail_count
    from public.mail_outbox manager_mail
    where upper(coalesce(manager_mail.payment_scope_json->>'candidate_mail_authority',''))
            ='MANAGER_APPROVAL_V1'
      and manager_mail.payment_scope_json->>'candidate_manager_workflow_id'=v_workflow.id::text
      and manager_mail.payment_scope_json->>'candidate_manager_workflow_generation'=v_workflow.generation::text
      and manager_mail.payment_scope_json->>'candidate_approval_request_id'=v_approval.id::text
      and manager_mail.payment_scope_json->>'candidate_approval_request_generation'=v_approval.request_generation::text
      and upper(coalesce(manager_mail.payment_scope_json->>'candidate_manager_mail_kind',''))
            in ('INITIAL','REMINDER','RENEWAL')
      and (
        manager_mail.status='QUEUED'
        or (manager_mail.status='SENT' and manager_mail.sent_at is not null
          and upper(coalesce(manager_mail.provider_status,'')) in ('ACCEPTED','SENT','SUCCESS','OK'))
      );
    if v_approval.expires_at_utc<=p_now_utc or v_approval.resend_count>=5
       or v_manager_provider_accepted_at is null
       or v_manager_provider_accepted_at+interval '24 hours'>p_now_utc
       or v_manager_pending_mail_count>0 then
      raise exception 'MANAGER_REMINDER_NOT_ELIGIBLE' using errcode='55000';
    end if;
    v_token_hash:=decode(v_payload->>'approval_token_hash_hex','hex');
    update public.candidate_approval_requests set
      token_hash=v_token_hash,resend_count=resend_count+1,
      initial_sent_at_utc=null,last_sent_at_utc=null,next_reminder_at_utc=null,
      updated_at_utc=p_now_utc
    where id=v_approval.id returning * into v_approval;
    v_mail_id:=private._candidate_queue_mail_v1(
      coalesce(v_payload->'mail','{}'::jsonb)||jsonb_build_object(
        'payment_scope_json',jsonb_build_object(
          'candidate_mail_authority','MANAGER_APPROVAL_V1',
          'candidate_manager_mail_kind','REMINDER',
          'candidate_manager_workflow_id',v_workflow.id,
          'candidate_manager_workflow_generation',v_workflow.generation,
          'candidate_approval_request_id',v_approval.id,
          'candidate_approval_request_generation',v_approval.request_generation,
          'candidate_manager_mail_retired',false
        )
      ),v_approval.manager_email_normalized,
      'CANDIDATE_MANAGER_REMINDER_V1:'||v_approval.id::text||':'||v_approval.resend_count::text,
      'candidate-manager-reminder:'||v_approval.id::text||':'||v_approval.resend_count::text,
      v_workflow.id,p_now_utc);
    v_response:=jsonb_build_object('ok',true,'workflow_id',v_workflow.id,'state',v_workflow.state,
      'generation',v_workflow.generation,'approval_request_id',v_approval.id,
      'resend_count',v_approval.resend_count,
      'previous_provider_accepted_at_utc',v_manager_provider_accepted_at,
      'reminder_delivery_pending',true,
      'mail_outbox_id',v_mail_id);
    update public.candidate_submission_workflows set
      last_mutation_idempotency_key=p_idempotency_key,last_mutation_response_json=v_response,
      updated_at_utc=p_now_utc where id=v_workflow.id;

  elsif v_action='RENEW' then
    if v_workflow.state<>'AWAITING_MANAGER_APPROVAL'
       or v_workflow.review_manifest_sha256 is null then
      raise exception 'MANAGER_APPROVAL_NOT_RENEWABLE' using errcode='55000';
    end if;
    if nullif(v_payload->>'approval_request_id','') is null
       or nullif(v_payload->>'approval_request_generation','') is null then
      raise exception 'CANDIDATE_REQUEST_GENERATION_STALE' using errcode='40001';
    end if;
    select * into v_approval from public.candidate_approval_requests
    where workflow_id=v_workflow.id and method='EMAIL'
      and id=(v_payload->>'approval_request_id')::uuid
      and request_generation=(v_payload->>'approval_request_generation')::integer
    for update;
    if found and v_approval.state='PENDING' and v_approval.expires_at_utc<=p_now_utc then
      update public.candidate_approval_requests set
        state='EXPIRED',updated_at_utc=p_now_utc
      where id=v_approval.id returning * into v_approval;
    end if;
    if not found or v_approval.state<>'EXPIRED'
       or v_approval.review_manifest_sha256 is distinct from v_workflow.review_manifest_sha256 then
      raise exception 'MANAGER_APPROVAL_NOT_RENEWABLE' using errcode='55000';
    end if;
    if coalesce(v_payload->>'approval_token_hash_hex','') !~ '^[0-9a-fA-F]{64}$' then
      raise exception 'CANDIDATE_APPROVAL_TOKEN_INVALID' using errcode='22023';
    end if;
    v_token_hash:=decode(v_payload->>'approval_token_hash_hex','hex');
    update public.candidate_approval_requests set
      state='SUPERSEDED',superseded_at_utc=p_now_utc,updated_at_utc=p_now_utc where id=v_approval.id;
    insert into public.candidate_approval_requests(
      workflow_id,workflow_generation,request_generation,method,state,manager_email_normalized,
      token_hash,expires_at_utc,initial_sent_at_utc,last_sent_at_utc,next_reminder_at_utc,
      renewal_count,review_manifest_sha256,required_component_ids,required_component_manifest_json,
      manager_review_timesheet_component_id,manager_review_timesheet_sha256,
      idempotency_key,created_at_utc,updated_at_utc
    ) values (
      v_workflow.id,v_workflow.generation,v_approval.request_generation+1,'EMAIL','PENDING',
      v_approval.manager_email_normalized,v_token_hash,p_now_utc+interval '7 days',null,null,
      null,v_approval.renewal_count+1,v_approval.review_manifest_sha256,
      v_approval.required_component_ids,v_approval.required_component_manifest_json,
      v_approval.manager_review_timesheet_component_id,v_approval.manager_review_timesheet_sha256,
      p_idempotency_key,p_now_utc,p_now_utc
    ) returning * into v_approval;
    v_mail_id:=private._candidate_queue_mail_v1(
      coalesce(v_payload->'mail','{}'::jsonb)||jsonb_build_object(
        'payment_scope_json',jsonb_build_object(
          'candidate_mail_authority','MANAGER_APPROVAL_V1',
          'candidate_manager_mail_kind','RENEWAL',
          'candidate_manager_workflow_id',v_workflow.id,
          'candidate_manager_workflow_generation',v_workflow.generation,
          'candidate_approval_request_id',v_approval.id,
          'candidate_approval_request_generation',v_approval.request_generation,
          'candidate_manager_mail_retired',false
        )
      ),v_approval.manager_email_normalized,
      'CANDIDATE_MANAGER_RENEW_V1:'||v_approval.id::text,
      'candidate-manager-renew:'||v_approval.id::text,v_workflow.id,p_now_utc);
    v_response:=jsonb_build_object('ok',true,'workflow_id',v_workflow.id,
      'state','AWAITING_MANAGER_APPROVAL','generation',v_workflow.generation,
      'approval_request_id',v_approval.id,'expires_at_utc',v_approval.expires_at_utc,
      'renewal_count',v_approval.renewal_count,'mail_outbox_id',v_mail_id);
    update public.candidate_submission_workflows set
      last_mutation_idempotency_key=p_idempotency_key,last_mutation_response_json=v_response,
      updated_at_utc=p_now_utc where id=v_workflow.id;

  elsif v_action='MANAGER_REQUEST_CANCEL' then
    if not v_is_service_action then
      raise exception 'CANDIDATE_MANAGER_REQUEST_CANCEL_SERVICE_REQUIRED' using errcode='42501';
    end if;
    v_cancel_reason:=nullif(btrim(coalesce(v_payload->>'reason_note',v_payload->>'reason','')), '');
    v_cancel_reason_code:=coalesce(
      nullif(upper(btrim(coalesce(v_payload->>'reason_code',''))),''),
      'OFFICE_MANAGER_REQUEST_CANCELLED'
    );
    if v_cancel_reason is null then
      raise exception 'CANDIDATE_CANCELLATION_REASON_REQUIRED' using errcode='22023';
    end if;
    if length(v_cancel_reason)>1000 then
      raise exception 'CANDIDATE_CANCELLATION_REASON_INVALID' using errcode='22023';
    end if;
    v_audit_reason:=v_cancel_reason;
    if v_workflow.state<>'AWAITING_MANAGER_APPROVAL' then
      raise exception 'MANAGER_APPROVAL_REQUEST_NOT_CANCELLABLE' using errcode='55000';
    end if;
    select request_row.* into v_approval
    from public.candidate_approval_requests request_row
    where request_row.id=(v_payload->>'approval_request_id')::uuid
      and request_row.workflow_id=v_workflow.id
      and request_row.workflow_generation=v_workflow.generation
      and request_row.request_generation=(v_payload->>'approval_request_generation')::integer
      and request_row.method='EMAIL'
      and request_row.state='PENDING'
    for update;
    if not found then
      raise exception 'MANAGER_APPROVAL_REQUEST_NOT_CANCELLABLE' using errcode='55000';
    end if;
    v_manager_retirement_result:=private._candidate_manager_mail_retire_v1(
      v_workflow.id,v_workflow.generation,array[v_approval.id],
      'APPROVAL_REQUEST_CANCELLED',p_now_utc
    );
    update public.candidate_approval_requests set
      state='CANCELLED',cancelled_at_utc=p_now_utc,updated_at_utc=p_now_utc
    where id=v_approval.id;
    update public.candidate_submission_components set
      state='SUPERSEDED',superseded_at_utc=p_now_utc
    where workflow_id=v_workflow.id
      and workflow_generation=v_workflow.generation
      and approval_request_id=v_approval.id
      and component_kind='MANAGER_SIGNATURE'
      and state<>'SUPERSEDED';
    if coalesce((v_manager_retirement_result->>'withdrawal_required')::boolean,false) then
      perform private._candidate_queue_mail_v1(
        jsonb_build_object(
          'subject','Timesheet approval request withdrawn',
          'body_text','The approval request for this timesheet has been withdrawn by CloudTMS. No further action is required.',
          'body_html','<p>The approval request for this timesheet has been withdrawn by CloudTMS. No further action is required.</p>',
          'payment_scope_json',jsonb_build_object(
            'candidate_mail_authority','MANAGER_APPROVAL_V1',
            'candidate_manager_mail_kind','WITHDRAWAL',
            'candidate_manager_workflow_id',v_workflow.id,
            'candidate_manager_workflow_generation',v_workflow.generation,
            'candidate_approval_request_id',v_approval.id,
            'candidate_approval_request_generation',v_approval.request_generation,
            'candidate_manager_mail_retired',false
          )
        ),v_approval.manager_email_normalized,
        'CANDIDATE_MANAGER_WITHDRAWAL_V1:'||v_approval.id::text||':'||v_workflow.generation::text,
        'candidate-manager-withdrawal:'||v_approval.id::text,v_workflow.id,p_now_utc
      );
      v_manager_withdrawal_count:=1;
    end if;
    v_response:=jsonb_build_object(
      'ok',true,'workflow_id',v_workflow.id,
      'state','READY_FOR_MANAGER_APPROVAL','generation',v_workflow.generation,
      'approval_request_id',v_approval.id,'manager_request_cancelled',true,
      'cancellation_reason',v_cancel_reason,
      'cancellation_reason_code',v_cancel_reason_code,
      'manager_withdrawal_count',v_manager_withdrawal_count,
      'manager_mail_retirement',v_manager_retirement_result,
      'claim_cancelled',false
    );
    update public.candidate_submission_workflows set
      state='READY_FOR_MANAGER_APPROVAL',route='ELECTRONIC',
      last_mutation_idempotency_key=p_idempotency_key,
      last_mutation_response_json=v_response,updated_at_utc=p_now_utc
    where id=v_workflow.id returning * into v_workflow;

  elsif v_action='CANCEL_MANAGER_HANDOFF' then
    if v_workflow.state<>'AWAITING_MANAGER_APPROVAL' or v_workflow.route<>'PHONE' then
      raise exception 'MANAGER_PHONE_HANDOFF_NOT_CANCELLABLE' using errcode='55000';
    end if;
    select * into v_approval from public.candidate_approval_requests
    where workflow_id=v_workflow.id and workflow_generation=v_workflow.generation
      and method='PHONE' and state='PENDING'
      and (not coalesce((v_payload->>'service_office_action')::boolean,false)
        or (id=(v_payload->>'approval_request_id')::uuid
          and request_generation=(v_payload->>'approval_request_generation')::integer))
    order by request_generation desc limit 1 for update;
    if not found then raise exception 'MANAGER_PHONE_HANDOFF_NOT_CANCELLABLE' using errcode='55000'; end if;
    update public.candidate_approval_requests set
      state='CANCELLED',cancelled_at_utc=p_now_utc,updated_at_utc=p_now_utc
    where id=v_approval.id;
    update public.candidate_submission_components set
      state='SUPERSEDED',superseded_at_utc=p_now_utc
    where workflow_id=v_workflow.id and workflow_generation=v_workflow.generation
      and approval_request_id=v_approval.id and component_kind='MANAGER_SIGNATURE'
      and state<>'SUPERSEDED';
    v_response:=jsonb_build_object('ok',true,'workflow_id',v_workflow.id,
      'state','READY_FOR_MANAGER_APPROVAL','generation',v_workflow.generation,
      'approval_request_id',v_approval.id,'handoff_cancelled',true);
    update public.candidate_submission_workflows set
      state='READY_FOR_MANAGER_APPROVAL',route='ELECTRONIC',
      last_mutation_idempotency_key=p_idempotency_key,last_mutation_response_json=v_response,
      updated_at_utc=p_now_utc where id=v_workflow.id returning * into v_workflow;

  elsif v_action='MANAGER_PROVIDER_SUBMIT_PERMIT' then
    if not v_is_service_action then
      raise exception 'CANDIDATE_MANAGER_PROVIDER_SUBMIT_PERMIT_SERVICE_REQUIRED'
        using errcode='42501';
    end if;
    v_provider_lease_token:=nullif(btrim(coalesce(v_payload->>'attempt_lease_token','')),'');
    if v_provider_lease_token is null
       or coalesce(v_payload->>'mail_outbox_id','')
          !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      raise exception 'CANDIDATE_MANAGER_PROVIDER_PERMIT_INVALID' using errcode='22023';
    end if;
    select candidate_mail.* into v_manager_mail
    from public.mail_outbox candidate_mail
    where candidate_mail.id=(v_payload->>'mail_outbox_id')::uuid
      and candidate_mail.type='TIMESHEET_GENERAL'
      and candidate_mail.context_kind='CANDIDATE_WORKFLOW'
      and candidate_mail.context_id=v_workflow.id
      and candidate_mail.status='QUEUED'
      and candidate_mail.sent_at is null
      and candidate_mail.attempt_lease_token=v_provider_lease_token
      and candidate_mail.attempt_lease_expires_at_utc>p_now_utc
      and upper(coalesce(candidate_mail.payment_scope_json->>'candidate_mail_authority',''))
            ='MANAGER_APPROVAL_V1'
      and lower(coalesce(candidate_mail.payment_scope_json->>'candidate_manager_mail_retired','false'))
            in ('false','f','0','no')
    for update;
    if not found then
      raise exception 'CANDIDATE_MANAGER_PROVIDER_MAIL_STALE' using errcode='40001';
    end if;
    v_manager_mail_kind:=upper(coalesce(
      v_manager_mail.payment_scope_json->>'candidate_manager_mail_kind',''
    ));
    if v_manager_mail_kind not in ('INITIAL','REMINDER','RENEWAL','WITHDRAWAL')
       or coalesce(v_manager_mail.payment_scope_json->>'candidate_approval_request_id','')
          !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       or coalesce(v_manager_mail.payment_scope_json->>'candidate_approval_request_generation','')
          !~ '^[1-9][0-9]{0,8}$'
       or coalesce(v_manager_mail.payment_scope_json->>'candidate_manager_workflow_generation','')
          !~ '^[1-9][0-9]{0,8}$' then
      raise exception 'CANDIDATE_MANAGER_PROVIDER_MAIL_STALE' using errcode='40001';
    end if;
    select request_row.* into v_approval
    from public.candidate_approval_requests request_row
    where request_row.id=(v_manager_mail.payment_scope_json->>'candidate_approval_request_id')::uuid
      and request_row.workflow_id=v_workflow.id
      and request_row.workflow_generation=
            (v_manager_mail.payment_scope_json->>'candidate_manager_workflow_generation')::integer
      and request_row.request_generation=
            (v_manager_mail.payment_scope_json->>'candidate_approval_request_generation')::integer
      and request_row.method='EMAIL'
      and request_row.manager_email_normalized=v_manager_mail."to"
    for update;
    if not found then
      raise exception 'CANDIDATE_MANAGER_PROVIDER_MAIL_STALE' using errcode='40001';
    end if;
    if v_manager_mail_kind='WITHDRAWAL' then
      if v_approval.state not in ('CANCELLED','SUPERSEDED','EXPIRED','REFUSED') then
        raise exception 'CANDIDATE_MANAGER_PROVIDER_MAIL_STALE' using errcode='40001';
      end if;
    elsif v_approval.state<>'PENDING' or v_approval.expires_at_utc<=p_now_utc
       or v_workflow.route<>'EMAIL' or v_workflow.state<>'AWAITING_MANAGER_APPROVAL'
       or v_workflow.generation<>v_approval.workflow_generation
       or v_approval.review_manifest_sha256 is distinct from v_workflow.review_manifest_sha256 then
      raise exception 'CANDIDATE_MANAGER_PROVIDER_MAIL_STALE' using errcode='40001';
    end if;
    v_provider_permit_expires_at:=greatest(
      v_manager_mail.attempt_lease_expires_at_utc,p_now_utc+interval '15 minutes'
    );
    update public.mail_outbox candidate_mail
    set attempt_lease_expires_at_utc=v_provider_permit_expires_at
    where candidate_mail.id=v_manager_mail.id
      and candidate_mail.status='QUEUED' and candidate_mail.sent_at is null
      and candidate_mail.attempt_lease_token=v_provider_lease_token
      and candidate_mail.attempt_lease_expires_at_utc>p_now_utc
      and lower(coalesce(candidate_mail.payment_scope_json->>'candidate_manager_mail_retired','false'))
            in ('false','f','0','no');
    if not found then
      raise exception 'CANDIDATE_MANAGER_PROVIDER_MAIL_STALE' using errcode='40001';
    end if;
    v_response:=jsonb_build_object(
      'ok',true,'workflow_id',v_workflow.id,'generation',v_workflow.generation,
      'approval_request_id',v_approval.id,'mail_outbox_id',v_manager_mail.id,
      'approval_request_generation',v_approval.request_generation,
      'approval_workflow_generation',v_approval.workflow_generation,
      'manager_mail_kind',v_manager_mail_kind,'provider_submit_permit',true,
      'provider_submit_permit_expires_at_utc',v_provider_permit_expires_at
    );

  elsif v_action='PAPER_PROVIDER_SUBMIT_PERMIT' then
    if not v_is_service_action or p_session_id is not null then
      raise exception 'CANDIDATE_PAPER_PROVIDER_SUBMIT_PERMIT_SERVICE_REQUIRED'
        using errcode='28000';
    end if;
    v_paper_mail_id:=nullif(btrim(coalesce(v_payload->>'mail_outbox_id','')),'')::uuid;
    v_provider_lease_token:=nullif(btrim(coalesce(v_payload->>'attempt_lease_token','')),'');
    v_paper_manifest_sha256:=lower(btrim(coalesce(
      v_payload->>'paper_return_manifest_sha256',''
    )));
    if v_paper_mail_id is null or v_provider_lease_token is null
       or v_paper_manifest_sha256 !~ '^[0-9a-f]{64}$' then
      raise exception 'CANDIDATE_PAPER_PROVIDER_BINDING_INVALID' using errcode='22023';
    end if;
    if v_workflow.route<>'PAPER'
       or v_workflow.state<>'AWAITING_PAPER_RETURN'
       or v_workflow.paper_return_manifest_sha256 is null
       or encode(v_workflow.paper_return_manifest_sha256,'hex')<>v_paper_manifest_sha256 then
      raise exception 'CANDIDATE_PAPER_PROVIDER_WORKFLOW_STALE' using errcode='40001';
    end if;
    select candidate_mail.* into v_paper_mail
    from public.mail_outbox candidate_mail
    where candidate_mail.id=v_paper_mail_id
      and candidate_mail.type='TIMESHEET_QR'
      and candidate_mail.status='QUEUED'
      and candidate_mail.sent_at is null
      and candidate_mail.context_kind='timesheets'
      and candidate_mail.context_id=coalesce(
        v_workflow.target_timesheet_id,v_workflow.anchor_timesheet_id
      )
      and candidate_mail.attempt_lease_token=v_provider_lease_token
      and candidate_mail.attempt_lease_expires_at_utc>p_now_utc
      and candidate_mail.payment_scope_json->>'candidate_mail_authority'='CANDIDATE_PAPER_V1'
      and candidate_mail.payment_scope_json->>'candidate_workflow_id'=v_workflow.id::text
      and candidate_mail.payment_scope_json->>'candidate_workflow_generation'=v_workflow.generation::text
      and lower(coalesce(candidate_mail.payment_scope_json->>'paper_return_manifest_sha256',''))
            =v_paper_manifest_sha256
      and lower(coalesce(candidate_mail.payment_scope_json->>'candidate_paper_generation_retired','false'))
            in ('false','f','0','no')
      and lower(coalesce(candidate_mail.payment_scope_json->>'candidate_paper_pack_ready','false'))
            in ('true','t','1','yes')
      and lower(coalesce(candidate_mail.payment_scope_json->>'mail_held_until_pdf_rendered','false'))
            in ('false','f','0','no')
      and jsonb_typeof(candidate_mail.attachments)='array'
      and jsonb_array_length(candidate_mail.attachments)>0
      and candidate_mail.attachments->0->>'candidate_workflow_id'=v_workflow.id::text
      and candidate_mail.attachments->0->>'candidate_workflow_generation'=v_workflow.generation::text
      and lower(coalesce(candidate_mail.attachments->0->>'paper_return_manifest_sha256',''))
            =v_paper_manifest_sha256
    for update;
    if not found then
      raise exception 'CANDIDATE_PAPER_PROVIDER_MAIL_STALE' using errcode='40001';
    end if;
    v_provider_permit_expires_at:=greatest(
      v_paper_mail.attempt_lease_expires_at_utc,
      p_now_utc+interval '15 minutes'
    );
    update public.mail_outbox candidate_mail
    set attempt_lease_expires_at_utc=v_provider_permit_expires_at
    where candidate_mail.id=v_paper_mail.id
      and candidate_mail.status='QUEUED'
      and candidate_mail.sent_at is null
      and candidate_mail.attempt_lease_token=v_provider_lease_token
      and candidate_mail.attempt_lease_expires_at_utc>p_now_utc
      and lower(coalesce(candidate_mail.payment_scope_json->>'candidate_paper_generation_retired','false'))
            in ('false','f','0','no');
    if not found then
      raise exception 'CANDIDATE_PAPER_PROVIDER_MAIL_STALE' using errcode='40001';
    end if;
    v_response:=jsonb_build_object(
      'ok',true,'workflow_id',v_workflow.id,'state',v_workflow.state,
      'generation',v_workflow.generation,'mail_outbox_id',v_paper_mail.id,
      'provider_submit_permit',true,
      'provider_submit_permit_expires_at_utc',v_provider_permit_expires_at
    );

  elsif v_action in ('CANCEL','SUPERSEDE') then
    if v_workflow.state in ('FINALISED','CANCELLED','REJECTED','SUPERSEDED') then
      raise exception 'CANDIDATE_WORKFLOW_NOT_CANCELLABLE' using errcode='55000';
    end if;
    if v_action='CANCEL' then
      v_cancel_reason:=nullif(btrim(coalesce(v_payload->>'reason_note',v_payload->>'reason','')), '');
      v_cancel_reason_code:=nullif(upper(btrim(coalesce(v_payload->>'reason_code',''))),'');
      if v_cancel_reason is null then
        raise exception 'CANDIDATE_CANCELLATION_REASON_REQUIRED' using errcode='22023';
      end if;
      if length(v_cancel_reason)>1000 then
        raise exception 'CANDIDATE_CANCELLATION_REASON_INVALID' using errcode='22023';
      end if;
      v_audit_reason:=v_cancel_reason;
    end if;
    if v_workflow.route='PAPER'
       and v_workflow.state in ('AWAITING_PAPER_RETURN','RECEIVED') then
      v_paper_retirement_result:=private._candidate_paper_delivery_retire_set_v1(
        array[v_workflow.id],array[v_workflow.generation],
        case when v_action='CANCEL' then 'WORKFLOW_CANCELLED' else 'WORKFLOW_SUPERSEDED' end,
        p_now_utc
      );
      if not coalesce((v_paper_retirement_result->>'retired')::boolean,false)
         or not coalesce(
           (v_paper_retirement_result->>'qr_invalidation_proven')::boolean,false
         ) then
        raise exception 'CANDIDATE_PAPER_QR_INVALIDATION_NOT_PROVEN'
          using errcode='40001',detail=v_paper_retirement_result::text;
      end if;
    end if;
    select coalesce(array_agg(locked_request.id order by locked_request.id),array[]::uuid[])
    into v_manager_request_ids
    from (
      select request_row.id
      from public.candidate_approval_requests request_row
      where request_row.workflow_id=v_workflow.id
        and request_row.workflow_generation=v_workflow.generation
        and request_row.method='EMAIL'
        and request_row.state in ('PENDING','APPROVED')
      order by request_row.id
      for update
    ) locked_request;
    if cardinality(v_manager_request_ids)>0 then
      v_manager_retirement_result:=private._candidate_manager_mail_retire_v1(
        v_workflow.id,v_workflow.generation,v_manager_request_ids,
        case when v_action='CANCEL' then 'WORKFLOW_CANCELLED' else 'WORKFLOW_SUPERSEDED' end,
        p_now_utc
      );
    end if;
    update public.candidate_approval_requests set
      state=case when v_action='CANCEL' then 'CANCELLED' else 'SUPERSEDED' end,
      cancelled_at_utc=case when v_action='CANCEL' then p_now_utc else cancelled_at_utc end,
      superseded_at_utc=case when v_action='SUPERSEDE' then p_now_utc else superseded_at_utc end,
      updated_at_utc=p_now_utc where workflow_id=v_workflow.id and state in ('PENDING','APPROVED');
    if v_action='CANCEL' and coalesce((v_manager_retirement_result->>'withdrawal_required')::boolean,false) then
      for v_manager_withdrawal_request_id in
        select value::uuid
        from jsonb_array_elements_text(coalesce(
          v_manager_retirement_result->'withdrawal_request_ids','[]'::jsonb
        )) value
      loop
        select request_row.* into v_approval
        from public.candidate_approval_requests request_row
        where request_row.id=v_manager_withdrawal_request_id
          and request_row.workflow_id=v_workflow.id
          and request_row.workflow_generation=v_workflow.generation
          and request_row.method='EMAIL'
          and request_row.state='CANCELLED';
        if found then
          perform private._candidate_queue_mail_v1(
            jsonb_build_object(
              'subject','Timesheet approval request withdrawn',
              'body_text','The approval request for this timesheet has been withdrawn by CloudTMS. No further action is required.',
              'body_html','<p>The approval request for this timesheet has been withdrawn by CloudTMS. No further action is required.</p>',
              'payment_scope_json',jsonb_build_object(
                'candidate_mail_authority','MANAGER_APPROVAL_V1',
                'candidate_manager_mail_kind','WITHDRAWAL',
                'candidate_manager_workflow_id',v_workflow.id,
                'candidate_manager_workflow_generation',v_workflow.generation,
                'candidate_approval_request_id',v_approval.id,
                'candidate_approval_request_generation',v_approval.request_generation,
                'candidate_manager_mail_retired',false
              )
            ),v_approval.manager_email_normalized,
            'CANDIDATE_MANAGER_WITHDRAWAL_V1:'||v_approval.id::text||':'||v_workflow.generation::text,
            'candidate-manager-withdrawal:'||v_approval.id::text,v_workflow.id,p_now_utc
          );
          v_manager_withdrawal_count:=v_manager_withdrawal_count+1;
        end if;
      end loop;
    end if;
    update public.candidate_submission_components set
      state='SUPERSEDED',superseded_at_utc=p_now_utc,
      review_render_state=case when review_render_state='NOT_REQUIRED' then review_render_state else 'SUPERSEDED' end,
      final_signed_render_state=case when final_signed_render_state='NOT_REQUIRED' then final_signed_render_state else 'SUPERSEDED' end
    where workflow_id=v_workflow.id and state not in ('SUPERSEDED','REJECTED');
    v_response:=jsonb_build_object('ok',true,'workflow_id',v_workflow.id,
      'state',v_action||case when v_action='CANCEL' then 'LED' else 'D' end,
      'generation',v_next_generation,
      'cancellation_reason',case when v_action='CANCEL' then v_cancel_reason else null end,
      'cancellation_reason_code',case when v_action='CANCEL' then v_cancel_reason_code else null end,
      'manager_withdrawal_count',v_manager_withdrawal_count,
      'manager_mail_retirement',v_manager_retirement_result);
    update public.candidate_submission_workflows set
      state=case when v_action='CANCEL' then 'CANCELLED' else 'SUPERSEDED' end,
      generation=v_next_generation,cancelled_at_utc=case when v_action='CANCEL' then p_now_utc else cancelled_at_utc end,
      last_mutation_idempotency_key=p_idempotency_key,last_mutation_response_json=v_response,
      updated_at_utc=p_now_utc where id=v_workflow.id;

  elsif v_action='PAPER_PREPARE' then
    if nullif(btrim(coalesce(p_idempotency_key,'')),'') is null then
      raise exception 'CANDIDATE_IDEMPOTENCY_KEY_REQUIRED' using errcode='22023';
    end if;
    if v_workflow.state not in ('WORKER_SUBMITTED','AWAITING_PAPER_RETURN') then
      raise exception 'CANDIDATE_WORKFLOW_TRANSITION_INVALID' using errcode='55000';
    end if;
    if v_workflow.scope='DAILY' then
      raise exception 'CANDIDATE_PAPER_ROUTE_NOT_ALLOWED' using errcode='55000';
    end if;
    if v_workflow.workflow_kind='CONTRACT_EXPENSE' then
      select week_row.* into v_anchor_week
      from public.contract_weeks week_row
      where week_row.timesheet_id=v_workflow.anchor_timesheet_id
        and week_row.contract_id=v_workflow.contract_id
        and week_row.week_ending_date=v_workflow.week_ending_date;
      if not found then raise exception 'CANDIDATE_WORKFLOW_ANCHOR_MISMATCH' using errcode='40001'; end if;
      v_route_authority:=private._candidate_route_family_v1(v_workflow.anchor_timesheet_id,v_anchor_week.id);
    else
      v_route_authority:=private._candidate_route_family_v1(v_workflow.target_timesheet_id,v_workflow.contract_week_id);
    end if;
    if not coalesce((v_route_authority->>'candidate_paper_submission_allowed')::boolean,false) then
      raise exception 'CANDIDATE_PAPER_ROUTE_NOT_ALLOWED' using errcode='55000',detail=v_route_authority::text;
    end if;
    update public.candidate_approval_requests set
      state='SUPERSEDED',superseded_at_utc=p_now_utc,updated_at_utc=p_now_utc
    where workflow_id=v_workflow.id and state='PENDING';

    select coalesce(jsonb_agg(jsonb_build_object(
      'page_key',case source_component.component_kind
        when 'MILEAGE_FORM' then 'MILEAGE_FORM:' else 'EXPENSE_EVIDENCE:' end
        ||coalesce(source_component.source_component_id,source_component.id)::text,
      'component_kind',source_component.component_kind,
      'expense_category',source_component.expense_category,
      'source_component_id',coalesce(source_component.source_component_id,source_component.id),
      'source_content_sha256',encode(source_component.source_content_sha256,'hex')
    ) order by source_component.component_no,source_component.id),'[]'::jsonb)
    into v_paper_source_pages
    from public.candidate_submission_components source_component
    where source_component.workflow_id=v_workflow.id
      and source_component.workflow_generation=v_workflow.generation
      and source_component.component_kind in ('MILEAGE_FORM','EXPENSE_EVIDENCE')
      and source_component.state='IMMUTABLE'
      and source_component.source_content_sha256 is not null;

    v_paper_manifest:=jsonb_build_object(
      'workflow_id',v_workflow.id,
      'workflow_generation',v_workflow.generation,
      'immutable_submission_sha256',encode(v_workflow.immutable_submission_sha256,'hex'),
      'pages',
        case when v_workflow.workflow_kind<>'CONTRACT_EXPENSE'
          then jsonb_build_array(jsonb_build_object(
            'page_key','HOURS_TIMESHEET','component_kind','HOURS_TIMESHEET'))
          else '[]'::jsonb end
        || case when v_workflow.workflow_kind in ('CONTRACT_COMBINED','CONTRACT_EXPENSE')
          then jsonb_build_array(jsonb_build_object(
            'page_key','EXPENSE_SUMMARY','component_kind','EXPENSE_SUMMARY'))
          else '[]'::jsonb end
        || v_paper_source_pages
    );
    update public.candidate_submission_workflows set
      state='AWAITING_PAPER_RETURN',route='PAPER',policy_snapshot_json=v_policy,
      paper_return_manifest_json=v_paper_manifest,
      paper_return_manifest_sha256=private._candidate_sha256_jsonb_v1(v_paper_manifest),
      updated_at_utc=p_now_utc where id=v_workflow.id returning * into v_workflow;

    -- The existing QR/document/email authority is composed inside this
    -- transaction. A PAPER workflow is not accepted unless its exact held
    -- email operation exists and is bound to this frozen manifest.
    execute
      'select public.timesheet_qr_send_enqueue_v1($1,$2,$3,$4,$5)'
      into v_paper_pack_result
      using v_paper_timesheet_id,v_paper_timesheet_id,null::uuid,
        p_idempotency_key||':paper-pack',p_now_utc;

    if not coalesce((v_paper_pack_result->>'ok')::boolean,false)
       or not coalesce((v_paper_pack_result->>'queued')::boolean,false)
       or not coalesce((v_paper_pack_result->>'recipient_available')::boolean,false) then
      if coalesce(v_paper_pack_result->>'error_code','') in (
        'CANDIDATE_EMAIL_MISSING','CANDIDATE_EMAIL_OPTED_OUT','CANDIDATE_NOT_FOUND'
      ) then
        raise exception 'CANDIDATE_PAPER_EMAIL_NOT_AVAILABLE'
          using errcode='55000',detail=jsonb_build_object(
            'code','CANDIDATE_PAPER_EMAIL_NOT_AVAILABLE',
            'cause',v_paper_pack_result->>'error_code'
          )::text;
      end if;
      raise exception 'CANDIDATE_PAPER_PACK_QUEUE_FAILED'
        using errcode='55000',detail=jsonb_build_object(
          'code','CANDIDATE_PAPER_PACK_QUEUE_FAILED',
          'cause',coalesce(v_paper_pack_result->>'error_code','UNKNOWN')
        )::text;
    end if;

    v_mail_id:=nullif(v_paper_pack_result->>'mail_outbox_id','')::uuid;
    if v_mail_id is null then
      raise exception 'CANDIDATE_PAPER_OUTBOX_NOT_READY' using errcode='55000';
    end if;
    perform 1
    from public.mail_outbox candidate_paper_mail
    where candidate_paper_mail.id=v_mail_id
      and candidate_paper_mail.type='TIMESHEET_QR'
      and candidate_paper_mail.context_kind='timesheets'
      and candidate_paper_mail.context_id=v_paper_timesheet_id
      and candidate_paper_mail.status='QUEUED'
      and candidate_paper_mail.attempt_lease_token is null
      and candidate_paper_mail.payment_scope_json->>'candidate_workflow_id'=v_workflow.id::text
      and candidate_paper_mail.payment_scope_json->>'candidate_workflow_generation'=v_workflow.generation::text
      and lower(coalesce(candidate_paper_mail.payment_scope_json->>'paper_return_manifest_sha256',''))
            =encode(v_workflow.paper_return_manifest_sha256,'hex')
      and lower(coalesce(candidate_paper_mail.payment_scope_json->>'candidate_paper_pack_ready','false'))
            in ('false','f','0','no')
      and lower(coalesce(candidate_paper_mail.payment_scope_json->>'mail_held_until_pdf_rendered','false'))
            in ('true','t','1','yes')
      and candidate_paper_mail.payment_scope_json->>'mail_hold_reason'='CANDIDATE_PAPER_PACK_PENDING'
      and jsonb_typeof(candidate_paper_mail.attachments)='array'
      and jsonb_array_length(candidate_paper_mail.attachments)=0
    for update;
    if not found then
      raise exception 'CANDIDATE_PAPER_OUTBOX_NOT_READY' using errcode='55000';
    end if;

    v_response:=jsonb_build_object('ok',true,'workflow_id',v_workflow.id,
      'state','AWAITING_PAPER_RETURN','generation',v_workflow.generation,
      'paper_return_manifest_sha256',encode(v_workflow.paper_return_manifest_sha256,'hex'),
      'paper_return_page_count',jsonb_array_length(v_paper_manifest->'pages'),
      'paper_pack',jsonb_build_object(
        'queued',true,
        'recipient_available',true,
        'mail_outbox_id',v_mail_id,
        'send_state',v_paper_pack_result->>'send_state',
        'document_operation_id',v_paper_pack_result->>'document_operation_id',
        'document_version_id',v_paper_pack_result->>'document_version_id',
        'document_version_status',v_paper_pack_result->>'document_version_status',
        'current_timesheet_id',v_paper_pack_result->>'current_timesheet_id',
        'current_version',v_paper_pack_result->'current_version'
      ));
    update public.candidate_submission_workflows set
      last_mutation_idempotency_key=p_idempotency_key,
      last_mutation_response_json=v_response,
      updated_at_utc=p_now_utc
    where id=v_workflow.id returning * into v_workflow;

  elsif v_action='PAPER_PACK_ATTEMPT_CLAIM' then
    if not v_is_service_action or p_session_id is not null
       or not coalesce((v_payload->>'service_paper_pack_attempt')::boolean,false) then
      raise exception 'CANDIDATE_PAPER_PACK_ATTEMPT_SERVICE_REQUIRED' using errcode='28000';
    end if;
    if v_workflow.state<>'AWAITING_PAPER_RETURN' or v_workflow.route<>'PAPER'
       or v_workflow.paper_return_manifest_sha256 is null then
      raise exception 'CANDIDATE_PAPER_WORKFLOW_STALE' using errcode='40001';
    end if;
    v_paper_mail_id:=nullif(btrim(coalesce(v_payload->>'mail_outbox_id','')),'')::uuid;
    v_paper_manifest_sha256:=lower(btrim(coalesce(v_payload->>'paper_return_manifest_sha256','')));
    v_paper_pack_attempt_token:=lower(btrim(coalesce(v_payload->>'paper_pack_attempt_token','')));
    v_paper_pack_operation_id:=nullif(btrim(coalesce(
      v_payload->>'paper_pack_operation_id',p_idempotency_key,''
    )), '');
    if v_paper_mail_id is null
       or v_paper_manifest_sha256 !~ '^[0-9a-f]{64}$'
       or v_paper_manifest_sha256<>encode(v_workflow.paper_return_manifest_sha256,'hex')
       or v_paper_pack_attempt_token !~ '^[0-9a-f]{64}$'
       or v_paper_pack_operation_id is null
       or length(v_paper_pack_operation_id)>200 then
      raise exception 'CANDIDATE_PAPER_PACK_ATTEMPT_RECEIPT_INVALID' using errcode='22023';
    end if;
    select * into v_paper_mail
    from public.mail_outbox candidate_paper_mail
    where candidate_paper_mail.id=v_paper_mail_id
      and candidate_paper_mail.type='TIMESHEET_QR'
      and candidate_paper_mail.context_kind='timesheets'
      and candidate_paper_mail.payment_scope_json->>'candidate_mail_authority'='CANDIDATE_PAPER_V1'
      and candidate_paper_mail.payment_scope_json->>'candidate_workflow_id'=v_workflow.id::text
      and candidate_paper_mail.payment_scope_json->>'candidate_workflow_generation'=v_workflow.generation::text
      and lower(coalesce(candidate_paper_mail.payment_scope_json->>'paper_return_manifest_sha256',''))
            =v_paper_manifest_sha256
    for update;
    if not found then
      raise exception 'CANDIDATE_PAPER_OUTBOX_NOT_READY' using errcode='40001';
    end if;
    if lower(coalesce(v_paper_mail.payment_scope_json->>'candidate_paper_generation_retired','false'))
         in ('true','t','1','yes') then
      raise exception 'CANDIDATE_PAPER_WORKFLOW_STALE' using errcode='40001';
    end if;
    if lower(coalesce(v_paper_mail.payment_scope_json->>'candidate_paper_pack_ready','false'))
         in ('true','t','1','yes') then
      v_response:=jsonb_build_object(
        'ok',true,'workflow_id',v_workflow.id,'generation',v_workflow.generation,
        'mail_outbox_id',v_paper_mail.id,'paper_pack_attempt_state','READY',
        'paper_pack_operation_id',v_paper_mail.payment_scope_json->>'candidate_paper_pack_operation_id',
        'claim_acquired_new',false,
        'paper_pack_attempt_count',coalesce(
          nullif(v_paper_mail.payment_scope_json->>'candidate_paper_pack_attempt_count','')::integer,0
        )
      );
    else
      v_paper_failure_class:=upper(coalesce(
        v_paper_mail.payment_scope_json->>'candidate_paper_pack_failure_class',''
      ));
      if v_paper_failure_class='TERMINAL' then
        raise exception 'CANDIDATE_PAPER_PACK_FAILED_TERMINAL' using errcode='55000';
      end if;
      v_paper_pack_next_retry_at:=nullif(
        v_paper_mail.payment_scope_json->>'candidate_paper_pack_next_retry_at_utc',''
      )::timestamptz;
      if v_paper_failure_class='RETRYABLE'
         and v_paper_pack_next_retry_at is not null and v_paper_pack_next_retry_at>p_now_utc then
        raise exception 'CANDIDATE_PAPER_PACK_RETRY_BACKOFF_ACTIVE'
          using errcode='55000',detail=jsonb_build_object(
            'code','CANDIDATE_PAPER_PACK_RETRY_BACKOFF_ACTIVE',
            'next_retry_at_utc',v_paper_pack_next_retry_at
          )::text;
      end if;
      if nullif(v_paper_mail.payment_scope_json->>'candidate_paper_pack_attempt_token','') is not null
         and nullif(v_paper_mail.payment_scope_json->>'candidate_paper_pack_attempt_expires_at_utc','')::timestamptz
               >p_now_utc then
        raise exception 'CANDIDATE_PAPER_PACK_ATTEMPT_IN_PROGRESS' using errcode='40001';
      end if;
      v_paper_pack_attempt_count:=coalesce(
        nullif(v_paper_mail.payment_scope_json->>'candidate_paper_pack_attempt_count','')::integer,0
      )+1;
      v_paper_pack_attempt_expires_at:=p_now_utc+interval '10 minutes';
      update public.mail_outbox candidate_paper_mail
      set payment_scope_json=candidate_paper_mail.payment_scope_json||jsonb_build_object(
        'candidate_paper_pack_attempt_token',v_paper_pack_attempt_token,
        'candidate_paper_pack_attempt_expires_at_utc',v_paper_pack_attempt_expires_at,
        'candidate_paper_pack_attempt_count',v_paper_pack_attempt_count,
        'candidate_paper_pack_last_attempted_at_utc',p_now_utc,
        'candidate_paper_pack_operation_id',v_paper_pack_operation_id,
        'candidate_paper_pack_operation_state','CLAIMED'
      )
      where candidate_paper_mail.id=v_paper_mail.id;
      v_response:=jsonb_build_object(
        'ok',true,'workflow_id',v_workflow.id,'generation',v_workflow.generation,
        'mail_outbox_id',v_paper_mail.id,'paper_pack_attempt_state','CLAIMED',
        'paper_pack_operation_id',v_paper_pack_operation_id,
        'claim_acquired_new',true,
        'paper_pack_attempt_token',v_paper_pack_attempt_token,
        'paper_pack_attempt_count',v_paper_pack_attempt_count,
        'paper_pack_attempt_expires_at_utc',v_paper_pack_attempt_expires_at
      );
    end if;

  elsif v_action='PAPER_PACK_MARK_FAILURE' then
    if not v_is_service_action or p_session_id is not null
       or not coalesce((v_payload->>'service_paper_pack_failure')::boolean,false) then
      raise exception 'CANDIDATE_PAPER_PACK_FAILURE_SERVICE_REQUIRED' using errcode='28000';
    end if;
    if v_workflow.state<>'AWAITING_PAPER_RETURN' or v_workflow.route<>'PAPER'
       or v_workflow.paper_return_manifest_sha256 is null then
      raise exception 'CANDIDATE_PAPER_WORKFLOW_STALE' using errcode='40001';
    end if;
    v_paper_mail_id:=nullif(btrim(coalesce(v_payload->>'mail_outbox_id','')),'')::uuid;
    v_paper_manifest_sha256:=lower(btrim(coalesce(v_payload->>'paper_return_manifest_sha256','')));
    v_paper_failure_code:=upper(btrim(coalesce(v_payload->>'error_code','')));
    v_paper_pack_operation_id:=nullif(btrim(coalesce(
      v_payload->>'paper_pack_operation_id',''
    )), '');
    if v_paper_manifest_sha256 !~ '^[0-9a-f]{64}$'
       or v_paper_manifest_sha256<>encode(v_workflow.paper_return_manifest_sha256,'hex')
       or v_paper_failure_code='' then
      raise exception 'CANDIDATE_PAPER_PACK_FAILURE_RECEIPT_INVALID' using errcode='22023';
    end if;
    if v_paper_failure_code not in (
      'CANDIDATE_PAPER_PACK_ASSEMBLY_TRANSIENT',
      'CANDIDATE_PAPER_SOURCE_READ_TRANSIENT',
      'CANDIDATE_PAPER_R2_WRITE_TRANSIENT',
      'CANDIDATE_PAPER_DOCUMENT_FAILED',
      'CANDIDATE_PAPER_OUTBOX_NOT_READY',
      'CANDIDATE_PAPER_RETURN_MANIFEST_STALE',
      'CANDIDATE_PAPER_PACK_MEDIA_TYPE_INVALID',
      'CANDIDATE_PAPER_PACK_COMPONENT_MISSING',
      'CANDIDATE_PAPER_PACK_INCOMPLETE',
      'CANDIDATE_PAPER_PACK_IDENTITY_INVALID',
      'CANDIDATE_PAPER_PACK_IDENTITY_CONFLICT',
      'CANDIDATE_PAPER_OUTBOX_CONFLICT',
      'CANDIDATE_PAPER_PACK_OPERATIONAL_REVIEW_REQUIRED'
    ) then
      v_paper_failure_code:='CANDIDATE_PAPER_PACK_OPERATIONAL_REVIEW_REQUIRED';
    end if;
    v_paper_failure_class:=case
      when v_paper_failure_code in (
        'CANDIDATE_PAPER_PACK_ASSEMBLY_TRANSIENT',
        'CANDIDATE_PAPER_SOURCE_READ_TRANSIENT',
        'CANDIDATE_PAPER_R2_WRITE_TRANSIENT'
      ) then 'RETRYABLE'
      when v_paper_failure_code in (
        'CANDIDATE_PAPER_RETURN_MANIFEST_STALE',
        'CANDIDATE_PAPER_DOCUMENT_FAILED',
        'CANDIDATE_PAPER_OUTBOX_NOT_READY',
        'CANDIDATE_PAPER_PACK_MEDIA_TYPE_INVALID',
        'CANDIDATE_PAPER_PACK_COMPONENT_MISSING',
        'CANDIDATE_PAPER_PACK_INCOMPLETE',
        'CANDIDATE_PAPER_PACK_IDENTITY_INVALID',
        'CANDIDATE_PAPER_PACK_IDENTITY_CONFLICT',
        'CANDIDATE_PAPER_OUTBOX_CONFLICT',
        'CANDIDATE_PAPER_PACK_OPERATIONAL_REVIEW_REQUIRED'
      ) then 'TERMINAL'
      else 'TERMINAL' end;
    v_paper_failure_retryable:=v_paper_failure_class='RETRYABLE';
    v_paper_pack_attempt_token:=lower(btrim(coalesce(v_payload->>'paper_pack_attempt_token','')));
    if v_paper_mail_id is null then
      v_response:=jsonb_build_object(
        'ok',true,'workflow_id',v_workflow.id,'generation',v_workflow.generation,
        'mail_outbox_id',null,'paper_pack_state','FAILED_TERMINAL',
        'failure_scope','WORKFLOW','failure_class','TERMINAL',
        'failure_code',v_paper_failure_code,'retryable',false,
        'paper_pack_operation_id',v_paper_pack_operation_id,
        'failure_contract_version','CANDIDATE_PAPER_PACK_FAILURE_V2'
      );
    else
    select * into v_paper_mail
    from public.mail_outbox candidate_paper_mail
    where candidate_paper_mail.id=v_paper_mail_id
      and candidate_paper_mail.type='TIMESHEET_QR'
      and candidate_paper_mail.context_kind='timesheets'
      and candidate_paper_mail.payment_scope_json->>'candidate_mail_authority'='CANDIDATE_PAPER_V1'
      and candidate_paper_mail.payment_scope_json->>'candidate_workflow_id'=v_workflow.id::text
      and candidate_paper_mail.payment_scope_json->>'candidate_workflow_generation'=v_workflow.generation::text
      and lower(coalesce(candidate_paper_mail.payment_scope_json->>'paper_return_manifest_sha256',''))
            =v_paper_manifest_sha256
    for update;
    if not found then
      raise exception 'CANDIDATE_PAPER_OUTBOX_NOT_READY' using errcode='40001';
    end if;
    if nullif(btrim(coalesce(v_paper_mail.attempt_lease_token,'')),'') is not null
       and v_paper_mail.attempt_lease_expires_at_utc>p_now_utc then
      raise exception 'CANDIDATE_PAPER_MAIL_DELIVERY_IN_PROGRESS' using errcode='40001';
    end if;
    if lower(coalesce(v_paper_mail.payment_scope_json->>'candidate_paper_generation_retired','false'))
         in ('true','t','1','yes') then
      raise exception 'CANDIDATE_PAPER_WORKFLOW_STALE' using errcode='40001';
    end if;
    if nullif(v_paper_mail.payment_scope_json->>'candidate_paper_pack_attempt_token','') is not null
       and lower(v_paper_mail.payment_scope_json->>'candidate_paper_pack_attempt_token')
             is distinct from nullif(v_paper_pack_attempt_token,'') then
      raise exception 'CANDIDATE_PAPER_PACK_ATTEMPT_STALE' using errcode='40001';
    end if;
    if v_paper_pack_operation_id is not null
       and nullif(v_paper_mail.payment_scope_json->>'candidate_paper_pack_operation_id','')
             is distinct from v_paper_pack_operation_id then
      raise exception 'CANDIDATE_PAPER_PACK_ATTEMPT_STALE' using errcode='40001';
    end if;
    v_paper_pack_attempt_count:=coalesce(
      nullif(v_paper_mail.payment_scope_json->>'candidate_paper_pack_attempt_count','')::integer,0
    );
    v_paper_pack_next_retry_at:=case when v_paper_failure_retryable then p_now_utc+case
      when v_paper_pack_attempt_count<=1 then interval '1 minute'
      when v_paper_pack_attempt_count=2 then interval '5 minutes'
      when v_paper_pack_attempt_count=3 then interval '15 minutes'
      else interval '30 minutes' end else null end;
    update public.mail_outbox candidate_paper_mail
    set payment_scope_json=candidate_paper_mail.payment_scope_json||jsonb_build_object(
      'candidate_paper_pack_ready',false,
      'candidate_paper_pack_retryable',v_paper_failure_retryable,
      'candidate_paper_pack_failure_class',v_paper_failure_class,
      'candidate_paper_pack_failure_code',v_paper_failure_code,
      'candidate_paper_pack_failure_contract_version','CANDIDATE_PAPER_PACK_FAILURE_V2',
      'candidate_paper_pack_failed_at_utc',p_now_utc,
      'candidate_paper_pack_next_retry_at_utc',v_paper_pack_next_retry_at,
      'candidate_paper_pack_attempt_token',null,
      'candidate_paper_pack_attempt_expires_at_utc',null,
      'candidate_paper_pack_operation_id',coalesce(
        v_paper_pack_operation_id,
        candidate_paper_mail.payment_scope_json->>'candidate_paper_pack_operation_id'
      ),
      'candidate_paper_pack_operation_state',case when v_paper_failure_retryable
        then 'FAILED_RETRYABLE' else 'FAILED_TERMINAL' end
    )
    where candidate_paper_mail.id=v_paper_mail.id;
    v_response:=jsonb_build_object(
      'ok',true,'workflow_id',v_workflow.id,'generation',v_workflow.generation,
      'mail_outbox_id',v_paper_mail.id,'paper_pack_state',
        case when v_paper_failure_retryable then 'FAILED_RETRYABLE' else 'FAILED_TERMINAL' end,
      'failure_class',v_paper_failure_class,'failure_code',v_paper_failure_code,
      'paper_pack_operation_id',coalesce(
        v_paper_pack_operation_id,
        v_paper_mail.payment_scope_json->>'candidate_paper_pack_operation_id'
      ),
      'retryable',v_paper_failure_retryable,
      'failure_contract_version','CANDIDATE_PAPER_PACK_FAILURE_V2',
      'paper_pack_attempt_count',v_paper_pack_attempt_count,
      'next_retry_at_utc',v_paper_pack_next_retry_at
    );
    end if;
    update public.candidate_submission_workflows
    set last_mutation_idempotency_key=p_idempotency_key,
        last_mutation_response_json=v_response,updated_at_utc=p_now_utc
    where id=v_workflow.id and generation=v_workflow.generation;

  elsif v_action='PAPER_PACK_RELEASE' then
    if not v_is_service_action or p_session_id is not null then
      raise exception 'CANDIDATE_PAPER_PACK_RELEASE_SERVICE_REQUIRED' using errcode='28000';
    end if;
    if v_workflow.state<>'AWAITING_PAPER_RETURN' or v_workflow.route<>'PAPER' then
      raise exception 'CANDIDATE_PAPER_WORKFLOW_STALE' using errcode='40001';
    end if;
    if v_workflow.paper_return_manifest_sha256 is null
       or private._candidate_sha256_jsonb_v1(v_workflow.paper_return_manifest_json)
          is distinct from v_workflow.paper_return_manifest_sha256 then
      raise exception 'CANDIDATE_PAPER_RETURN_MANIFEST_STALE' using errcode='55000';
    end if;

    v_paper_timesheet_id:=coalesce(v_workflow.target_timesheet_id,v_workflow.anchor_timesheet_id);
    v_paper_mail_id:=nullif(btrim(coalesce(v_payload->>'mail_outbox_id','')),'')::uuid;
    v_paper_manifest_sha256:=lower(btrim(coalesce(v_payload->>'paper_return_manifest_sha256','')));
    v_paper_pack_storage_key:=nullif(btrim(coalesce(v_payload->>'complete_pack_storage_key','')),'');
    v_paper_pack_sha256:=lower(btrim(coalesce(v_payload->>'complete_pack_sha256','')));
    v_paper_pack_media_type:=lower(btrim(coalesce(v_payload->>'complete_pack_media_type','')));
    v_paper_base_document_sha256:=lower(btrim(coalesce(v_payload->>'base_document_sha256','')));
    v_paper_branding_contract_sha256:=lower(btrim(coalesce(v_payload->>'branding_contract_sha256','')));
    v_paper_renderer_contract_version:=btrim(coalesce(v_payload->>'renderer_contract_version',''));
    v_paper_pack_attempt_token:=lower(btrim(coalesce(v_payload->>'paper_pack_attempt_token','')));
    v_paper_pack_operation_id:=nullif(btrim(coalesce(
      v_payload->>'paper_pack_operation_id',''
    )), '');
    begin
      v_paper_pack_byte_size:=(v_payload->>'complete_pack_byte_size')::bigint;
      v_paper_pack_page_count:=(v_payload->>'complete_pack_page_count')::integer;
    exception when others then
      raise exception 'CANDIDATE_PAPER_PACK_RECEIPT_INVALID' using errcode='22023';
    end;
    if v_paper_mail_id is null
       or v_paper_manifest_sha256 !~ '^[0-9a-f]{64}$'
       or v_paper_pack_sha256 !~ '^[0-9a-f]{64}$'
       or v_paper_base_document_sha256 !~ '^[0-9a-f]{64}$'
       or v_paper_branding_contract_sha256 !~ '^[0-9a-f]{64}$'
       or v_paper_pack_media_type<>'application/pdf'
       or coalesce(v_paper_pack_byte_size,0)<1
       or coalesce(v_paper_pack_page_count,0)<1
       or v_paper_renderer_contract_version=''
       or (v_paper_pack_attempt_token<>'' and v_paper_pack_operation_id is null)
       or v_paper_manifest_sha256<>encode(v_workflow.paper_return_manifest_sha256,'hex')
       or v_paper_renderer_contract_version<>coalesce(
         v_workflow.renderer_contract_version,
         v_workflow.immutable_submission_json#>>'{official_presentation,renderer_contract_version}'
       )
       or v_paper_branding_contract_sha256<>lower(coalesce(
         v_workflow.immutable_submission_json#>>'{official_presentation,branding,branding_contract_sha256}',''
       )) then
      raise exception 'CANDIDATE_PAPER_PACK_RECEIPT_INVALID' using errcode='22023';
    end if;
    v_paper_expected_storage_key:='candidate-app/'||lower(v_environment)||'/'
      ||v_workflow.id::text||'/'||v_workflow.generation::text||'/paper-pack/'
      ||v_paper_manifest_sha256||'-'||v_paper_base_document_sha256||'-'
      ||v_paper_branding_contract_sha256||'-'||v_paper_renderer_contract_version||'.pdf';
    if v_paper_pack_storage_key is distinct from v_paper_expected_storage_key then
      raise exception 'CANDIDATE_PAPER_PACK_IDENTITY_CONFLICT' using errcode='40001';
    end if;
    if jsonb_array_length(coalesce(v_workflow.paper_return_manifest_json->'pages','[]'::jsonb))
         <>v_paper_pack_page_count then
      raise exception 'CANDIDATE_PAPER_PACK_PAGE_COUNT_MISMATCH' using errcode='22023';
    end if;

    select count(*)::integer into v_paper_outbox_count
    from public.mail_outbox candidate_paper_mail
    where candidate_paper_mail.type='TIMESHEET_QR'
      and candidate_paper_mail.context_kind='timesheets'
      and candidate_paper_mail.context_id=v_paper_timesheet_id
      and candidate_paper_mail.payment_scope_json->>'candidate_mail_authority'='CANDIDATE_PAPER_V1'
      and candidate_paper_mail.payment_scope_json->>'candidate_workflow_id'=v_workflow.id::text
      and candidate_paper_mail.payment_scope_json->>'candidate_workflow_generation'=v_workflow.generation::text
      and lower(coalesce(candidate_paper_mail.payment_scope_json->>'paper_return_manifest_sha256',''))
            =v_paper_manifest_sha256;
    if v_paper_outbox_count<>1 then
      raise exception 'CANDIDATE_PAPER_OUTBOX_CONFLICT' using errcode='40001';
    end if;

    select * into v_paper_mail
    from public.mail_outbox candidate_paper_mail
    where candidate_paper_mail.id=v_paper_mail_id
      and candidate_paper_mail.type='TIMESHEET_QR'
      and candidate_paper_mail.context_kind='timesheets'
      and candidate_paper_mail.context_id=v_paper_timesheet_id
      and candidate_paper_mail.payment_scope_json->>'candidate_mail_authority'='CANDIDATE_PAPER_V1'
      and candidate_paper_mail.payment_scope_json->>'candidate_workflow_id'=v_workflow.id::text
      and candidate_paper_mail.payment_scope_json->>'candidate_workflow_generation'=v_workflow.generation::text
      and lower(coalesce(candidate_paper_mail.payment_scope_json->>'paper_return_manifest_sha256',''))
            =v_paper_manifest_sha256
    for update;
    if not found then
      raise exception 'CANDIDATE_PAPER_OUTBOX_NOT_READY' using errcode='40001';
    end if;
    if v_paper_mail.status='FAILED' then
      raise exception 'CANDIDATE_PAPER_OUTBOX_FAILED' using errcode='55000';
    end if;
    if nullif(btrim(coalesce(v_paper_mail.attempt_lease_token,'')),'') is not null then
      raise exception 'CANDIDATE_PAPER_MAIL_DELIVERY_IN_PROGRESS' using errcode='40001';
    end if;
    if nullif(v_paper_mail.payment_scope_json->>'candidate_paper_pack_attempt_token','') is not null
       and lower(v_paper_mail.payment_scope_json->>'candidate_paper_pack_attempt_token')
             is distinct from nullif(v_paper_pack_attempt_token,'') then
      raise exception 'CANDIDATE_PAPER_PACK_ATTEMPT_STALE' using errcode='40001';
    end if;
    if v_paper_pack_operation_id is not null
       and nullif(v_paper_mail.payment_scope_json->>'candidate_paper_pack_operation_id','')
             is distinct from v_paper_pack_operation_id then
      raise exception 'CANDIDATE_PAPER_PACK_ATTEMPT_STALE' using errcode='40001';
    end if;
    if lower(coalesce(v_paper_mail.payment_scope_json->>'candidate_paper_generation_retired','false'))
         in ('true','t','1','yes') then
      raise exception 'CANDIDATE_PAPER_WORKFLOW_STALE' using errcode='40001';
    end if;

    v_paper_pack_attachment:=jsonb_build_array(jsonb_build_object(
      'r2_key',v_paper_pack_storage_key,
      'filename','Timesheet_'||coalesce(v_workflow.week_ending_date::text,v_paper_timesheet_id::text)||'.pdf',
      'content_type','application/pdf','sha256',v_paper_pack_sha256,
      'size_bytes',v_paper_pack_byte_size,'page_count',v_paper_pack_page_count,
      'candidate_workflow_id',v_workflow.id,
      'candidate_workflow_generation',v_workflow.generation,
      'paper_return_manifest_sha256',v_paper_manifest_sha256
    ));

    if v_paper_mail.status in ('QUEUED','SENT')
       and lower(coalesce(v_paper_mail.payment_scope_json->>'candidate_paper_pack_ready','false'))
            in ('true','t','1','yes')
       and v_paper_mail.attachments=v_paper_pack_attachment
       and v_paper_mail.payment_scope_json->>'candidate_complete_pack_storage_key'=v_paper_pack_storage_key
       and lower(coalesce(v_paper_mail.payment_scope_json->>'candidate_complete_pack_sha256',''))=v_paper_pack_sha256
       and v_paper_mail.payment_scope_json->>'candidate_complete_pack_size_bytes'=v_paper_pack_byte_size::text
       and v_paper_mail.payment_scope_json->>'candidate_complete_pack_page_count'=v_paper_pack_page_count::text then
      v_paper_release_idempotent:=true;
    elsif v_paper_mail.status='SENT' then
      raise exception 'CANDIDATE_PAPER_OUTBOX_ALREADY_SENT' using errcode='55000';
    elsif v_paper_mail.status<>'QUEUED'
       or lower(coalesce(v_paper_mail.payment_scope_json->>'candidate_paper_pack_ready','false'))
            not in ('false','f','0','no')
       or lower(coalesce(v_paper_mail.payment_scope_json->>'mail_held_until_pdf_rendered','false'))
            not in ('true','t','1','yes')
       or v_paper_mail.payment_scope_json->>'mail_hold_reason'<>'CANDIDATE_PAPER_PACK_PENDING'
       or jsonb_typeof(v_paper_mail.attachments)<>'array'
       or jsonb_array_length(v_paper_mail.attachments)<>0 then
      raise exception 'CANDIDATE_PAPER_OUTBOX_NOT_READY' using errcode='40001';
    else
      update public.mail_outbox candidate_paper_mail
      set attachments=v_paper_pack_attachment,
          scheduled_for_utc=p_now_utc,
          next_attempt_at_utc=p_now_utc,
          payment_scope_json=candidate_paper_mail.payment_scope_json||jsonb_build_object(
            'candidate_paper_pack_ready',true,
            'candidate_paper_pack_retryable',false,
            'candidate_paper_pack_failure_class',null,
            'candidate_paper_pack_failure_code',null,
            'candidate_paper_pack_failure_contract_version',null,
            'candidate_paper_pack_failed_at_utc',null,
            'candidate_paper_pack_next_retry_at_utc',null,
            'candidate_paper_pack_attempt_token',null,
            'candidate_paper_pack_attempt_expires_at_utc',null,
            'candidate_paper_pack_operation_id',coalesce(
              v_paper_pack_operation_id,
              candidate_paper_mail.payment_scope_json->>'candidate_paper_pack_operation_id'
            ),
            'candidate_paper_pack_operation_state','READY',
            'mail_held_until_pdf_rendered',false,
            'mail_delayed_for_pdf_render',false,
            'mail_hold_reason',null,
            'candidate_complete_pack_storage_key',v_paper_pack_storage_key,
            'candidate_complete_pack_sha256',v_paper_pack_sha256,
            'candidate_complete_pack_size_bytes',v_paper_pack_byte_size,
            'candidate_complete_pack_page_count',v_paper_pack_page_count,
            'candidate_complete_pack_media_type','application/pdf',
            'candidate_complete_pack_ready_at_utc',p_now_utc,
            'candidate_complete_pack_base_document_sha256',v_paper_base_document_sha256,
            'candidate_complete_pack_branding_contract_sha256',v_paper_branding_contract_sha256,
            'candidate_complete_pack_renderer_contract_version',v_paper_renderer_contract_version
          )
      where candidate_paper_mail.id=v_paper_mail.id
        and candidate_paper_mail.status='QUEUED'
        and candidate_paper_mail.attempt_lease_token is null
        and lower(coalesce(candidate_paper_mail.payment_scope_json->>'candidate_paper_pack_ready','false'))
              in ('false','f','0','no')
        and lower(coalesce(candidate_paper_mail.payment_scope_json->>'candidate_paper_generation_retired','false'))
              in ('false','f','0','no');
      if not found then
        raise exception 'CANDIDATE_PAPER_OUTBOX_NOT_READY' using errcode='40001';
      end if;
    end if;

    insert into public.candidate_notifications(
      account_id,candidate_id,workflow_id,timesheet_id,event_type,preference_category,
      template_key,template_params,deep_link_json,state,push_state,dedupe_key,created_at_utc
    ) values (
      v_workflow.account_id,v_workflow.candidate_id,v_workflow.id,v_paper_timesheet_id,
      'PAPER_PACK_READY','resubmission_required','candidate-paper-pack-ready-v1',
      jsonb_build_object('page_count',v_paper_pack_page_count,'workflow_generation',v_workflow.generation),
      jsonb_build_object('type','paper_pack','timesheet_id',v_paper_timesheet_id,
        'workflow_id',v_workflow.id,'workflow_generation',v_workflow.generation),
      'UNREAD','PENDING',
      'CANDIDATE_PAPER_PACK_READY_V1:'||v_workflow.id::text||':'
        ||v_workflow.generation::text||':'||v_paper_manifest_sha256,
      p_now_utc
    ) on conflict(dedupe_key) do nothing
    returning id into v_paper_notification_id;
    if v_paper_notification_id is null then
      select notification.id into v_paper_notification_id
      from public.candidate_notifications notification
      where notification.dedupe_key='CANDIDATE_PAPER_PACK_READY_V1:'||v_workflow.id::text||':'
        ||v_workflow.generation::text||':'||v_paper_manifest_sha256;
    end if;

    update public.candidate_submission_workflows
    set updated_at_utc=p_now_utc
    where id=v_workflow.id
      and generation=v_workflow.generation
      and state='AWAITING_PAPER_RETURN'
      and route='PAPER';
    if not found then
      raise exception 'CANDIDATE_PAPER_WORKFLOW_STALE' using errcode='40001';
    end if;

    v_response:=jsonb_build_object(
      'ok',true,'workflow_id',v_workflow.id,'generation',v_workflow.generation,
      'state',v_workflow.state,'timesheet_id',v_paper_timesheet_id,
      'mail_outbox_id',v_paper_mail.id,'notification_id',v_paper_notification_id,
      'paper_return_manifest_sha256',v_paper_manifest_sha256,
      'paper_pack_operation_id',coalesce(
        v_paper_pack_operation_id,
        v_paper_mail.payment_scope_json->>'candidate_paper_pack_operation_id'
      ),
      'complete_pack_storage_key',v_paper_pack_storage_key,
      'complete_pack_sha256',v_paper_pack_sha256,
      'complete_pack_byte_size',v_paper_pack_byte_size,
      'complete_pack_page_count',v_paper_pack_page_count,
      'idempotent_replay',v_paper_release_idempotent
    );

  elsif v_action='PAPER_RETURN' then
    if v_workflow.state<>'AWAITING_PAPER_RETURN' then
      raise exception 'CANDIDATE_WORKFLOW_TRANSITION_INVALID' using errcode='55000';
    end if;
    if v_workflow.paper_return_manifest_sha256 is null
       or private._candidate_sha256_jsonb_v1(v_workflow.paper_return_manifest_json)
          is distinct from v_workflow.paper_return_manifest_sha256 then
      raise exception 'CANDIDATE_PAPER_RETURN_MANIFEST_STALE' using errcode='55000';
    end if;
    -- The claimed mail lease is the provider-submit permit. PAPER return and
    -- every authority-changing transition lock the same exact delivery row,
    -- so provider submission cannot be authorised and then invalidated before
    -- its external call. An active permit is a controlled retryable conflict.
    select count(*)::integer into v_paper_outbox_count
    from public.mail_outbox candidate_mail
    where candidate_mail.type='TIMESHEET_QR'
      and candidate_mail.context_kind='timesheets'
      and candidate_mail.payment_scope_json->>'candidate_workflow_id'=v_workflow.id::text
      and candidate_mail.payment_scope_json->>'candidate_workflow_generation'=v_workflow.generation::text
      and lower(coalesce(candidate_mail.payment_scope_json->>'paper_return_manifest_sha256',''))
            =encode(v_workflow.paper_return_manifest_sha256,'hex');
    if v_paper_outbox_count<>1 then
      raise exception 'CANDIDATE_PAPER_OUTBOX_CONFLICT' using errcode='40001';
    end if;
    select candidate_mail.* into v_paper_mail
    from public.mail_outbox candidate_mail
    where candidate_mail.type='TIMESHEET_QR'
      and candidate_mail.context_kind='timesheets'
      and candidate_mail.payment_scope_json->>'candidate_workflow_id'=v_workflow.id::text
      and candidate_mail.payment_scope_json->>'candidate_workflow_generation'=v_workflow.generation::text
      and lower(coalesce(candidate_mail.payment_scope_json->>'paper_return_manifest_sha256',''))
            =encode(v_workflow.paper_return_manifest_sha256,'hex')
    for update;
    if nullif(btrim(coalesce(v_paper_mail.attempt_lease_token,'')),'') is not null
       and (v_paper_mail.attempt_lease_expires_at_utc is null
         or v_paper_mail.attempt_lease_expires_at_utc>p_now_utc) then
      raise exception 'CANDIDATE_PAPER_MAIL_DELIVERY_IN_PROGRESS'
        using errcode='40001',detail=jsonb_build_object(
          'workflow_id',v_workflow.id,'generation',v_workflow.generation,
          'mail_outbox_id',v_paper_mail.id
        )::text;
    end if;
    if lower(coalesce(v_paper_mail.payment_scope_json->>'candidate_paper_generation_retired','false'))
         in ('true','t','1','yes') then
      raise exception 'CANDIDATE_PAPER_WORKFLOW_STALE' using errcode='40001';
    end if;
    if exists(
      select 1
      from jsonb_array_elements(v_workflow.paper_return_manifest_json->'pages') expected_page
      where (
        select count(*)
        from public.candidate_submission_components returned_page
        where returned_page.workflow_id=v_workflow.id
          and returned_page.workflow_generation=v_workflow.generation
          and returned_page.component_kind='SIGNED_RETURN'
          and returned_page.paper_return_page_key=expected_page->>'page_key'
          and returned_page.state='IMMUTABLE'
          and returned_page.source_content_sha256 is not null
      )<>1
    ) or exists(
      select 1
      from public.candidate_submission_components returned_page
      where returned_page.workflow_id=v_workflow.id
        and returned_page.workflow_generation=v_workflow.generation
        and returned_page.component_kind='SIGNED_RETURN'
        and returned_page.state='IMMUTABLE'
        and not exists(
          select 1
          from jsonb_array_elements(v_workflow.paper_return_manifest_json->'pages') expected_page
          where expected_page->>'page_key'=returned_page.paper_return_page_key
        )
    ) then raise exception 'CANDIDATE_PAPER_RETURN_INCOMPLETE' using errcode='22023'; end if;
    v_response:=jsonb_build_object('ok',true,'workflow_id',v_workflow.id,
      'state','RECEIVED','generation',v_workflow.generation);
    update public.candidate_submission_workflows set
      state='RECEIVED',last_mutation_idempotency_key=p_idempotency_key,
      last_mutation_response_json=v_response,updated_at_utc=p_now_utc
    where id=v_workflow.id returning * into v_workflow;

  elsif v_action='MARK_READ' then
    update public.candidate_notifications set state='READ',read_at_utc=p_now_utc
    where id=nullif(v_payload->>'notification_id','')::uuid
      and account_id=v_account_id and state='UNREAD';
    v_response:=jsonb_build_object('ok',true,
      'notification_id',nullif(v_payload->>'notification_id','')::uuid,'state','READ');
  else
    raise exception 'CANDIDATE_WORKFLOW_ACTION_INVALID'
      using errcode='22023',detail=jsonb_build_object(
        'code','CANDIDATE_WORKFLOW_ACTION_INVALID','action',v_action)::text;
  end if;

  perform private._candidate_audit_v1('candidate_submission_workflow',v_workflow.id::text,
    'CANDIDATE_WORKFLOW_'||v_action,
    jsonb_build_object('state',v_workflow.state,'generation',v_workflow.generation),
    v_response,v_audit_reason,null,p_idempotency_key,p_now_utc);
  if v_mutation_request_sha256 is not null then
    perform private._candidate_workflow_mutation_receipt_v1(
      v_workflow.id,p_idempotency_key,v_mutation_request_sha256,v_action,
      v_mutation_channel,v_mutation_actor_identity,v_response,p_now_utc
    );
  end if;
  return v_response;
exception
  when unique_violation then
    get stacked diagnostics v_constraint_name=constraint_name;
    if v_constraint_name='candidate_submission_components_source_sha256_uq' then
      raise exception 'CANDIDATE_EVIDENCE_BYTES_ALREADY_USED' using errcode='23505';
    elsif v_constraint_name in (
      'candidate_submission_components_hours_review_uq',
      'candidate_submission_components_required_ordinal_uq'
    ) then
      raise exception 'MANAGER_REVIEW_DOCUMENT_STALE' using errcode='23505';
    elsif v_constraint_name='candidate_submission_workflows_one_active_expense_uq' then
      raise exception 'CANDIDATE_EXPENSE_CLAIM_ALREADY_ACTIVE' using errcode='23505';
    elsif v_constraint_name='candidate_submission_workflows_account_idempotency_uq' then
      raise exception 'CANDIDATE_IDEMPOTENCY_CONFLICT' using errcode='40001';
    elsif v_constraint_name='candidate_submission_workflows_replacement_source_uq' then
      raise exception 'CANDIDATE_REJECTED_WORKFLOW_ALREADY_REPLACED' using errcode='40001';
    elsif v_constraint_name='candidate_submission_components_paper_return_page_uq' then
      raise exception 'CANDIDATE_PAPER_RETURN_PAGE_DUPLICATE' using errcode='23505';
    end if;
    raise;
end;
$function$;

-- client_create_with_settings_v1(uuid,jsonb,uuid,jsonb,timestamp with time zone)
CREATE OR REPLACE FUNCTION public.client_create_with_settings_v1(p_client_id uuid, p_client_json jsonb, p_actor_user_id uuid, p_settings_json jsonb DEFAULT '{}'::jsonb, p_now_utc timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_now timestamptz := COALESCE(p_now_utc, now());
  v_client_payload jsonb := COALESCE(p_client_json, '{}'::jsonb);
  v_settings_payload jsonb := COALESCE(p_settings_json, '{}'::jsonb);

  v_client_input public.clients%ROWTYPE;
  v_settings_input public.client_settings%ROWTYPE;
  v_global public.settings_defaults%ROWTYPE;
  v_client public.clients%ROWTYPE;
  v_settings public.client_settings%ROWTYPE;
  v_existing_client public.clients%ROWTYPE;
  v_existing_settings public.client_settings%ROWTYPE;

  v_unknown_client_keys text[] := ARRAY[]::text[];
  v_unknown_settings_keys text[] := ARRAY[]::text[];
  v_client_mismatch_keys text[] := ARRAY[]::text[];
  v_settings_mismatch_keys text[] := ARRAY[]::text[];
  v_lock_acquired boolean := false;
  v_replay boolean := false;
  v_candidate_settings_enabled boolean := private._candidate_feature_enabled_current_v1('candidate_settings');
BEGIN
  IF p_client_id IS NULL THEN
    RAISE EXCEPTION 'CLIENT_CREATE_ID_REQUIRED'
      USING ERRCODE = '22023',
            DETAIL = jsonb_build_object('code', 'CLIENT_CREATE_ID_REQUIRED')::text;
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'CLIENT_CREATE_ACTOR_REQUIRED'
      USING ERRCODE = '22023',
            DETAIL = jsonb_build_object('code', 'CLIENT_CREATE_ACTOR_REQUIRED')::text;
  END IF;

  PERFORM 1
  FROM public.tms_users AS actor_row
  WHERE actor_row.id = p_actor_user_id
    AND COALESCE(actor_row.is_active, false) = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'CLIENT_CREATE_ACTOR_INVALID'
      USING ERRCODE = '42501',
            DETAIL = jsonb_build_object(
              'code', 'CLIENT_CREATE_ACTOR_INVALID',
              'actor_user_id', p_actor_user_id::text
            )::text;
  END IF;

  IF jsonb_typeof(v_client_payload) <> 'object' THEN
    RAISE EXCEPTION 'CLIENT_CREATE_PAYLOAD_MUST_BE_OBJECT'
      USING ERRCODE = '22023';
  END IF;

  IF jsonb_typeof(v_settings_payload) <> 'object' THEN
    RAISE EXCEPTION 'CLIENT_SETTINGS_PAYLOAD_MUST_BE_OBJECT'
      USING ERRCODE = '22023';
  END IF;

  IF octet_length(v_client_payload::text) > 65536 THEN
    RAISE EXCEPTION 'CLIENT_CREATE_PAYLOAD_TOO_LARGE'
      USING ERRCODE = '22023',
            DETAIL = jsonb_build_object(
              'code', 'CLIENT_CREATE_PAYLOAD_TOO_LARGE',
              'max_bytes', 65536
            )::text;
  END IF;

  IF octet_length(v_settings_payload::text) > 131072 THEN
    RAISE EXCEPTION 'CLIENT_SETTINGS_PAYLOAD_TOO_LARGE'
      USING ERRCODE = '22023',
            DETAIL = jsonb_build_object(
              'code', 'CLIENT_SETTINGS_PAYLOAD_TOO_LARGE',
              'max_bytes', 131072
            )::text;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_each(v_client_payload) AS supplied_field(field_name, field_value)
    WHERE supplied_field.field_name IN ('name', 'vat_chargeable', 'payment_terms_days')
      AND supplied_field.field_value = 'null'::jsonb
  ) THEN
    RAISE EXCEPTION 'CLIENT_CREATE_REQUIRED_FIELD_NULL'
      USING ERRCODE = '22023',
            DETAIL = jsonb_build_object(
              'code', 'CLIENT_CREATE_REQUIRED_FIELD_NULL'
            )::text;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_each(v_settings_payload) AS supplied_field(field_name, field_value)
    WHERE (
      supplied_field.field_name IN (
      'effective_from',
      'hr_validation_required',
      'ts_reference_required',
      'autoprocess_hr',
      'pay_reference_required',
      'invoice_reference_required',
      'default_submission_mode',
      'is_nhsp',
      'self_bill_no_invoices_sent',
      'daily_calc_of_invoices',
      'no_timesheet_required',
      'group_nightsat_sunbh',
      'requires_hr',
      'hr_attach_to_invoice',
      'ts_attach_to_invoice',
      'auto_invoice_default',
      'send_manual_invoices_to_different_email',
      'invoice_consolidation_mode',
      'reference_number_required_to_issue_invoice',
      'opt_in_email',
      'opt_in_sms',
      'opt_in_whatsapp',
      'healthroster_import_auto_authorise',
      'nhsp_import_auto_authorise'
      )
      OR (v_candidate_settings_enabled AND supplied_field.field_name IN (
      'candidate_expenses_require_separate_timesheet',
      'candidate_paper_submission_enabled',
      'candidate_manager_approval_policy_json',
      'allow_daily_manager_authorise_on_phone',
      'allow_daily_manager_authorise_by_email'
      ))
    )
      AND supplied_field.field_value = 'null'::jsonb
  ) THEN
    RAISE EXCEPTION 'CLIENT_SETTINGS_REQUIRED_FIELD_NULL'
      USING ERRCODE = '22023',
            DETAIL = jsonb_build_object(
              'code', 'CLIENT_SETTINGS_REQUIRED_FIELD_NULL'
            )::text;
  END IF;

  SELECT COALESCE(array_agg(key_name ORDER BY key_name), ARRAY[]::text[])
  INTO v_unknown_client_keys
  FROM jsonb_object_keys(v_client_payload) AS supplied_key(key_name)
  WHERE supplied_key.key_name <> ALL (
    ARRAY[
      'name',
      'invoice_address',
      'primary_invoice_email',
      'ap_phone',
      'vat_chargeable',
      'payment_terms_days',
      'mileage_charge_rate',
      'ts_queries_email',
      'client_address',
      'contact_title',
      'contact_known_as',
      'contact_forename',
      'contact_surname',
      'contact_job_title',
      'contact_tel',
      'contact_mobile',
      'contact_email',
      'website',
      'notes'
    ]::text[]
  );

  IF cardinality(v_unknown_client_keys) > 0 THEN
    RAISE EXCEPTION 'CLIENT_CREATE_UNKNOWN_FIELDS'
      USING ERRCODE = '22023',
            DETAIL = jsonb_build_object(
              'code', 'CLIENT_CREATE_UNKNOWN_FIELDS',
              'unknown_fields', to_jsonb(v_unknown_client_keys)
            )::text;
  END IF;

  SELECT COALESCE(array_agg(key_name ORDER BY key_name), ARRAY[]::text[])
  INTO v_unknown_settings_keys
  FROM jsonb_object_keys(v_settings_payload) AS supplied_key(key_name)
  WHERE supplied_key.key_name <> ALL (
    ARRAY[
      'timezone_id',
      'day_start',
      'day_end',
      'night_start',
      'night_end',
      'bh_source',
      'bh_list',
      'bh_feed_url',
      'vat_rate_pct',
      'holiday_pay_pct',
      'erni_pct',
      'apply_holiday_to',
      'apply_erni_to',
      'margin_includes',
      'effective_from',
      'hr_validation_required',
      'ts_reference_required',
      'week_ending_weekday',
      'autoprocess_hr',
      'pay_reference_required',
      'invoice_reference_required',
      'default_submission_mode',
      'sat_start',
      'sat_end',
      'sun_start',
      'sun_end',
      'is_nhsp',
      'self_bill_no_invoices_sent',
      'daily_calc_of_invoices',
      'no_timesheet_required',
      'group_nightsat_sunbh',
      'requires_hr',
      'hr_attach_to_invoice',
      'ts_attach_to_invoice',
      'bh_start',
      'bh_end',
      'auto_invoice_default',
      'send_manual_invoices_to_different_email',
      'manual_invoices_alt_email_address',
      'invoice_consolidation_mode',
      'reference_number_required_to_issue_invoice',
      'opt_in_email',
      'opt_in_sms',
      'opt_in_whatsapp',
      'healthroster_import_auto_authorise',
      'nhsp_import_auto_authorise',
      'reversal_complete_financials_date',
      'reversal_replacement_financials_date'
    ]::text[] || CASE WHEN v_candidate_settings_enabled THEN ARRAY[
      'candidate_electronic_auto_authorise',
      'candidate_expenses_require_separate_timesheet',
      'candidate_paper_submission_enabled',
      'candidate_expense_invoice_email',
      'candidate_manager_approval_policy_json',
      'allow_daily_manager_authorise_on_phone',
      'allow_daily_manager_authorise_by_email'
    ]::text[] ELSE ARRAY[]::text[] END
  );

  IF cardinality(v_unknown_settings_keys) > 0 THEN
    RAISE EXCEPTION 'CLIENT_SETTINGS_UNKNOWN_FIELDS'
      USING ERRCODE = '22023',
            DETAIL = jsonb_build_object(
              'code', 'CLIENT_SETTINGS_UNKNOWN_FIELDS',
              'unknown_fields', to_jsonb(v_unknown_settings_keys)
            )::text;
  END IF;

  SELECT *
  INTO v_client_input
  FROM jsonb_populate_record(NULL::public.clients, v_client_payload);

  SELECT *
  INTO v_settings_input
  FROM jsonb_populate_record(NULL::public.client_settings, v_settings_payload);

  IF v_candidate_settings_enabled
     AND v_settings_payload ? 'candidate_manager_approval_policy_json' THEN
    v_settings_input.candidate_manager_approval_policy_json :=
      private._candidate_normalize_manager_policy_v1(
        v_settings_input.candidate_manager_approval_policy_json
      );
  END IF;

  PERFORM public._ctms_assert_import_correction_settings_write_v1(
    COALESCE(v_settings_input.is_nhsp, false),
    COALESCE(v_settings_input.requires_hr, false),
    COALESCE(v_settings_input.no_timesheet_required, false),
    CASE WHEN v_settings_payload ? 'reversal_complete_financials_date'
      THEN v_settings_input.reversal_complete_financials_date
      ELSE NULL::public.correction_financials_date_basis_enum
    END,
    CASE WHEN v_settings_payload ? 'reversal_replacement_financials_date'
      THEN v_settings_input.reversal_replacement_financials_date
      ELSE NULL::public.correction_financials_date_basis_enum
    END
  );

  IF NULLIF(BTRIM(COALESCE(v_client_input.name, '')), '') IS NULL THEN
    RAISE EXCEPTION 'CLIENT_CREATE_NAME_REQUIRED'
      USING ERRCODE = '22023',
            DETAIL = jsonb_build_object('code', 'CLIENT_CREATE_NAME_REQUIRED')::text;
  END IF;

  IF char_length(v_client_input.name) > 500 THEN
    RAISE EXCEPTION 'CLIENT_CREATE_NAME_TOO_LONG'
      USING ERRCODE = '22023',
            DETAIL = jsonb_build_object(
              'code', 'CLIENT_CREATE_NAME_TOO_LONG',
              'max_characters', 500
            )::text;
  END IF;

  IF COALESCE(v_client_input.payment_terms_days, 30) < 0
     OR COALESCE(v_client_input.payment_terms_days, 30) > 365 THEN
    RAISE EXCEPTION 'CLIENT_CREATE_PAYMENT_TERMS_OUT_OF_RANGE'
      USING ERRCODE = '22023',
            DETAIL = jsonb_build_object(
              'code', 'CLIENT_CREATE_PAYMENT_TERMS_OUT_OF_RANGE',
              'min', 0,
              'max', 365
            )::text;
  END IF;

  IF v_client_input.mileage_charge_rate IS NOT NULL
     AND v_client_input.mileage_charge_rate < 0 THEN
    RAISE EXCEPTION 'CLIENT_CREATE_MILEAGE_RATE_NEGATIVE'
      USING ERRCODE = '22023';
  END IF;

  IF v_client_input.primary_invoice_email IS NOT NULL
     AND char_length(v_client_input.primary_invoice_email) > 320 THEN
    RAISE EXCEPTION 'CLIENT_CREATE_PRIMARY_EMAIL_TOO_LONG'
      USING ERRCODE = '22023';
  END IF;

  IF v_client_input.contact_email IS NOT NULL
     AND char_length(v_client_input.contact_email) > 320 THEN
    RAISE EXCEPTION 'CLIENT_CREATE_CONTACT_EMAIL_TOO_LONG'
      USING ERRCODE = '22023';
  END IF;

  IF v_client_input.notes IS NOT NULL
     AND char_length(v_client_input.notes) > 20000 THEN
    RAISE EXCEPTION 'CLIENT_CREATE_NOTES_TOO_LONG'
      USING ERRCODE = '22023';
  END IF;

  IF v_candidate_settings_enabled AND jsonb_typeof(COALESCE(
       v_settings_input.candidate_manager_approval_policy_json,
       '{}'::jsonb
     )) <> 'object' THEN
    RAISE EXCEPTION 'CLIENT_SETTINGS_CANDIDATE_MANAGER_POLICY_INVALID'
      USING ERRCODE = '22023';
  END IF;

  IF v_candidate_settings_enabled
     AND COALESCE(v_settings_input.allow_daily_manager_authorise_on_phone, true) = false
     AND COALESCE(v_settings_input.allow_daily_manager_authorise_by_email, false) = false THEN
    RAISE EXCEPTION 'CLIENT_SETTINGS_DAILY_MANAGER_METHOD_REQUIRED'
      USING ERRCODE = '22023';
  END IF;

  IF v_candidate_settings_enabled
     AND (
       COALESCE(v_settings_input.is_nhsp, false)
       OR (
         COALESCE(v_settings_input.requires_hr, false)
         AND COALESCE(v_settings_input.no_timesheet_required, false)
       )
     ) THEN
    IF NOT COALESCE(v_settings_input.candidate_expenses_require_separate_timesheet, false) THEN
      RAISE EXCEPTION 'CANDIDATE_IMPORT_EXPENSE_SEPARATION_REQUIRED'
        USING ERRCODE = '22023';
    END IF;
    IF NULLIF(BTRIM(v_settings_input.candidate_expense_invoice_email), '') IS NULL
       OR char_length(BTRIM(v_settings_input.candidate_expense_invoice_email)) > 320
       OR BTRIM(v_settings_input.candidate_expense_invoice_email)
          !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN
      RAISE EXCEPTION 'CANDIDATE_IMPORT_EXPENSE_EMAIL_REQUIRED'
        USING ERRCODE = '22023';
    END IF;
  END IF;

  SELECT settings_row.*
  INTO v_global
  FROM public.settings_defaults AS settings_row
  WHERE settings_row.id = 1
  FOR SHARE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'CLIENT_CREATE_GLOBAL_SETTINGS_MISSING'
      USING ERRCODE = 'P0001';
  END IF;

  IF v_candidate_settings_enabled
     AND COALESCE((COALESCE(
       v_settings_input.candidate_manager_approval_policy_json,
       '{"approved_emails":[],"approved_domains":[],"allow_free_business_email":false}'::jsonb
     )->>'allow_free_business_email')::boolean, false)
     AND (
       jsonb_typeof(v_global.candidate_barred_manager_email_domains) <> 'array'
       OR jsonb_array_length(v_global.candidate_barred_manager_email_domains) = 0
     ) THEN
    RAISE EXCEPTION 'CANDIDATE_BARRED_MANAGER_DOMAIN_POLICY_REQUIRED'
      USING ERRCODE = '22023';
  END IF;

  v_lock_acquired := pg_try_advisory_xact_lock(
    hashtextextended(
      'CLIENT_CREATE_WITH_SETTINGS|' || p_client_id::text,
      24062026
    )
  );

  IF NOT v_lock_acquired THEN
    RAISE EXCEPTION 'CLIENT_CREATE_LOCK_BUSY'
      USING ERRCODE = '55P03',
            DETAIL = jsonb_build_object(
              'code', 'CLIENT_CREATE_LOCK_BUSY',
              'client_id', p_client_id::text,
              'retryable', true
            )::text;
  END IF;

  SELECT client_row.*
  INTO v_existing_client
  FROM public.clients AS client_row
  WHERE client_row.id = p_client_id
  FOR UPDATE;

  IF FOUND THEN
    SELECT settings_row.*
    INTO v_existing_settings
    FROM public.client_settings AS settings_row
    WHERE settings_row.client_id = p_client_id
    ORDER BY
      settings_row.effective_from DESC NULLS LAST,
      settings_row.updated_at DESC,
      settings_row.id DESC
    LIMIT 1
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'CLIENT_CREATE_REPLAY_SETTINGS_MISSING'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'CLIENT_CREATE_REPLAY_SETTINGS_MISSING',
                'client_id', p_client_id::text
              )::text;
    END IF;

    SELECT COALESCE(array_agg(key_name ORDER BY key_name), ARRAY[]::text[])
    INTO v_client_mismatch_keys
    FROM jsonb_object_keys(v_client_payload) AS requested_key(key_name)
    WHERE (to_jsonb(v_existing_client) -> requested_key.key_name)
          IS DISTINCT FROM
          (to_jsonb(v_client_input) -> requested_key.key_name);

    SELECT COALESCE(array_agg(key_name ORDER BY key_name), ARRAY[]::text[])
    INTO v_settings_mismatch_keys
    FROM jsonb_object_keys(v_settings_payload) AS requested_key(key_name)
    WHERE (to_jsonb(v_existing_settings) -> requested_key.key_name)
          IS DISTINCT FROM
          (to_jsonb(v_settings_input) -> requested_key.key_name);

    IF cardinality(v_client_mismatch_keys) > 0
       OR cardinality(v_settings_mismatch_keys) > 0 THEN
      RAISE EXCEPTION 'CLIENT_CREATE_IDEMPOTENCY_CONFLICT'
        USING ERRCODE = '23505',
              DETAIL = jsonb_build_object(
                'code', 'CLIENT_CREATE_IDEMPOTENCY_CONFLICT',
                'client_id', p_client_id::text,
                'client_mismatch_fields', to_jsonb(v_client_mismatch_keys),
                'settings_mismatch_fields', to_jsonb(v_settings_mismatch_keys)
              )::text;
    END IF;

    v_replay := true;
    v_client := v_existing_client;
    v_settings := v_existing_settings;
  ELSE
    INSERT INTO public.clients (
      id,
      name,
      invoice_address,
      primary_invoice_email,
      ap_phone,
      vat_chargeable,
      payment_terms_days,
      created_at,
      updated_at,
      mileage_charge_rate,
      ts_queries_email,
      client_address,
      contact_title,
      contact_known_as,
      contact_forename,
      contact_surname,
      contact_job_title,
      contact_tel,
      contact_mobile,
      contact_email,
      website,
      notes
    )
    VALUES (
      p_client_id,
      BTRIM(v_client_input.name),
      v_client_input.invoice_address,
      v_client_input.primary_invoice_email,
      v_client_input.ap_phone,
      COALESCE(v_client_input.vat_chargeable, true),
      COALESCE(v_client_input.payment_terms_days, 30),
      v_now,
      v_now,
      v_client_input.mileage_charge_rate,
      v_client_input.ts_queries_email,
      v_client_input.client_address,
      v_client_input.contact_title,
      v_client_input.contact_known_as,
      v_client_input.contact_forename,
      v_client_input.contact_surname,
      v_client_input.contact_job_title,
      v_client_input.contact_tel,
      v_client_input.contact_mobile,
      v_client_input.contact_email,
      v_client_input.website,
      v_client_input.notes
    )
    RETURNING *
    INTO v_client;

    INSERT INTO public.client_settings (
      client_id,
      timezone_id,
      day_start,
      day_end,
      night_start,
      night_end,
      bh_source,
      bh_list,
      bh_feed_url,
      vat_rate_pct,
      holiday_pay_pct,
      erni_pct,
      apply_holiday_to,
      apply_erni_to,
      margin_includes,
      effective_from,
      created_at,
      updated_at,
      hr_validation_required,
      ts_reference_required,
      week_ending_weekday,
      autoprocess_hr,
      pay_reference_required,
      invoice_reference_required,
      default_submission_mode,
      sat_start,
      sat_end,
      sun_start,
      sun_end,
      is_nhsp,
      self_bill_no_invoices_sent,
      daily_calc_of_invoices,
      no_timesheet_required,
      group_nightsat_sunbh,
      requires_hr,
      hr_attach_to_invoice,
      ts_attach_to_invoice,
      bh_start,
      bh_end,
      auto_invoice_default,
      send_manual_invoices_to_different_email,
      manual_invoices_alt_email_address,
      invoice_consolidation_mode,
      reference_number_required_to_issue_invoice,
      opt_in_email,
      opt_in_sms,
      opt_in_whatsapp,
      healthroster_import_auto_authorise,
      nhsp_import_auto_authorise,
      reversal_complete_financials_date,
      reversal_replacement_financials_date,
      candidate_electronic_auto_authorise,
      candidate_expenses_require_separate_timesheet,
      candidate_paper_submission_enabled,
      candidate_expense_invoice_email,
      candidate_manager_approval_policy_json,
      allow_daily_manager_authorise_on_phone,
      allow_daily_manager_authorise_by_email
    )
    VALUES (
      p_client_id,
      CASE WHEN v_settings_payload ? 'timezone_id'
        THEN v_settings_input.timezone_id ELSE v_global.timezone_id END,
      CASE WHEN v_settings_payload ? 'day_start'
        THEN v_settings_input.day_start ELSE v_global.day_start END,
      CASE WHEN v_settings_payload ? 'day_end'
        THEN v_settings_input.day_end ELSE v_global.day_end END,
      CASE WHEN v_settings_payload ? 'night_start'
        THEN v_settings_input.night_start ELSE v_global.night_start END,
      CASE WHEN v_settings_payload ? 'night_end'
        THEN v_settings_input.night_end ELSE v_global.night_end END,
      CASE WHEN v_settings_payload ? 'bh_source'
        THEN v_settings_input.bh_source ELSE v_global.bh_source END,
      CASE WHEN v_settings_payload ? 'bh_list'
        THEN v_settings_input.bh_list ELSE v_global.bh_list END,
      CASE WHEN v_settings_payload ? 'bh_feed_url'
        THEN v_settings_input.bh_feed_url ELSE v_global.bh_feed_url END,
      v_settings_input.vat_rate_pct,
      v_settings_input.holiday_pay_pct,
      v_settings_input.erni_pct,
      v_settings_input.apply_holiday_to,
      v_settings_input.apply_erni_to,
      v_settings_input.margin_includes,
      COALESCE(
        v_settings_input.effective_from,
        (v_now AT TIME ZONE 'Europe/London')::date
      ),
      v_now,
      v_now,
      COALESCE(v_settings_input.hr_validation_required, false),
      CASE WHEN v_settings_payload ? 'ts_reference_required'
        THEN COALESCE(v_settings_input.ts_reference_required, false)
        ELSE COALESCE(v_global.ts_reference_required, false)
      END,
      v_settings_input.week_ending_weekday,
      COALESCE(v_settings_input.autoprocess_hr, false),
      COALESCE(v_settings_input.pay_reference_required, false),
      COALESCE(v_settings_input.invoice_reference_required, false),
      COALESCE(
        v_settings_input.default_submission_mode,
        'ELECTRONIC'::public.submission_mode_enum
      ),
      CASE WHEN v_settings_payload ? 'sat_start'
        THEN v_settings_input.sat_start ELSE v_global.sat_start END,
      CASE WHEN v_settings_payload ? 'sat_end'
        THEN v_settings_input.sat_end ELSE v_global.sat_end END,
      CASE WHEN v_settings_payload ? 'sun_start'
        THEN v_settings_input.sun_start ELSE v_global.sun_start END,
      CASE WHEN v_settings_payload ? 'sun_end'
        THEN v_settings_input.sun_end ELSE v_global.sun_end END,
      COALESCE(v_settings_input.is_nhsp, false),
      COALESCE(v_settings_input.self_bill_no_invoices_sent, false),
      COALESCE(v_settings_input.daily_calc_of_invoices, false),
      COALESCE(v_settings_input.no_timesheet_required, false),
      COALESCE(v_settings_input.group_nightsat_sunbh, false),
      COALESCE(v_settings_input.requires_hr, false),
      CASE WHEN v_settings_payload ? 'hr_attach_to_invoice'
        THEN COALESCE(v_settings_input.hr_attach_to_invoice, true)
        ELSE COALESCE(v_global.hr_attach_to_invoice, true)
      END,
      CASE WHEN v_settings_payload ? 'ts_attach_to_invoice'
        THEN COALESCE(v_settings_input.ts_attach_to_invoice, true)
        ELSE COALESCE(v_global.ts_attach_to_invoice, true)
      END,
      CASE WHEN v_settings_payload ? 'bh_start'
        THEN v_settings_input.bh_start ELSE v_global.bh_start END,
      CASE WHEN v_settings_payload ? 'bh_end'
        THEN v_settings_input.bh_end ELSE v_global.bh_end END,
      COALESCE(v_settings_input.auto_invoice_default, false),
      COALESCE(
        v_settings_input.send_manual_invoices_to_different_email,
        false
      ),
      v_settings_input.manual_invoices_alt_email_address,
      COALESCE(
        v_settings_input.invoice_consolidation_mode,
        'NONE'::public.invoice_consolidation_mode_enum
      ),
      COALESCE(
        v_settings_input.reference_number_required_to_issue_invoice,
        false
      ),
      COALESCE(v_settings_input.opt_in_email, true),
      COALESCE(v_settings_input.opt_in_sms, true),
      COALESCE(v_settings_input.opt_in_whatsapp, true),
      CASE WHEN v_settings_payload ? 'healthroster_import_auto_authorise'
        THEN COALESCE(
          v_settings_input.healthroster_import_auto_authorise,
          v_global.healthroster_import_auto_authorise_default
        )
        ELSE v_global.healthroster_import_auto_authorise_default
      END,
      CASE WHEN v_settings_payload ? 'nhsp_import_auto_authorise'
        THEN COALESCE(
          v_settings_input.nhsp_import_auto_authorise,
          v_global.nhsp_import_auto_authorise_default
        )
        ELSE v_global.nhsp_import_auto_authorise_default
      END,
      CASE WHEN (
        COALESCE(v_settings_input.is_nhsp, false) = true
        OR (
          COALESCE(v_settings_input.requires_hr, false) = true
          AND COALESCE(v_settings_input.no_timesheet_required, false) = true
        )
      ) AND v_settings_payload ? 'reversal_complete_financials_date'
        THEN v_settings_input.reversal_complete_financials_date
        ELSE NULL::public.correction_financials_date_basis_enum
      END,
      CASE WHEN (
        COALESCE(v_settings_input.is_nhsp, false) = true
        OR (
          COALESCE(v_settings_input.requires_hr, false) = true
          AND COALESCE(v_settings_input.no_timesheet_required, false) = true
        )
      ) AND v_settings_payload ? 'reversal_replacement_financials_date'
        THEN v_settings_input.reversal_replacement_financials_date
        ELSE NULL::public.correction_financials_date_basis_enum
      END,
      CASE WHEN v_candidate_settings_enabled AND v_settings_payload ? 'candidate_electronic_auto_authorise'
        THEN v_settings_input.candidate_electronic_auto_authorise
        ELSE NULL::boolean END,
      CASE WHEN v_candidate_settings_enabled
        THEN COALESCE(v_settings_input.candidate_expenses_require_separate_timesheet, false)
        ELSE false END,
      CASE WHEN v_candidate_settings_enabled
        THEN COALESCE(v_settings_input.candidate_paper_submission_enabled, false)
        ELSE false END,
      CASE WHEN v_candidate_settings_enabled
        THEN NULLIF(BTRIM(v_settings_input.candidate_expense_invoice_email), '')
        ELSE NULL::text END,
      CASE WHEN v_candidate_settings_enabled THEN COALESCE(
          v_settings_input.candidate_manager_approval_policy_json,
          '{"approved_emails":[],"approved_domains":[],"allow_free_business_email":false}'::jsonb
        )
        ELSE '{"approved_emails":[],"approved_domains":[],"allow_free_business_email":false}'::jsonb
      END,
      CASE WHEN v_candidate_settings_enabled
        THEN COALESCE(v_settings_input.allow_daily_manager_authorise_on_phone, true)
        ELSE true END,
      CASE WHEN v_candidate_settings_enabled
        THEN COALESCE(v_settings_input.allow_daily_manager_authorise_by_email, false)
        ELSE false END
    )
    RETURNING *
    INTO v_settings;

    PERFORM public._inv_write_audit(
      p_actor_user_id,
      'CLIENT_CREATED_WITH_SETTINGS',
      jsonb_build_object(
        'client_id', v_client.id::text,
        'client_ref', v_client.cli_ref,
        'client_name', v_client.name,
        'client_settings_id', v_settings.id::text,
        'healthroster_import_auto_authorise',
          v_settings.healthroster_import_auto_authorise,
        'nhsp_import_auto_authorise',
          v_settings.nhsp_import_auto_authorise,
        'correction_policy_eligible',
          (v_settings.is_nhsp OR (v_settings.requires_hr AND v_settings.no_timesheet_required)),
        'reversal_complete_financials_date_override',
          v_settings.reversal_complete_financials_date,
        'reversal_complete_financials_date_effective',
          COALESCE(v_settings.reversal_complete_financials_date, v_global.reversal_complete_financials_date),
        'reversal_replacement_financials_date_override',
          v_settings.reversal_replacement_financials_date,
        'reversal_replacement_financials_date_effective',
          COALESCE(v_settings.reversal_replacement_financials_date, v_global.reversal_replacement_financials_date),
        'correction_setting_source',
          CASE WHEN v_settings.reversal_complete_financials_date IS NULL
                 AND v_settings.reversal_replacement_financials_date IS NULL
            THEN 'GLOBAL' ELSE 'CLIENT_OR_MIXED' END,
        'copied_global_settings_updated_at', v_global.updated_at
      ),
      'client',
      v_client.id::text,
      NULL::jsonb,
      'Atomic client and initial settings creation',
      NULL::text,
      NULL::text,
      'client-create-with-settings:' || v_client.id::text
    );
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'replay', v_replay,
    'client', to_jsonb(v_client),
    'client_settings', to_jsonb(v_settings),
    'policy', jsonb_build_object(
      'healthroster', public.import_auto_authorise_policy_resolve_v1(
        'HEALTHROSTER'::public.hr_source_enum,
        v_client.id,
        NULL::uuid,
        false
      ),
      'nhsp', public.import_auto_authorise_policy_resolve_v1(
        'NHSP'::public.hr_source_enum,
        v_client.id,
        NULL::uuid,
        false
      )
    )
  );
END;
$function$;

-- client_delete_apply(uuid,uuid,text)
CREATE OR REPLACE FUNCTION public.client_delete_apply(p_client_id uuid, p_actor_user_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_elig jsonb;
  v_can boolean;
  v_deleted_rev bigint;
  v_seq bigint;
  v_before jsonb;
BEGIN
  v_elig := public.client_delete_eligibility(p_client_id);
  v_can := COALESCE((v_elig->>'can_delete')::boolean, false);

  IF v_can IS NOT TRUE THEN
    RAISE EXCEPTION '%', COALESCE(v_elig->>'reason', 'Client cannot be deleted');
  END IF;

  -- Lock client row
  SELECT jsonb_build_object(
           'id', c.id::text,
           'name', c.name,
           'cli_ref', c.cli_ref
         )
    INTO v_before
  FROM public.clients c
  WHERE c.id = p_client_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Client not found';
  END IF;

  -- Non-blocking dependents (verified tables)
  DELETE FROM public.client_hospitals ch WHERE ch.client_id = p_client_id;
  DELETE FROM public.client_settings cs WHERE cs.client_id = p_client_id;
  DELETE FROM public.rates_client_defaults rcd WHERE rcd.client_id = p_client_id;
  DELETE FROM public.legacy_eclipse_client_map lec WHERE lec.client_id = p_client_id;

  -- Delete client
  DELETE FROM public.clients c WHERE c.id = p_client_id;

  -- Bump change counter and record deleted_rev
  PERFORM public._change_bump('clients');
  SELECT acc.seq INTO v_seq
  FROM public.app_change_counters acc
  WHERE acc.entity_key = 'clients'
  LIMIT 1;

  v_deleted_rev := COALESCE(v_seq, 0);

  INSERT INTO public.clients_tombstones (id, deleted_rev, deleted_at)
  VALUES (p_client_id, v_deleted_rev, now())
  ON CONFLICT (id) DO UPDATE
    SET deleted_rev = EXCLUDED.deleted_rev,
        deleted_at  = EXCLUDED.deleted_at;

  PERFORM public._audit_insert(
    'clients',
    p_client_id::text,
    'DELETE',
    v_before,
    jsonb_build_object('deleted_rev', v_deleted_rev),
    COALESCE(p_reason, 'DELETE'),
    p_actor_user_id
  );

  RETURN jsonb_build_object('deleted', true, 'client_id', p_client_id::text, 'deleted_rev', v_deleted_rev);
END;
$function$;

-- client_delete_eligibility(uuid)
CREATE OR REPLACE FUNCTION public.client_delete_eligibility(p_client_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_contracts int;
  v_contract_weeks int;
  v_timesheets int;
  v_invoices int;
  v_reason text := null;
  v_can boolean := true;
BEGIN
  IF p_client_id IS NULL THEN
    RAISE EXCEPTION 'client_id is required';
  END IF;

  SELECT COUNT(*) INTO v_contracts
  FROM public.contracts ct
  WHERE ct.client_id = p_client_id;

  SELECT COUNT(*) INTO v_contract_weeks
  FROM public.contract_weeks cw
  JOIN public.contracts ct ON ct.id = cw.contract_id
  WHERE ct.client_id = p_client_id;

  SELECT COUNT(*) INTO v_timesheets
  FROM public.timesheets t
  JOIN public.contracts ct ON ct.id = t.contract_id
  WHERE ct.client_id = p_client_id;

  SELECT COUNT(*) INTO v_invoices
  FROM public.invoices inv
  WHERE inv.client_id = p_client_id;

  IF v_contracts > 0 OR v_contract_weeks > 0 OR v_timesheets > 0 OR v_invoices > 0 THEN
    v_can := false;
    v_reason := 'Client cannot be deleted because related records exist.';
  END IF;

  RETURN jsonb_build_object(
    'client_id', p_client_id::text,
    'can_delete', v_can,
    'reason', v_reason,
    'blockers', jsonb_build_object(
      'contracts', v_contracts,
      'contract_weeks', v_contract_weeks,
      'timesheets', v_timesheets,
      'invoices', v_invoices
    )
  );
END;
$function$;

-- client_list_ids(jsonb)
CREATE OR REPLACE FUNCTION public.client_list_ids(p_filters jsonb)
 RETURNS TABLE(id uuid)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_q text := null;
  v_cli_ref text := null;
  v_primary_invoice_email text := null;
  v_invoice_address text := null;
  v_ap_phone text := null;
  v_vat_chargeable text := null;
  v_payment_terms_days integer := null;
  v_mileage_charge_rate numeric := null;
  v_ts_queries_email text := null;
  v_created_from timestamptz := null;
  v_created_to timestamptz := null;
  v_updated_from timestamptz := null;
  v_updated_to timestamptz := null;
  v_notes text := null;
  v_ids uuid[] := null;
begin
  if p_filters is null then
    p_filters := '{}'::jsonb;
  end if;

  v_q := nullif(btrim(coalesce(p_filters->>'q', coalesce(p_filters->>'name', ''))), '');
  v_cli_ref := nullif(btrim(coalesce(p_filters->>'cli_ref', '')), '');
  v_primary_invoice_email := nullif(btrim(coalesce(p_filters->>'primary_invoice_email', '')), '');
  v_invoice_address := nullif(btrim(coalesce(p_filters->>'invoice_address', '')), '');
  v_ap_phone := nullif(btrim(coalesce(p_filters->>'ap_phone', '')), '');
  v_vat_chargeable := nullif(lower(btrim(coalesce(p_filters->>'vat_chargeable', ''))), '');
  v_notes := nullif(btrim(coalesce(p_filters->>'notes', '')), '');
  v_ts_queries_email := nullif(btrim(coalesce(p_filters->>'ts_queries_email', '')), '');

  begin
    if nullif(btrim(coalesce(p_filters->>'payment_terms_days', '')), '') is not null then
      v_payment_terms_days := (p_filters->>'payment_terms_days')::integer;
    end if;
  exception when others then
    v_payment_terms_days := null;
  end;

  begin
    if nullif(btrim(coalesce(p_filters->>'mileage_charge_rate', '')), '') is not null then
      v_mileage_charge_rate := (p_filters->>'mileage_charge_rate')::numeric;
    end if;
  exception when others then
    v_mileage_charge_rate := null;
  end;

  begin
    if nullif(btrim(coalesce(p_filters->>'created_from', '')), '') is not null then
      v_created_from := (p_filters->>'created_from')::timestamptz;
    end if;
  exception when others then
    v_created_from := null;
  end;

  begin
    if nullif(btrim(coalesce(p_filters->>'created_to', '')), '') is not null then
      v_created_to := (p_filters->>'created_to')::timestamptz;
    end if;
  exception when others then
    v_created_to := null;
  end;

  begin
    if nullif(btrim(coalesce(p_filters->>'updated_from', '')), '') is not null then
      v_updated_from := (p_filters->>'updated_from')::timestamptz;
    end if;
  exception when others then
    v_updated_from := null;
  end;

  begin
    if nullif(btrim(coalesce(p_filters->>'updated_to', '')), '') is not null then
      v_updated_to := (p_filters->>'updated_to')::timestamptz;
    end if;
  exception when others then
    v_updated_to := null;
  end;

  begin
    if p_filters ? 'ids' then
      if jsonb_typeof(p_filters->'ids') = 'array' then
        select array_agg(val::uuid)
        into v_ids
        from (
          select distinct nullif(btrim(e.value), '') as val
          from jsonb_array_elements_text(p_filters->'ids') as e(value)
        ) s
        where s.val is not null;
      elsif nullif(btrim(coalesce(p_filters->>'ids', '')), '') is not null then
        select array_agg(val::uuid)
        into v_ids
        from (
          select distinct nullif(btrim(x), '') as val
          from unnest(regexp_split_to_array(p_filters->>'ids', '\s*,\s*')) as u(x)
        ) s
        where s.val is not null;
      end if;
    end if;
  exception when others then
    v_ids := null;
  end;

  return query
  select c.id
  from public.clients c
  where (v_ids is null or c.id = any(v_ids))
    and (v_q is null or c.name ilike ('%' || v_q || '%'))
    and (v_cli_ref is null or c.cli_ref ilike ('%' || v_cli_ref || '%'))
    and (v_primary_invoice_email is null or c.primary_invoice_email ilike ('%' || v_primary_invoice_email || '%'))
    and (v_invoice_address is null or c.invoice_address ilike ('%' || v_invoice_address || '%'))
    and (v_ap_phone is null or c.ap_phone ilike ('%' || v_ap_phone || '%'))
    and (
      v_notes is null
      or c.notes ilike ('%' || replace(replace(replace(v_notes, E'\\', E'\\\\'), '%', E'\\%'), '_', E'\\_') || '%') escape '\\'
    )
    and (
      v_vat_chargeable is null
      or (v_vat_chargeable = 'true' and c.vat_chargeable = true)
      or (v_vat_chargeable = 'false' and c.vat_chargeable = false)
    )
    and (v_payment_terms_days is null or c.payment_terms_days = v_payment_terms_days)
    and (v_mileage_charge_rate is null or c.mileage_charge_rate = v_mileage_charge_rate)
    and (v_ts_queries_email is null or c.ts_queries_email ilike ('%' || v_ts_queries_email || '%'))
    and (v_created_from is null or c.created_at >= v_created_from)
    and (v_created_to is null or c.created_at <= v_created_to)
    and (v_updated_from is null or c.updated_at >= v_updated_from)
    and (v_updated_to is null or c.updated_at <= v_updated_to)
  order by c.id;
end;
$function$;

